/*
 * AQA A-Level Mathematics (7357) — Exam Practice Question Bank
 * Shape: { topicId: { name, questions: [{ q, marks, command, markScheme, diagram? }] } }
 * Topic ids unchanged so topics-config.js still matches.
 *
 * WHY THIS SHAPE. Every item is written the way the board writes it: whole
 * questions with lettered parts and part marks in square brackets where the
 * papers use them ('Hence', 'Show that', 'You must show detailed reasoning'),
 * modelling contexts with 'state a limitation' parts in pure topics, and
 * statistics and mechanics always set in context with hypothesis tests written
 * in full. Multiple-choice items are not in this bank.
 *
 * TARIFFS. Items run from 2 to 10 marks, most 3–6, as AQA questions do. Mix per
 * topic: 10% 2, 18% 3, 20% 4, 18% 5, 14% 6, 10% 7, 6% 8, 2% 9, 2% 10.
 *
 * MARK SCHEMES. AQA layout: one line per mark with M1 / A1 / B1 / E1 / R1 / dM1
 * codes, ft, CAO, AWRT, Condone and ISW where AQA uses them; codes sum to the
 * tariff.
 *
 * Data marked "written for this practice question" is invented but realistic and
 * every calculation has been checked.
 * Drawing canvas flag (diagram: true) enables the sketch area in practice.html.
 */

const MATHS_AQA_PRACTICE = {
  '1.1': {
    name: 'Proof',
    questions: [
      { q: `Sam makes the following claim.\n\n"For every positive integer \\(n\\), the number \\(3^n + 2\\) is prime."\n\nProve that Sam's claim is false.`, marks: 2, command: 'Prove', markScheme: `M1 Tests values of \\(n\\) and finds one giving a composite number, e.g. \\(n = 5\\): \\(3^5 + 2 = 245\\)\nE1 States \\(245 = 5 \\times 49\\) (or \\(5 \\times 7^2\\)) so 245 is not prime, therefore the claim is false\nCondone any valid counter-example (e.g. \\(n = 9\\): \\(19685 = 5 \\times 3937\\)). Values \\(n = 1, 2, 3, 4\\) give 5, 11, 29, 83, which are all prime, so do not credit these.\nGuidance: E1 requires a concluding statement that the claim is false.` },
      { q: `Disprove the statement\n\n"If \\(a\\) and \\(b\\) are both irrational, then \\(ab\\) is irrational."`, marks: 2, command: 'Disprove', markScheme: `M1 Chooses two irrational numbers whose product is rational, e.g. \\(a = \\sqrt{2}\\), \\(b = \\sqrt{2}\\), or \\(a = \\sqrt{2}\\), \\(b = \\sqrt{8}\\)\nE1 Shows the product is rational (\\(\\sqrt{2} \\times \\sqrt{2} = 2\\), or \\(\\sqrt{16} = 4\\)) and concludes the statement is false\nCAO for a fully correct counter-example with conclusion.` },
      { q: `A student writes\n\n"\\(\\sin(A + B) \\equiv \\sin A + \\sin B\\) for all angles \\(A\\) and \\(B\\)."\n\nShow that the student is wrong.`, marks: 2, command: 'Show that', markScheme: `M1 Substitutes specific values and evaluates both sides, e.g. \\(A = B = 90°\\): LHS \\(= \\sin 180° = 0\\), RHS \\(= 1 + 1 = 2\\)\nE1 States \\(0 \\neq 2\\) so the identity does not hold, hence the student is wrong\nAny correct counter-example is acceptable (e.g. \\(A = B = 30°\\): \\(\\frac{\\sqrt{3}}{2} \\neq 1\\)).` },
      { q: `Prove that the difference between the squares of any two consecutive integers is always odd.`, marks: 2, command: 'Prove', markScheme: `M1 Uses \\(n\\) and \\(n + 1\\) and forms \\((n + 1)^2 - n^2 = 2n + 1\\)\nE1 States that \\(2n\\) is even so \\(2n + 1\\) is odd, hence the difference is always odd\nDo not award E1 for numerical examples only.` },
      { q: `Prove that the product of any two odd numbers is odd.`, marks: 3, command: 'Prove', markScheme: `B1 Represents two (general, not necessarily equal) odd numbers as \\(2m + 1\\) and \\(2n + 1\\), where \\(m\\) and \\(n\\) are integers\nM1 Expands: \\((2m + 1)(2n + 1) = 4mn + 2m + 2n + 1 = 2(2mn + m + n) + 1\\)\nE1 States that \\(2mn + m + n\\) is an integer, so the product is one more than an even number and is therefore odd\nB0 if the same letter is used for both numbers (e.g. \\(2n + 1\\) and \\(2n + 3\\)) unless the proof is restricted to consecutive odd numbers; that only proves a special case.` },
      { q: `Prove by exhaustion that there are no prime numbers between 90 and 96.`, marks: 3, command: 'Prove', markScheme: `M1 Considers each of 91, 92, 93, 94 and 95\nA1 Shows each has a factor other than 1 and itself: \\(91 = 7 \\times 13\\), \\(92 = 2 \\times 46\\), \\(93 = 3 \\times 31\\), \\(94 = 2 \\times 47\\), \\(95 = 5 \\times 19\\)\nE1 Concludes that none of these numbers is prime, so there are no primes between 90 and 96\nCondone "92 and 94 are even" in place of factorisations.` },
      { q: `Priya claims that\n\n"whenever \\(p\\) is a prime number, \\(2^p - 1\\) is also a prime number."\n\nShe checks \\(p = 2, 3, 5\\) and \\(7\\) and finds that \\(3, 7, 31\\) and \\(127\\) are all prime.\n\nBy considering \\(p = 11\\), prove that Priya's claim is false.`, marks: 3, command: 'Prove', markScheme: `M1 Evaluates \\(2^{11} - 1 = 2047\\)\nA1 Finds a factorisation, \\(2047 = 23 \\times 89\\)\nE1 States that 11 is prime but 2047 is not prime, so the claim is false\nA0 for an unsupported statement that 2047 is not prime.` },
      { q: `The daily running cost, \\(£C\\) thousand, of a machine that is used for \\(x\\) hours each day is modelled by\n\n\\(C = x^2 - 6x + 10\\)\n\nProve that the model always predicts a positive running cost.`, marks: 3, command: 'Prove', markScheme: `M1 Completes the square: \\(x^2 - 6x + 10 = (x - 3)^2 + 1\\)\nA1 Correct completed square form\nE1 States \\((x - 3)^2 \\geq 0\\) for all \\(x\\), so \\(C \\geq 1 \\gt 0\\); hence the cost is always positive\nAlternative: M1 discriminant \\(36 - 40 = -4\\), A1 \\(-4 \\lt 0\\) so no real roots, E1 positive coefficient of \\(x^2\\) (curve above axis) so \\(C \\gt 0\\) for all \\(x\\).` },
      { q: `Prove that\n\n\\((\\sin \\theta + \\cos \\theta)^2 \\equiv 1 + \\sin 2\\theta\\)`, marks: 3, command: 'Prove', markScheme: `M1 Expands: \\(\\sin^2\\theta + 2\\sin\\theta\\cos\\theta + \\cos^2\\theta\\)\nM1 Uses \\(\\sin^2\\theta + \\cos^2\\theta \\equiv 1\\) or \\(2\\sin\\theta\\cos\\theta \\equiv \\sin 2\\theta\\)\nR1 Uses both correctly to reach \\(1 + \\sin 2\\theta\\), with a complete argument from one side to the other\nR0 if the working starts from the statement to be proved and manipulates both sides without a conclusion.` },
      { q: `A ball is thrown vertically upwards. Its height, \\(h\\) metres, above the ground \\(t\\) seconds after it is thrown is modelled by\n\n\\(h = 2 + 20t - 5t^2\\)\n\nProve that, according to the model, the ball never reaches a height of 25 metres.`, marks: 3, command: 'Prove', markScheme: `M1 Completes the square or differentiates to find the maximum: \\(h = 22 - 5(t - 2)^2\\), or \\(\\frac{dh}{dt} = 20 - 10t = 0 \\Rightarrow t = 2\\)\nA1 Maximum height is 22 m\nE1 States \\(22 \\lt 25\\) so the ball never reaches 25 m\nAlternative: M1 sets \\(5t^2 - 20t + 23 = 0\\); A1 discriminant \\(400 - 460 = -60\\); E1 negative so no real solutions, so height 25 m is never reached.` },
      { q: `Prove that, if \\(n\\) is an odd integer, then \\(n^2 + 3\\) is a multiple of 4.`, marks: 3, command: 'Prove', markScheme: `B1 Writes \\(n = 2k + 1\\) where \\(k\\) is an integer\nM1 Expands: \\((2k + 1)^2 + 3 = 4k^2 + 4k + 4\\)\nE1 Writes as \\(4(k^2 + k + 1)\\), where \\(k^2 + k + 1\\) is an integer, so \\(n^2 + 3\\) is a multiple of 4` },
      { q: `Prove that \\(n^3 - n\\) is divisible by 6 for all integers \\(n\\).`, marks: 4, command: 'Prove', markScheme: `M1 Factorises: \\(n^3 - n = n(n^2 - 1)\\)\nA1 \\(= (n - 1)n(n + 1)\\)\nE1 States this is the product of three consecutive integers, so at least one factor is even and exactly one factor is a multiple of 3\nE1 Concludes that the product is divisible by \\(2 \\times 3 = 6\\) (2 and 3 are coprime/prime), so \\(n^3 - n\\) is divisible by 6\nAlternative by exhaustion using \\(n = 6k, 6k + 1, \\ldots, 6k + 5\\): M1 sets up all six cases, A1 at least three correct, A1 all correct, E1 conclusion.` },
      { q: `Prove that every square number is either a multiple of 4 or one more than a multiple of 4.`, marks: 4, command: 'Prove', markScheme: `M1 Considers the two cases \\(n = 2k\\) (even) and \\(n = 2k + 1\\) (odd), where \\(k\\) is an integer\nA1 \\((2k)^2 = 4k^2\\), a multiple of 4\nA1 \\((2k + 1)^2 = 4k^2 + 4k + 1 = 4(k^2 + k) + 1\\), one more than a multiple of 4\nE1 States that every integer is either even or odd, so all square numbers are covered; hence the result is true\nGuidance: E1 requires reference to all integers being covered by the two cases.` },
      { q: `Prove by contradiction that the sum of a rational number and an irrational number is irrational.`, marks: 4, command: 'Prove', markScheme: `B1 Assumes that \\(\\frac{a}{b} + x = \\frac{c}{d}\\), where \\(x\\) is irrational, \\(a, b, c, d\\) are integers and \\(b, d \\neq 0\\)\nM1 Rearranges: \\(x = \\frac{c}{d} - \\frac{a}{b} = \\frac{bc - ad}{bd}\\)\nR1 States that \\(bc - ad\\) and \\(bd\\) are integers with \\(bd \\neq 0\\), so \\(x\\) is rational\nE1 This contradicts \\(x\\) being irrational, so the assumption is false and the sum is irrational\nGuidance: E1 requires the words "contradiction" (or equivalent) and a conclusion.` },
      { q: `Prove by contradiction that \\(\\log_2 3\\) is irrational.`, marks: 4, command: 'Prove', markScheme: `B1 Assumes \\(\\log_2 3 = \\frac{p}{q}\\) where \\(p\\) and \\(q\\) are positive integers (positive because \\(\\log_2 3 \\gt 0\\))\nM1 Converts to \\(2^{p/q} = 3\\) and hence \\(2^p = 3^q\\)\nR1 States that \\(2^p\\) is even (as \\(p \\geq 1\\)) and \\(3^q\\) is odd, so they cannot be equal\nE1 Contradiction, so \\(\\log_2 3\\) is irrational` },
      { q: `A small company models its weekly profit, \\(£P\\) thousand, when it employs \\(x\\) part-time staff, by\n\n\\(P = -2x^2 + 12x - 23\\)\n\n(a) Prove that the model predicts that the company makes a loss every week, whatever the value of \\(x\\). [3]\n\n(b) The company has made a profit in most weeks of the last year.\nState what this suggests about the model. [1]`, marks: 4, command: 'Prove', markScheme: `(a)\nM1 Attempts to complete the square: \\(-2(x^2 - 6x) - 23 = -2(x - 3)^2 + 18 - 23\\)\nA1 \\(P = -5 - 2(x - 3)^2\\)\nE1 Since \\(-2(x - 3)^2 \\leq 0\\), \\(P \\leq -5 \\lt 0\\) for all \\(x\\); so the model always predicts a loss\nAlternative: M1 \\(\\frac{dP}{dx} = 12 - 4x = 0\\), A1 maximum \\(P = -5\\) at \\(x = 3\\), E1 conclusion.\n(b)\nE1 The model is not suitable / not valid (it contradicts the real data) and needs refining, e.g. other factors such as sales or prices affect profit` },
      { q: `Prove that the product of four consecutive integers, plus 1, is always a square number.`, marks: 4, command: 'Prove', markScheme: `M1 Writes \\(n(n + 1)(n + 2)(n + 3) + 1\\) and pairs factors: \\(n(n + 3) = n^2 + 3n\\), \\((n + 1)(n + 2) = n^2 + 3n + 2\\)\nA1 \\((n^2 + 3n)(n^2 + 3n + 2) + 1\\), or full expansion \\(n^4 + 6n^3 + 11n^2 + 6n + 1\\)\nM1 Uses \\(m = n^2 + 3n\\) to get \\(m^2 + 2m + 1 = (m + 1)^2\\), or compares with \\((n^2 + an + b)^2\\)\nE1 Shows the expression is \\((n^2 + 3n + 1)^2\\), the square of an integer, so it is always a square number` },
      { q: `A student is asked to prove that \\(n^2 + 3n + 2\\) is even for every positive integer \\(n\\).\n\nThe student writes\n\n"When \\(n = 1\\), \\(n^2 + 3n + 2 = 6\\). When \\(n = 2\\) it is 12. When \\(n = 3\\) it is 20. These are all even, so \\(n^2 + 3n + 2\\) is always even."\n\n(a) Explain why the student's argument is not a valid proof. [1]\n\n(b) Prove that \\(n^2 + 3n + 2\\) is even for every positive integer \\(n\\). [3]`, marks: 4, command: 'Prove', markScheme: `(a)\nE1 Checking a few values does not prove the result for all (infinitely many) positive integers\n(b)\nM1 Factorises: \\(n^2 + 3n + 2 = (n + 1)(n + 2)\\)\nA1 Identifies \\(n + 1\\) and \\(n + 2\\) as consecutive integers, so one of them is even\nE1 The product of an even number and an integer is even, so \\(n^2 + 3n + 2\\) is always even\nAlternative for (b): M1 considers \\(n\\) even and \\(n\\) odd, A1 both cases correct, E1 conclusion.` },
      { q: `Prove that\n\n\\(\\frac{1 - \\cos 2\\theta}{\\sin 2\\theta} \\equiv \\tan \\theta\\)\n\nfor all values of \\(\\theta\\) for which the left-hand side is defined.`, marks: 4, command: 'Prove', markScheme: `M1 Uses \\(\\cos 2\\theta \\equiv 1 - 2\\sin^2\\theta\\) in the numerator\nM1 Uses \\(\\sin 2\\theta \\equiv 2\\sin\\theta\\cos\\theta\\) in the denominator\nA1 Obtains \\(\\frac{2\\sin^2\\theta}{2\\sin\\theta\\cos\\theta}\\)\nR1 Cancels \\(2\\sin\\theta\\) (non-zero since the LHS is defined) to reach \\(\\frac{\\sin\\theta}{\\cos\\theta} = \\tan\\theta\\), completing a clear argument from LHS to RHS\nCondone omission of the comment about \\(\\sin\\theta \\neq 0\\).` },
      { q: `Prove by contradiction that \\(\\sqrt{2}\\) is irrational.`, marks: 5, command: 'Prove', markScheme: `B1 Assumes \\(\\sqrt{2} = \\frac{a}{b}\\), where \\(a\\) and \\(b\\) are integers with no common factor (fraction in its simplest form), \\(b \\neq 0\\)\nM1 Squares and rearranges: \\(a^2 = 2b^2\\)\nA1 Deduces \\(a^2\\) is even, so \\(a\\) is even (since the square of an odd number is odd)\nM1 Substitutes \\(a = 2k\\): \\(4k^2 = 2b^2 \\Rightarrow b^2 = 2k^2\\), so \\(b\\) is even\nE1 Then \\(a\\) and \\(b\\) have a common factor of 2, which contradicts the assumption; hence \\(\\sqrt{2}\\) is irrational\nGuidance: E1 requires a clear statement of the contradiction and a conclusion.` },
      { q: `Prove by contradiction that there are no integers \\(a\\) and \\(b\\) such that\n\n\\(a^2 - 4b = 2\\)`, marks: 5, command: 'Prove', markScheme: `B1 Assumes there are integers \\(a\\) and \\(b\\) such that \\(a^2 - 4b = 2\\)\nM1 \\(a^2 = 4b + 2 = 2(2b + 1)\\) is even, so \\(a\\) is even\nA1 Writes \\(a = 2k\\), giving \\(4k^2 = 4b + 2\\)\nA1 Obtains \\(2k^2 - 2b = 1\\) (or \\(4(k^2 - b) = 2\\)); the left-hand side is even (or a multiple of 4) but the right-hand side is not\nE1 This is a contradiction, so no such integers \\(a\\) and \\(b\\) exist` },
      { q: `(a) Explain why every prime number greater than 3 can be written in the form \\(6k + 1\\) or \\(6k - 1\\), where \\(k\\) is a positive integer. [2]\n\n(b) Hence prove that, if \\(p\\) is a prime number greater than 3, then \\(p^2 - 1\\) is a multiple of 12. [3]`, marks: 5, command: 'Prove', markScheme: `(a)\nB1 Every integer can be written as one of \\(6k, 6k \\pm 1, 6k \\pm 2, 6k + 3\\)\nE1 \\(6k\\) and \\(6k \\pm 2\\) are even and \\(6k + 3 = 3(2k + 1)\\) is a multiple of 3, so a prime greater than 3 must be \\(6k \\pm 1\\)\n(b)\nM1 Expands \\((6k \\pm 1)^2 - 1\\)\nA1 \\(= 36k^2 \\pm 12k\\)\nE1 \\(= 12(3k^2 \\pm k)\\), where \\(3k^2 \\pm k\\) is an integer, so \\(p^2 - 1\\) is a multiple of 12\nGuidance: E1 in (b) requires both cases to be dealt with.` },
      { q: `A manufacturer models the average cost, \\(£A\\), of producing each item when \\(x\\) hundred items are made by\n\n\\(A = x + \\frac{9}{x}\\), \\(x \\gt 0\\)\n\n(a) Prove that, according to the model, the average cost is never less than £6. [4]\n\n(b) State the number of items that should be made to achieve an average cost of exactly £6. [1]`, marks: 5, command: 'Prove', markScheme: `(a)\nM1 Starts from \\((x - 3)^2 \\geq 0\\) (or considers \\(A - 6\\))\nA1 Expands: \\(x^2 - 6x + 9 \\geq 0\\), so \\(x^2 + 9 \\geq 6x\\)\nR1 Divides by \\(x\\), stating that \\(x \\gt 0\\) so the inequality is not reversed: \\(x + \\frac{9}{x} \\geq 6\\)\nE1 Hence \\(A \\geq 6\\): the average cost is never less than £6\nAlternative: \\(A - 6 = \\frac{(x - 3)^2}{x}\\) M1 A1, R1 numerator \\(\\geq 0\\) and \\(x \\gt 0\\), E1 conclusion. Calculus route: M1 \\(\\frac{dA}{dx} = 1 - \\frac{9}{x^2} = 0\\), A1 \\(x = 3\\), \\(A = 6\\), R1 shows it is a minimum (e.g. \\(\\frac{d^2A}{dx^2} = \\frac{18}{x^3} \\gt 0\\)) and the only stationary point for \\(x \\gt 0\\), E1 conclusion.\n(b)\nB1 \\(x = 3\\), i.e. 300 items` },
      { q: `Prove by exhaustion that no square number has a last digit of 2, 3, 7 or 8.`, marks: 5, command: 'Prove', markScheme: `R1 States that the last digit of \\(n^2\\) depends only on the last digit of \\(n\\) (e.g. \\(n = 10a + b\\) gives \\(n^2 = 100a^2 + 20ab + b^2\\))\nM1 Considers all ten possible last digits \\(b = 0, 1, \\ldots, 9\\)\nA1 At least five correct last digits of \\(b^2\\)\nA1 All correct: 0, 1, 4, 9, 6, 5, 6, 9, 4, 1\nE1 The last digit of a square is always 0, 1, 4, 5, 6 or 9, so never 2, 3, 7 or 8` },
      { q: `Prove by contradiction that there are no positive integers \\(x\\) and \\(y\\) such that\n\n\\(x^2 - y^2 = 1\\)`, marks: 5, command: 'Prove', markScheme: `B1 Assumes there exist positive integers \\(x\\) and \\(y\\) with \\(x^2 - y^2 = 1\\)\nM1 Factorises: \\((x - y)(x + y) = 1\\)\nA1 Since \\(x + y\\) is a positive integer, \\(x - y\\) is also a positive integer, so \\(x + y = 1\\) and \\(x - y = 1\\)\nA1 Solves to get \\(x = 1\\), \\(y = 0\\)\nE1 \\(y = 0\\) is not positive, which is a contradiction; hence no such positive integers exist\nAlternative: R1 \\(x + y \\geq 2\\) for positive integers so \\((x - y)(x + y) = 1\\) is impossible, with appropriate marks.` },
      { q: `Water is let into and out of a storage tank. The volume of water, \\(V\\) litres, in the tank \\(t\\) hours after midnight is modelled by\n\n\\(V = 2t^3 - 15t^2 + 36t + 50\\), \\(0 \\leq t \\leq 5\\)\n\nThe engineer claims that the volume of water in the tank is increasing throughout this period.\n\n(a) Prove that the engineer's claim is false. [3]\n\n(b) Prove that, according to the model, the volume of water never falls below 50 litres for \\(0 \\leq t \\leq 5\\). [2]`, marks: 5, command: 'Prove', markScheme: `(a)\nM1 Differentiates: \\(\\frac{dV}{dt} = 6t^2 - 30t + 36\\)\nA1 \\(= 6(t - 2)(t - 3)\\), or evaluates at a suitable value, e.g. \\(t = 2.5\\) gives \\(\\frac{dV}{dt} = -1.5\\)\nE1 \\(\\frac{dV}{dt} \\lt 0\\) for \\(2 \\lt t \\lt 3\\), so the volume is decreasing then; the claim is false\n(b)\nM1 Evaluates \\(V\\) at the end points and the local minimum: \\(V(0) = 50\\), \\(V(3) = 77\\), \\(V(5) = 105\\)\nE1 The least value is 50 litres (at \\(t = 0\\)), so \\(V \\geq 50\\) throughout\nCondone omission of \\(V(5)\\) if it is stated that \\(V\\) is increasing for \\(3 \\lt t \\leq 5\\).` },
      { q: `(a) Prove that the square of any odd integer is one more than a multiple of 8. [3]\n\n(b) Hence prove that the sum of the squares of two odd integers can never be a square number. [3]`, marks: 6, command: 'Prove', markScheme: `(a)\nM1 Writes \\((2k + 1)^2 = 4k^2 + 4k + 1 = 4k(k + 1) + 1\\)\nA1 States \\(k(k + 1)\\) is a product of consecutive integers, so it is even: \\(k(k + 1) = 2m\\)\nE1 Hence \\((2k + 1)^2 = 8m + 1\\), one more than a multiple of 8\n(b)\nM1 Uses (a): \\(a^2 + b^2 = (8m + 1) + (8n + 1) = 8(m + n) + 2\\)\nR1 This is even but leaves remainder 2 on division by 4 (it is \\(4(2m + 2n) + 2\\))\nE1 Any even square is \\((2c)^2 = 4c^2\\), a multiple of 4, and any odd square is odd; so \\(a^2 + b^2\\) cannot be a square number` },
      { q: `Prove by contradiction that \\(\\sqrt[3]{2}\\) is irrational.`, marks: 6, command: 'Prove', markScheme: `B1 Assumes \\(\\sqrt[3]{2} = \\frac{a}{b}\\), where \\(a\\) and \\(b\\) are integers with no common factor, \\(b \\neq 0\\)\nM1 Cubes: \\(a^3 = 2b^3\\)\nA1 \\(a^3\\) is even so \\(a\\) is even, with reason (if \\(a\\) were odd, \\(a^3\\) would be odd)\nM1 Substitutes \\(a = 2k\\): \\(8k^3 = 2b^3\\)\nA1 \\(b^3 = 4k^3\\), which is even, so \\(b\\) is even\nE1 \\(a\\) and \\(b\\) share the factor 2, contradicting the assumption; so \\(\\sqrt[3]{2}\\) is irrational` },
      { q: `(a) Prove that\n\n\\(\\cos 3\\theta \\equiv 4\\cos^3\\theta - 3\\cos\\theta\\) [4]\n\n(b) Hence show that \\(x = \\cos 20°\\) is a root of the equation\n\n\\(8x^3 - 6x - 1 = 0\\) [2]`, marks: 6, command: 'Prove', markScheme: `(a)\nM1 Writes \\(\\cos 3\\theta = \\cos(2\\theta + \\theta) = \\cos 2\\theta\\cos\\theta - \\sin 2\\theta\\sin\\theta\\)\nM1 Uses \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\) and \\(\\sin 2\\theta = 2\\sin\\theta\\cos\\theta\\)\nA1 Obtains \\(2\\cos^3\\theta - \\cos\\theta - 2\\sin^2\\theta\\cos\\theta\\)\nR1 Uses \\(\\sin^2\\theta = 1 - \\cos^2\\theta\\) to reach \\(4\\cos^3\\theta - 3\\cos\\theta\\) with a complete argument\n(b)\nM1 Uses \\(\\theta = 20°\\): \\(4\\cos^3 20° - 3\\cos 20° = \\cos 60° = \\frac{1}{2}\\)\nA1 Multiplies by 2 and rearranges to \\(8x^3 - 6x - 1 = 0\\) with \\(x = \\cos 20°\\), so it is a root` },
      { q: `(a) Prove by contradiction that, if \\(n^2\\) is a multiple of 3, then \\(n\\) is a multiple of 3. [3]\n\n(b) Hence prove by contradiction that \\(\\sqrt{3}\\) is irrational. [3]`, marks: 6, command: 'Prove', markScheme: `(a)\nB1 Assumes \\(n^2\\) is a multiple of 3 but \\(n\\) is not, so \\(n = 3k + 1\\) or \\(n = 3k + 2\\)\nM1 Squares: \\(9k^2 + 6k + 1 = 3(3k^2 + 2k) + 1\\) and \\(9k^2 + 12k + 4 = 3(3k^2 + 4k + 1) + 1\\)\nE1 Neither is a multiple of 3, which is a contradiction; so \\(n\\) is a multiple of 3\n(b)\nM1 Assumes \\(\\sqrt{3} = \\frac{a}{b}\\) in lowest terms and obtains \\(a^2 = 3b^2\\)\nA1 By (a), \\(a = 3k\\), so \\(9k^2 = 3b^2\\), \\(b^2 = 3k^2\\), and by (a) \\(b\\) is a multiple of 3\nE1 \\(a\\) and \\(b\\) have a common factor 3, contradicting lowest terms; hence \\(\\sqrt{3}\\) is irrational` },
      { q: `A farmer has 400 m of fencing to enclose a field.\n\n(a) The farmer first considers a rectangular field with sides \\(x\\) metres and \\(y\\) metres, using all of the fencing.\nProve that the area of the field cannot exceed \\(10\\,000\\) m². [3]\n\n(b) Prove that, for any rectangle with perimeter \\(P\\), the area is at most \\(\\frac{P^2}{16}\\). [2]\n\n(c) The farmer claims that no field enclosed by 400 m of fencing can have an area greater than \\(10\\,000\\) m².\nShow that the farmer's claim is false. [1]`, marks: 6, command: 'Prove', markScheme: `(a)\nM1 Uses \\(2x + 2y = 400\\) so area \\(= x(200 - x)\\)\nA1 Completes the square: \\(200x - x^2 = 10\\,000 - (x - 100)^2\\)\nE1 \\((x - 100)^2 \\geq 0\\), so area \\(\\leq 10\\,000\\) m²\n(b)\nM1 Area \\(= x\\left(\\frac{P}{2} - x\\right) = \\frac{P^2}{16} - \\left(x - \\frac{P}{4}\\right)^2\\)\nE1 Since the square term is \\(\\geq 0\\), area \\(\\leq \\frac{P^2}{16}\\)\n(c)\nB1 A circular field: radius \\(\\frac{200}{\\pi}\\), area \\(\\pi\\left(\\frac{200}{\\pi}\\right)^2 = \\frac{40\\,000}{\\pi} \\approx 12\\,700\\) m² \\(\\gt 10\\,000\\) m², so the claim is false\nAWRT 12 700 m². Any other valid shape with area greater than \\(10\\,000\\) m² (e.g. a regular hexagon, area AWRT 11 500 m²) is acceptable.` },
      { q: `Prove that \\(n^2 + n + 1\\) is not divisible by 5 for any integer \\(n\\).`, marks: 6, command: 'Prove', markScheme: `B1 States that every integer is of the form \\(5k, 5k + 1, 5k + 2, 5k + 3\\) or \\(5k + 4\\)\nM1 Substitutes at least one form and expands, e.g. \\((5k + 2)^2 + (5k + 2) + 1 = 25k^2 + 25k + 7\\)\nA1 \\(n = 5k\\): \\(5(5k^2 + k) + 1\\); \\(n = 5k + 1\\): \\(5(5k^2 + 3k) + 3\\)\nA1 \\(n = 5k + 2\\): \\(5(5k^2 + 5k + 1) + 2\\); \\(n = 5k + 3\\): \\(5(5k^2 + 7k + 2) + 3\\); \\(n = 5k + 4\\): \\(5(5k^2 + 9k + 4) + 1\\)\nR1 The remainders on division by 5 are 1, 3, 2, 3, 1, none of which is 0\nE1 Hence \\(n^2 + n + 1\\) is never divisible by 5` },
      { q: `Ayesha makes the following statement.\n\n"For all real numbers \\(x\\), if \\(x^2 \\gt 4\\) then \\(x \\gt 2\\)."\n\n(a) Prove that Ayesha's statement is false. [2]\n\n(b) Prove that, for all real numbers \\(x\\), if \\(x \\gt 2\\) then \\(x^3 - 4x \\gt 0\\). [3]\n\n(c) Write down the converse of the statement in (b), and determine whether the converse is true. Fully justify your answer. [2]`, marks: 7, command: 'Prove', markScheme: `(a)\nM1 Chooses a value of \\(x\\) with \\(x \\lt -2\\), e.g. \\(x = -3\\): \\(x^2 = 9 \\gt 4\\)\nE1 But \\(-3\\) is not greater than 2, so the statement is false\n(b)\nM1 Factorises: \\(x^3 - 4x = x(x - 2)(x + 2)\\)\nA1 For \\(x \\gt 2\\): \\(x \\gt 0\\), \\(x - 2 \\gt 0\\) and \\(x + 2 \\gt 0\\)\nE1 A product of three positive numbers is positive, so \\(x^3 - 4x \\gt 0\\)\n(c)\nB1 Converse: "if \\(x^3 - 4x \\gt 0\\) then \\(x \\gt 2\\)"\nB1 False, with counter-example, e.g. \\(x = -1\\): \\(-1 + 4 = 3 \\gt 0\\) but \\(-1\\) is not greater than 2` },
      { q: `(a) Prove that, for all positive real numbers \\(a\\) and \\(b\\),\n\n\\(\\frac{a + b}{2} \\geq \\sqrt{ab}\\) [3]\n\n(b) Prove that\n\n\\(\\tan\\theta + \\cot\\theta \\equiv 2\\,\\text{cosec}\\, 2\\theta\\) [2]\n\n(c) Hence prove that \\(\\tan\\theta + \\cot\\theta \\geq 2\\) for \\(0 \\lt \\theta \\lt \\frac{\\pi}{2}\\), stating the value of \\(\\theta\\) for which equality holds. [2]`, marks: 7, command: 'Prove', markScheme: `(a)\nM1 Starts from \\((\\sqrt{a} - \\sqrt{b})^2 \\geq 0\\)\nA1 Expands: \\(a - 2\\sqrt{ab} + b \\geq 0\\)\nE1 Rearranges to \\(\\frac{a + b}{2} \\geq \\sqrt{ab}\\), noting \\(\\sqrt{a}\\), \\(\\sqrt{b}\\) are real because \\(a, b \\gt 0\\)\n(b)\nM1 \\(\\frac{\\sin\\theta}{\\cos\\theta} + \\frac{\\cos\\theta}{\\sin\\theta} = \\frac{\\sin^2\\theta + \\cos^2\\theta}{\\sin\\theta\\cos\\theta} = \\frac{1}{\\sin\\theta\\cos\\theta}\\)\nR1 Uses \\(\\sin\\theta\\cos\\theta = \\frac{1}{2}\\sin 2\\theta\\) to reach \\(\\frac{2}{\\sin 2\\theta} = 2\\,\\text{cosec}\\, 2\\theta\\)\n(c)\nM1 For \\(0 \\lt \\theta \\lt \\frac{\\pi}{2}\\), \\(0 \\lt \\sin 2\\theta \\leq 1\\), so \\(2\\,\\text{cosec}\\, 2\\theta \\geq 2\\) (or uses (a) with \\(a = \\tan\\theta\\), \\(b = \\cot\\theta\\), \\(ab = 1\\))\nA1 Equality when \\(\\sin 2\\theta = 1\\), i.e. \\(\\theta = \\frac{\\pi}{4}\\)` },
      { q: `(a) Prove that the product of two rational numbers is rational. [2]\n\n(b) Prove by contradiction that, if \\(x\\) is irrational and \\(y\\) is a non-zero rational number, then \\(xy\\) is irrational. [3]\n\n(c) Given that \\(\\sqrt{2}\\) is irrational, hence prove that \\(\\sqrt{8}\\) is irrational. [2]`, marks: 7, command: 'Prove', markScheme: `(a)\nM1 Writes \\(\\frac{a}{b} \\times \\frac{c}{d} = \\frac{ac}{bd}\\), with \\(a, b, c, d\\) integers, \\(b, d \\neq 0\\)\nE1 \\(ac\\) and \\(bd\\) are integers, \\(bd \\neq 0\\), so the product is rational\n(b)\nB1 Assumes \\(xy = \\frac{p}{q}\\) is rational, with \\(y = \\frac{c}{d}\\), \\(c, d \\neq 0\\)\nM1 Rearranges: \\(x = \\frac{p}{q} \\times \\frac{d}{c} = \\frac{pd}{qc}\\)\nE1 This is rational (by (a), since \\(\\frac{d}{c}\\) is rational as \\(c \\neq 0\\)), contradicting \\(x\\) irrational; so \\(xy\\) is irrational\n(c)\nB1 \\(\\sqrt{8} = 2\\sqrt{2}\\)\nE1 2 is a non-zero rational and \\(\\sqrt{2}\\) is irrational, so by (b) \\(\\sqrt{8}\\) is irrational` },
      { q: `A road bridge has an arch above a river. A model for the arch, with the \\(x\\)-axis along the water level, is\n\n\\(y = 6 - \\frac{x^2}{6}\\), \\(y \\geq 0\\)\n\nwhere \\(x\\) and \\(y\\) are measured in metres.\nA straight support cable is modelled by the line \\(y = x + 8\\).\n\n(a) Prove that, according to the model, the cable does not meet the arch. [4]\n\n(b) Find the width of the arch at water level. [2]\n\n(c) State one limitation of the model. [1]`, marks: 7, command: 'Prove', markScheme: `(a)\nM1 Equates: \\(6 - \\frac{x^2}{6} = x + 8\\)\nA1 Obtains \\(x^2 + 6x + 12 = 0\\)\nM1 Finds the discriminant: \\(6^2 - 4 \\times 1 \\times 12\\)\nE1 \\(= -12 \\lt 0\\), so there are no real solutions and the cable does not meet the arch\nAlternative: M1 A1 as above, M1 completes the square \\((x + 3)^2 + 3\\), E1 always \\(\\geq 3\\) so never 0.\n(b)\nM1 Sets \\(y = 0\\): \\(x^2 = 36\\), \\(x = \\pm 6\\)\nA1 Width 12 m\n(c)\nE1 Valid limitation, e.g. a real cable sags (is not a straight line); the arch has thickness so is not a single curve; the water level changes` },
      { q: `(a) Prove by contradiction that there are infinitely many prime numbers. [5]\n\n(b) A student claims that\n\n"if \\(p_1, p_2, \\ldots, p_n\\) are the first \\(n\\) prime numbers, then \\(p_1 p_2 \\cdots p_n + 1\\) is always prime."\n\nBy considering the first six prime numbers, prove that the student's claim is false. [3]`, marks: 8, command: 'Prove', markScheme: `(a)\nB1 Assumes there are finitely many primes, \\(p_1, p_2, \\ldots, p_n\\) (a complete list)\nM1 Considers \\(N = p_1 p_2 \\cdots p_n + 1\\)\nA1 \\(N\\) leaves remainder 1 when divided by each \\(p_i\\), so none of \\(p_1, \\ldots, p_n\\) is a factor of \\(N\\)\nR1 \\(N\\) is greater than 1, so either \\(N\\) is prime or it has a prime factor; in either case there is a prime not in the list\nE1 This contradicts the list being complete, so there are infinitely many primes\nR0 for claiming that \\(N\\) itself must be prime.\n(b)\nM1 Evaluates \\(2 \\times 3 \\times 5 \\times 7 \\times 11 \\times 13 + 1 = 30\\,031\\)\nA1 \\(30\\,031 = 59 \\times 509\\)\nE1 30 031 is not prime, so the claim is false` },
      { q: `The function f is defined by\n\n\\(f(x) = x^3 + 3x^2 + 6x - 5\\), \\(x \\in \\mathbb{R}\\)\n\n(a) Prove that f is an increasing function. [3]\n\n(b) Hence prove that the equation \\(f(x) = 0\\) has exactly one real root. [3]\n\n(c) Show that this root lies between 0.6 and 0.7 [2]`, marks: 8, command: 'Prove', markScheme: `(a)\nM1 Differentiates: \\(f'(x) = 3x^2 + 6x + 6\\)\nA1 Completes the square: \\(3(x + 1)^2 + 3\\)\nE1 \\(3(x + 1)^2 \\geq 0\\), so \\(f'(x) \\geq 3 \\gt 0\\) for all \\(x\\); f is increasing\nAlternative to A1: discriminant \\(36 - 72 = -36 \\lt 0\\) with positive leading coefficient.\n(b)\nE1 As f is (strictly) increasing, the graph crosses the \\(x\\)-axis at most once\nM1 Finds a change of sign, e.g. \\(f(0) = -5 \\lt 0\\) and \\(f(1) = 5 \\gt 0\\)\nE1 f is continuous, so there is at least one root; hence exactly one real root\n(c)\nM1 \\(f(0.6) = -0.104\\) and \\(f(0.7) = 1.013\\)\nA1 Change of sign and f continuous, so the root lies between 0.6 and 0.7\nAWRT \\(-0.10\\) and \\(1.01\\).` },
      { q: `(a) Prove by exhaustion that the square of any integer leaves a remainder of 0 or 1 when divided by 3. [3]\n\n(b) Hence prove that, if \\(a^2 + b^2\\) is a multiple of 3, then both \\(a\\) and \\(b\\) are multiples of 3. [3]\n\n(c) Prove by contradiction that there are no positive integers \\(a\\), \\(b\\) and \\(c\\) such that\n\n\\(a^2 + b^2 = 3c^2\\)\n\nYou may assume that, if such integers existed, they could be chosen to have no common factor greater than 1. [3]`, marks: 9, command: 'Prove', markScheme: `(a)\nM1 Considers \\(n = 3k\\), \\(3k + 1\\), \\(3k + 2\\)\nA1 \\(9k^2 = 3(3k^2)\\); \\(9k^2 + 6k + 1 = 3(3k^2 + 2k) + 1\\); \\(9k^2 + 12k + 4 = 3(3k^2 + 4k + 1) + 1\\)\nE1 Remainders 0, 1, 1, and these three forms cover all integers, so the remainder is always 0 or 1\n(b)\nM1 The possible remainders of \\(a^2 + b^2\\) on division by 3 are \\(0 + 0 = 0\\), \\(0 + 1 = 1\\), \\(1 + 1 = 2\\)\nA1 Remainder 0 only when both \\(a^2\\) and \\(b^2\\) have remainder 0\nE1 From (a), \\(n^2\\) has remainder 0 only when \\(n = 3k\\), so \\(a\\) and \\(b\\) are both multiples of 3\n(c)\nM1 Assumes such \\(a, b, c\\) exist with no common factor; \\(a^2 + b^2 = 3c^2\\) is a multiple of 3, so by (b) \\(a = 3p\\), \\(b = 3q\\)\nA1 \\(9p^2 + 9q^2 = 3c^2 \\Rightarrow c^2 = 3(p^2 + q^2)\\), so \\(c^2\\) and hence \\(c\\) is a multiple of 3 (by (a))\nE1 Then 3 is a common factor of \\(a\\), \\(b\\) and \\(c\\): a contradiction, so no such positive integers exist` },
      { q: `A student investigates the expression\n\n\\(f(n) = n^2 - n + 41\\)\n\nwhere \\(n\\) is an integer.\n\n(a) Show that \\(f(1 - n) = f(n)\\) for all integers \\(n\\). [2]\n\n(b) Prove that \\(f(n)\\) is odd for all integers \\(n\\). [2]\n\n(c) Prove that \\(f(n)\\) is never divisible by 3 or by 5. [4]\n\n(d) The student notices that \\(f(n)\\) is prime for \\(n = 1, 2, 3, \\ldots, 10\\) and claims that \\(f(n)\\) is prime for every positive integer \\(n\\).\nProve that the student's claim is false. [2]`, marks: 10, command: 'Prove', markScheme: `(a)\nM1 Substitutes: \\((1 - n)^2 - (1 - n) + 41 = 1 - 2n + n^2 - 1 + n + 41\\)\nA1 \\(= n^2 - n + 41 = f(n)\\)\n(b)\nM1 \\(n^2 - n = n(n - 1)\\), a product of consecutive integers, so even\nE1 Even + 41 (odd) is odd, so \\(f(n)\\) is odd\n(c)\nM1 Considers \\(n = 3k, 3k + 1, 3k + 2\\): remainders of \\(f(n)\\) on division by 3 are 2, 2, 1\nA1 None is 0, so \\(f(n)\\) is never divisible by 3\nM1 Considers \\(n = 5k, 5k + 1, \\ldots, 5k + 4\\): remainders on division by 5 are 1, 1, 3, 2, 3\nA1 None is 0, so \\(f(n)\\) is never divisible by 5\nFor each M1, at least one case must be expanded algebraically, e.g. \\(f(3k + 2) = 9k^2 + 9k + 43 = 3(3k^2 + 3k + 14) + 1\\).\n(d)\nM1 Chooses \\(n = 41\\): \\(f(41) = 41^2 = 1681\\) (or \\(n = 42\\): \\(1763 = 41 \\times 43\\))\nE1 1681 \\(= 41 \\times 41\\) is not prime, so the claim is false` }
    ]
  },
  '1.2': {
    name: 'Algebra & Functions',
    questions: [
      { q: `A van hire company models the cost, £\\(C\\), of hiring a van for \\(d\\) days by\n\\(C = 45 + 30d\\)\n(data written for this practice question)\n\n(a) State the meaning of the number 45 in this model. [1]\n(b) The company only hires vans for a whole number of days, up to a maximum of 14 days. State a suitable domain for \\(d\\). [1]`, marks: 2, command: 'State', markScheme: `(a) B1: A fixed charge of £45 that is paid however many days the van is hired (e.g. booking fee / insurance). Condone "the cost for 0 days".\n(b) B1: \\(d \\in \\{1, 2, 3, \\ldots, 14\\}\\) or "\\(d\\) is an integer with \\(1 \\leq d \\leq 14\\)". Must indicate integer values.` },
      { q: `Express \\(4^{x} \\times 8^{2-x}\\) in the form \\(2^{ax+b}\\), where \\(a\\) and \\(b\\) are integers.`, marks: 2, command: 'Express', markScheme: `M1: Writes \\(4^{x} = 2^{2x}\\) or \\(8^{2-x} = 2^{3(2-x)}\\)\nA1: \\(2^{6-x}\\) (i.e. \\(a = -1\\), \\(b = 6\\)) CAO` },
      { q: `The graph of \\(y = f(x)\\) is transformed onto the graph of \\(y = f(x+3) - 2\\).\n\nDescribe fully the single transformation.`, marks: 2, command: 'Describe', markScheme: `B1: Translation\nB1: by vector \\(\\begin{pmatrix} -3 \\\\ -2 \\end{pmatrix}\\) (condone "3 left and 2 down" for this mark)\nAnswer: translation by \\(\\begin{pmatrix} -3 \\\\ -2 \\end{pmatrix}\\). A combination of two transformations scores B0 B1 at most.` },
      { q: `The function f is defined by\n\\(f(x) = (x-2)^2 + 5, \\quad x \\geq 2\\)\n\nFind \\(f^{-1}(x)\\), stating its domain.`, marks: 2, command: 'Find', markScheme: `M1: Sets \\(y = (x-2)^2 + 5\\) and rearranges to \\(x = 2 \\pm \\sqrt{y-5}\\) (or swaps \\(x\\) and \\(y\\) first)\nA1: \\(f^{-1}(x) = 2 + \\sqrt{x-5}\\), \\(x \\geq 5\\). Must reject the negative root and state the domain. CAO` },
      { q: `Do not use a calculator in this question.\n\nExpress \\(\\dfrac{5+\\sqrt{3}}{2-\\sqrt{3}}\\) in the form \\(a + b\\sqrt{3}\\), where \\(a\\) and \\(b\\) are integers.\n\nYou must show every step of your working.`, marks: 3, command: 'Express', markScheme: `M1: Multiplies numerator and denominator by \\(2+\\sqrt{3}\\)\nA1: Denominator \\(= 4 - 3 = 1\\), or numerator expanded correctly to \\(10 + 5\\sqrt{3} + 2\\sqrt{3} + 3\\)\nA1: \\(13 + 7\\sqrt{3}\\) CAO\nAnswer from a calculator with no working scores 0.` },
      { q: `Find the set of values of \\(x\\) for which\n\\(2x^2 + x - 15 \\gt 0\\)\n\nGive your answer in set notation.`, marks: 3, command: 'Find', markScheme: `M1: Factorises to \\((2x-5)(x+3)\\) or finds critical values by formula\nA1: Critical values \\(x = \\frac{5}{2}\\) and \\(x = -3\\)\nA1: \\(\\{x : x \\lt -3\\} \\cup \\{x : x \\gt \\frac{5}{2}\\}\\) CAO in set notation. Condone \\(\\{x : x \\lt -3 \\text{ or } x \\gt 2.5\\}\\). \\(x \\lt -3\\) or \\(x \\gt 2.5\\) not in set notation scores A0.` },
      { q: `Solve the equation\n\\(|2x - 3| = x + 4\\)`, marks: 3, command: 'Solve', markScheme: `M1: Forms either \\(2x - 3 = x + 4\\) or \\(-(2x-3) = x + 4\\) (or squares both sides: \\(3x^2 - 20x - 7 = 0\\))\nA1: \\(x = 7\\)\nA1: \\(x = -\\frac{1}{3}\\)\nBoth solutions are valid since \\(x + 4 \\gt 0\\) in each case; no extra solutions to be given (A0 if extra values not rejected).` },
      { q: `A taxi firm models the fare, £\\(F\\), for a journey of \\(d\\) miles by\n\\(F = f(d) = 2.5 + 1.6d\\)\nDuring a promotion, the price paid is given by \\(g(F) = 0.8F\\).\n(data written for this practice question)\n\n(a) Find an expression for \\(gf(d)\\). [1]\n(b) A customer pays £14.80 during the promotion. Find the length of the journey. [2]`, marks: 3, command: 'Find', markScheme: `(a) B1: \\(gf(d) = 0.8(2.5 + 1.6d) = 2 + 1.28d\\) (either form)\n(b) M1: Sets \\(2 + 1.28d = 14.80\\) ft their (a)\nA1: \\(d = 10\\) miles CAO` },
      { q: `A company models its weekly profit, £\\(P\\) thousand, when it sells an item at £\\(x\\), by\n\\(P = -2x^2 + 28x - 66\\)\n(data written for this practice question)\n\n(a) Express \\(P\\) in the form \\(a(x-b)^2 + c\\). [2]\n(b) Hence state the maximum weekly profit predicted by the model and the price at which it occurs. [1]`, marks: 3, command: 'Express', markScheme: `(a) M1: \\(-2[(x-7)^2 - 49] - 66\\) or compares coefficients to find \\(b = 7\\)\nA1: \\(P = -2(x-7)^2 + 32\\) CAO\n(b) B1ft: Maximum profit £32 000 when the price is £7. Must include units/context.` },
      { q: `The equation \\(kx^2 + 4x + (k-3) = 0\\), where \\(k\\) is a non-zero constant, has equal roots.\n\nFind the possible values of \\(k\\).`, marks: 3, command: 'Find', markScheme: `M1: Uses \\(b^2 - 4ac = 0\\): \\(16 - 4k(k-3) = 0\\)\nA1: Correct quadratic \\(k^2 - 3k - 4 = 0\\) (or equivalent)\nA1: \\(k = 4\\) or \\(k = -1\\) CAO` },
      { q: `Express \\(2x^3 - 3x^2 + 4x - 7\\) in the form\n\\((x-2)(ax^2 + bx + c) + d\\)\nwhere \\(a\\), \\(b\\), \\(c\\) and \\(d\\) are integers.`, marks: 3, command: 'Express', markScheme: `M1: Algebraic division by \\((x-2)\\) or comparison of coefficients, reaching \\(2x^2 + x + \\ldots\\)\nA1: Quotient \\(2x^2 + x + 6\\)\nB1: \\(d = 5\\) (may come from the remainder theorem, \\(f(2) = 16 - 12 + 8 - 7 = 5\\))\nAnswer: \\((x-2)(2x^2 + x + 6) + 5\\)` },
      { q: `A rectangular garden has a perimeter of 34 m. The diagonal of the garden is 13 m.\n\nBy forming and solving a pair of simultaneous equations, find the length and width of the garden.`, marks: 4, command: 'Find', markScheme: `B1: Forms \\(x + y = 17\\) and \\(x^2 + y^2 = 169\\)\nM1: Substitutes \\(y = 17 - x\\) to obtain a quadratic in one variable\nA1: \\(x^2 - 17x + 60 = 0\\) (or equivalent), giving \\(x = 5\\) or \\(x = 12\\)\nA1: The garden is 12 m by 5 m CAO. Must be in context.` },
      { q: `Express \\(\\dfrac{3x^2 - x + 4}{(x+1)(x-1)^2}\\) in partial fractions.`, marks: 4, command: 'Express', markScheme: `B1: Correct form \\(\\dfrac{A}{x+1} + \\dfrac{B}{x-1} + \\dfrac{C}{(x-1)^2}\\)\nM1: \\(3x^2 - x + 4 \\equiv A(x-1)^2 + B(x+1)(x-1) + C(x+1)\\) and substitutes a value or compares coefficients\nA1: Two of \\(A = 2\\), \\(B = 1\\), \\(C = 3\\)\nA1: All three correct\nAnswer: \\(\\dfrac{2}{x+1} + \\dfrac{1}{x-1} + \\dfrac{3}{(x-1)^2}\\)` },
      { q: `An engineer models a straight road by the line \\(y = kx - 2\\) and the edge of a lake by the curve \\(y = x^2 + x + 2\\), where \\(k\\) is a constant.\n(data written for this practice question)\n\nThe road must not meet the edge of the lake.\n\nFind the set of possible values of \\(k\\). Give your answer in set notation.`, marks: 4, command: 'Find', markScheme: `M1: Equates and rearranges: \\(x^2 + (1-k)x + 4 = 0\\)\nM1: Uses \\(b^2 - 4ac \\lt 0\\): \\((1-k)^2 - 16 \\lt 0\\)\nA1: Critical values \\(k = -3\\) and \\(k = 5\\)\nA1: \\(\\{k : -3 \\lt k \\lt 5\\}\\) CAO in set notation` },
      { q: `The function f is defined by\n\\(f(x) = 3 + \\dfrac{2}{x-1}, \\quad x \\gt 1\\)\n\n(a) State the range of f. [1]\n(b) Find \\(f^{-1}(x)\\), stating its domain. [3]`, marks: 4, command: 'Find', markScheme: `(a) B1: \\(f(x) \\gt 3\\)\n(b) M1: Sets \\(y = 3 + \\frac{2}{x-1}\\) and makes \\(x\\) the subject: \\(x - 1 = \\frac{2}{y-3}\\)\nA1: \\(f^{-1}(x) = 1 + \\dfrac{2}{x-3}\\) (or \\(\\dfrac{x-1}{x-3}\\))\nB1ft: Domain \\(x \\gt 3\\), ft their range in (a)` },
      { q: `(a) Sketch the graph of \\(y = |3x - 6|\\), stating the coordinates of any points where the graph meets the coordinate axes. [2]\n(b) Hence, or otherwise, solve the inequality \\(|3x - 6| \\gt x\\). [2]`, marks: 4, command: 'Sketch', diagram: true, markScheme: `(a) B1: V-shaped graph with vertex on the \\(x\\)-axis, entirely on or above the \\(x\\)-axis\nB1: Vertex at \\((2, 0)\\) and \\(y\\)-intercept \\((0, 6)\\)\n(b) M1: Finds critical values from \\(3x - 6 = x\\) and \\(-(3x - 6) = x\\): \\(x = 3\\), \\(x = \\frac{3}{2}\\)\nA1: \\(x \\lt \\frac{3}{2}\\) or \\(x \\gt 3\\) CAO` },
      { q: `The depth of water, \\(d\\) metres, at a harbour \\(t\\) hours after midnight on one day is modelled by \\(d = f(t)\\). The model predicts a maximum depth of 5 m at \\(t = 2\\).\n(data written for this practice question)\n\n(a) The next day, the depth is modelled by \\(d = f(t-1) + 0.5\\). State the maximum depth predicted for that day and the time at which it occurs. [2]\n(b) At a second harbour, the depth is modelled by \\(d = 1.2f(t)\\). Write down the coordinates of the maximum point of this graph and interpret the transformation in context. [2]`, marks: 4, command: 'State', markScheme: `(a) B1: Maximum depth 5.5 m\nB1: at \\(t = 3\\), i.e. 3 am\n(b) B1: \\((2, 6)\\)\nE1: Every depth at the second harbour is 1.2 times (20% more than) the depth at the first harbour at the same time; high tide is at the same time.` },
      { q: `Do not use a calculator in this question.\n\nSolve the equation\n\\(3x^{\\frac{2}{3}} - 10x^{\\frac{1}{3}} + 3 = 0\\)`, marks: 4, command: 'Solve', markScheme: `M1: Recognises a quadratic in \\(x^{\\frac{1}{3}}\\), e.g. lets \\(u = x^{\\frac{1}{3}}\\): \\(3u^2 - 10u + 3 = 0\\)\nA1: \\((3u - 1)(u - 3) = 0\\), so \\(u = \\frac{1}{3}\\) or \\(u = 3\\)\nM1: Cubes their values of \\(u\\)\nA1: \\(x = \\frac{1}{27}\\) or \\(x = 27\\) CAO` },
      { q: `The region R is bounded by the curve \\(y = 4 - x^2\\) and the line \\(y = x + 2\\). R lies above the line and below the curve.\n\n(a) Find the coordinates of the points where the line meets the curve. [2]\n(b) Write down the inequalities that define R. [2]`, marks: 4, command: 'Find', markScheme: `(a) M1: \\(4 - x^2 = x + 2 \\Rightarrow x^2 + x - 2 = 0\\)\nA1: \\((-2, 0)\\) and \\((1, 3)\\)\n(b) B1: \\(y \\geq x + 2\\) (condone strict inequality throughout)\nB1: \\(y \\leq 4 - x^2\\)\nCondone \\(x + 2 \\leq y \\leq 4 - x^2\\). Inequalities for \\(x\\) alone (\\(-2 \\leq x \\leq 1\\)) are not needed but are not penalised.` },
      { q: `(a) Write \\(9^x\\) in terms of \\(y\\), where \\(y = 3^x\\). [1]\n(b) Hence solve the equation\n\\(3^{2x+1} - 28(3^x) + 9 = 0\\) [4]`, marks: 5, command: 'Solve', markScheme: `(a) B1: \\(9^x = y^2\\)\n(b) M1: Writes \\(3^{2x+1} = 3y^2\\) to form \\(3y^2 - 28y + 9 = 0\\)\nA1: \\((3y - 1)(y - 9) = 0\\), so \\(y = \\frac{1}{3}\\) or \\(y = 9\\)\nM1: Solves \\(3^x = \\) their value(s)\nA1: \\(x = -1\\) or \\(x = 2\\) CAO` },
      { q: `The arch of a footbridge is modelled by the curve\n\\(y = kx(20 - x), \\quad 0 \\leq x \\leq 20\\)\nwhere \\(x\\) metres is the horizontal distance from one end of the arch and \\(y\\) metres is the height of the arch above the road. The arch is 20 m wide at road level and its maximum height is 8 m.\n(data written for this practice question)\n\n(a) Show that \\(k = 0.08\\). [2]\n(b) A lorry is 4 m wide and 7.5 m high. It drives along the road through the centre of the arch. Determine whether the lorry can pass under the arch. Fully justify your answer. [2]\n(c) State one limitation of the model. [1]`, marks: 5, command: 'Determine', markScheme: `(a) M1: Uses the symmetry, maximum at \\(x = 10\\): \\(k \\times 10 \\times 10 = 8\\)\nA1: \\(k = 0.08\\) AG, convincingly shown\n(b) M1: Finds height at the edge of the lorry, \\(x = 8\\) (or \\(x = 12\\)): \\(0.08 \\times 8 \\times 12\\)\nA1: \\(= 7.68\\) m, which is greater than 7.5 m, so the lorry can pass (just) under the arch. Must have conclusion.\n(c) E1: e.g. the arch has thickness / the road may not be level / the real arch may not be an exact parabola / the lorry may not be exactly central or may have a rounded roof.` },
      { q: `A drug is given to a patient. The concentration, \\(C\\) mg per litre, of the drug in the blood \\(t\\) hours later is modelled by\n\\(C = \\dfrac{20t}{t^2 + 4}, \\quad t \\geq 0\\)\n(data written for this practice question)\n\n(a) Show that, if \\(C = k\\), then \\(kt^2 - 20t + 4k = 0\\). [1]\n(b) Hence find the maximum concentration predicted by the model, and the time at which it occurs. [3]\n(c) State one limitation of the model. [1]`, marks: 5, command: 'Find', markScheme: `(a) B1: \\(k(t^2 + 4) = 20t \\Rightarrow kt^2 - 20t + 4k = 0\\) AG\n(b) M1: For real \\(t\\), uses \\(b^2 - 4ac \\geq 0\\): \\(400 - 16k^2 \\geq 0\\)\nA1: \\(k \\leq 5\\), so the maximum concentration is 5 mg per litre\nA1: When \\(k = 5\\): \\(5t^2 - 20t + 20 = 0 \\Rightarrow (t - 2)^2 = 0\\), \\(t = 2\\) hours\n(c) E1: e.g. the model takes no account of further doses / the patient's body mass or metabolism; the concentration never actually reaches zero in the model.` },
      { q: `The equation \\(x^2 + kx + (k - 2) = 0\\), where \\(k\\) is a real constant, is given.\n\n(a) Prove that the equation has two distinct real roots for all values of \\(k\\). [3]\n(b) Given that one root of the equation is \\(x = 1\\), find the value of \\(k\\) and the other root. [2]`, marks: 5, command: 'Prove', markScheme: `(a) M1: Discriminant \\(k^2 - 4(k - 2) = k^2 - 4k + 8\\)\nM1: Completes the square: \\((k - 2)^2 + 4\\)\nA1: Since \\((k-2)^2 \\geq 0\\), the discriminant \\(\\geq 4 \\gt 0\\), so two distinct real roots for all \\(k\\). Must have conclusion.\n(b) B1: \\(1 + k + k - 2 = 0 \\Rightarrow k = \\frac{1}{2}\\)\nB1: Other root \\(x = -\\frac{3}{2}\\) (from \\(2x^2 + x - 3 = (2x + 3)(x - 1)\\) or product of roots)` },
      { q: `Find the set of values of \\(x\\) that satisfy both\n\\(2x + 1 \\lt 15\\)\nand\n\\(x^2 - 8x + 12 \\geq 0\\)\n\nGive your answer in set notation.`, marks: 5, command: 'Find', markScheme: `B1: \\(x \\lt 7\\)\nM1: Factorises \\((x - 2)(x - 6)\\) or finds critical values 2 and 6\nA1: \\(x \\leq 2\\) or \\(x \\geq 6\\)\nM1: Combines both inequalities correctly (e.g. on a number line)\nA1: \\(\\{x : x \\leq 2\\} \\cup \\{x : 6 \\leq x \\lt 7\\}\\) CAO in set notation` },
      { q: `The function f is defined by\n\\(f(x) = 4 - |2x - 1|, \\quad x \\in \\mathbb{R}\\)\n\n(a) Sketch the graph of \\(y = f(x)\\), stating the coordinates of the vertex and of the points where the graph meets the coordinate axes. [3]\n(b) Solve the equation \\(f(x) = x\\). [2]`, marks: 5, command: 'Sketch', diagram: true, markScheme: `(a) B1: Inverted V shape\nB1: Vertex at \\(\\left(\\frac{1}{2}, 4\\right)\\)\nB1: Intercepts \\((0, 3)\\), \\(\\left(-\\frac{3}{2}, 0\\right)\\) and \\(\\left(\\frac{5}{2}, 0\\right)\\)\n(b) M1: Solves \\(4 - (2x - 1) = x\\) or \\(4 + (2x - 1) = x\\)\nA1: \\(x = \\frac{5}{3}\\) and \\(x = -3\\) CAO` },
      { q: `(a) Express \\(\\dfrac{2x^2 + 4x + 3}{(x - 1)(x + 2)}\\) in the form \\(A + \\dfrac{B}{x - 1} + \\dfrac{C}{x + 2}\\), where \\(A\\), \\(B\\) and \\(C\\) are integers. [4]\n(b) Hence write down the equation of the horizontal asymptote of the curve \\(y = \\dfrac{2x^2 + 4x + 3}{(x - 1)(x + 2)}\\). [1]`, marks: 5, command: 'Express', markScheme: `(a) B1: \\(A = 2\\) (by division or comparing \\(x^2\\) coefficients)\nM1: \\(2x^2 + 4x + 3 \\equiv 2(x-1)(x+2) + B(x+2) + C(x-1)\\) and substitutes \\(x = 1\\) or \\(x = -2\\)\nA1: \\(B = 3\\)\nA1: \\(C = -1\\)\nAnswer: \\(2 + \\dfrac{3}{x - 1} - \\dfrac{1}{x + 2}\\)\n(b) B1ft: \\(y = 2\\)` },
      { q: `A ball is thrown upwards from a balcony. Its height, \\(h\\) metres, above the ground \\(t\\) seconds after it is thrown is modelled by\n\\(h = 2 + 8t - 5t^2\\)\n(data written for this practice question)\n\n(a) Express \\(h\\) in the form \\(a - b(t - c)^2\\). [2]\n(b) Hence state the maximum height of the ball. [1]\n(c) Find the time at which the ball hits the ground. Give your answer to 3 significant figures. [2]\n(d) State one limitation of the model. [1]`, marks: 6, command: 'Express', markScheme: `(a) M1: \\(-5[(t - 0.8)^2 - 0.64] + 2\\)\nA1: \\(h = 5.2 - 5(t - 0.8)^2\\)\n(b) B1ft: 5.2 m\n(c) M1: Solves \\(5t^2 - 8t - 2 = 0\\) (or \\(5(t - 0.8)^2 = 5.2\\))\nA1: \\(t = 1.82\\) s AWRT; must reject the negative root \\(-0.220\\)\n(d) E1: e.g. ignores air resistance / ball treated as a particle / the ground may not be level / ball may hit the balcony or a wall.` },
      { q: `The function f is defined by\n\\(f(x) = x^2 - 4x + 7, \\quad x \\geq 2\\)\n\n(a) Find the range of f. [1]\n(b) Find \\(f^{-1}(x)\\) and state its domain. [3]\n(c) Show that the equation \\(f(x) = x\\) has no real solutions, and explain what this tells you about the graphs of \\(y = f(x)\\) and \\(y = f^{-1}(x)\\). [2]`, marks: 6, command: 'Show that', markScheme: `(a) B1: \\(f(x) \\geq 3\\) (from \\(f(x) = (x - 2)^2 + 3\\))\n(b) M1: \\(y = (x - 2)^2 + 3\\) and rearranges to \\(x = 2 \\pm \\sqrt{y - 3}\\)\nA1: \\(f^{-1}(x) = 2 + \\sqrt{x - 3}\\) (positive root only)\nB1ft: Domain \\(x \\geq 3\\)\n(c) M1: \\(x^2 - 5x + 7 = 0\\), discriminant \\(25 - 28 = -3 \\lt 0\\), so no real solutions\nE1: The graphs of \\(y = f(x)\\) and \\(y = f^{-1}(x)\\) are reflections in \\(y = x\\), and \\(y = f(x)\\) does not meet \\(y = x\\), so the two graphs do not intersect.` },
      { q: `A farmer uses 40 m of fencing to make a rectangular pen against a straight wall. The wall forms one side of the pen and the fencing forms the other three sides. The two sides perpendicular to the wall are each \\(x\\) metres long and the side parallel to the wall is \\(y\\) metres long. The area of the pen is 150 m².\n\n(a) Show that \\(x^2 - 20x + 75 = 0\\). [3]\n(b) Find the possible dimensions of the pen. [2]\n(c) The farmer wants the longest side of the pen to be no more than 20 m. State which dimensions the farmer should use. [1]`, marks: 6, command: 'Show that', markScheme: `(a) B1: \\(2x + y = 40\\)\nB1: \\(xy = 150\\)\nM1: Substitutes \\(y = 40 - 2x\\): \\(x(40 - 2x) = 150 \\Rightarrow 2x^2 - 40x + 150 = 0 \\Rightarrow x^2 - 20x + 75 = 0\\) AG\n(b) M1: \\((x - 5)(x - 15) = 0\\)\nA1: \\(x = 5\\), \\(y = 30\\) or \\(x = 15\\), \\(y = 10\\)\n(c) B1ft: 15 m by 10 m (the 5 m by 30 m pen has a side longer than 20 m)` },
      { q: `Sketch the graph of\n\\(y = \\dfrac{1}{x - 2} + 3\\)\nstating the equations of any asymptotes and the coordinates of any points where the graph meets the coordinate axes, and describe the transformations that map the graph of \\(y = \\dfrac{1}{x}\\) onto this graph.`, marks: 6, command: 'Sketch', diagram: true, markScheme: `B1: Translation by \\(\\begin{pmatrix} 2 \\\\ 3 \\end{pmatrix}\\) (or 2 right and 3 up) from \\(y = \\frac{1}{x}\\)\nB1: Correct shape: two branches of a reciprocal curve in the correct quadrants relative to the asymptotes\nB1: Vertical asymptote \\(x = 2\\)\nB1: Horizontal asymptote \\(y = 3\\)\nB1: \\(y\\)-intercept \\(\\left(0, \\frac{5}{2}\\right)\\)\nB1: \\(x\\)-intercept \\(\\left(\\frac{5}{3}, 0\\right)\\)` },
      { q: `The polynomial \\(p(x)\\) is given by\n\\(p(x) = x^3 + ax^2 + bx - 12\\)\nwhere \\(a\\) and \\(b\\) are constants.\n\n\\((x + 2)\\) is a factor of \\(p(x)\\). When \\(p(x)\\) is divided by \\((x - 1)\\), the remainder is 6.\n\nFind the exact roots of the equation \\(p(x) = 0\\).`, marks: 6, command: 'Find', markScheme: `M1: Uses \\(p(-2) = 0\\): \\(-8 + 4a - 2b - 12 = 0\\)\nM1: Uses \\(p(1) = 6\\): \\(1 + a + b - 12 = 6\\)\nA1: \\(a = 9\\), \\(b = 8\\)\nM1: Divides \\(x^3 + 9x^2 + 8x - 12\\) by \\((x + 2)\\) to obtain a quadratic factor\nA1: \\(x^2 + 7x - 6\\)\nA1: \\(x = -2\\), \\(x = \\dfrac{-7 \\pm \\sqrt{73}}{2}\\) CAO exact` },
      { q: `The fuel economy, \\(E\\) miles per gallon, of a car travelling at a constant speed of \\(v\\) mph is modelled by\n\\(E = -0.012v^2 + 1.2v + 10, \\quad 20 \\leq v \\leq 80\\)\n(data written for this practice question)\n\n(a) Express \\(E\\) in the form \\(p - q(v - r)^2\\). [2]\n(b) State the speed at which the car is most economical, according to the model. [1]\n(c) Find the range of speeds for which the fuel economy is at least 37 miles per gallon. [2]\n(d) Comment on the suitability of using the model for a speed of 110 mph. [1]`, marks: 6, command: 'Find', markScheme: `(a) M1: \\(-0.012[(v - 50)^2 - 2500] + 10\\)\nA1: \\(E = 40 - 0.012(v - 50)^2\\)\n(b) B1ft: 50 mph\n(c) M1: \\(0.012(v - 50)^2 \\leq 3 \\Rightarrow (v - 50)^2 \\leq 250\\)\nA1: \\(34.2 \\leq v \\leq 65.8\\) mph AWRT\n(d) E1: At 110 mph the model gives \\(E = -3.2\\), which is impossible, so the model is unsuitable (and 110 mph is outside the stated domain).` },
      { q: `The function f is defined by\n\\(f(x) = \\dfrac{3x + 1}{x - 2}, \\quad x \\in \\mathbb{R}, \\ x \\neq 2\\)\n\n(a) Find \\(f^{-1}(x)\\), stating its domain. [3]\n(b) Find \\(ff(x)\\), giving your answer as a single fraction in its simplest form. [2]\n(c) The function g is defined by \\(g(x) = x^2 + 3\\), \\(x \\in \\mathbb{R}\\). Find the range of \\(fg\\). [2]`, marks: 7, command: 'Find', markScheme: `(a) M1: \\(y(x - 2) = 3x + 1 \\Rightarrow x(y - 3) = 2y + 1\\)\nA1: \\(f^{-1}(x) = \\dfrac{2x + 1}{x - 3}\\)\nB1: Domain \\(x \\in \\mathbb{R}, x \\neq 3\\)\n(b) M1: \\(\\dfrac{3\\left(\\frac{3x+1}{x-2}\\right) + 1}{\\frac{3x+1}{x-2} - 2}\\) and multiplies through by \\((x - 2)\\)\nA1: \\(ff(x) = \\dfrac{10x + 1}{x + 5}\\)\n(c) M1: Range of g is \\(g(x) \\geq 3\\), and writes \\(f(x) = 3 + \\frac{7}{x-2}\\) or finds \\(f(3) = 10\\)\nA1: \\(3 \\lt fg(x) \\leq 10\\) CAO` },
      { q: `The curve C has equation \\(y = f(x)\\), where\n\\(f(x) = (x + 1)(x - 2)^2\\)\n\n(a) Sketch C, stating the coordinates of the points where C meets the coordinate axes. [3]\n(b) Write down the roots of the equation \\(f(x - 3) = 0\\). [1]\n(c) The curve C is translated by the vector \\(\\begin{pmatrix} -a \\\\ 0 \\end{pmatrix}\\) to give the curve \\(y = f(x + a)\\). The new curve passes through the origin. Find the possible values of \\(a\\). [2]\n(d) Find the \\(y\\)-coordinate of the point where the curve \\(y = 2f(-x)\\) meets the \\(y\\)-axis. [1]`, marks: 7, command: 'Sketch', diagram: true, markScheme: `(a) B1: Positive cubic shape\nB1: Crosses at \\((-1, 0)\\) and touches the \\(x\\)-axis at \\((2, 0)\\)\nB1: \\(y\\)-intercept \\((0, 4)\\)\n(b) B1: \\(x = 2\\) and \\(x = 5\\)\n(c) M1: \\(f(a) = 0\\), so \\(a\\) is a root of f\nA1: \\(a = -1\\) or \\(a = 2\\)\n(d) B1: \\(2f(0) = 8\\)` },
      { q: `(a) Find the coordinates of the points of intersection of the curve \\(y = x^2 - 4x\\) and the line \\(y = 2x - 5\\). [3]\n(b) On the same axes, sketch the curve and the line, and shade the region that satisfies both \\(y \\geq x^2 - 4x\\) and \\(y \\leq 2x - 5\\). [3]\n(c) Using your answer to (a), write down the set of values of \\(x\\) for which \\(x^2 - 4x \\leq 2x - 5\\), giving your answer in set notation. [1]`, marks: 7, command: 'Sketch', diagram: true, markScheme: `(a) M1: \\(x^2 - 4x = 2x - 5 \\Rightarrow x^2 - 6x + 5 = 0\\)\nA1: \\(x = 1\\), \\(x = 5\\)\nA1: \\((1, -3)\\) and \\((5, 5)\\)\n(b) B1: U-shaped parabola through \\((0, 0)\\) and \\((4, 0)\\)\nB1: Line with positive gradient crossing the curve at the points found in (a)\nB1: Correct region shaded: between the line (above) and curve (below) for \\(1 \\leq x \\leq 5\\)\n(c) B1ft: \\(\\{x : 1 \\leq x \\leq 5\\}\\)` },
      { q: `Do not use a calculator in this question.\n\nA right-angled triangle has shorter sides of length \\((2 + \\sqrt{3})\\) cm and \\((2 - \\sqrt{3})\\) cm.\n\n(a) Find the exact area of the triangle. [2]\n(b) Show that the length of the hypotenuse is \\(\\sqrt{14}\\) cm. [3]\n(c) Show that the ratio of the longer of the two shorter sides to the other shorter side can be written as \\(7 + 4\\sqrt{3}\\). [2]`, marks: 7, command: 'Show that', markScheme: `(a) M1: \\(\\frac{1}{2}(2 + \\sqrt{3})(2 - \\sqrt{3})\\) and expands, using \\(4 - 3\\)\nA1: \\(\\frac{1}{2}\\) cm² CAO\n(b) M1: Uses Pythagoras: \\((2 + \\sqrt{3})^2 + (2 - \\sqrt{3})^2\\)\nA1: Expands both correctly: \\(7 + 4\\sqrt{3}\\) and \\(7 - 4\\sqrt{3}\\)\nA1: Sum \\(= 14\\), so hypotenuse \\(= \\sqrt{14}\\) cm AG\n(c) M1: \\(\\dfrac{2 + \\sqrt{3}}{2 - \\sqrt{3}} \\times \\dfrac{2 + \\sqrt{3}}{2 + \\sqrt{3}}\\)\nA1: \\(= \\dfrac{7 + 4\\sqrt{3}}{1} = 7 + 4\\sqrt{3}\\) AG` },
      { q: `The function f is defined by \\(f(x) = x^2 - 4x\\), \\(x \\in \\mathbb{R}\\).\n\n(a) Express \\(f(x)\\) in the form \\((x - a)^2 + b\\) and state the coordinates of the vertex of \\(y = f(x)\\). [2]\n(b) Sketch the graph of \\(y = |f(x)|\\), stating the coordinates of the points where it meets the coordinate axes and of its local maximum point. [3]\n(c) Find the set of values of \\(k\\) for which the equation \\(|x^2 - 4x| = k\\) has exactly four real solutions. [1]\n(d) Solve the equation \\(|x^2 - 4x| = 3\\), giving your answers in exact form. [2]`, marks: 8, command: 'Sketch', diagram: true, markScheme: `(a) B1: \\((x - 2)^2 - 4\\)\nB1ft: Vertex \\((2, -4)\\)\n(b) B1: Shape: U-shaped outer parts with the section between the roots reflected above the \\(x\\)-axis (W shape), no part below the \\(x\\)-axis\nB1: Meets the axes at \\((0, 0)\\) and \\((4, 0)\\)\nB1ft: Local maximum at \\((2, 4)\\)\n(c) B1ft: \\(\\{k : 0 \\lt k \\lt 4\\}\\)\n(d) M1: Solves \\(x^2 - 4x = 3\\) or \\(x^2 - 4x = -3\\)\nA1: \\(x = 2 \\pm \\sqrt{7}\\), \\(x = 1\\), \\(x = 3\\) (all four) CAO` },
      { q: `The curve C has equation \\(x^2 + xy + y^2 = 12\\).\nThe line L has equation \\(y = x + k\\), where \\(k\\) is a constant.\n\n(a) Show that the \\(x\\)-coordinates of any points of intersection of C and L satisfy\n\\(3x^2 + 3kx + k^2 - 12 = 0\\) [2]\n(b) Find the set of values of \\(k\\) for which L meets C at two distinct points. Give your answer in exact form. [3]\n(c) In the case \\(k = 6\\), find the coordinates of the points of intersection of C and L. [3]`, marks: 8, command: 'Find', markScheme: `(a) M1: Substitutes \\(y = x + k\\): \\(x^2 + x(x + k) + (x + k)^2 = 12\\)\nA1: Expands to \\(3x^2 + 3kx + k^2 - 12 = 0\\) AG with no errors\n(b) M1: Uses \\(b^2 - 4ac \\gt 0\\): \\(9k^2 - 12(k^2 - 12) \\gt 0\\)\nA1: \\(k^2 \\lt 48\\)\nA1: \\(-4\\sqrt{3} \\lt k \\lt 4\\sqrt{3}\\) CAO (condone set notation or not)\n(c) M1: \\(3x^2 + 18x + 24 = 0 \\Rightarrow x^2 + 6x + 8 = 0\\)\nA1: \\(x = -2\\) or \\(x = -4\\)\nA1: \\((-2, 4)\\) and \\((-4, 2)\\)` },
      { q: `\\(p(x) = 2x^3 - 3x^2 - 11x + 6\\)\n\n(a) Use the factor theorem to show that \\((x - 3)\\) is a factor of \\(p(x)\\). [2]\n(b) Express \\(p(x)\\) as the product of three linear factors. [3]\n(c) Sketch the graph of \\(y = p(x)\\), stating the coordinates of the points where it meets the coordinate axes. [2]\n(d) Hence solve the inequality \\(p(x) \\leq 0\\), giving your answer in set notation. [2]`, marks: 9, command: 'Sketch', diagram: true, markScheme: `(a) M1: Evaluates \\(p(3) = 54 - 27 - 33 + 6\\)\nA1: \\(= 0\\), so \\((x - 3)\\) is a factor. Must have conclusion.\n(b) M1: Divides by \\((x - 3)\\) or compares coefficients to obtain a quadratic factor\nA1: \\(2x^2 + 3x - 2\\)\nA1: \\(p(x) = (x - 3)(2x - 1)(x + 2)\\)\n(c) B1: Positive cubic shape crossing the \\(x\\)-axis three times\nB1ft: \\((-2, 0)\\), \\(\\left(\\frac{1}{2}, 0\\right)\\), \\((3, 0)\\) and \\((0, 6)\\)\n(d) M1ft: Uses their sketch to identify regions below the \\(x\\)-axis\nA1: \\(\\{x : x \\leq -2\\} \\cup \\{x : \\frac{1}{2} \\leq x \\leq 3\\}\\) CAO` },
      { q: `An open box is made from a rectangular sheet of card measuring 30 cm by 20 cm. A square of side \\(x\\) cm is cut from each corner and the sides are folded up.\n\n(a) Show that the volume, \\(V\\) cm³, of the box is given by\n\\(V = 4x^3 - 100x^2 + 600x\\) [2]\n(b) State the set of values of \\(x\\) for which the model is valid. [1]\n(c) The volume of the box is 1008 cm³. Use the factor theorem to show that \\((x - 3)\\) is a factor of \\(4x^3 - 100x^2 + 600x - 1008\\). [2]\n(d) Hence find all the possible values of \\(x\\) for which the volume is 1008 cm³. Give non-integer answers to 3 significant figures and fully justify any values you reject. [4]\n(e) State one limitation of the model. [1]`, marks: 10, command: 'Find', markScheme: `(a) M1: \\(V = x(30 - 2x)(20 - 2x)\\)\nA1: Expands correctly to \\(4x^3 - 100x^2 + 600x\\) AG\n(b) B1: \\(0 \\lt x \\lt 10\\)\n(c) M1: Substitutes \\(x = 3\\): \\(108 - 900 + 1800 - 1008\\)\nA1: \\(= 0\\), so \\((x - 3)\\) is a factor\n(d) M1: Divides to obtain quadratic factor: \\(4(x - 3)(x^2 - 22x + 84)\\)\nA1: \\(x^2 - 22x + 84\\) correct\nA1: \\(x = 11 \\pm \\sqrt{37}\\): \\(x = 4.92\\) AWRT and \\(x = 17.1\\)\nR1: Rejects \\(x = 17.1\\) as it is not in \\(0 \\lt x \\lt 10\\) (the 20 cm side would be negative). Final answer \\(x = 3\\) or \\(x = 4.92\\)\n(e) E1: e.g. the thickness of the card is ignored / card may be wasted in folding / the corners cannot be cut exactly.` }
    ]
  },
  '1.3': {
    name: 'Coordinate Geometry',
    questions: [
      { q: `The line \\(L\\) has equation \\(3x - 5y + 15 = 0\\)\n\nFind the coordinates of the points where \\(L\\) crosses the coordinate axes.`, marks: 2, command: 'Find', markScheme: `B1: \\((-5, 0)\\)\nB1: \\((0, 3)\\)\nCondone coordinates given as \\(x = -5\\), \\(y = 3\\) if clearly identified with the correct axes.` },
      { q: `A circle has equation \\((x + 4)^2 + (y - 1)^2 = 18\\)\n\nWrite down the coordinates of its centre and find its radius, giving your answer in the form \\(a\\sqrt{2}\\)`, marks: 2, command: 'Find', markScheme: `B1: centre \\((-4, 1)\\)\nB1: radius \\(\\sqrt{18} = 3\\sqrt{2}\\) CAO` },
      { q: `A curve is defined by the parametric equations\n\\(x = 2t + 1\\), \\(y = t^2 - 3\\)\n\nFind a Cartesian equation of the curve in the form \\(y = f(x)\\)`, marks: 2, command: 'Find', markScheme: `M1: rearranges to \\(t = \\frac{x - 1}{2}\\) and substitutes into \\(y\\)\nA1: \\(y = \\frac{(x - 1)^2}{4} - 3\\) or equivalent, e.g. \\(y = \\frac{x^2 - 2x - 11}{4}\\). ISW` },
      { q: `A taxi company models the fare, \\(£C\\), for a journey of \\(d\\) miles by\n\\(C = 2.50 + 1.80d\\)\n\n(a) Interpret the value 1.80 in the context of the model. [1]\n(b) Interpret the value 2.50 in the context of the model. [1]`, marks: 2, command: 'Interpret', markScheme: `(a) E1: each additional mile adds £1.80 to the fare (cost per mile)\n(b) E1: £2.50 is a fixed/starting charge, the fare before any distance is travelled\nAccept equivalent wording; must refer to the context.` },
      { q: `The points \\(A\\) and \\(B\\) have coordinates \\((-2, 7)\\) and \\((4, -1)\\) respectively.\n\nFind an equation of the line \\(AB\\), giving your answer in the form \\(ax + by + c = 0\\), where \\(a\\), \\(b\\) and \\(c\\) are integers.`, marks: 3, command: 'Find', markScheme: `M1: gradient \\(\\frac{-1 - 7}{4 - (-2)} = -\\frac{4}{3}\\)\nM1: uses \\(y - 7 = -\\frac{4}{3}(x + 2)\\) or \\(y = mx + c\\) with their gradient and a correct point\nA1: \\(4x + 3y - 13 = 0\\) or any integer multiple. CAO for integer form` },
      { q: `Find an equation of the line which passes through the point \\((5, -3)\\) and is perpendicular to the line \\(2x - 3y = 7\\)\n\nGive your answer in the form \\(ax + by + c = 0\\), where \\(a\\), \\(b\\) and \\(c\\) are integers.`, marks: 3, command: 'Find', markScheme: `B1: gradient of given line is \\(\\frac{2}{3}\\)\nM1: uses perpendicular gradient \\(-\\frac{3}{2}\\) (negative reciprocal of their gradient) with \\((5, -3)\\)\nA1: \\(3x + 2y - 9 = 0\\) or any integer multiple` },
      { q: `The circle \\(C\\) has equation \\(x^2 + y^2 + 10x - 6y + 9 = 0\\)\n\nShow that \\(C\\) has radius 5 and state the coordinates of its centre.`, marks: 3, command: 'Show that', markScheme: `M1: completes the square for both \\(x\\) and \\(y\\): \\((x + 5)^2 - 25 + (y - 3)^2 - 9 + 9 = 0\\)\nA1: \\((x + 5)^2 + (y - 3)^2 = 25\\), hence radius \\(= 5\\) (AG, must see \\(25\\) or \\(r^2 = 25\\))\nB1: centre \\((-5, 3)\\)` },
      { q: `A curve has parametric equations\n\\(x = 3\\cos\\theta\\), \\(y = 2\\sin\\theta\\), \\(0 \\leq \\theta \\lt 2\\pi\\)\n\nShow that a Cartesian equation of the curve is \\(4x^2 + 9y^2 = 36\\)`, marks: 3, command: 'Show that', markScheme: `M1: writes \\(\\cos\\theta = \\frac{x}{3}\\) and \\(\\sin\\theta = \\frac{y}{2}\\)\nM1: uses \\(\\cos^2\\theta + \\sin^2\\theta = 1\\) to obtain \\(\\frac{x^2}{9} + \\frac{y^2}{4} = 1\\)\nA1: multiplies by 36 to reach \\(4x^2 + 9y^2 = 36\\) with no errors seen (AG)` },
      { q: `The point \\(P(7, k)\\) lies on the circle with equation \\((x - 3)^2 + (y + 2)^2 = 25\\)\n\nFind the possible values of \\(k\\).`, marks: 3, command: 'Find', markScheme: `M1: substitutes \\(x = 7\\): \\(16 + (k + 2)^2 = 25\\)\nM1: \\((k + 2)^2 = 9\\), so \\(k + 2 = \\pm 3\\)\nA1: \\(k = 1\\) or \\(k = -5\\). Both required` },
      { q: `A hot-air balloon descends at a steady rate. Its height above the ground is \\(h\\) metres, \\(t\\) minutes after it begins to descend. When \\(t = 2\\), \\(h = 850\\) and when \\(t = 10\\), \\(h = 450\\) (data written for this practice question).\nThe height is modelled as a linear function of \\(t\\).\n\n(a) Find an equation for \\(h\\) in terms of \\(t\\). [2]\n(b) Use the model to find the time at which the balloon reaches the ground. [1]`, marks: 3, command: 'Find', markScheme: `(a) M1: gradient \\(\\frac{450 - 850}{10 - 2} = -50\\)\nA1: \\(h = 950 - 50t\\)\n(b) B1ft: \\(t = 19\\) minutes (ft their linear model, \\(h = 0\\))` },
      { q: `A curve is defined by the parametric equations\n\\(x = \\frac{1}{t + 1}\\), \\(y = \\frac{t}{t + 1}\\), \\(t \\neq -1\\)\n\nShow that every point on the curve lies on a straight line, and find the equation of this line.`, marks: 3, command: 'Show that', markScheme: `M1: obtains \\(t + 1 = \\frac{1}{x}\\), so \\(t = \\frac{1 - x}{x}\\)\nM1: substitutes into \\(y\\), or notes \\(y = t \\times x\\), or adds: \\(x + y = \\frac{1 + t}{t + 1}\\)\nA1: \\(x + y = 1\\) (or \\(y = 1 - x\\)), a straight line` },
      { q: `The points \\(A\\) and \\(B\\) have coordinates \\((-3, 2)\\) and \\((5, 6)\\) respectively.\n\nFind an equation of the perpendicular bisector of \\(AB\\).`, marks: 4, command: 'Find', markScheme: `B1: midpoint \\((1, 4)\\)\nM1: gradient of \\(AB = \\frac{4}{8} = \\frac{1}{2}\\)\nM1: perpendicular gradient \\(-2\\) used with their midpoint\nA1: \\(y = -2x + 6\\) or equivalent, e.g. \\(2x + y - 6 = 0\\)` },
      { q: `The circle \\(C\\) has equation \\(x^2 + y^2 - 6x + 2y - 15 = 0\\)\nThe point \\(P(6, 3)\\) lies on \\(C\\).\n\nFind an equation of the tangent to \\(C\\) at \\(P\\), giving your answer in the form \\(ax + by = c\\), where \\(a\\), \\(b\\) and \\(c\\) are integers.`, marks: 4, command: 'Find', markScheme: `B1: centre \\((3, -1)\\)\nM1: gradient of radius to \\(P\\): \\(\\frac{3 - (-1)}{6 - 3} = \\frac{4}{3}\\)\nM1: tangent gradient \\(-\\frac{3}{4}\\) used with \\((6, 3)\\)\nA1: \\(3x + 4y = 30\\) or any integer multiple` },
      { q: `The line \\(y = x + c\\) is a tangent to the circle \\(x^2 + y^2 = 8\\)\n\nFind the possible values of \\(c\\).\nFully justify your answer.`, marks: 4, command: 'Find', markScheme: `M1: substitutes: \\(x^2 + (x + c)^2 = 8\\)\nA1: \\(2x^2 + 2cx + c^2 - 8 = 0\\)\nM1: uses discriminant \\(= 0\\) for tangency: \\((2c)^2 - 4(2)(c^2 - 8) = 0\\)\nA1: \\(c = 4\\) or \\(c = -4\\)\nAlternative: perpendicular from centre to line has length \\(\\sqrt{8}\\) – award M1 A1 M1 A1 for a complete correct geometric method.` },
      { q: `A remote-controlled car moves on a flat playground. Relative to a fixed origin, its position at time \\(t\\) seconds is modelled by\n\\(x = t^2 + 1\\), \\(y = 2t - 1\\)\nwhere \\(x\\) and \\(y\\) are in metres. A straight wall runs along the line \\(y = x - 5\\)\n\nFind the coordinates of the points at which the path of the car meets the line of the wall.`, marks: 4, command: 'Find', markScheme: `M1: substitutes the parametric equations into the line: \\(2t - 1 = t^2 + 1 - 5\\)\nA1: \\(t^2 - 2t - 3 = 0\\)\nM1: solves their quadratic: \\(t = 3\\) or \\(t = -1\\)\nA1: \\((10, 5)\\) and \\((2, -3)\\)\nCondone: accept rejection of \\(t = -1\\) on the grounds that \\(t \\geq 0\\), giving only \\((10, 5)\\), if reason stated.` },
      { q: `The points \\(A(1, 1)\\), \\(B(5, 3)\\) and \\(C(3, 7)\\) are the vertices of a triangle.\n\n(a) Show that angle \\(ABC\\) is a right angle. [2]\n(b) Hence find the area of triangle \\(ABC\\). [2]`, marks: 4, command: 'Show that', markScheme: `(a) M1: gradient \\(AB = \\frac{1}{2}\\) and gradient \\(BC = \\frac{4}{-2} = -2\\)\nR1: product of gradients \\(= -1\\), so \\(AB\\) is perpendicular to \\(BC\\) and angle \\(ABC = 90°\\)\n(b) M1: \\(AB = \\sqrt{20}\\) and \\(BC = \\sqrt{20}\\), uses \\(\\frac{1}{2} \\times AB \\times BC\\)\nA1: area \\(= 10\\)` },
      { q: `A gardener marks two posts, \\(A\\) and \\(B\\), at opposite ends of a diameter of a circular pond. Relative to a fixed origin, with distances in metres, \\(A\\) is at \\((-1, 5)\\) and \\(B\\) is at \\((7, -1)\\)\n\nFind an equation of the circle that forms the edge of the pond.`, marks: 4, command: 'Find', markScheme: `M1: centre is the midpoint of \\(AB\\)\nA1: centre \\((3, 2)\\)\nM1: radius \\(= \\frac{1}{2}\\sqrt{8^2 + 6^2}\\) or distance from centre to \\(A\\)\nA1: \\((x - 3)^2 + (y - 2)^2 = 25\\)` },
      { q: `A ball is thrown from a point \\(O\\). Its position \\(t\\) seconds later is modelled by\n\\(x = 12t\\), \\(y = 1.5 + 9t - 4.9t^2\\)\nwhere \\(x\\) metres is the horizontal distance from \\(O\\) and \\(y\\) metres is the height above horizontal ground.\n\nUse the model to find the horizontal distance travelled by the ball before it hits the ground.\nGive your answer to three significant figures.`, marks: 4, command: 'Find', markScheme: `M1: sets \\(y = 0\\): \\(4.9t^2 - 9t - 1.5 = 0\\)\nM1: uses formula or calculator to solve their quadratic\nA1: \\(t = 1.99\\) (AWRT; reject negative root)\nA1: \\(x = 23.9\\) m AWRT` },
      { q: `A phone mast is at the origin \\(O\\). The mast provides signal inside the circle \\(x^2 + y^2 = 10\\), where \\(x\\) and \\(y\\) are measured in kilometres. A straight road follows the line \\(x + y = 4\\)\n\nFind the coordinates of the points where the road enters and leaves the region with signal.`, marks: 4, command: 'Find', markScheme: `M1: substitutes \\(y = 4 - x\\): \\(x^2 + (4 - x)^2 = 10\\)\nA1: \\(x^2 - 4x + 3 = 0\\) (or \\(2x^2 - 8x + 6 = 0\\))\nM1: solves: \\(x = 1\\) or \\(x = 3\\)\nA1: \\((1, 3)\\) and \\((3, 1)\\)` },
      { q: `A circle has its centre on the \\(x\\)-axis and passes through the points \\((1, 4)\\) and \\((5, 2)\\)\n\nFind an equation of the circle.`, marks: 5, command: 'Find', markScheme: `M1: lets centre be \\((a, 0)\\) and equates distances: \\((1 - a)^2 + 16 = (5 - a)^2 + 4\\)\nA1: correct equation\nA1: \\(8a = 12\\), \\(a = \\frac{3}{2}\\)\nM1: finds \\(r^2\\) using their \\(a\\): \\(\\left(1 - \\frac{3}{2}\\right)^2 + 16\\)\nA1: \\(\\left(x - \\frac{3}{2}\\right)^2 + y^2 = \\frac{65}{4}\\)\nAlternative: perpendicular bisector of the two points meets \\(y = 0\\) at \\(x = \\frac{3}{2}\\) – mark equivalently.` },
      { q: `The line \\(y = kx\\), where \\(k\\) is a constant, is a tangent to the circle \\((x - 3)^2 + y^2 = 5\\)\n\nFind the exact possible values of \\(k\\).`, marks: 5, command: 'Find', markScheme: `M1: substitutes \\(y = kx\\): \\((x - 3)^2 + k^2x^2 = 5\\)\nA1: \\((1 + k^2)x^2 - 6x + 4 = 0\\)\nM1: discriminant \\(= 0\\): \\(36 - 16(1 + k^2) = 0\\)\nA1: \\(k^2 = \\frac{5}{4}\\)\nA1: \\(k = \\pm\\frac{\\sqrt{5}}{2}\\) CAO exact` },
      { q: `The points \\(A(-2, 4)\\), \\(B(4, 6)\\) and \\(C(6, 0)\\) lie on a circle.\n\n(a) Show that \\(AB\\) is perpendicular to \\(BC\\). [2]\n(b) Hence find an equation of the circle. [3]`, marks: 5, command: 'Show that', markScheme: `(a) M1: gradient \\(AB = \\frac{2}{6} = \\frac{1}{3}\\), gradient \\(BC = \\frac{-6}{2} = -3\\)\nR1: product \\(= -1\\), so perpendicular\n(b) E1: angle in a semicircle is \\(90°\\), so \\(AC\\) is a diameter\nM1: centre is midpoint of \\(AC = (2, 2)\\) and \\(r^2 = 4^2 + 2^2\\)\nA1: \\((x - 2)^2 + (y - 2)^2 = 20\\)` },
      { q: `A curve has parametric equations\n\\(x = 1 + \\sin\\theta\\), \\(y = \\cos 2\\theta\\), \\(0 \\leq \\theta \\leq 2\\pi\\)\n\n(a) Find a Cartesian equation of the curve in the form \\(y = f(x)\\) [3]\n(b) State the set of possible values of \\(x\\) and the set of possible values of \\(y\\) on this curve. [2]`, marks: 5, command: 'Find', markScheme: `(a) M1: uses \\(\\cos 2\\theta = 1 - 2\\sin^2\\theta\\)\nM1: substitutes \\(\\sin\\theta = x - 1\\)\nA1: \\(y = 1 - 2(x - 1)^2\\) or \\(y = -2x^2 + 4x - 1\\)\n(b) B1: \\(0 \\leq x \\leq 2\\)\nB1: \\(-1 \\leq y \\leq 1\\)` },
      { q: `The line \\(L_1\\) has equation \\(y = 2x - 4\\) and the line \\(L_2\\) has equation \\(x + 3y = 9\\)\n\n(a) Find the coordinates of the point of intersection of \\(L_1\\) and \\(L_2\\) [2]\n(b) Find the area of the triangle formed by \\(L_1\\), \\(L_2\\) and the \\(y\\)-axis. [3]`, marks: 5, command: 'Find', markScheme: `(a) M1: substitutes to obtain \\(x + 3(2x - 4) = 9\\)\nA1: \\((3, 2)\\)\n(b) B1: \\(y\\)-intercepts \\(-4\\) and \\(3\\)\nM1: \\(\\frac{1}{2} \\times (3 - (-4)) \\times\\) their \\(x\\)-coordinate\nA1: area \\(= \\frac{21}{2}\\) (10.5)` },
      { q: `Two printing companies charge for printing leaflets (data written for this practice question).\nCompany A charges £25 plus 15p per leaflet.\nCompany B's total charge, \\(£C\\), for \\(n\\) leaflets is modelled as a linear function of \\(n\\). Company B charges £60 for 200 leaflets and £100 for 600 leaflets.\n\n(a) Find an equation for \\(C\\) in terms of \\(n\\) for Company B. [2]\n(b) Find the number of leaflets for which the two companies charge the same amount. [2]\n(c) Interpret the gradient of Company B's model in context. [1]`, marks: 5, command: 'Find', markScheme: `(a) M1: gradient \\(\\frac{100 - 60}{600 - 200} = 0.1\\)\nA1: \\(C = 40 + 0.1n\\)\n(b) M1: equates \\(25 + 0.15n = 40 + 0.1n\\) (their B)\nA1: \\(n = 300\\)\n(c) E1: Company B charges 10p for each extra leaflet` },
      { q: `A curve has parametric equations\n\\(x = t^2 - 4\\), \\(y = t^3 - 4t\\)\n\n(a) Find the coordinates of the points where the curve meets the \\(x\\)-axis. [3]\n(b) Find the coordinates of the points where the curve meets the line \\(x = 5\\) [2]`, marks: 5, command: 'Find', markScheme: `(a) M1: sets \\(t^3 - 4t = 0\\), i.e. \\(t(t^2 - 4) = 0\\)\nA1: \\(t = 0, 2, -2\\)\nA1: \\((-4, 0)\\) and \\((0, 0)\\) only\n(b) M1: \\(t^2 - 4 = 5\\), so \\(t = \\pm 3\\)\nA1: \\((5, 15)\\) and \\((5, -15)\\)` },
      { q: `On a map of a park, a straight footpath follows the line through the points \\((0, 4)\\) and \\((6, 1)\\). Distances on the map are in units of 100 metres.\nA new straight path is to be built from a café at \\(H(5, 6)\\) to meet the footpath at the point \\(F\\), so that the new path is as short as possible.\n\n(a) Find the coordinates of \\(F\\). [4]\n(b) Find the length of the new path, giving your answer to the nearest metre. [2]`, marks: 6, command: 'Find', markScheme: `(a) M1: footpath gradient \\(-\\frac{1}{2}\\), equation \\(y = 4 - \\frac{1}{2}x\\)\nM1: new path is perpendicular: gradient 2 through \\(H\\), \\(y = 2x - 4\\)\nM1: solves simultaneously\nA1: \\(F(3.2, 2.4)\\)\n(b) M1: \\(HF = \\sqrt{1.8^2 + 3.6^2} = \\sqrt{16.2}\\)\nA1: 402 m (AWRT)` },
      { q: `The cross-section of a bridge arch is modelled as an arc of a circle. The arch spans 40 metres along horizontal ground and its highest point is 8 metres above the ground.\nTake the origin at ground level directly below the highest point, with the \\(x\\)-axis along the ground.\n\n(a) Show that the centre of the circle is at \\((0, -21)\\) and find its radius. [3]\n(b) Find the height of the arch at a horizontal distance of 12 metres from the origin, giving your answer to three significant figures. [2]\n(c) State one limitation of the model. [1]`, marks: 6, command: 'Show that', markScheme: `(a) M1: centre \\((0, -k)\\) with \\(20^2 + k^2 = (8 + k)^2\\)\nA1: \\(400 = 64 + 16k\\), \\(k = 21\\) (AG)\nA1: radius \\(29\\) m\n(b) M1: \\(x = 12\\): \\(144 + (y + 21)^2 = 841\\)\nA1: \\(y = 5.40\\) m AWRT\n(c) E1: e.g. a real arch has thickness / is not exactly circular / ground may not be level` },
      { q: `The circle \\(C\\) has equation \\(x^2 + y^2 - 4x - 8y + 11 = 0\\) and centre \\(Q\\).\n\n(a) Find the coordinates of \\(Q\\) and the radius of \\(C\\). [2]\n(b) The point \\(P\\) has coordinates \\((8, 1)\\). A tangent from \\(P\\) touches \\(C\\) at the point \\(T\\).\nFind the exact length of \\(PT\\). [3]\n(c) Hence find the area of triangle \\(PQT\\). [1]`, marks: 6, command: 'Find', markScheme: `(a) B1: \\(Q(2, 4)\\)\nB1: radius 3\n(b) M1: \\(PQ^2 = 6^2 + 3^2 = 45\\)\nM1: angle \\(QTP = 90°\\) (radius perpendicular to tangent): \\(PT^2 = PQ^2 - 3^2\\)\nA1: \\(PT = 6\\)\n(c) B1ft: area \\(= \\frac{1}{2} \\times 3 \\times 6 = 9\\)` },
      { q: `The circle \\(C\\) has equation \\((x - 1)^2 + (y - 2)^2 = 25\\)\nThe line \\(L\\) has equation \\(y = x + 2\\)\n\n(a) Find the coordinates of the points \\(A\\) and \\(B\\) where \\(L\\) intersects \\(C\\). [4]\n(b) Sketch \\(C\\) and \\(L\\) on the same axes, labelling the centre of \\(C\\) and the points \\(A\\) and \\(B\\). [2]`, marks: 6, command: 'Find', diagram: true, markScheme: `(a) M1: substitutes: \\((x - 1)^2 + x^2 = 25\\)\nA1: \\(x^2 - x - 12 = 0\\)\nM1: solves: \\(x = 4\\) or \\(x = -3\\)\nA1: \\((4, 6)\\) and \\((-3, -1)\\)\n(b) B1: circle centre \\((1, 2)\\), radius 5, correctly positioned\nB1: line of positive gradient through \\((0, 2)\\) cutting the circle at their two labelled points` },
      { q: `A ball is kicked from a point \\(O\\) on horizontal ground. Its position \\(t\\) seconds later is modelled by\n\\(x = 15t\\), \\(y = 2 + 10t - 4.9t^2\\)\nwhere \\(x\\) metres is the horizontal distance from \\(O\\) and \\(y\\) metres is the height above the ground.\n\n(a) Show that the path of the ball satisfies \\(y = 2 + \\frac{2}{3}x - \\frac{49}{2250}x^2\\) [3]\n(b) A fence 1.8 metres high stands 20 metres horizontally from \\(O\\). Determine whether the ball passes over the fence. [2]\n(c) State one limitation of the model. [1]`, marks: 6, command: 'Show that', markScheme: `(a) M1: \\(t = \\frac{x}{15}\\) substituted into \\(y\\)\nA1: \\(10t = \\frac{2}{3}x\\)\nA1: \\(4.9 \\times \\frac{x^2}{225} = \\frac{49}{2250}x^2\\), completing the given result (AG)\n(b) M1: substitutes \\(x = 20\\): \\(y = 6.62\\) (AWRT 6.6)\nA1: \\(6.62 \\gt 1.8\\) so the ball clears the fence\n(c) E1: e.g. air resistance ignored / ball treated as a particle / spin ignored` },
      { q: `A circle lies in the first quadrant and touches both the \\(x\\)-axis and the \\(y\\)-axis. The circle passes through the point \\((2, 1)\\)\n\nFind the two possible equations of the circle.`, marks: 6, command: 'Find', markScheme: `M1: centre \\((a, a)\\) and radius \\(a\\) (touches both axes)\nA1: \\((x - a)^2 + (y - a)^2 = a^2\\)\nM1: substitutes \\((2, 1)\\): \\((2 - a)^2 + (1 - a)^2 = a^2\\)\nA1: \\(a^2 - 6a + 5 = 0\\)\nA1: \\(a = 1\\) or \\(a = 5\\)\nA1: \\((x - 1)^2 + (y - 1)^2 = 1\\) and \\((x - 5)^2 + (y - 5)^2 = 25\\)` },
      { q: `A garden sprinkler is placed at the point \\(S(4, 3)\\). It waters all points within 5 metres of \\(S\\). Coordinates are in metres relative to a corner of the garden.\nA straight path in the garden follows the line \\(x + 2y = 20\\)\n\n(a) Write down an equation of the boundary of the region watered by the sprinkler. [1]\n(b) Find the coordinates of the points where the path crosses this boundary. [4]\n(c) Find the length of path that gets wet, giving your answer in the form \\(a\\sqrt{5}\\) metres. [2]`, marks: 7, command: 'Find', markScheme: `(a) B1: \\((x - 4)^2 + (y - 3)^2 = 25\\)\n(b) M1: substitutes \\(x = 20 - 2y\\): \\((16 - 2y)^2 + (y - 3)^2 = 25\\)\nA1: \\(y^2 - 14y + 48 = 0\\) (or \\(5y^2 - 70y + 240 = 0\\))\nM1: solves: \\(y = 6\\) or \\(y = 8\\)\nA1: \\((8, 6)\\) and \\((4, 8)\\)\n(c) M1: distance \\(\\sqrt{4^2 + 2^2}\\) between their points\nA1: \\(2\\sqrt{5}\\) m` },
      { q: `The points \\(A(3, 4)\\) and \\(B(-3, 4)\\) lie on the circle \\(x^2 + y^2 = 25\\), which has centre \\(O\\).\nThe tangents to the circle at \\(A\\) and at \\(B\\) meet at the point \\(T\\).\n\n(a) Find an equation of the tangent at \\(A\\). [3]\n(b) Show that \\(T\\) has coordinates \\(\\left(0, \\frac{25}{4}\\right)\\) [2]\n(c) Find the area of the quadrilateral \\(OATB\\). [2]`, marks: 7, command: 'Find', markScheme: `(a) M1: gradient \\(OA = \\frac{4}{3}\\)\nM1: tangent gradient \\(-\\frac{3}{4}\\) used with \\(A\\)\nA1: \\(3x + 4y = 25\\)\n(b) M1: tangent at \\(B\\) is \\(-3x + 4y = 25\\) (or uses symmetry in the \\(y\\)-axis)\nA1: solves to obtain \\(x = 0\\), \\(y = \\frac{25}{4}\\) (AG)\n(c) M1: \\(AT = \\sqrt{3^2 + \\left(\\frac{9}{4}\\right)^2} = \\frac{15}{4}\\) and area \\(= 2 \\times \\frac{1}{2} \\times 5 \\times AT\\)\nA1: \\(\\frac{75}{4}\\) (18.75)` },
      { q: `A curve \\(C\\) has parametric equations\n\\(x = 3 + 5\\cos\\theta\\), \\(y = -2 + 5\\sin\\theta\\), \\(0 \\leq \\theta \\lt 2\\pi\\)\n\n(a) Show that \\(C\\) is a circle, stating its centre and radius. [3]\n(b) Find the coordinates of the points where \\(C\\) meets the line \\(y = 2\\) [2]\n(c) Find the values of \\(\\theta\\) at these points, giving your answers to three significant figures. [2]`, marks: 7, command: 'Show that', markScheme: `(a) M1: \\(\\cos\\theta = \\frac{x - 3}{5}\\), \\(\\sin\\theta = \\frac{y + 2}{5}\\) and uses \\(\\cos^2\\theta + \\sin^2\\theta = 1\\)\nA1: \\((x - 3)^2 + (y + 2)^2 = 25\\)\nA1: circle with centre \\((3, -2)\\) and radius 5\n(b) M1: \\((x - 3)^2 + 16 = 25\\)\nA1: \\((0, 2)\\) and \\((6, 2)\\)\n(c) M1: \\(\\sin\\theta = \\frac{4}{5}\\) with \\(\\cos\\theta = \\pm\\frac{3}{5}\\)\nA1: \\(\\theta = 0.927\\) at \\((6, 2)\\) and \\(\\theta = 2.21\\) at \\((0, 2)\\) AWRT` },
      { q: `The line \\(y = x + c\\) does not meet the circle \\((x - 2)^2 + (y + 1)^2 = 8\\)\n\nFind the set of possible values of \\(c\\).\nFully justify your answer.`, marks: 7, command: 'Find', markScheme: `M1: substitutes \\(y = x + c\\): \\((x - 2)^2 + (x + c + 1)^2 = 8\\)\nA1: \\(2x^2 + (2c - 2)x + c^2 + 2c - 3 = 0\\)\nM1: uses discriminant \\(\\lt 0\\) for no intersection\nA1: \\((2c - 2)^2 - 8(c^2 + 2c - 3) \\lt 0\\), simplifying to \\(c^2 + 6c - 7 \\gt 0\\)\nM1: finds critical values from \\((c + 7)(c - 1) = 0\\)\nA1: \\(c = -7\\), \\(c = 1\\)\nA1: \\(c \\lt -7\\) or \\(c \\gt 1\\) CAO` },
      { q: `A Ferris wheel rotates at a constant rate. The position of a passenger \\(t\\) seconds after boarding is modelled by\n\\(x = 20\\sin\\left(\\frac{\\pi t}{15}\\right)\\), \\(y = 22 - 20\\cos\\left(\\frac{\\pi t}{15}\\right)\\)\nwhere \\(x\\) metres is the horizontal displacement from the vertical line through the centre of the wheel and \\(y\\) metres is the height above the ground.\n\n(a) Find a Cartesian equation for the path of the passenger. [2]\n(b) Find the minimum and maximum heights of the passenger above the ground. [2]\n(c) Find the time taken for one complete revolution. [1]\n(d) Find the first time at which the passenger is 32 metres above the ground. [2]\n(e) State one limitation of the model. [1]`, marks: 8, command: 'Find', markScheme: `(a) M1: uses \\(\\sin^2 + \\cos^2 = 1\\) with \\(\\frac{x}{20}\\) and \\(\\frac{22 - y}{20}\\)\nA1: \\(x^2 + (y - 22)^2 = 400\\)\n(b) B1: minimum 2 m\nB1: maximum 42 m\n(c) B1: 30 seconds\n(d) M1: \\(\\cos\\left(\\frac{\\pi t}{15}\\right) = -\\frac{1}{2}\\)\nA1: \\(\\frac{\\pi t}{15} = \\frac{2\\pi}{3}\\), \\(t = 10\\) s\n(e) E1: e.g. the wheel may not rotate at constant speed / stops to let passengers on / passenger treated as a point` },
      { q: `The points \\(A(6, 6)\\), \\(B(-1, 5)\\) and \\(C(0, -2)\\) lie on the circle \\(C_1\\)\n\n(a) Find an equation of the perpendicular bisector of \\(AB\\). [3]\n(b) The perpendicular bisector of \\(BC\\) has equation \\(x - 7y + 11 = 0\\)\nHence find the coordinates of the centre of \\(C_1\\) [2]\n(c) Find an equation of \\(C_1\\) [1]\n(d) Find an equation of the tangent to \\(C_1\\) at \\(A\\), giving your answer in the form \\(ax + by + c = 0\\), where \\(a\\), \\(b\\) and \\(c\\) are integers. [2]`, marks: 8, command: 'Find', markScheme: `(a) B1: midpoint \\(\\left(\\frac{5}{2}, \\frac{11}{2}\\right)\\)\nM1: gradient \\(AB = \\frac{1}{7}\\), perpendicular gradient \\(-7\\)\nA1: \\(y = -7x + 23\\) or equivalent\n(b) M1: solves their bisector with \\(x - 7y + 11 = 0\\)\nA1: centre \\((3, 2)\\)\n(c) B1ft: \\((x - 3)^2 + (y - 2)^2 = 25\\)\n(d) M1: radius gradient \\(\\frac{4}{3}\\), tangent gradient \\(-\\frac{3}{4}\\) through \\(A\\)\nA1: \\(3x + 4y - 42 = 0\\)` },
      { q: `A golf ball is struck from a point \\(O\\) at the bottom of a straight slope. Its position \\(t\\) seconds later is modelled by\n\\(x = 20t\\), \\(y = 15t - 5t^2\\)\nwhere \\(x\\) metres is the horizontal distance from \\(O\\) and \\(y\\) metres is the height above \\(O\\).\nThe surface of the slope is modelled by the line \\(y = \\frac{1}{4}x\\), \\(x \\geq 0\\)\n\n(a) Find a Cartesian equation for the path of the ball, in the form \\(y = f(x)\\) [3]\n(b) Find the coordinates of the point where the ball lands on the slope. [4]\n(c) Find the distance up the slope from \\(O\\) to where the ball lands, giving your answer to three significant figures. [1]\n(d) State one limitation of the model. [1]`, marks: 9, command: 'Find', markScheme: `(a) M1: \\(t = \\frac{x}{20}\\) substituted into \\(y\\)\nA1: \\(15t = \\frac{3}{4}x\\)\nA1: \\(y = \\frac{3}{4}x - \\frac{x^2}{80}\\)\n(b) M1: equates \\(\\frac{3}{4}x - \\frac{x^2}{80} = \\frac{1}{4}x\\) (or uses \\(15t - 5t^2 = 5t\\))\nA1: \\(\\frac{x}{2} = \\frac{x^2}{80}\\) (or \\(5t^2 = 10t\\))\ndM1: solves, rejecting \\(x = 0\\) (\\(t = 0\\)) as the starting point\nA1: \\((40, 10)\\)\n(c) B1ft: \\(\\sqrt{40^2 + 10^2} = 41.2\\) m AWRT\n(d) E1: e.g. air resistance ignored / slope not perfectly straight / ball treated as a particle` },
      { q: `The circle \\(C\\) has equation \\(x^2 + y^2 - 10x - 4y + 4 = 0\\)\n\n(a) Find the coordinates of the centre of \\(C\\) and the radius of \\(C\\). [3]\n(b) The line \\(L\\) has equation \\(y = 2x - 3\\)\n\\(L\\) intersects \\(C\\) at the points \\(P\\) and \\(Q\\), where \\(P\\) has the smaller \\(x\\)-coordinate.\nFind the coordinates of \\(P\\) and \\(Q\\). [4]\n(c) The tangents to \\(C\\) at \\(P\\) and at \\(Q\\) meet at the point \\(R\\).\nFind the coordinates of \\(R\\).\nFully justify your answer. [3]`, marks: 10, command: 'Find', markScheme: `(a) M1: completes the square: \\((x - 5)^2 + (y - 2)^2 = 25 + 4 - 4\\)\nA1: centre \\((5, 2)\\)\nA1: radius 5\n(b) M1: substitutes \\(y = 2x - 3\\): \\((x - 5)^2 + (2x - 5)^2 = 25\\)\nA1: \\(x^2 - 6x + 5 = 0\\) (or \\(5x^2 - 30x + 25 = 0\\))\nM1: solves: \\(x = 1\\) or \\(x = 5\\)\nA1: \\(P(1, -1)\\), \\(Q(5, 7)\\)\n(c) B1: radius to \\(Q\\) is vertical, so tangent at \\(Q\\) is \\(y = 7\\)\nM1: radius to \\(P\\) has gradient \\(\\frac{3}{4}\\), so tangent at \\(P\\) has gradient \\(-\\frac{4}{3}\\): \\(4x + 3y - 1 = 0\\)\nA1: \\(R(-5, 7)\\)` }
    ]
  },
  '1.4': {
    name: 'Sequences & Series',
    questions: [
      { q: `Find the coefficient of \\(x^3\\) in the expansion of \\((2 - x)^7\\).`, marks: 2, command: 'Find', markScheme: `M1: Correct term identified, \\(\\binom{7}{3}(2)^4(-x)^3\\) (condone missing brackets if recovered)\nA1: \\(-560\\) CAO\nCondone \\(-560x^3\\) for the coefficient.` },
      { q: `Find the value of\n\\[\\sum_{r=1}^{20} (3r + 2)\\]`, marks: 2, command: 'Find', markScheme: `M1: Recognises an arithmetic series with \\(a = 5\\), last term 62 (or \\(d = 3\\)) and \\(n = 20\\), and uses a correct sum formula, e.g. \\(\\frac{20}{2}(5 + 62)\\)\nA1: 670 CAO` },
      { q: `A sequence is defined by\n\\(u_1 = 3\\), \\(u_{n+1} = \\frac{4}{u_n}\\)\n\n(a) Find \\(u_2\\) and \\(u_3\\). [1]\n(b) State the period of the sequence. [1]`, marks: 2, command: 'Find', markScheme: `(a) B1: \\(u_2 = \\frac{4}{3}\\) and \\(u_3 = 3\\)\n(b) B1: Period 2 (sequence is periodic with order 2)` },
      { q: `A geometric series has first term 40 and sum to infinity 160.\n\nFind the common ratio of the series.`, marks: 2, command: 'Find', markScheme: `M1: Uses \\(\\frac{40}{1 - r} = 160\\)\nA1: \\(r = \\frac{3}{4}\\) (or 0.75) CAO` },
      { q: `Find the first three terms, in ascending powers of \\(x\\), of the binomial expansion of \\((3 + 2x)^5\\).\n\nGive each term in its simplest form.`, marks: 3, command: 'Find', markScheme: `B1: Constant term 243\nM1: Correct binomial structure for at least one of the \\(x\\) or \\(x^2\\) terms, e.g. \\(\\binom{5}{2}3^3(2x)^2\\)\nA1: \\(810x + 1080x^2\\)\nFinal answer: \\(243 + 810x + 1080x^2\\). ISW` },
      { q: `(a) Find the binomial expansion of \\(\\sqrt{1 - 4x}\\) up to and including the term in \\(x^2\\). [2]\n(b) State the range of values of \\(x\\) for which the expansion is valid. [1]`, marks: 3, command: 'Find', markScheme: `(a) M1: Uses \\((1 + y)^{\\frac{1}{2}}\\) with \\(y = -4x\\), e.g. \\(1 + \\frac{1}{2}(-4x) + \\frac{\\frac{1}{2}(-\\frac{1}{2})}{2!}(-4x)^2\\)\nA1: \\(1 - 2x - 2x^2\\)\n(b) B1: \\(|x| \\lt \\frac{1}{4}\\) (or \\(-\\frac{1}{4} \\lt x \\lt \\frac{1}{4}\\)). Condone \\(\\leq\\)` },
      { q: `The 5th term of an arithmetic sequence is 17 and the 12th term is 45.\n\nFind the sum of the first 30 terms of the sequence.`, marks: 3, command: 'Find', markScheme: `M1: Forms two equations \\(a + 4d = 17\\) and \\(a + 11d = 45\\) and solves\nA1: \\(a = 1\\), \\(d = 4\\)\nA1: \\(S_{30} = \\frac{30}{2}(2 + 29 \\times 4) = 1770\\) CAO` },
      { q: `The \\(n\\)th term of a sequence is given by\n\\[u_n = \\frac{3n}{n + 1}\\]\n\nProve that the sequence is increasing.`, marks: 3, command: 'Prove', markScheme: `M1: Considers \\(u_{n+1} - u_n = \\frac{3(n+1)}{n+2} - \\frac{3n}{n+1}\\) and attempts a common denominator\nA1: \\(= \\frac{3[(n+1)^2 - n(n+2)]}{(n+1)(n+2)} = \\frac{3}{(n+1)(n+2)}\\)\nR1: States that \\(\\frac{3}{(n+1)(n+2)} \\gt 0\\) for all \\(n \\geq 1\\), so \\(u_{n+1} \\gt u_n\\) and the sequence is increasing` },
      { q: `Find the value of\n\\[\\sum_{r=1}^{10} 3 \\times 2^r\\]`, marks: 3, command: 'Find', markScheme: `B1: Identifies geometric series with first term 6 and common ratio 2 (10 terms)\nM1: Uses \\(S_n = \\frac{a(r^n - 1)}{r - 1}\\), e.g. \\(\\frac{6(2^{10} - 1)}{2 - 1}\\)\nA1: 6138 CAO` },
      { q: `Priya buys a new car for £18 000. A model for the value of the car assumes that its value falls by 15% each year. (data written for this practice question)\n\n(a) Use the model to find the value of the car 5 years after it is bought. Give your answer to the nearest pound. [2]\n(b) State one limitation of the model. [1]`, marks: 3, command: 'Find', markScheme: `(a) M1: \\(18000 \\times 0.85^5\\)\nA1: £7987 (AWRT £7990)\n(b) E1: Any valid limitation, e.g. the rate of depreciation is unlikely to stay constant; depends on mileage/condition; the model never gives a value of zero` },
      { q: `The geometric series\n\\[1 + (2x - 1) + (2x - 1)^2 + (2x - 1)^3 + \\ldots\\]\nis convergent.\n\nFind the set of possible values of \\(x\\), and find an expression for the sum to infinity of the series in terms of \\(x\\).`, marks: 3, command: 'Find', markScheme: `M1: Uses \\(|2x - 1| \\lt 1\\) (common ratio condition)\nA1: \\(0 \\lt x \\lt 1\\)\nB1: \\(S_\\infty = \\frac{1}{1 - (2x - 1)} = \\frac{1}{2 - 2x}\\) (or equivalent)` },
      { q: `Find the binomial expansion of \\((1 - 3x)^{-2}\\) up to and including the term in \\(x^3\\), stating the range of values of \\(x\\) for which the expansion is valid.`, marks: 4, command: 'Find', markScheme: `M1: Correct structure for the \\(x^2\\) or \\(x^3\\) term, e.g. \\(\\frac{(-2)(-3)}{2!}(-3x)^2\\)\nA1: \\(1 + 6x\\)\nA1: \\(+ 27x^2 + 108x^3\\)\nB1: \\(|x| \\lt \\frac{1}{3}\\)\nFinal answer: \\(1 + 6x + 27x^2 + 108x^3\\), valid for \\(|x| \\lt \\frac{1}{3}\\)` },
      { q: `A sequence is defined by\n\\(u_1 = 2\\), \\(u_{n+1} = ku_n + 3\\)\nwhere \\(k\\) is a positive constant.\n\nGiven that \\(u_3 = 23\\), find the value of \\(k\\) and hence find \\(u_4\\).`, marks: 4, command: 'Find', markScheme: `M1: \\(u_2 = 2k + 3\\) and \\(u_3 = k(2k + 3) + 3\\)\nM1: Forms and solves \\(2k^2 + 3k - 20 = 0\\), e.g. \\((2k - 5)(k + 4) = 0\\)\nA1: \\(k = \\frac{5}{2}\\) only (rejects \\(k = -4\\) as \\(k\\) is positive)\nA1ft: \\(u_4 = \\frac{5}{2} \\times 23 + 3 = 60.5\\)` },
      { q: `A theatre is designed so that the first row has 20 seats and each row after the first has 2 more seats than the row in front of it. (data written for this practice question)\n\nThe theatre must have at least 1000 seats.\n\nFind the least number of rows needed.`, marks: 4, command: 'Find', markScheme: `M1: Uses arithmetic series sum with \\(a = 20\\), \\(d = 2\\): \\(\\frac{n}{2}(40 + 2(n - 1))\\)\nA1: \\(n(n + 19) \\geq 1000\\) (or \\(n^2 + 19n - 1000 = 0\\))\nM1: Solves the quadratic, \\(n = 23.5\\ldots\\), or tests \\(n = 23\\) (966) and \\(n = 24\\) (1032)\nA1: 24 rows CAO` },
      { q: `An arithmetic series has first term \\(a\\) and common difference \\(d\\).\n\nProve that the sum of the first \\(n\\) terms of the series is\n\\[\\frac{n}{2}\\left[2a + (n - 1)d\\right]\\]`, marks: 4, command: 'Prove', markScheme: `B1: \\(S_n = a + (a + d) + (a + 2d) + \\ldots + [a + (n - 1)d]\\)\nM1: Writes the series in reverse: \\(S_n = [a + (n - 1)d] + [a + (n - 2)d] + \\ldots + a\\)\nM1: Adds the two to obtain \\(2S_n = n[2a + (n - 1)d]\\) (pairs each total \\(2a + (n - 1)d\\))\nA1: Completes rigorously to \\(S_n = \\frac{n}{2}[2a + (n - 1)d]\\)` },
      { q: `(a) Find the first three terms, in ascending powers of \\(x\\), of the expansion of \\(\\left(1 + \\frac{x}{4}\\right)^8\\). [2]\n(b) Use your answer to (a), with a suitable value of \\(x\\), to find an estimate for \\(1.0025^8\\). Give your answer to 6 decimal places. [2]`, marks: 4, command: 'Find', markScheme: `(a) M1: \\(1 + 8\\left(\\frac{x}{4}\\right) + \\binom{8}{2}\\left(\\frac{x}{4}\\right)^2\\)\nA1: \\(1 + 2x + \\frac{7}{4}x^2\\)\n(b) M1: Uses \\(x = 0.01\\)\nA1: 1.020175 CAO` },
      { q: `(a) Show that\n\\[\\sum_{r=1}^{n} (2r - 5) = n(n - 4)\\] [2]\n(b) Hence find the value of\n\\[\\sum_{r=10}^{30} (2r - 5)\\] [2]`, marks: 4, command: 'Show that', markScheme: `(a) M1: Arithmetic series with first term \\(-3\\), last term \\(2n - 5\\): \\(\\frac{n}{2}(-3 + 2n - 5)\\)\nA1: \\(= \\frac{n}{2}(2n - 8) = n(n - 4)\\) AG, convincingly shown\n(b) M1: \\(30(26) - 9(5)\\)\nA1: 735 CAO` },
      { q: `Ali starts a savings plan. He saves £50 in the first month and each month after that he saves £5 more than in the previous month. (data written for this practice question)\n\n(a) Find the amount Ali saves in the 24th month. [1]\n(b) Find the total amount Ali saves in the first 24 months. [2]\n(c) State one reason why this model may not be realistic over a long period of time. [1]`, marks: 4, command: 'Find', markScheme: `(a) B1: £165\n(b) M1: \\(\\frac{24}{2}(2 \\times 50 + 23 \\times 5)\\) or \\(\\frac{24}{2}(50 + 165)\\)\nA1: £2580\n(c) E1: e.g. monthly savings increase without limit and Ali's income is unlikely to allow this; he may need to withdraw money` },
      { q: `A charity receives donations from a fundraising campaign. It receives £120 in the first month, and in each following month the amount received is 80% of the amount received in the previous month. (data written for this practice question)\n\nFind the least number of months after which the total amount received is more than 99% of the total amount the model predicts the charity will ever receive.`, marks: 4, command: 'Find', markScheme: `B1: \\(S_\\infty = \\frac{120}{1 - 0.8} = 600\\)\nM1: Forms \\(\\frac{120(1 - 0.8^n)}{0.2} \\gt 594\\) or \\(0.8^n \\lt 0.01\\)\nM1: Uses logarithms: \\(n \\gt \\frac{\\ln 0.01}{\\ln 0.8} = 20.6\\ldots\\)\nA1: 21 months CAO` },
      { q: `Find the binomial expansion of \\((2 + x)^{-3}\\) up to and including the term in \\(x^2\\).\n\nState the range of values of \\(x\\) for which the expansion is valid.`, marks: 5, command: 'Find', markScheme: `M1: Takes out the factor: \\(2^{-3}\\left(1 + \\frac{x}{2}\\right)^{-3}\\)\nM1: Correct structure, e.g. \\(1 + (-3)\\frac{x}{2} + \\frac{(-3)(-4)}{2!}\\left(\\frac{x}{2}\\right)^2\\)\nA1: \\(\\frac{1}{8} - \\frac{3}{16}x\\)\nA1: \\(+ \\frac{3}{16}x^2\\)\nB1: \\(|x| \\lt 2\\)` },
      { q: `In the binomial expansion of \\((1 + kx)^8\\), where \\(k\\) is a non-zero constant, the coefficient of \\(x^3\\) is equal to the coefficient of \\(x^2\\).\n\n(a) Find the value of \\(k\\). [3]\n(b) Hence find the coefficient of \\(x^4\\) in the expansion. [2]`, marks: 5, command: 'Find', markScheme: `(a) B1: Coefficients \\(28k^2\\) and \\(56k^3\\)\nM1: Equates: \\(56k^3 = 28k^2\\)\nA1: \\(k = \\frac{1}{2}\\) (rejects \\(k = 0\\))\n(b) M1: \\(\\binom{8}{4}k^4 = 70 \\times \\frac{1}{16}\\)\nA1ft: \\(\\frac{35}{8}\\)` },
      { q: `The second term of a geometric series is 6 and the sum to infinity of the series is 27.\n\nFind the two possible values of the common ratio and the corresponding values of the first term.`, marks: 5, command: 'Find', markScheme: `M1: \\(ar = 6\\)\nM1: \\(\\frac{a}{1 - r} = 27\\)\nM1: Eliminates \\(a\\) to form a quadratic, \\(27r^2 - 27r + 6 = 0\\), i.e. \\(9r^2 - 9r + 2 = 0\\)\nA1: \\(r = \\frac{1}{3}\\) or \\(r = \\frac{2}{3}\\)\nA1: \\(a = 18\\) when \\(r = \\frac{1}{3}\\); \\(a = 9\\) when \\(r = \\frac{2}{3}\\)` },
      { q: `A sequence is defined by\n\\(u_1 = 2\\), \\(u_{n+1} = \\frac{1}{1 - u_n}\\)\n\n(a) Find \\(u_2\\), \\(u_3\\) and \\(u_4\\). [2]\n(b) Find the value of\n\\[\\sum_{n=1}^{100} u_n\\] [3]`, marks: 5, command: 'Find', markScheme: `(a) B1: \\(u_2 = -1\\), \\(u_3 = \\frac{1}{2}\\)\nB1: \\(u_4 = 2\\) (and so the sequence is periodic with period 3)\n(b) M1: Sum of one cycle: \\(2 - 1 + \\frac{1}{2} = \\frac{3}{2}\\)\nM1: \\(33 \\times \\frac{3}{2} + u_{100}\\), with \\(u_{100} = u_1 = 2\\)\nA1: 51.5 CAO` },
      { q: `The number of fish in a lake at the start of year \\(n\\) is modelled by \\(u_n\\), where\n\\(u_1 = 2000\\), \\(u_{n+1} = 1.08u_n - 300\\)\n(data written for this practice question)\n\n(a) Find \\(u_3\\). [2]\n(b) Find the value of \\(P\\) such that, if the number of fish at the start of a year were \\(P\\), the model predicts the number would stay constant. [2]\n(c) Explain what the model predicts will happen to the number of fish in the long term. [1]`, marks: 5, command: 'Find', markScheme: `(a) M1: \\(u_2 = 1.08 \\times 2000 - 300 = 1860\\)\nA1: \\(u_3 = 1708.8\\) (accept 1709 or 1708)\n(b) M1: \\(P = 1.08P - 300\\)\nA1: \\(P = 3750\\)\n(c) E1: Since \\(u_1 \\lt 3750\\) the number of fish decreases each year (at an increasing rate) and the fish will die out` },
      { q: `The first three terms of a geometric sequence are\n\\(x + 1\\), \\(x + 5\\), \\(4x - 1\\)\n\n(a) Find the two possible values of \\(x\\). [3]\n(b) For the value of \\(x\\) that is an integer, find the sum of the first 8 terms of the sequence. [2]`, marks: 5, command: 'Find', markScheme: `(a) M1: \\((x + 5)^2 = (x + 1)(4x - 1)\\) (or equates ratios)\nM1: Forms and solves \\(3x^2 - 7x - 26 = 0\\)\nA1: \\(x = -2\\) or \\(x = \\frac{13}{3}\\)\n(b) M1: \\(x = -2\\) gives \\(a = -1\\), \\(r = -3\\), and uses \\(\\frac{-1(1 - (-3)^8)}{1 - (-3)}\\)\nA1: 1640 CAO` },
      { q: `A patient takes a dose of 8 mg of a drug at the same time each day. A model assumes that 60% of the drug in the body remains one day later. The amount of drug, in mg, in the body immediately after the \\(n\\)th dose is \\(u_n\\), where\n\\(u_1 = 8\\), \\(u_{n+1} = 0.6u_n + 8\\)\n(data written for this practice question)\n\n(a) Find \\(u_3\\). [1]\n(b) The sequence converges to a limit \\(L\\). Find \\(L\\). [2]\n(c) Show that \\(u_{n+1} - L = 0.6(u_n - L)\\) and hence explain why the sequence is increasing. [2]`, marks: 5, command: 'Find', markScheme: `(a) B1: \\(u_2 = 12.8\\), \\(u_3 = 15.68\\)\n(b) M1: \\(L = 0.6L + 8\\)\nA1: \\(L = 20\\)\n(c) M1: \\(u_{n+1} - 20 = 0.6u_n + 8 - 20 = 0.6u_n - 12 = 0.6(u_n - 20)\\)\nR1: \\(u_1 \\lt 20\\) so every \\(u_n \\lt 20\\), and the gap to 20 is multiplied by 0.6 each day, so each term is closer to 20 from below, i.e. \\(u_{n+1} \\gt u_n\\)` },
      { q: `(a) Find the binomial expansion of \\(\\sqrt{1 - 2x}\\) up to and including the term in \\(x^2\\). [2]\n(b) State the range of values of \\(x\\) for which the expansion is valid. [1]\n(c) By substituting \\(x = 0.01\\) into your expansion, find an approximation for \\(\\sqrt{2}\\). Give your answer as a fraction in its simplest form. [3]`, marks: 6, command: 'Find', markScheme: `(a) M1: \\(1 + \\frac{1}{2}(-2x) + \\frac{\\frac{1}{2}(-\\frac{1}{2})}{2!}(-2x)^2\\)\nA1: \\(1 - x - \\frac{1}{2}x^2\\)\n(b) B1: \\(|x| \\lt \\frac{1}{2}\\)\n(c) M1: \\(\\sqrt{0.98} = \\sqrt{\\frac{98}{100}} = \\frac{7\\sqrt{2}}{10}\\)\nM1: \\(\\frac{7\\sqrt{2}}{10} \\approx 1 - 0.01 - 0.00005 = 0.98995\\)\nA1: \\(\\sqrt{2} \\approx \\frac{19799}{14000}\\) CAO` },
      { q: `An arithmetic series is\n\\(3 + 7 + 11 + 15 + \\ldots\\)\n\n(a) Show that the sum of the first \\(n\\) terms of the series is \\(n(2n + 1)\\). [2]\n(b) Given that the sum of the first \\(n\\) terms is 1953, find \\(n\\). [2]\n(c) Find the sum of the 10th to the 20th terms inclusive. [2]`, marks: 6, command: 'Show that', markScheme: `(a) M1: \\(\\frac{n}{2}(2 \\times 3 + 4(n - 1))\\)\nA1: \\(= \\frac{n}{2}(4n + 2) = n(2n + 1)\\) AG\n(b) M1: Solves \\(2n^2 + n - 1953 = 0\\)\nA1: \\(n = 31\\) only\n(c) M1: \\(S_{20} - S_9 = 20(41) - 9(19)\\)\nA1: 649 CAO` },
      { q: `A company buys a machine for £45 000. The value of the machine at the end of each year is modelled as being 80% of its value at the start of that year. (data written for this practice question)\n\n(a) Show that the model predicts a value of £23 040 at the end of the third year. [1]\n(b) Find the first year at the end of which the model predicts the value of the machine will be less than £5000. [3]\n(c) Comment on the suitability of the model for predicting the value of the machine after many years. [2]`, marks: 6, command: 'Find', markScheme: `(a) B1: \\(45000 \\times 0.8^3 = 23040\\) AG\n(b) M1: \\(45000 \\times 0.8^n \\lt 5000\\)\nM1: \\(n \\gt \\frac{\\ln \\frac{1}{9}}{\\ln 0.8} = 9.85\\ldots\\)\nA1: 10th year\n(c) E1: The model predicts the value never reaches zero, whereas the machine may wear out or have only a scrap value\nE1: Depreciation of 20% per year may not be constant, e.g. larger loss early on, or repairs/obsolescence may change the rate` },
      { q: `(a) Find the value of\n\\[\\sum_{r=1}^{\\infty} 5(0.4)^r\\] [2]\n(b) Find the least value of \\(n\\) for which\n\\[\\sum_{r=1}^{\\infty} 5(0.4)^r - \\sum_{r=1}^{n} 5(0.4)^r \\lt 0.001\\] [4]`, marks: 6, command: 'Find', markScheme: `(a) M1: \\(\\frac{a}{1 - r}\\) with \\(a = 2\\), \\(r = 0.4\\)\nA1: \\(\\frac{10}{3}\\)\n(b) M1: \\(\\sum_{r=1}^{n} 5(0.4)^r = \\frac{2(1 - 0.4^n)}{0.6}\\)\nA1: Difference \\(= \\frac{10}{3}(0.4)^n\\), so \\(\\frac{10}{3}(0.4)^n \\lt 0.001\\)\nM1: \\(n \\gt \\frac{\\ln 0.0003}{\\ln 0.4} = 8.85\\ldots\\)\nA1: \\(n = 9\\) CAO` },
      { q: `\\[f(x) = \\frac{5 - x}{(1 + x)(1 - 2x)}\\]\n\n(a) Express \\(f(x)\\) in the form \\(\\frac{A}{1 + x} + \\frac{B}{1 - 2x}\\), where \\(A\\) and \\(B\\) are constants. [2]\n(b) Hence find the binomial expansion of \\(f(x)\\) up to and including the term in \\(x^2\\). [3]\n(c) State the range of values of \\(x\\) for which this expansion is valid. [1]`, marks: 6, command: 'Express', markScheme: `(a) M1: \\(5 - x = A(1 - 2x) + B(1 + x)\\) and substitutes or compares coefficients\nA1: \\(A = 2\\), \\(B = 3\\)\n(b) M1: \\((1 + x)^{-1} = 1 - x + x^2\\) or \\((1 - 2x)^{-1} = 1 + 2x + 4x^2\\)\nM1: Combines \\(2(1 - x + x^2) + 3(1 + 2x + 4x^2)\\)\nA1: \\(5 + 4x + 14x^2\\)\n(c) B1: \\(|x| \\lt \\frac{1}{2}\\)` },
      { q: `An arithmetic series has first term \\(a\\) and common difference \\(d\\).\n\nThe sum of the first 10 terms of the series is four times the sum of the first 5 terms.\nThe 15th term of the series is 87.\n\nFind the sum of the first 20 terms of the series.`, marks: 6, command: 'Find', markScheme: `M1: \\(S_{10} = 5(2a + 9d)\\)\nM1: \\(5(2a + 9d) = 4 \\times \\frac{5}{2}(2a + 4d)\\)\nA1: \\(d = 2a\\)\nM1: \\(a + 14d = 87\\), substitutes to obtain \\(29a = 87\\)\nA1: \\(a = 3\\), \\(d = 6\\)\nA1: \\(S_{20} = 10(6 + 19 \\times 6) = 1200\\) CAO` },
      { q: `Sam takes out a loan of £12 000. At the end of each month, interest of 0.5% of the amount owed is added, and then Sam makes a repayment of £\\(P\\). (data written for this practice question)\n\n(a) Show that the amount owed immediately after the \\(n\\)th repayment is\n\\[12000(1.005)^n - 200P(1.005^n - 1)\\] [3]\n(b) The loan is fully repaid after 48 monthly repayments. Find \\(P\\), giving your answer to the nearest penny. [3]\n(c) State one assumption made in this model. [1]`, marks: 7, command: 'Show that', markScheme: `(a) M1: After 1 month \\(12000(1.005) - P\\); after 2 months \\(12000(1.005)^2 - 1.005P - P\\)\nM1: After \\(n\\) months \\(12000(1.005)^n - P(1 + 1.005 + \\ldots + 1.005^{n-1})\\), and uses geometric series sum \\(\\frac{1.005^n - 1}{0.005}\\)\nA1: \\(\\frac{1}{0.005} = 200\\) giving the printed result AG\n(b) M1: Sets \\(12000(1.005)^{48} - 200P(1.005^{48} - 1) = 0\\)\ndM1: Rearranges for \\(P\\)\nA1: £281.82 CAO\n(c) B1: e.g. the interest rate stays at 0.5% per month for the whole loan; Sam makes every repayment on time` },
      { q: `(a) Find the binomial expansion of \\((8 - 3x)^{\\frac{1}{3}}\\) up to and including the term in \\(x^2\\). [4]\n(b) State the range of values of \\(x\\) for which the expansion is valid. [1]\n(c) Use your expansion with \\(x = 0.01\\) to find an approximation for \\(\\sqrt[3]{7.97}\\). Give your answer to 7 decimal places. [2]`, marks: 7, command: 'Find', markScheme: `(a) B1: \\(8^{\\frac{1}{3}}\\left(1 - \\frac{3x}{8}\\right)^{\\frac{1}{3}} = 2\\left(1 - \\frac{3x}{8}\\right)^{\\frac{1}{3}}\\)\nM1: \\(1 + \\frac{1}{3}\\left(-\\frac{3x}{8}\\right) + \\frac{\\frac{1}{3}(-\\frac{2}{3})}{2!}\\left(-\\frac{3x}{8}\\right)^2\\)\nA1: \\(2 - \\frac{1}{4}x\\)\nA1: \\(- \\frac{1}{32}x^2\\)\n(b) B1: \\(|x| \\lt \\frac{8}{3}\\)\n(c) M1: \\(2 - 0.0025 - 0.000003125\\)\nA1: 1.9974969 (from 1.997496875)` },
      { q: `Ruth pays £1000 into a savings account at the start of each year. The account pays compound interest of 3% per year, added at the end of each year. She makes no withdrawals. (data written for this practice question)\n\n(a) Show that the amount in the account at the end of the second year is £2090.90 [2]\n(b) Show that the amount in the account at the end of the \\(n\\)th year is\n\\[\\frac{103000}{3}(1.03^n - 1)\\] [2]\n(c) Find the first year at the end of which the amount in the account is more than £20 000. [2]\n(d) State one limitation of this model. [1]`, marks: 7, command: 'Show that', markScheme: `(a) M1: \\((1000 \\times 1.03 + 1000) \\times 1.03\\)\nA1: £2090.90 AG\n(b) M1: \\(1000(1.03 + 1.03^2 + \\ldots + 1.03^n)\\), geometric with \\(a = 1030\\), \\(r = 1.03\\)\nA1: \\(\\frac{1030(1.03^n - 1)}{0.03} = \\frac{103000}{3}(1.03^n - 1)\\) AG\n(c) M1: \\(1.03^n \\gt 1 + \\frac{60000}{103000}\\), \\(n \\gt 15.5\\ldots\\)\nA1: 16th year\n(d) E1: e.g. interest rate unlikely to stay at 3%; Ruth may not be able to pay £1000 every year` },
      { q: `(a) Find the first four terms, in ascending powers of \\(x\\), of the binomial expansion of \\(\\left(1 + \\frac{x}{2}\\right)^{10}\\). Give each term in its simplest form. [3]\n(b) In the expansion of \\((a + bx)\\left(1 + \\frac{x}{2}\\right)^{10}\\), where \\(a\\) and \\(b\\) are constants, the coefficient of \\(x\\) is 0 and the coefficient of \\(x^2\\) is \\(-55\\).\nFind the values of \\(a\\) and \\(b\\). [4]`, marks: 7, command: 'Find', markScheme: `(a) M1: Correct structure, e.g. \\(\\binom{10}{2}\\left(\\frac{x}{2}\\right)^2\\)\nA1: \\(1 + 5x\\)\nA1: \\(+ \\frac{45}{4}x^2 + 15x^3\\)\n(b) M1: Coefficient of \\(x\\): \\(5a + b = 0\\)\nM1: Coefficient of \\(x^2\\): \\(\\frac{45}{4}a + 5b = -55\\)\ndM1: Solves simultaneously\nA1: \\(a = 4\\), \\(b = -20\\)` },
      { q: `A ball is dropped from a height of 2 m onto horizontal ground. A model assumes that after each bounce the ball rises to \\(\\frac{3}{4}\\) of the height from which it last fell. (data written for this practice question)\n\n(a) Show that the model predicts that the ball rises to a height of \\(\\frac{27}{32}\\) m after the third bounce. [1]\n(b) Find the total vertical distance travelled by the ball from when it is dropped until it hits the ground for the 6th time. Give your answer to 3 significant figures. [3]\n(c) Show that, according to the model, the total vertical distance travelled by the ball can never exceed 14 m. [3]\n(d) Comment on the model's prediction of how many times the ball bounces. [1]`, marks: 8, command: 'Show that', markScheme: `(a) B1: \\(2 \\times \\left(\\frac{3}{4}\\right)^3 = \\frac{54}{64} = \\frac{27}{32}\\) AG\n(b) M1: Five rebounds before the 6th impact; each travelled up and down: \\(2 + 2\\sum_{k=1}^{5} 2\\left(\\frac{3}{4}\\right)^k\\)\nM1: Uses geometric sum: \\(\\frac{1.5(1 - 0.75^5)}{0.25} = 4.576\\ldots\\)\nA1: 11.2 m (AWRT 11.2)\n(c) M1: Uses sum to infinity of the rebound heights: \\(\\frac{1.5}{1 - 0.75} = 6\\)\nM1: Total \\(= 2 + 2 \\times 6\\)\nA1: \\(= 14\\), and partial sums are always less than the sum to infinity, so the distance never exceeds 14 m\n(d) E1: The model predicts the ball bounces infinitely many times, which is unrealistic; in reality it stops bouncing after a finite number of bounces` },
      { q: `(a) Find the binomial expansion of \\((4 - x)^{-\\frac{1}{2}}\\) up to and including the term in \\(x^2\\). [4]\n(b) Hence find the expansion of\n\\[\\frac{3 + x}{\\sqrt{4 - x}}\\]\nup to and including the term in \\(x^2\\). [2]\n(c) State the range of values of \\(x\\) for which the expansion is valid. [1]\n(d) Explain why your expansion should not be used to find an approximate value of \\(\\frac{3 + x}{\\sqrt{4 - x}}\\) when \\(x = 5\\). [1]`, marks: 8, command: 'Find', markScheme: `(a) B1: \\(4^{-\\frac{1}{2}}\\left(1 - \\frac{x}{4}\\right)^{-\\frac{1}{2}} = \\frac{1}{2}\\left(1 - \\frac{x}{4}\\right)^{-\\frac{1}{2}}\\)\nM1: \\(1 + \\left(-\\frac{1}{2}\\right)\\left(-\\frac{x}{4}\\right) + \\frac{(-\\frac{1}{2})(-\\frac{3}{2})}{2!}\\left(-\\frac{x}{4}\\right)^2\\)\nA1: \\(\\frac{1}{2} + \\frac{1}{16}x\\)\nA1: \\(+ \\frac{3}{256}x^2\\)\n(b) M1: \\((3 + x)\\left(\\frac{1}{2} + \\frac{1}{16}x + \\frac{3}{256}x^2\\right)\\)\nA1: \\(\\frac{3}{2} + \\frac{11}{16}x + \\frac{25}{256}x^2\\)\n(c) B1: \\(|x| \\lt 4\\)\n(d) E1: \\(x = 5\\) is outside the range of validity \\(|x| \\lt 4\\) (and \\(\\sqrt{4 - 5}\\) is not real)` },
      { q: `Jo is offered two jobs. (data written for this practice question)\n\nJob A: a salary of £24 000 in the first year, increasing by £1200 each year.\nJob B: a salary of £22 000 in the first year, increasing by 6% each year.\n\n(a) Show that in the 5th year, Job A pays a higher salary than Job B. [2]\n(b) Find the first year in which the salary for Job B is greater than the salary for Job A. [3]\n(c) Determine which job gives the greater total salary over the first 10 years, and by how much. Give your answer to the nearest pound. [3]\n(d) Give one reason why the model for Job B may not be realistic over a long period. [1]`, marks: 9, command: 'Show that', markScheme: `(a) M1: \\(24000 + 4 \\times 1200 = 28800\\) and \\(22000 \\times 1.06^4\\)\nA1: \\(22000 \\times 1.06^4 = 27774.49\\ldots\\), which is less than 28800\n(b) M1: Compares \\(24000 + 1200(n - 1)\\) with \\(22000 \\times 1.06^{n-1}\\)\nM1: Evaluates for year 6 (30000 and 29440.96) and year 7 (31200 and 31207.42)\nA1: Year 7\n(c) M1: Job A: \\(\\frac{10}{2}(48000 + 9 \\times 1200) = 294000\\)\nM1: Job B: \\(\\frac{22000(1.06^{10} - 1)}{0.06} = 289977.49\\ldots\\)\nA1: Job A, by £4023 (AWRT)\n(d) E1: e.g. a 6% rise every year is unlikely to continue; salary increases depend on inflation/promotion; salary would grow without limit` },
      { q: `A lake is stocked with fish. At the start of each year 500 fish are added, and a model assumes that during each year 10% of the fish present at the start of that year are lost. The number of fish at the start of year \\(n\\), just after the new fish are added, is \\(u_n\\), where\n\\(u_1 = 2000\\), \\(u_{n+1} = 0.9u_n + 500\\)\n(data written for this practice question)\n\n(a) Find \\(u_2\\) and \\(u_3\\). [2]\n(b) Verify that \\(u_n = 5000 - 3000(0.9)^{n-1}\\) satisfies both \\(u_1 = 2000\\) and \\(u_{n+1} = 0.9u_n + 500\\). [3]\n(c) Find the first year in which the number of fish is greater than 4500. [3]\n(d) State the number of fish that the model predicts in the long term. [1]\n(e) State one limitation of the model. [1]`, marks: 10, command: 'Verify', markScheme: `(a) B1: \\(u_2 = 2300\\)\nB1: \\(u_3 = 2570\\)\n(b) B1: \\(u_1 = 5000 - 3000(0.9)^0 = 2000\\)\nM1: \\(0.9u_n + 500 = 0.9(5000 - 3000(0.9)^{n-1}) + 500 = 4500 - 3000(0.9)^n + 500\\)\nA1: \\(= 5000 - 3000(0.9)^n = u_{n+1}\\), with a concluding statement\n(c) M1: \\(5000 - 3000(0.9)^{n-1} \\gt 4500\\), i.e. \\((0.9)^{n-1} \\lt \\frac{1}{6}\\)\nM1: \\(n - 1 \\gt \\frac{\\ln \\frac{1}{6}}{\\ln 0.9} = 17.006\\ldots\\)\nA1: Year 19\n(d) B1: 5000 fish\n(e) E1: e.g. the loss rate may vary from year to year; the lake may have a maximum capacity; fish breeding is ignored` }
    ]
  },
  '1.5': {
    name: 'Trigonometry',
    questions: [
      { q: `Given that \\(\\theta\\) is small and measured in radians, show that\n\\(3 - 2\\cos\\theta + \\theta\\sin\\theta \\approx 1 + 2\\theta^2\\)`, marks: 2, command: 'Show that', markScheme: `M1: Uses \\(\\cos\\theta \\approx 1 - \\frac{\\theta^2}{2}\\) and \\(\\sin\\theta \\approx \\theta\\) in the expression\nA1: \\(3 - 2 + \\theta^2 + \\theta^2 = 1 + 2\\theta^2\\) AG, convincingly shown with no errors\nCondone \\(\\approx\\) written as \\(=\\) once.` },
      { q: `A sector of a circle has radius 5 cm and area 15 cm².\n\nFind the angle of the sector in radians.`, marks: 2, command: 'Find', markScheme: `M1: \\(\\frac{1}{2} \\times 5^2 \\times \\theta = 15\\)\nA1: \\(\\theta = 1.2\\) CAO\nAn answer in degrees only scores M1 A0.` },
      { q: `Given that \\(\\cos x = -\\frac{1}{3}\\) and that \\(x\\) is obtuse, find the exact value of \\(\\tan x\\).\n\nDo not use a calculator.`, marks: 2, command: 'Find', markScheme: `M1: Finds \\(\\sin x = \\frac{\\sqrt{8}}{3}\\) or \\(\\frac{2\\sqrt{2}}{3}\\), e.g. from \\(\\sin^2 x + \\cos^2 x = 1\\) or a right-angled triangle with sides 1, \\(\\sqrt{8}\\), 3\nA1: \\(\\tan x = -2\\sqrt{2}\\) (accept \\(-\\sqrt{8}\\)) CAO; positive answer scores A0` },
      { q: `Find the exact value of \\(\\arcsin\\left(-\\frac{\\sqrt{3}}{2}\\right) + \\arccos\\left(\\frac{1}{2}\\right)\\).\n\nDo not use a calculator.`, marks: 2, command: 'Find', markScheme: `B1: \\(\\arcsin\\left(-\\frac{\\sqrt{3}}{2}\\right) = -\\frac{\\pi}{3}\\) (principal value)\nB1: \\(\\arccos\\frac{1}{2} = \\frac{\\pi}{3}\\) and total \\(= 0\\) CAO` },
      { q: `In triangle \\(ABC\\), \\(AB = 10\\) cm, \\(BC = 7\\) cm and angle \\(BAC = 40°\\).\n\nFind the two possible values of angle \\(ACB\\), giving your answers to one decimal place.`, marks: 3, command: 'Find', markScheme: `M1: Sine rule \\(\\frac{\\sin C}{10} = \\frac{\\sin 40°}{7}\\), so \\(\\sin C = 0.9183\\ldots\\)\nA1: \\(C = 66.7°\\) AWRT\nA1: \\(C = 113.3°\\) AWRT (from \\(180° - 66.7°\\))` },
      { q: `A gardener marks out a triangular flower bed. Two of its sides are 12 m and 15 m long and the angle between them is obtuse. The area of the bed is 80 m².\n(data written for this practice question)\n\nFind the angle between the two given sides, giving your answer to the nearest 0.1°.`, marks: 3, command: 'Find', markScheme: `M1: \\(\\frac{1}{2} \\times 12 \\times 15 \\sin\\theta = 80\\)\nA1: \\(\\sin\\theta = \\frac{8}{9}\\) (0.888…)\nA1: \\(\\theta = 117.3°\\) AWRT (obtuse value); 62.7° alone scores A0` },
      { q: `Prove that \\(\\sec^2 x + \\csc^2 x \\equiv \\sec^2 x \\csc^2 x\\)`, marks: 3, command: 'Prove', markScheme: `M1: Writes LHS as \\(\\frac{1}{\\cos^2 x} + \\frac{1}{\\sin^2 x}\\)\nM1: Combines over common denominator \\(\\frac{\\sin^2 x + \\cos^2 x}{\\sin^2 x \\cos^2 x}\\)\nA1: Uses \\(\\sin^2 x + \\cos^2 x = 1\\) to obtain \\(\\frac{1}{\\sin^2 x\\cos^2 x} = \\sec^2 x \\csc^2 x\\); fully correct argument with conclusion` },
      { q: `Use small-angle approximations to find the value of\n\\(\\frac{1 - \\cos 4\\theta}{\\theta\\tan 3\\theta}\\)\nwhen \\(\\theta\\) is small and non-zero.`, marks: 3, command: 'Use', markScheme: `M1: \\(1 - \\cos 4\\theta \\approx 1 - \\left(1 - \\frac{(4\\theta)^2}{2}\\right) = 8\\theta^2\\)\nM1: \\(\\tan 3\\theta \\approx 3\\theta\\), so denominator \\(\\approx 3\\theta^2\\)\nA1: \\(\\frac{8}{3}\\) CAO` },
      { q: `The curve \\(y = 2\\cos\\left(x + \\frac{\\pi}{4}\\right) - 1\\) is defined for \\(0 \\leq x \\leq 2\\pi\\).\n\nFind the exact coordinates of the maximum point and of the minimum point of the curve.`, marks: 3, command: 'Find', markScheme: `B1: Maximum at \\(x = \\frac{7\\pi}{4}\\) (where \\(x + \\frac{\\pi}{4} = 2\\pi\\))\nB1: Minimum at \\(x = \\frac{3\\pi}{4}\\) (where \\(x + \\frac{\\pi}{4} = \\pi\\))\nB1: \\(\\left(\\frac{7\\pi}{4}, 1\\right)\\) and \\(\\left(\\frac{3\\pi}{4}, -3\\right)\\) — both \\(y\\)-values correct` },
      { q: `Solve the equation\n\\(\\tan(2\\theta - 30°) = 1\\)\nfor \\(0° \\leq \\theta \\leq 180°\\).`, marks: 3, command: 'Solve', markScheme: `M1: \\(2\\theta - 30° = 45°\\) (and considers range \\(-30° \\leq 2\\theta - 30° \\leq 330°\\))\nA1: \\(\\theta = 37.5°\\)\nA1: \\(\\theta = 127.5°\\), and no extra values in range` },
      { q: `A car windscreen wiper consists of an arm \\(OB\\) of length 50 cm that rotates about \\(O\\). The rubber blade is fixed along the arm from a point 15 cm from \\(O\\) to the end \\(B\\). On each sweep the arm turns through an angle of \\(\\frac{2\\pi}{3}\\) radians.\n(data written for this practice question)\n\nFind the area of windscreen cleaned by the blade on one sweep. Give your answer to 3 significant figures.`, marks: 3, command: 'Find', markScheme: `M1: Uses \\(\\frac{1}{2}r^2\\theta\\) with \\(\\theta = \\frac{2\\pi}{3}\\) for \\(r = 50\\) or \\(r = 15\\)\nM1: Subtracts: \\(\\frac{1}{2}(50^2 - 15^2) \\times \\frac{2\\pi}{3}\\)\nA1: \\(2380\\) cm² AWRT (exact \\(\\frac{2275\\pi}{3}\\))` },
      { q: `A ship leaves port \\(O\\) and sails 12 km on a bearing of 040° to a point \\(P\\). It then sails 8 km on a bearing of 110° to a point \\(Q\\).\n\nFind the distance \\(OQ\\), giving your answer to 3 significant figures.`, marks: 4, command: 'Find', markScheme: `M1: Attempts angle \\(OPQ\\) using bearings (e.g. back bearing 220° minus 110°)\nA1: Angle \\(OPQ = 110°\\)\nM1: Cosine rule \\(OQ^2 = 12^2 + 8^2 - 2(12)(8)\\cos 110°\\)\nA1: \\(OQ = 16.5\\) km AWRT` },
      { q: `Without using a calculator, show that \\(\\tan 15° = 2 - \\sqrt{3}\\)`, marks: 4, command: 'Show that', markScheme: `M1: Writes \\(\\tan 15° = \\tan(45° - 30°) = \\frac{\\tan 45° - \\tan 30°}{1 + \\tan 45° \\tan 30°}\\)\nA1: \\(= \\frac{1 - \\frac{1}{\\sqrt{3}}}{1 + \\frac{1}{\\sqrt{3}}} = \\frac{\\sqrt{3} - 1}{\\sqrt{3} + 1}\\)\nM1: Rationalises the denominator: multiplies by \\(\\frac{\\sqrt{3} - 1}{\\sqrt{3} - 1}\\)\nA1: \\(\\frac{4 - 2\\sqrt{3}}{2} = 2 - \\sqrt{3}\\) AG, all steps shown\nAlternative via \\(\\tan(60° - 45°)\\) scores equivalently.` },
      { q: `(a) Sketch the graph of \\(y = \\arccos x\\), stating the coordinates of its end points. [2]\n(b) Solve the equation \\(\\arccos(2x - 1) = \\frac{2\\pi}{3}\\) [2]`, marks: 4, command: 'Sketch', diagram: true, markScheme: `(a)\nB1: Decreasing curve defined only for \\(-1 \\leq x \\leq 1\\), passing through \\(\\left(0, \\frac{\\pi}{2}\\right)\\)\nB1: End points \\((-1, \\pi)\\) and \\((1, 0)\\) stated\n(b)\nM1: \\(2x - 1 = \\cos\\frac{2\\pi}{3} = -\\frac{1}{2}\\)\nA1: \\(x = \\frac{1}{4}\\) CAO` },
      { q: `(a) Given that \\(\\theta\\) is small, show that \\(4\\cos 3\\theta + 2\\sin\\theta - 3 \\approx 1 + 2\\theta - 18\\theta^2\\) [2]\n(b) Hence find an approximate value of \\(4\\cos 0.3 + 2\\sin 0.1 - 3\\) and find the percentage error in this approximation. Give the percentage error to 2 significant figures. [2]`, marks: 4, command: 'Show that', markScheme: `(a)\nM1: Uses \\(\\cos 3\\theta \\approx 1 - \\frac{9\\theta^2}{2}\\) and \\(\\sin\\theta \\approx \\theta\\)\nA1: \\(4 - 18\\theta^2 + 2\\theta - 3 = 1 + 2\\theta - 18\\theta^2\\) AG\n(b)\nB1: \\(\\theta = 0.1\\) gives approximation \\(1.02\\)\nB1: True value 1.02101…, percentage error \\(\\frac{1.02101 - 1.02}{1.02101} \\times 100 = 0.099\\%\\) AWRT 0.099 (condone 0.1)` },
      { q: `Prove that\n\\(\\frac{\\cos x}{1 - \\sin x} - \\tan x \\equiv \\sec x\\)`, marks: 4, command: 'Prove', markScheme: `M1: Writes \\(\\tan x = \\frac{\\sin x}{\\cos x}\\) and combines into a single fraction over \\(\\cos x(1 - \\sin x)\\)\nA1: Numerator \\(\\cos^2 x - \\sin x + \\sin^2 x\\)\nM1: Uses \\(\\sin^2 x + \\cos^2 x = 1\\) to get \\(\\frac{1 - \\sin x}{\\cos x(1 - \\sin x)}\\)\nA1: Cancels to \\(\\frac{1}{\\cos x} = \\sec x\\); complete and rigorous with conclusion` },
      { q: `Solve the equation\n\\(\\cos 2x = 3\\sin x - 1\\)\nfor \\(0 \\leq x \\leq 2\\pi\\), giving your answers in exact form.`, marks: 4, command: 'Solve', markScheme: `M1: Uses \\(\\cos 2x = 1 - 2\\sin^2 x\\) to form a quadratic in \\(\\sin x\\)\nA1: \\(2\\sin^2 x + 3\\sin x - 2 = 0\\)\nM1: Factorises \\((2\\sin x - 1)(\\sin x + 2) = 0\\) and rejects \\(\\sin x = -2\\)\nA1: \\(x = \\frac{\\pi}{6}, \\frac{5\\pi}{6}\\) only` },
      { q: `The height above the ground, \\(h\\) metres, of a passenger on a Ferris wheel is modelled by\n\\(h = 18 - 16\\cos\\left(\\frac{\\pi t}{10}\\right)\\)\nwhere \\(t\\) is the time in minutes after the passenger boards.\n(model written for this practice question)\n\n(a) State the maximum height of the passenger and the time taken for one complete revolution. [2]\n(b) Find the time after boarding when the passenger first reaches a height of 26 m. Give your answer in minutes and seconds. [2]`, marks: 4, command: 'Find', markScheme: `(a)\nB1: Maximum height 34 m\nB1: One revolution takes 20 minutes\n(b)\nM1: \\(\\cos\\left(\\frac{\\pi t}{10}\\right) = -\\frac{1}{2}\\) so \\(\\frac{\\pi t}{10} = \\frac{2\\pi}{3}\\)\nA1: \\(t = \\frac{20}{3}\\) minutes = 6 minutes 40 seconds` },
      { q: `The points \\(A\\) and \\(B\\) lie on a circle with centre \\(O\\) and radius 8 cm. The angle \\(AOB\\) is 1.2 radians.\n\nFind the area of the minor segment cut off by the chord \\(AB\\). Give your answer to 3 significant figures.`, marks: 4, command: 'Find', markScheme: `M1: Sector area \\(\\frac{1}{2} \\times 8^2 \\times 1.2 = 38.4\\)\nM1: Triangle area \\(\\frac{1}{2} \\times 8^2 \\sin 1.2\\) (= 29.8…)\ndM1: Subtracts triangle from sector\nA1: \\(8.57\\) cm² AWRT\nUsing \\(\\sin 1.2°\\) scores M1 M0 dM1 A0.` },
      { q: `Solve the equation\n\\(3\\sec^2\\theta - 5\\tan\\theta - 5 = 0\\)\nfor \\(0° \\leq \\theta \\leq 360°\\), giving your answers to the nearest 0.1°.`, marks: 5, command: 'Solve', markScheme: `M1: Uses \\(\\sec^2\\theta = 1 + \\tan^2\\theta\\)\nA1: \\(3\\tan^2\\theta - 5\\tan\\theta - 2 = 0\\)\nM1: Solves: \\((3\\tan\\theta + 1)(\\tan\\theta - 2) = 0\\), \\(\\tan\\theta = 2\\) or \\(-\\frac{1}{3}\\)\nA1: \\(\\theta = 63.4°, 243.4°\\)\nA1: \\(\\theta = 161.6°, 341.6°\\)\nDeduct final A1 for extra values in range.` },
      { q: `(a) Express \\(5\\sin x - 12\\cos x\\) in the form \\(R\\sin(x - \\alpha)\\), where \\(R \\gt 0\\) and \\(0° \\lt \\alpha \\lt 90°\\). Give \\(\\alpha\\) to 2 decimal places. [3]\n(b) Hence find the minimum value of\n\\(\\frac{20}{15 + 5\\sin x - 12\\cos x}\\)\nand the value of \\(x\\) in the interval \\(0° \\leq x \\leq 360°\\) at which it occurs. [2]`, marks: 5, command: 'Express', markScheme: `(a)\nB1: \\(R = 13\\)\nM1: \\(\\tan\\alpha = \\frac{12}{5}\\)\nA1: \\(\\alpha = 67.38°\\) AWRT\n(b)\nB1ft: Minimum value \\(\\frac{20}{28} = \\frac{5}{7}\\)\nB1ft: \\(x - 67.38° = 90°\\), so \\(x = 157.38°\\) AWRT 157.4°` },
      { q: `Two points \\(A\\) and \\(B\\) are 50 m apart on level ground, in a straight line with the foot \\(F\\) of a vertical tower \\(FT\\). \\(B\\) is between \\(A\\) and \\(F\\). The angle of elevation of the top \\(T\\) of the tower from \\(A\\) is 28° and from \\(B\\) is 41°.\n(data written for this practice question)\n\nFind the height of the tower, giving your answer to 3 significant figures.`, marks: 5, command: 'Find', markScheme: `B1: Angle \\(ATB = 13°\\) (or angle \\(ABT = 139°\\))\nM1: Sine rule in triangle \\(ABT\\): \\(\\frac{BT}{\\sin 28°} = \\frac{50}{\\sin 13°}\\)\nA1: \\(BT = 104.3\\ldots\\) m\nM1: Height \\(= BT\\sin 41°\\)\nA1: \\(68.5\\) m AWRT` },
      { q: `Find all the solutions of\n\\(\\sin 2\\theta = \\sin\\theta\\)\nin the interval \\(-\\pi \\leq \\theta \\leq \\pi\\), giving your answers in exact form.\n\nYou must show detailed reasoning.`, marks: 5, command: 'Find', markScheme: `M1: Uses \\(\\sin 2\\theta = 2\\sin\\theta\\cos\\theta\\)\nM1: Factorises \\(\\sin\\theta(2\\cos\\theta - 1) = 0\\) (dividing by \\(\\sin\\theta\\) loses roots: M0)\nA1: \\(\\sin\\theta = 0\\) or \\(\\cos\\theta = \\frac{1}{2}\\)\nA1: \\(\\theta = -\\pi, 0, \\pi\\)\nA1: \\(\\theta = -\\frac{\\pi}{3}, \\frac{\\pi}{3}\\)` },
      { q: `The depth of water, \\(D\\) metres, at the entrance to a harbour is modelled by\n\\(D = 5 + 3\\sin(0.5t)\\)\nwhere \\(t\\) is the number of hours after midnight and \\(0.5t\\) is in radians.\n(model written for this practice question)\n\n(a) Find the minimum depth of water and the time, to the nearest minute, at which it first occurs after midnight. [2]\n(b) A boat can only enter the harbour when the depth of water is at least 6.5 m. Find the first period of time after midnight during which the boat can enter. Give times to the nearest minute. [3]`, marks: 5, command: 'Find', markScheme: `(a)\nB1: Minimum depth 2 m\nB1: \\(0.5t = \\frac{3\\pi}{2}\\), \\(t = 3\\pi = 9.42\\) h, i.e. 09:25 (condone 09:26)\n(b)\nM1: \\(\\sin(0.5t) \\geq \\frac{1}{2}\\)\nA1: \\(\\frac{\\pi}{6} \\leq 0.5t \\leq \\frac{5\\pi}{6}\\), so \\(\\frac{\\pi}{3} \\leq t \\leq \\frac{5\\pi}{3}\\)\nA1: From 01:03 to 05:14` },
      { q: `(a) Show that the equation\n\\(\\sin(x + 60°) = 2\\sin x\\)\ncan be written as \\(\\tan x = \\frac{1}{\\sqrt{3}}\\) [3]\n(b) Hence solve \\(\\sin(x + 60°) = 2\\sin x\\) for \\(0° \\leq x \\leq 360°\\) [2]`, marks: 5, command: 'Show that', markScheme: `(a)\nM1: Expands \\(\\sin x\\cos 60° + \\cos x\\sin 60°\\)\nA1: \\(\\frac{1}{2}\\sin x + \\frac{\\sqrt{3}}{2}\\cos x = 2\\sin x\\)\nA1: \\(\\frac{\\sqrt{3}}{2}\\cos x = \\frac{3}{2}\\sin x\\), so \\(\\tan x = \\frac{\\sqrt{3}}{3} = \\frac{1}{\\sqrt{3}}\\) AG\n(b)\nB1: \\(x = 30°\\)\nB1: \\(x = 210°\\), no extras` },
      { q: `A flower bed is in the shape of a sector of a circle with radius \\(r\\) metres and angle \\(\\theta\\) radians. The bed has a perimeter of 20 m and an area of 16 m².\n(data written for this practice question)\n\nFind the value of \\(r\\) and the value of \\(\\theta\\). Fully justify your answer.`, marks: 5, command: 'Find', markScheme: `B1: Forms both equations \\(2r + r\\theta = 20\\) and \\(\\frac{1}{2}r^2\\theta = 16\\)\nM1: Eliminates \\(\\theta\\), e.g. \\(\\frac{1}{2}r(20 - 2r) = 16\\)\nA1: \\(r^2 - 10r + 16 = 0\\), so \\(r = 2\\) or \\(r = 8\\)\nE1: Rejects \\(r = 2\\) because it gives \\(\\theta = 8\\), which is greater than \\(2\\pi\\)\nA1: \\(r = 8\\), \\(\\theta = 0.5\\)` },
      { q: `(a) Prove that \\(\\frac{1 + \\cos 2x}{\\sin 2x} \\equiv \\cot x\\) [3]\n(b) Hence solve the equation\n\\(\\frac{1 + \\cos 2x}{\\sin 2x} = 3\\tan x\\)\nfor \\(0 \\lt x \\lt \\pi\\), giving your answers in exact form. [3]`, marks: 6, command: 'Prove', markScheme: `(a)\nM1: Uses \\(\\cos 2x = 2\\cos^2 x - 1\\) in the numerator\nM1: Uses \\(\\sin 2x = 2\\sin x\\cos x\\)\nA1: \\(\\frac{2\\cos^2 x}{2\\sin x\\cos x} = \\frac{\\cos x}{\\sin x} = \\cot x\\); complete proof\n(b)\nM1: \\(\\cot x = 3\\tan x\\), so \\(\\tan^2 x = \\frac{1}{3}\\)\nA1: \\(\\tan x = \\pm\\frac{1}{\\sqrt{3}}\\)\nA1: \\(x = \\frac{\\pi}{6}, \\frac{5\\pi}{6}\\) CAO` },
      { q: `In triangle \\(ABC\\), \\(AB = x\\) cm, \\(AC = (x + 3)\\) cm, \\(BC = 7\\) cm and angle \\(BAC = 60°\\).\n\nFind the exact area of triangle \\(ABC\\).`, marks: 6, command: 'Find', markScheme: `M1: Cosine rule \\(7^2 = x^2 + (x + 3)^2 - 2x(x + 3)\\cos 60°\\)\nA1: \\(49 = x^2 + 3x + 9\\), so \\(x^2 + 3x - 40 = 0\\)\nM1: Solves: \\((x + 8)(x - 5) = 0\\)\nA1: \\(x = 5\\) (rejecting \\(x = -8\\) as a length cannot be negative)\nM1: Area \\(= \\frac{1}{2} \\times 5 \\times 8 \\times \\sin 60°\\)\nA1: \\(10\\sqrt{3}\\) cm² CAO` },
      { q: `The temperature, \\(T\\) °C, inside a greenhouse is modelled by\n\\(T = 12 - 3\\cos\\left(\\frac{\\pi t}{12}\\right) - 4\\sin\\left(\\frac{\\pi t}{12}\\right)\\)\nwhere \\(t\\) is the number of hours after midnight, \\(0 \\leq t \\lt 24\\).\n(model written for this practice question)\n\n(a) Express \\(3\\cos\\left(\\frac{\\pi t}{12}\\right) + 4\\sin\\left(\\frac{\\pi t}{12}\\right)\\) in the form \\(R\\cos\\left(\\frac{\\pi t}{12} - \\alpha\\right)\\), where \\(R \\gt 0\\) and \\(0 \\lt \\alpha \\lt \\frac{\\pi}{2}\\). Give \\(\\alpha\\) to 4 decimal places. [3]\n(b) Hence find the maximum temperature predicted by the model and the time of day at which it occurs. [2]\n(c) Comment on the suitability of using this model to predict the temperature in the greenhouse every day for a year. [1]`, marks: 6, command: 'Express', markScheme: `(a)\nB1: \\(R = 5\\)\nM1: \\(\\tan\\alpha = \\frac{4}{3}\\)\nA1: \\(\\alpha = 0.9273\\) AWRT\n(b)\nB1ft: Maximum \\(T = 12 + 5 = 17\\) °C\nB1: \\(\\frac{\\pi t}{12} - 0.9273 = \\pi\\), \\(t = 15.54\\), i.e. AWRT 15:32 or 15:33\n(c)\nE1: e.g. Not suitable: the model gives the same pattern every day, but temperatures change with the seasons and the weather (cloud cover)` },
      { q: `(a) Prove that \\(\\cos 3\\theta \\equiv 4\\cos^3\\theta - 3\\cos\\theta\\) [4]\n(b) Hence solve \\(8\\cos^3\\theta - 6\\cos\\theta = 1\\) for \\(0° \\leq \\theta \\leq 180°\\) [2]`, marks: 6, command: 'Prove', markScheme: `(a)\nM1: Writes \\(\\cos 3\\theta = \\cos(2\\theta + \\theta) = \\cos 2\\theta\\cos\\theta - \\sin 2\\theta\\sin\\theta\\)\nM1: Substitutes \\(\\cos 2\\theta = 2\\cos^2\\theta - 1\\) and \\(\\sin 2\\theta = 2\\sin\\theta\\cos\\theta\\)\nM1: Uses \\(\\sin^2\\theta = 1 - \\cos^2\\theta\\)\nA1: \\(2\\cos^3\\theta - \\cos\\theta - 2\\cos\\theta + 2\\cos^3\\theta = 4\\cos^3\\theta - 3\\cos\\theta\\); complete proof\n(b)\nM1: \\(\\cos 3\\theta = \\frac{1}{2}\\), \\(3\\theta = 60°, 300°, 420°\\)\nA1: \\(\\theta = 20°, 100°, 140°\\) and no others` },
      { q: `The curve \\(y = a\\sin(bx) + c\\), where \\(a\\), \\(b\\) and \\(c\\) are positive constants, has a maximum point at \\(\\left(\\frac{\\pi}{8}, 7\\right)\\). The next minimum point to the right of this is \\(\\left(\\frac{3\\pi}{8}, 1\\right)\\).\n\n(a) Find the values of \\(a\\), \\(b\\) and \\(c\\). [4]\n(b) Sketch the curve for \\(0 \\leq x \\leq \\frac{\\pi}{2}\\), stating the coordinates of the points where it meets the \\(y\\)-axis and the line \\(x = \\frac{\\pi}{2}\\). [2]`, marks: 6, command: 'Find', diagram: true, markScheme: `(a)\nB1: \\(c = 4\\) (mid-value of 7 and 1)\nB1: \\(a = 3\\)\nM1: Half period \\(= \\frac{3\\pi}{8} - \\frac{\\pi}{8} = \\frac{\\pi}{4}\\), so period \\(\\frac{\\pi}{2} = \\frac{2\\pi}{b}\\)\nA1: \\(b = 4\\) (check: \\(\\sin\\left(4 \\times \\frac{\\pi}{8}\\right) = 1\\))\n(b)\nB1ft: One complete sine wave rising from \\((0, 4)\\) to max \\(\\left(\\frac{\\pi}{8}, 7\\right)\\), down to min \\(\\left(\\frac{3\\pi}{8}, 1\\right)\\)\nB1: \\((0, 4)\\) and \\(\\left(\\frac{\\pi}{2}, 4\\right)\\) stated` },
      { q: `A lawn is to be laid in the shape of a sector of a circle of radius \\(r\\) metres and angle \\(\\theta\\) radians. The perimeter of the lawn must be 40 m, the length of edging available.\n(data written for this practice question)\n\nFind the maximum possible area of the lawn and the corresponding value of \\(\\theta\\). Fully justify your answer.`, marks: 6, command: 'Find', markScheme: `M1: Perimeter \\(2r + r\\theta = 40\\), so \\(r\\theta = 40 - 2r\\)\nM1: Area \\(A = \\frac{1}{2}r^2\\theta = \\frac{1}{2}r(40 - 2r)\\)\nA1: \\(A = 20r - r^2\\)\nM1: Completes the square, \\(A = 100 - (r - 10)^2\\) (or differentiates and sets \\(20 - 2r = 0\\))\nA1: Maximum area 100 m² when \\(r = 10\\), justified (square term ≥ 0, or \\(A'' = -2 \\lt 0\\))\nA1: \\(\\theta = \\frac{40 - 20}{10} = 2\\) radians` },
      { q: `By first expressing \\(7\\sin x + 24\\cos x\\) in the form \\(R\\sin(x + \\alpha)\\), where \\(R \\gt 0\\) and \\(0° \\lt \\alpha \\lt 90°\\), solve the equation\n\\(7\\sin x + 24\\cos x = 15\\)\nfor \\(0° \\leq x \\leq 360°\\). Give your answers to one decimal place.`, marks: 7, command: 'Solve', markScheme: `B1: \\(R = 25\\)\nM1: \\(\\tan\\alpha = \\frac{24}{7}\\)\nA1: \\(\\alpha = 73.74°\\) AWRT\nM1: \\(\\sin(x + 73.74°) = \\frac{15}{25} = 0.6\\)\nM1: Considers the range \\(73.74° \\leq x + \\alpha \\leq 433.74°\\): \\(x + \\alpha = 143.13°, 396.87°\\)\nA1: \\(x = 69.4°\\)\nA1: \\(x = 323.1°\\), no extra values` },
      { q: `A large observation wheel has radius 60 m and its centre is 65 m above the ground. It rotates at a constant speed, completing one revolution every 30 minutes. A passenger boards at the lowest point at time \\(t = 0\\). The height, \\(h\\) metres, of the passenger above the ground is modelled by\n\\(h = 65 - 60\\cos\\left(\\frac{\\pi t}{15}\\right)\\)\nwhere \\(t\\) is in minutes.\n(model written for this practice question)\n\n(a) Find the height of the passenger 10 minutes after boarding. [2]\n(b) Find the length of time, during one revolution, for which the passenger is more than 100 m above the ground. Give your answer to the nearest tenth of a minute. [4]\n(c) State one limitation of the model. [1]`, marks: 7, command: 'Find', markScheme: `(a)\nM1: \\(h = 65 - 60\\cos\\left(\\frac{2\\pi}{3}\\right)\\)\nA1: \\(h = 95\\) m\n(b)\nM1: \\(65 - 60\\cos\\left(\\frac{\\pi t}{15}\\right) \\gt 100\\), so \\(\\cos\\left(\\frac{\\pi t}{15}\\right) \\lt -\\frac{7}{12}\\)\nA1: \\(\\frac{\\pi t}{15} = 2.1936\\), giving \\(t = 10.47\\)\nM1: Uses symmetry: second time \\(t = 30 - 10.47 = 19.53\\) and subtracts\nA1: 9.1 minutes AWRT\n(c)\nE1: e.g. The wheel may not rotate at a constant speed (it may stop for boarding); the passenger's height is measured to a seat, not a point on the rim` },
      { q: `Solve the equation\n\\(3\\cot^2 x - \\csc x = 7\\)\nfor \\(0° \\lt x \\lt 360°\\). Give your answers to one decimal place where appropriate.`, marks: 7, command: 'Solve', markScheme: `M1: Uses \\(\\cot^2 x = \\csc^2 x - 1\\)\nA1: \\(3\\csc^2 x - \\csc x - 10 = 0\\)\nM1: Factorises \\((3\\csc x + 5)(\\csc x - 2) = 0\\)\nA1: \\(\\csc x = 2\\) or \\(\\csc x = -\\frac{5}{3}\\)\nM1: Converts to \\(\\sin x = \\frac{1}{2}\\) or \\(\\sin x = -\\frac{3}{5}\\)\nA1: \\(x = 30°, 150°\\)\nA1: \\(x = 216.9°, 323.1°\\)` },
      { q: `(a) Prove that \\(\\sin 3x \\equiv 3\\sin x - 4\\sin^3 x\\) [4]\n(b) Hence show that \\(\\sin 10°\\) is a root of the equation \\(8s^3 - 6s + 1 = 0\\) [3]`, marks: 7, command: 'Prove', markScheme: `(a)\nM1: \\(\\sin 3x = \\sin(2x + x) = \\sin 2x\\cos x + \\cos 2x\\sin x\\)\nM1: Uses \\(\\sin 2x = 2\\sin x\\cos x\\) and \\(\\cos 2x = 1 - 2\\sin^2 x\\)\nM1: Replaces \\(\\cos^2 x\\) with \\(1 - \\sin^2 x\\)\nA1: \\(2\\sin x - 2\\sin^3 x + \\sin x - 2\\sin^3 x = 3\\sin x - 4\\sin^3 x\\); complete proof\n(b)\nM1: Substitutes \\(x = 10°\\): \\(\\sin 30° = 3\\sin 10° - 4\\sin^3 10°\\)\nA1: \\(\\frac{1}{2} = 3s - 4s^3\\) with \\(s = \\sin 10°\\)\nA1: Rearranges to \\(8s^3 - 6s + 1 = 0\\) with a concluding statement` },
      { q: `A drone flies in a straight line from its base \\(O\\) for 3.2 km on a bearing of 065° to a point \\(A\\). It then flies 4.5 km on a bearing of 170° to a point \\(B\\).\n(data written for this practice question)\n\n(a) Show that angle \\(OAB = 75°\\) [2]\n(b) Find the distance \\(OB\\). [3]\n(c) Find the bearing on which the drone must fly to return directly from \\(B\\) to \\(O\\). Give your answer to the nearest degree. [3]`, marks: 8, command: 'Find', markScheme: `(a)\nM1: Bearing of \\(O\\) from \\(A\\) is \\(065° + 180° = 245°\\)\nA1: Angle \\(OAB = 245° - 170° = 75°\\) AG\n(b)\nM1: \\(OB^2 = 3.2^2 + 4.5^2 - 2(3.2)(4.5)\\cos 75°\\)\nA1: \\(OB^2 = 23.04\\ldots\\)\nA1: \\(OB = 4.80\\) km AWRT\n(c)\nM1: Sine rule \\(\\sin OBA = \\frac{3.2\\sin 75°}{4.80}\\)\nA1: Angle \\(OBA = 40.1°\\) AWRT\nA1: Bearing of \\(A\\) from \\(B\\) is 350°, so bearing of \\(O\\) from \\(B\\) is \\(350° - 40.1° = 310°\\)` },
      { q: `\\(f(x) = 3\\cos^2 x - 2\\sqrt{3}\\sin x\\cos x + \\sin^2 x\\)\n\n(a) Show that \\(f(x) = 2 + \\cos 2x - \\sqrt{3}\\sin 2x\\) [3]\n(b) Hence express \\(f(x)\\) in the form \\(2 + R\\cos(2x + \\alpha)\\), where \\(R \\gt 0\\) and \\(0 \\lt \\alpha \\lt \\frac{\\pi}{2}\\), giving the exact values of \\(R\\) and \\(\\alpha\\). [2]\n(c) Hence solve \\(f(x) = 3\\) for \\(0 \\leq x \\leq \\pi\\), giving your answers in exact form. [3]`, marks: 8, command: 'Show that', markScheme: `(a)\nM1: Uses \\(\\cos^2 x = \\frac{1 + \\cos 2x}{2}\\) and \\(\\sin^2 x = \\frac{1 - \\cos 2x}{2}\\)\nM1: Uses \\(2\\sin x\\cos x = \\sin 2x\\)\nA1: \\(\\frac{3 + 3\\cos 2x + 1 - \\cos 2x}{2} - \\sqrt{3}\\sin 2x = 2 + \\cos 2x - \\sqrt{3}\\sin 2x\\) AG\n(b)\nB1: \\(R = 2\\)\nB1: \\(\\alpha = \\frac{\\pi}{3}\\)\n(c)\nM1: \\(\\cos\\left(2x + \\frac{\\pi}{3}\\right) = \\frac{1}{2}\\) with range \\(\\frac{\\pi}{3} \\leq 2x + \\frac{\\pi}{3} \\leq \\frac{7\\pi}{3}\\)\nA1: \\(2x + \\frac{\\pi}{3} = \\frac{\\pi}{3}, \\frac{5\\pi}{3}, \\frac{7\\pi}{3}\\)\nA1: \\(x = 0, \\frac{2\\pi}{3}, \\pi\\) CAO` },
      { q: `On one day, high tide at a harbour entrance occurs at 03:00, when the depth of water is 9.4 m. The next low tide occurs at 09:15, when the depth is 2.6 m.\n(data written for this practice question)\n\nThe depth of water, \\(D\\) metres, \\(t\\) hours after midnight, is modelled by\n\\(D = a + b\\cos\\left(k(t - 3)\\right)\\)\nwhere \\(a\\), \\(b\\) and \\(k\\) are positive constants and \\(k(t - 3)\\) is in radians.\n\n(a) Find the values of \\(a\\), \\(b\\) and \\(k\\). [4]\n(b) A ship needs a depth of at least 5 m to enter the harbour. Using the model, find the times between 03:00 and 15:30 when the ship cannot enter. Give your answers to the nearest minute. [4]\n(c) State one limitation of the model. [1]`, marks: 9, command: 'Find', markScheme: `(a)\nB1: \\(a = 6\\)\nB1: \\(b = 3.4\\)\nM1: Period \\(= 2 \\times 6.25 = 12.5\\) hours, so \\(k = \\frac{2\\pi}{12.5}\\)\nA1: \\(k = \\frac{4\\pi}{25}\\) (0.503 AWRT)\n(b)\nM1: \\(6 + 3.4\\cos(k(t - 3)) \\lt 5\\), so \\(\\cos(k(t - 3)) \\lt -\\frac{1}{3.4}\\)\nA1: \\(k(t - 3) = 1.869\\) or \\(4.414\\)\nM1: Solves for \\(t\\): \\(t = 3 + \\frac{1.869}{0.503} = 6.72\\) and \\(t = 3 + \\frac{4.414}{0.503} = 11.78\\)\nA1: Ship cannot enter from 06:43 to 11:47\n(c)\nE1: e.g. Tidal periods and heights vary from day to day (spring and neap tides); weather such as wind or storm surge also affects the depth` },
      { q: `\\(f(\\theta) = 4\\sin\\theta\\cos\\theta + 2\\cos^2\\theta\\)\n\n(a) Show that \\(f(\\theta) = 2\\sin 2\\theta + \\cos 2\\theta + 1\\) [2]\n(b) Express \\(2\\sin 2\\theta + \\cos 2\\theta\\) in the form \\(R\\sin(2\\theta + \\alpha)\\), where \\(R \\gt 0\\) and \\(0 \\lt \\alpha \\lt \\frac{\\pi}{2}\\). Give \\(R\\) in exact form and \\(\\alpha\\) to 4 decimal places. [3]\n(c) Hence solve \\(f(\\theta) = 2\\) for \\(0 \\leq \\theta \\leq \\pi\\), giving your answers to 3 decimal places where appropriate. [3]\n(d) State the maximum value of \\(f(\\theta)\\) and find the smallest positive value of \\(\\theta\\) at which it occurs. [2]`, marks: 10, command: 'Show that', markScheme: `(a)\nM1: Uses \\(4\\sin\\theta\\cos\\theta = 2\\sin 2\\theta\\) and \\(2\\cos^2\\theta = 1 + \\cos 2\\theta\\)\nA1: \\(f(\\theta) = 2\\sin 2\\theta + \\cos 2\\theta + 1\\) AG\n(b)\nB1: \\(R = \\sqrt{5}\\)\nM1: \\(\\tan\\alpha = \\frac{1}{2}\\)\nA1: \\(\\alpha = 0.4636\\) AWRT\n(c)\nM1: \\(\\sqrt{5}\\sin(2\\theta + \\alpha) = 1\\), \\(\\sin(2\\theta + \\alpha) = \\frac{1}{\\sqrt{5}}\\), considering range \\(\\alpha \\leq 2\\theta + \\alpha \\leq 2\\pi + \\alpha\\)\nA1: \\(2\\theta + \\alpha = 0.4636, 2.6779, 6.7468\\)\nA1: \\(\\theta = 0, 1.107, \\pi\\) (accept 3.142)\n(d)\nB1: Maximum value \\(1 + \\sqrt{5}\\)\nB1: \\(2\\theta + \\alpha = \\frac{\\pi}{2}\\), \\(\\theta = 0.554\\) AWRT` }
    ]
  },
  '1.6': {
    name: 'Exponentials & Logarithms',
    questions: [
      { q: `Solve the equation \\(3^x = 20\\)\n\nGive your answer to three significant figures.`, marks: 2, command: 'Solve', markScheme: `M1: Takes logs of both sides correctly, e.g. \\(x\\ln 3 = \\ln 20\\) or \\(x = \\log_3 20\\)\nA1: \\(x = 2.73\\) AWRT\nAnswer: \\(x = 2.73\\)` },
      { q: `Write \\(\\log_a 8 + 2\\log_a 3 - \\log_a 6\\) as a single logarithm.`, marks: 2, command: 'Write', markScheme: `M1: Uses the power law, \\(2\\log_a 3 = \\log_a 9\\), and attempts to combine using the multiplication or division law\nA1: \\(\\log_a 12\\) CAO\nAnswer: \\(\\log_a 12\\)` },
      { q: `A curve has equation \\(y = 4\\mathrm{e}^{3x}\\)\n\nFind the exact value of the gradient of the curve at the point where \\(x = \\ln 2\\)`, marks: 2, command: 'Find', markScheme: `M1: \\(\\frac{dy}{dx} = 12\\mathrm{e}^{3x}\\) (\\(k\\mathrm{e}^{3x}\\) with \\(k \\neq 4\\) scores M0)\nA1: \\(12\\mathrm{e}^{3\\ln 2} = 12 \\times 8 = 96\\) CAO\nAnswer: \\(96\\)` },
      { q: `The value, \\(V\\) pounds, of a car \\(t\\) years after it was first registered is modelled by\n\\(V = 18\\,000 \\times 0.85^t\\)\n\n(a) State the value of the car when it was first registered. [1]\n(b) Explain what the number 0.85 represents in this context. [1]`, marks: 2, command: 'State', markScheme: `(a) B1: £18 000\n(b) E1: The car loses 15% of its value each year (or: each year the value is 85% of its value the year before). Must refer to a yearly percentage or proportion.` },
      { q: `Solve the equation\n\\(\\ln(x + 3) - \\ln x = \\ln 4\\)`, marks: 3, command: 'Solve', markScheme: `M1: Combines the logarithms on the left: \\(\\ln\\left(\\frac{x+3}{x}\\right)\\)\nM1: Removes logarithms to obtain \\(\\frac{x+3}{x} = 4\\) or \\(x + 3 = 4x\\)\nA1: \\(x = 1\\) CAO\nAnswer: \\(x = 1\\)` },
      { q: `Solve the equation\n\\(\\mathrm{e}^{2x} - 5\\mathrm{e}^{x} + 6 = 0\\)\n\nGive your answers in exact form.`, marks: 3, command: 'Solve', markScheme: `M1: Recognises a quadratic in \\(\\mathrm{e}^x\\) and factorises or uses the formula: \\((\\mathrm{e}^x - 2)(\\mathrm{e}^x - 3) = 0\\)\nA1: \\(\\mathrm{e}^x = 2\\) or \\(\\mathrm{e}^x = 3\\)\nA1: \\(x = \\ln 2\\), \\(x = \\ln 3\\) (both required, exact)\nAnswer: \\(x = \\ln 2\\) or \\(x = \\ln 3\\)` },
      { q: `Solve the equation\n\\(5^{2x+1} = 3^{x+4}\\)\n\nGive your answer to three significant figures.`, marks: 3, command: 'Solve', markScheme: `M1: Takes logs of both sides: \\((2x + 1)\\ln 5 = (x + 4)\\ln 3\\)\nM1: Collects terms in \\(x\\): \\(x(2\\ln 5 - \\ln 3) = 4\\ln 3 - \\ln 5\\)\nA1: \\(x = 1.31\\) AWRT\nAnswer: \\(x = 1.31\\)` },
      { q: `The mass, \\(m\\) grams, of a radioactive substance remaining \\(t\\) years after it was first measured is modelled by\n\\(m = 80\\mathrm{e}^{-0.0231t}\\)\n\nFind the half-life of the substance according to the model.\n\nGive your answer to three significant figures.`, marks: 3, command: 'Find', markScheme: `M1: Sets \\(80\\mathrm{e}^{-0.0231t} = 40\\), or \\(\\mathrm{e}^{-0.0231t} = \\frac{1}{2}\\)\nM1: Takes natural logs correctly: \\(-0.0231t = \\ln\\frac{1}{2}\\)\nA1: \\(t = 30.0\\) years AWRT\nAnswer: 30.0 years` },
      { q: `Sketch the graph of \\(y = 3 - \\mathrm{e}^{2x}\\)\n\nState the coordinates of any points where the graph crosses the coordinate axes and the equation of its asymptote.`, marks: 3, command: 'Sketch', diagram: true, markScheme: `B1: Correct shape (decreasing curve, approaching a horizontal asymptote as \\(x \\to -\\infty\\)) with asymptote \\(y = 3\\) stated\nB1: \\(y\\)-intercept \\((0, 2)\\)\nB1: \\(x\\)-intercept \\(\\left(\\frac{1}{2}\\ln 3, 0\\right)\\); condone \\((0.549, 0)\\)` },
      { q: `Given that \\(\\log_3 x = a\\), express each of the following in terms of \\(a\\)\n\n(a) \\(\\log_3 (9x^2)\\) [2]\n(b) \\(\\log_x 27\\) [1]`, marks: 3, command: 'Express', markScheme: `(a) M1: Uses the multiplication law and the power law: \\(\\log_3 9 + 2\\log_3 x\\)\n(a) A1: \\(2 + 2a\\) CAO\n(b) B1: \\(\\frac{3}{a}\\) (from \\(\\log_x 27 = \\frac{\\log_3 27}{\\log_3 x}\\))` },
      { q: `A patient is given an injection of a drug. The concentration of the drug in the patient's blood, \\(C\\) mg per litre, \\(t\\) hours after the injection is modelled by\n\\(C = 12\\mathrm{e}^{-0.3t}\\)\n\nThe drug is effective while its concentration is at least 3 mg per litre.\n\nFind the length of time for which the drug is effective. Give your answer in hours to three significant figures.`, marks: 3, command: 'Find', markScheme: `M1: Sets \\(12\\mathrm{e}^{-0.3t} = 3\\)\nM1: Takes natural logs: \\(-0.3t = \\ln\\frac{1}{4}\\)\nA1: 4.62 hours AWRT\nAnswer: 4.62 hours` },
      { q: `Solve the equation\n\\(\\log_2 (x + 5) + \\log_2 (x - 2) = 3\\)\n\nFully justify your answer.`, marks: 4, command: 'Solve', markScheme: `M1: Combines: \\(\\log_2 \\left[(x+5)(x-2)\\right] = 3\\)\nM1: Removes logs: \\((x + 5)(x - 2) = 2^3 = 8\\)\nA1: \\(x^2 + 3x - 18 = 0\\), so \\(x = 3\\) or \\(x = -6\\)\nR1: Rejects \\(x = -6\\) because \\(\\log_2(x - 2)\\) (or \\(\\log_2(x+5)\\)) is undefined for this value; final answer \\(x = 3\\) only\nAnswer: \\(x = 3\\)` },
      { q: `Two variables \\(x\\) and \\(y\\) are related by an equation of the form \\(y = ax^n\\), where \\(a\\) and \\(n\\) are constants.\n\nA graph of \\(\\log_{10} y\\) against \\(\\log_{10} x\\) is a straight line passing through the points \\((1, 2.3)\\) and \\((3, 1.5)\\)\n\nFind the values of \\(a\\) and \\(n\\)\n\nGive the value of \\(a\\) to three significant figures.`, marks: 4, command: 'Find', markScheme: `M1: Takes logs to obtain \\(\\log_{10} y = \\log_{10} a + n\\log_{10} x\\)\nM1: Finds the gradient of the line and equates it to \\(n\\): \\(\\frac{1.5 - 2.3}{3 - 1}\\)\nA1: \\(n = -0.4\\)\nA1: Intercept \\(\\log_{10} a = 2.7\\), so \\(a = 10^{2.7} = 501\\) AWRT\nAnswer: \\(a = 501\\), \\(n = -0.4\\)` },
      { q: `The number of birds, \\(P\\), in a colony \\(t\\) years after the start of a study is modelled by\n\\(P = A\\mathrm{e}^{kt}\\), where \\(A\\) and \\(k\\) are constants.\n\nAt the start of the study there were 2500 birds in the colony. Five years later there were 3400 birds.\n\nFind the value of \\(t\\) when the model predicts that there will be 10 000 birds in the colony.`, marks: 4, command: 'Find', markScheme: `B1: \\(A = 2500\\)\nM1: \\(3400 = 2500\\mathrm{e}^{5k}\\), so \\(k = \\frac{1}{5}\\ln 1.36\\)\nA1: \\(k = 0.0615\\) AWRT (or exact)\nA1: \\(10\\,000 = 2500\\mathrm{e}^{kt}\\) gives \\(t = \\frac{\\ln 4}{k} = 22.5\\) AWRT\nAnswer: \\(t = 22.5\\)` },
      { q: `Do not use a calculator in this question.\n\nSolve the equation\n\\(2^{2x+1} - 9 \\times 2^x + 4 = 0\\)`, marks: 4, command: 'Solve', markScheme: `M1: Writes \\(2^{2x+1}\\) as \\(2(2^x)^2\\) to obtain \\(2y^2 - 9y + 4 = 0\\) where \\(y = 2^x\\)\nM1: Solves the quadratic: \\((2y - 1)(y - 4) = 0\\)\nA1: \\(2^x = \\frac{1}{2}\\) or \\(2^x = 4\\)\nA1: \\(x = -1\\) or \\(x = 2\\)\nAnswer: \\(x = -1\\), \\(x = 2\\)` },
      { q: `Solve the equation\n\\(2\\log_3 x - \\log_3 (x - 2) = 2\\)\n\nYou must show detailed reasoning.`, marks: 4, command: 'Solve', markScheme: `M1: Uses the power law and division law: \\(\\log_3 \\frac{x^2}{x - 2} = 2\\)\nM1: Removes logs: \\(\\frac{x^2}{x - 2} = 9\\)\nA1: \\(x^2 - 9x + 18 = 0\\)\nA1: \\(x = 3\\) or \\(x = 6\\) (both valid as both give \\(x - 2 \\gt 0\\))\nAnswer: \\(x = 3\\), \\(x = 6\\)` },
      { q: `A curve has equation \\(y = \\mathrm{e}^{2x} - 6x\\)\n\nFind the exact coordinates of the stationary point of the curve and determine its nature.\n\nFully justify your answer.`, marks: 4, command: 'Find', markScheme: `M1: \\(\\frac{dy}{dx} = 2\\mathrm{e}^{2x} - 6\\), set equal to 0\nA1: \\(\\mathrm{e}^{2x} = 3\\), so \\(x = \\frac{1}{2}\\ln 3\\)\nA1: \\(y = 3 - 3\\ln 3\\)\nB1: \\(\\frac{d^2y}{dx^2} = 4\\mathrm{e}^{2x} = 12 \\gt 0\\), so minimum point (or a correct sign-change argument)\nAnswer: \\(\\left(\\frac{1}{2}\\ln 3, 3 - 3\\ln 3\\right)\\), a minimum` },
      { q: `A cup of coffee is placed in a room. Its temperature, \\(T\\) °C, \\(t\\) minutes later is modelled by\n\\(T = 20 + 70\\mathrm{e}^{-0.04t}\\)\n\n(a) State the temperature of the room according to the model. [1]\n(b) Find the time it takes for the coffee to cool to 50 °C. Give your answer to the nearest minute. [3]`, marks: 4, command: 'Find', markScheme: `(a) B1: 20 °C\n(b) M1: \\(20 + 70\\mathrm{e}^{-0.04t} = 50\\), so \\(\\mathrm{e}^{-0.04t} = \\frac{3}{7}\\)\n(b) M1: \\(t = -\\frac{1}{0.04}\\ln\\frac{3}{7}\\) (= 25 ln(7/3))\n(b) A1: 21 minutes (from 21.18...)\nAnswer: (a) 20 °C (b) 21 minutes` },
      { q: `Two variables \\(x\\) and \\(y\\) are related by an equation of the form \\(y = kb^x\\), where \\(k\\) and \\(b\\) are positive constants.\n\nA graph of \\(\\log_{10} y\\) against \\(x\\) is a straight line passing through the points \\((2, 0.9)\\) and \\((6, 1.5)\\)\n\nFind the values of \\(k\\) and \\(b\\), giving your answers to three significant figures.`, marks: 4, command: 'Find', markScheme: `B1: \\(\\log_{10} y = \\log_{10} k + x\\log_{10} b\\)\nM1: Gradient \\(= \\frac{1.5 - 0.9}{6 - 2} = 0.15\\) and intercept \\(= 0.9 - 2(0.15) = 0.6\\)\nA1: \\(k = 10^{0.6} = 3.98\\) AWRT\nA1: \\(b = 10^{0.15} = 1.41\\) AWRT\nAnswer: \\(k = 3.98\\), \\(b = 1.41\\)` },
      { q: `The concentration, \\(C\\) mg per litre, of a drug in a patient's blood \\(t\\) hours after it is given is modelled by\n\\(C = C_0\\mathrm{e}^{-kt}\\), where \\(C_0\\) and \\(k\\) are constants.\n\nTwo hours after the drug is given, \\(C = 6.4\\). Five hours after the drug is given, \\(C = 3.2\\)\n\nFind the values of \\(C_0\\) and \\(k\\), giving your answers to three significant figures.`, marks: 5, command: 'Find', markScheme: `M1: Forms both equations: \\(6.4 = C_0\\mathrm{e}^{-2k}\\) and \\(3.2 = C_0\\mathrm{e}^{-5k}\\)\nM1: Divides to eliminate \\(C_0\\): \\(\\mathrm{e}^{3k} = 2\\)\nA1: \\(k = \\frac{1}{3}\\ln 2 = 0.231\\) AWRT\nM1: Substitutes their \\(k\\) to find \\(C_0\\): \\(C_0 = 6.4\\mathrm{e}^{2k}\\)\nA1: \\(C_0 = 10.2\\) AWRT\nAnswer: \\(C_0 = 10.2\\), \\(k = 0.231\\)` },
      { q: `Solve the simultaneous equations\n\\(xy = 32\\)\n\\(\\log_2 x - 2\\log_2 y = -1\\)\n\nwhere \\(x \\gt 0\\) and \\(y \\gt 0\\)`, marks: 5, command: 'Solve', markScheme: `M1: Uses the power law and division law: \\(\\log_2 \\frac{x}{y^2} = -1\\)\nA1: \\(\\frac{x}{y^2} = \\frac{1}{2}\\), i.e. \\(x = \\frac{1}{2}y^2\\)\nM1: Substitutes into \\(xy = 32\\): \\(\\frac{1}{2}y^3 = 32\\)\nA1: \\(y = 4\\)\nA1: \\(x = 8\\)\nAlternative: take \\(\\log_2\\) of the first equation, \\(\\log_2 x + \\log_2 y = 5\\), and solve the linear pair in \\(\\log_2 x\\), \\(\\log_2 y\\)\nAnswer: \\(x = 8\\), \\(y = 4\\)` },
      { q: `(a) On the same axes, sketch the graphs of \\(y = \\mathrm{e}^x\\) and \\(y = 4\\mathrm{e}^{-x}\\), stating the coordinates of the points where each graph meets the \\(y\\)-axis. [2]\n(b) Find the exact coordinates of the point of intersection of the two graphs. [3]`, marks: 5, command: 'Sketch', diagram: true, markScheme: `(a) B1: Correct shape for \\(y = \\mathrm{e}^x\\) through \\((0, 1)\\), above the \\(x\\)-axis\n(a) B1: Correct shape for \\(y = 4\\mathrm{e}^{-x}\\) through \\((0, 4)\\), decreasing, above the \\(x\\)-axis\n(b) M1: \\(\\mathrm{e}^x = 4\\mathrm{e}^{-x}\\) leading to \\(\\mathrm{e}^{2x} = 4\\)\n(b) A1: \\(x = \\frac{1}{2}\\ln 4 = \\ln 2\\)\n(b) A1: \\(y = 2\\); point \\((\\ln 2, 2)\\)` },
      { q: `A scientist believes that two quantities \\(x\\) and \\(y\\) are related by a model of the form \\(y = ax^n\\). She records the following values. (data written for this practice question)\n\n\\(x\\): 2, 4, 8, 16\n\\(y\\): 7.0, 12.1, 21.2, 36.8\n\n(a) Show that, if the model is correct, a graph of \\(\\ln y\\) against \\(\\ln x\\) is a straight line, stating its gradient and its intercept on the vertical axis. [2]\n(b) Use the values for \\(x = 2\\) and \\(x = 16\\) to estimate \\(a\\) and \\(n\\), giving your answers to two significant figures. [3]`, marks: 5, command: 'Show that', markScheme: `(a) M1: \\(\\ln y = \\ln a + n\\ln x\\)\n(a) A1: Of the form \\(Y = mX + c\\) with gradient \\(n\\) and intercept \\(\\ln a\\)\n(b) M1: Gradient \\(= \\frac{\\ln 36.8 - \\ln 7.0}{\\ln 16 - \\ln 2}\\)\n(b) A1: \\(n = 0.80\\) AWRT\n(b) A1: \\(a = \\frac{7.0}{2^n} = 4.0\\) AWRT (accept 4.0 to 4.1 using their rounded \\(n\\))\nAnswer: \\(a \\approx 4.0\\), \\(n \\approx 0.80\\)` },
      { q: `Solve the equation\n\\(3^{2x} = 4 \\times 3^x + 5\\)\n\nGive your answer to three significant figures. Fully justify your answer.`, marks: 5, command: 'Solve', markScheme: `M1: Forms a quadratic in \\(3^x\\): \\(y^2 - 4y - 5 = 0\\) where \\(y = 3^x\\)\nM1: Solves: \\((y - 5)(y + 1) = 0\\)\nA1: \\(3^x = 5\\) or \\(3^x = -1\\)\nE1: Rejects \\(3^x = -1\\) because \\(3^x \\gt 0\\) for all real \\(x\\)\nA1: \\(x = \\frac{\\ln 5}{\\ln 3} = 1.46\\) AWRT\nAnswer: \\(x = 1.46\\)` },
      { q: `Amy invests £5000 in a savings account. The value of her investment, \\(V\\) pounds, \\(t\\) years later is modelled by\n\\(V = 5000 \\times 1.035^t\\)\n\n(a) Find the value of the investment after 10 years according to the model. [1]\n(b) Find the number of complete years after which the model predicts that the value of the investment will first exceed £10 000 [3]\n(c) State one limitation of the model. [1]`, marks: 5, command: 'Find', markScheme: `(a) B1: £7053 (AWRT £7050)\n(b) M1: \\(1.035^t \\gt 2\\) (or \\(= 2\\))\n(b) M1: \\(t \\gt \\frac{\\ln 2}{\\ln 1.035}\\) (\\(= 20.1\\ldots\\))\n(b) A1: 21 years CAO\n(c) E1: e.g. the interest rate is unlikely to stay at 3.5% for many years; or interest may be added only at the end of each year so the value increases in steps, not continuously; or Amy may withdraw or add money` },
      { q: `A curve has equation \\(y = 3\\mathrm{e}^{2x} + 1\\)\n\nThe tangent to the curve at the point where \\(x = \\ln 2\\) meets the \\(x\\)-axis at the point \\(Q\\)\n\nFind the exact \\(x\\)-coordinate of \\(Q\\)`, marks: 5, command: 'Find', markScheme: `M1: \\(\\frac{dy}{dx} = 6\\mathrm{e}^{2x}\\)\nA1: Gradient at \\(x = \\ln 2\\) is \\(6 \\times 4 = 24\\)\nB1: \\(y = 3 \\times 4 + 1 = 13\\)\nM1: Equation of tangent: \\(y - 13 = 24(x - \\ln 2)\\) and sets \\(y = 0\\)\nA1: \\(x = \\ln 2 - \\frac{13}{24}\\) (or equivalent exact form)\nAnswer: \\(\\ln 2 - \\frac{13}{24}\\)` },
      { q: `The number of bacteria, \\(N\\), in a culture \\(t\\) hours after the start of an experiment is modelled by\n\\(N = 200\\mathrm{e}^{0.35t}\\)\n\n(a) Find the number of bacteria predicted by the model after 4 hours. [1]\n(b) Find the rate at which the number of bacteria is increasing when \\(t = 4\\) [2]\n(c) Find the time at which the model predicts there will be 5000 bacteria. [2]\n(d) State one limitation of the model. [1]`, marks: 6, command: 'Find', markScheme: `(a) B1: 811 CAO\n(b) M1: \\(\\frac{dN}{dt} = 70\\mathrm{e}^{0.35t}\\)\n(b) A1: 284 bacteria per hour AWRT\n(c) M1: \\(\\mathrm{e}^{0.35t} = 25\\), \\(t = \\frac{\\ln 25}{0.35}\\)\n(c) A1: 9.20 hours AWRT\n(d) E1: e.g. the model predicts unlimited growth, but space or nutrients will run out so growth will slow; or the number of bacteria must be an integer` },
      { q: `The weekly sales, \\(S\\), of a new phone game in week \\(t\\) after its launch are thought to follow a model of the form \\(S = kb^t\\). The sales in the first five weeks were (data written for this practice question)\n\n\\(t\\): 1, 2, 3, 4, 5\n\\(S\\): 120, 180, 270, 410, 610\n\n(a) Show that, if the model is correct, a graph of \\(\\log_{10} S\\) against \\(t\\) is a straight line. [2]\n(b) The equation of the line of best fit for \\(\\log_{10} S\\) against \\(t\\) is \\(\\log_{10} S = 1.904 + 0.176t\\)\nFind the values of \\(k\\) and \\(b\\), giving your answers to three significant figures. [3]\n(c) Interpret the value of \\(b\\) in this context. [1]`, marks: 6, command: 'Show that', markScheme: `(a) M1: \\(\\log_{10} S = \\log_{10} k + t\\log_{10} b\\)\n(a) A1: Compares with \\(Y = mX + c\\): straight line with gradient \\(\\log_{10} b\\) and intercept \\(\\log_{10} k\\)\n(b) M1: \\(\\log_{10} k = 1.904\\) or \\(\\log_{10} b = 0.176\\)\n(b) A1: \\(k = 80.2\\) AWRT\n(b) A1: \\(b = 1.50\\) AWRT\n(c) E1: Weekly sales increase by about 50% each week (or are multiplied by 1.5 each week)` },
      { q: `(a) Given that\n\\(\\log_a x = 3\\log_a 2 + \\frac{1}{2}\\log_a 25 - \\log_a 4\\)\nshow that \\(x = 10\\) [3]\n(b) Hence, or otherwise, solve the equation\n\\(\\log_a (y + 3) = 3\\log_a 2 + \\frac{1}{2}\\log_a 25 - \\log_a 4 + \\log_a y\\) [3]`, marks: 6, command: 'Show that', markScheme: `(a) M1: Uses the power law: \\(3\\log_a 2 = \\log_a 8\\) and \\(\\frac{1}{2}\\log_a 25 = \\log_a 5\\)\n(a) M1: Combines: \\(\\log_a \\frac{8 \\times 5}{4}\\)\n(a) A1: \\(\\log_a 10\\) so \\(x = 10\\) (AG, convincingly shown)\n(b) M1: \\(\\log_a (y + 3) = \\log_a 10 + \\log_a y = \\log_a 10y\\)\n(b) M1: \\(y + 3 = 10y\\)\n(b) A1: \\(y = \\frac{1}{3}\\)\nAnswer: (b) \\(y = \\frac{1}{3}\\)` },
      { q: `A metal block is heated to 400 °C and then left to cool in a room. Its temperature, \\(T\\) °C, \\(t\\) minutes after it starts to cool is modelled by\n\\(T = 25 + 375\\mathrm{e}^{-kt}\\)\n\nAfter 10 minutes the temperature of the block is 250 °C.\n\n(a) Show that \\(k = 0.0511\\) correct to three significant figures. [3]\n(b) Find the rate at which the temperature is decreasing when \\(t = 10\\) [2]\n(c) Explain why the model would not be suitable if the temperature of the room changed during the day. [1]`, marks: 6, command: 'Show that', markScheme: `(a) M1: \\(250 = 25 + 375\\mathrm{e}^{-10k}\\), so \\(\\mathrm{e}^{-10k} = 0.6\\)\n(a) M1: \\(k = -\\frac{1}{10}\\ln 0.6\\)\n(a) A1: \\(k = 0.05108\\ldots = 0.0511\\) (AG; must see more accuracy than 3 s.f. or exact form)\n(b) M1: \\(\\frac{dT}{dt} = -375k\\mathrm{e}^{-kt}\\)\n(b) A1: Decreasing at 11.5 °C per minute AWRT\n(c) E1: The constant 25 represents a fixed room temperature (the value \\(T\\) tends to); if the room temperature changes the long-term value would not be 25 °C` },
      { q: `A curve has equation \\(y = \\mathrm{e}^{2x} - 4\\mathrm{e}^{x} + 3\\)\n\n(a) Find the exact \\(x\\)-coordinates of the points where the curve crosses the \\(x\\)-axis. [2]\n(b) Find the exact coordinates of the stationary point of the curve. [3]\n(c) State the equation of the asymptote to the curve. [1]`, marks: 6, command: 'Find', markScheme: `(a) M1: \\((\\mathrm{e}^x - 1)(\\mathrm{e}^x - 3) = 0\\)\n(a) A1: \\(x = 0\\) and \\(x = \\ln 3\\)\n(b) M1: \\(\\frac{dy}{dx} = 2\\mathrm{e}^{2x} - 4\\mathrm{e}^x = 0\\)\n(b) A1: \\(\\mathrm{e}^x = 2\\), so \\(x = \\ln 2\\) (\\(\\mathrm{e}^x = 0\\) has no solution)\n(b) A1: \\((\\ln 2, -1)\\)\n(c) B1: \\(y = 3\\)` },
      { q: `Solve the equation\n\\(2\\ln(x + 2) - \\ln x = \\ln(2x + 5)\\)\n\nGive your answer in exact form. You must show detailed reasoning.`, marks: 6, command: 'Solve', markScheme: `M1: Uses the power law and division law: \\(\\ln \\frac{(x+2)^2}{x}\\)\nM1: Removes logs: \\((x + 2)^2 = x(2x + 5)\\)\nA1: \\(x^2 + x - 4 = 0\\)\nM1: Solves the quadratic using the formula or completing the square\nA1: \\(x = \\frac{-1 \\pm \\sqrt{17}}{2}\\)\nE1: Rejects \\(x = \\frac{-1 - \\sqrt{17}}{2}\\) because \\(\\ln x\\) is undefined for \\(x \\lt 0\\); final answer \\(x = \\frac{-1 + \\sqrt{17}}{2}\\)\nAnswer: \\(x = \\frac{-1 + \\sqrt{17}}{2}\\)` },
      { q: `A patient is given a dose of a drug at time \\(t = 0\\) hours. The concentration of the drug, \\(C\\) mg per litre, is modelled by\n\\(C = 15\\mathrm{e}^{-0.2t}\\) for \\(0 \\leq t \\lt 6\\)\n\nA second, identical dose is given at \\(t = 6\\), and for \\(t \\geq 6\\) the concentration is modelled by\n\\(C = 15\\mathrm{e}^{-0.2t} + 15\\mathrm{e}^{-0.2(t - 6)}\\)\n\n(a) Find the concentration immediately after the second dose is given. [2]\n(b) A third dose must be given when the concentration first falls to 4 mg per litre. Find how long after the second dose this happens. [3]\n(c) Give two reasons why the model may not be accurate for a particular patient. [2]`, marks: 7, command: 'Find', markScheme: `(a) M1: Substitutes \\(t = 6\\): \\(15\\mathrm{e}^{-1.2} + 15\\)\n(a) A1: 19.5 mg per litre AWRT\n(b) M1: \\(15\\mathrm{e}^{-0.2t}(1 + \\mathrm{e}^{1.2}) = 4\\)\n(b) M1: \\(t = -5\\ln\\left(\\frac{4}{15(1 + \\mathrm{e}^{1.2})}\\right)\\) (\\(= 13.9\\))\n(b) A1: 7.93 hours after the second dose AWRT (condone 7.9)\n(c) E1: e.g. the rate at which the drug is removed varies between patients (depends on body mass, age, kidney or liver function)\n(c) E1: e.g. the drug takes time to spread through the blood, so the concentration does not jump instantly; or the dose may not be absorbed fully` },
      { q: `Kepler suggested that the time, \\(T\\) years, that a planet takes to orbit the Sun is related to its mean distance from the Sun, \\(r\\) astronomical units (AU), by a model of the form \\(T = ar^n\\)\n\nThe table shows data for some planets.\n\nMercury: \\(r = 0.387\\), \\(T = 0.241\\)\nVenus: \\(r = 0.723\\), \\(T = 0.615\\)\nEarth: \\(r = 1.000\\), \\(T = 1.000\\)\nMars: \\(r = 1.524\\), \\(T = 1.881\\)\nJupiter: \\(r = 5.203\\), \\(T = 11.86\\)\n\n(a) Explain how a graph of \\(\\log_{10} T\\) against \\(\\log_{10} r\\) could be used to check whether the model is suitable. [2]\n(b) Use the data for Mercury and Jupiter to find estimates of \\(n\\) and \\(a\\), giving your answers to three significant figures. [4]\n(c) Saturn's mean distance from the Sun is 9.537 AU. Use your model to estimate the time Saturn takes to orbit the Sun. [1]`, marks: 7, command: 'Find', markScheme: `(a) M1: \\(\\log_{10} T = \\log_{10} a + n\\log_{10} r\\)\n(a) E1: If the points lie (close to) a straight line the model is suitable; gradient gives \\(n\\), intercept gives \\(\\log_{10} a\\)\n(b) M1: \\(n = \\frac{\\log_{10} 11.86 - \\log_{10} 0.241}{\\log_{10} 5.203 - \\log_{10} 0.387}\\)\n(b) A1: \\(n = 1.50\\) AWRT\n(b) M1: Substitutes to find \\(a\\), e.g. \\(a = \\frac{0.241}{0.387^n}\\)\n(b) A1: \\(a = 1.00\\) AWRT\n(c) B1ft: \\(T \\approx 29.4\\) years (accept 29.4 to 29.5)` },
      { q: `A curve has equation \\(y = \\ln(2x - 3)\\)\n\n(a) State the equation of the vertical asymptote to the curve. [1]\n(b) Find the coordinates of the point where the curve crosses the \\(x\\)-axis. [1]\n(c) Sketch the curve. [2]\n(d) The line \\(y = 1\\) meets the curve at the point \\(P\\). Find the exact \\(x\\)-coordinate of \\(P\\) [2]\n(e) Describe a sequence of two transformations that maps the graph of \\(y = \\ln x\\) onto the graph of \\(y = \\ln(2x - 3)\\) [1]`, marks: 7, command: 'Sketch', diagram: true, markScheme: `(a) B1: \\(x = \\frac{3}{2}\\)\n(b) B1: \\((2, 0)\\)\n(c) B1: Correct shape: increasing, concave, to the right of the asymptote, approaching it as \\(y \\to -\\infty\\)\n(c) B1: Asymptote and \\(x\\)-intercept shown\n(d) M1: \\(2x - 3 = \\mathrm{e}\\)\n(d) A1: \\(x = \\frac{\\mathrm{e} + 3}{2}\\)\n(e) B1: Translation by \\(\\begin{pmatrix} 3 \\\\ 0 \\end{pmatrix}\\) followed by a stretch parallel to the \\(x\\)-axis, scale factor \\(\\frac{1}{2}\\) (or stretch scale factor \\(\\frac{1}{2}\\) then translation \\(\\begin{pmatrix} 1.5 \\\\ 0 \\end{pmatrix}\\))` },
      { q: `Two models are proposed for the population, \\(P\\), of a town \\(t\\) years after 2000.\n\nModel A: \\(P = 1200\\mathrm{e}^{0.04t}\\)\nModel B: \\(P = 800\\mathrm{e}^{0.07t}\\)\n\n(a) Show that the two models predict the same population when \\(t = \\frac{100}{3}\\ln 1.5\\) [3]\n(b) Find the population predicted by both models at this time. [2]\n(c) The actual population in 2020 was 3100 (data written for this practice question). Determine which model gives the better prediction for 2020. [2]`, marks: 7, command: 'Show that', markScheme: `(a) M1: \\(1200\\mathrm{e}^{0.04t} = 800\\mathrm{e}^{0.07t}\\)\n(a) M1: \\(\\mathrm{e}^{0.03t} = 1.5\\)\n(a) A1: \\(t = \\frac{\\ln 1.5}{0.03} = \\frac{100}{3}\\ln 1.5\\) (AG)\n(b) M1: Substitutes, e.g. \\(1200\\mathrm{e}^{\\frac{4}{3}\\ln 1.5} = 1200 \\times 1.5^{4/3}\\)\n(b) A1: 2060 AWRT\n(c) M1: Evaluates both at \\(t = 20\\): A gives 2671, B gives 3244\n(c) A1: Model B is better as 3244 is closer to 3100 (difference 144 compared with 429)` },
      { q: `The count rate, \\(R\\) counts per second, from a radioactive sample is measured every 5 minutes. (data written for this practice question)\n\n\\(t\\) (minutes): 0, 5, 10, 15, 20\n\\(R\\): 820, 610, 450, 335, 248\n\nIt is suggested that \\(R = R_0\\mathrm{e}^{-\\lambda t}\\), where \\(R_0\\) and \\(\\lambda\\) are constants.\n\n(a) Show that, if this model is correct, a graph of \\(\\ln R\\) against \\(t\\) is a straight line, and state its gradient and intercept in terms of \\(R_0\\) and \\(\\lambda\\) [2]\n(b) Use the values at \\(t = 0\\) and \\(t = 20\\) to estimate \\(\\lambda\\), giving your answer to two significant figures. [2]\n(c) Hence estimate the half-life of the sample. [2]\n(d) A student says that, according to the model, the count rate will be zero after about two hours. Comment on this claim, and give one reason why measured values may not fit the model exactly. [2]`, marks: 8, command: 'Show that', markScheme: `(a) M1: \\(\\ln R = \\ln R_0 - \\lambda t\\)\n(a) A1: Straight line with gradient \\(-\\lambda\\) and intercept \\(\\ln R_0\\)\n(b) M1: Gradient \\(= \\frac{\\ln 248 - \\ln 820}{20}\\)\n(b) A1: \\(\\lambda = 0.060\\) AWRT\n(c) M1: \\(\\mathrm{e}^{-\\lambda t} = \\frac{1}{2}\\), \\(t = \\frac{\\ln 2}{\\lambda}\\)\n(c) A1ft: 11.6 minutes (accept 11.5 to 11.6)\n(d) E1: The claim is wrong: \\(\\mathrm{e}^{-\\lambda t} \\gt 0\\) for all \\(t\\), so the model never predicts zero (it predicts about 0.6 counts per second at 120 minutes)\n(d) E1: e.g. radioactive decay is random so counts fluctuate; or there is background radiation` },
      { q: `(a) Show that \\(\\log_9 x = \\frac{1}{2}\\log_3 x\\) for \\(x \\gt 0\\) [2]\n(b) Hence solve the equation \\(\\log_3 x + \\log_9 x = 3\\) [2]\n(c) Solve the simultaneous equations\n\\(xy = 243\\)\n\\(\\log_3 x - \\log_9 y = 1\\)\ngiving your answers in the form \\(3^k\\), where \\(k\\) is a rational number. [4]`, marks: 8, command: 'Solve', markScheme: `(a) M1: Lets \\(\\log_9 x = p\\), so \\(x = 9^p = 3^{2p}\\) (or uses change of base \\(\\frac{\\log_3 x}{\\log_3 9}\\))\n(a) A1: \\(\\log_3 x = 2p\\), hence \\(\\log_9 x = \\frac{1}{2}\\log_3 x\\) (AG)\n(b) M1: \\(\\frac{3}{2}\\log_3 x = 3\\)\n(b) A1: \\(x = 9\\)\n(c) M1: Takes \\(\\log_3\\) of the first equation: \\(\\log_3 x + \\log_3 y = 5\\)\n(c) M1: Uses (a) on the second: \\(\\log_3 x - \\frac{1}{2}\\log_3 y = 1\\), and solves the pair\n(c) A1: \\(\\log_3 y = \\frac{8}{3}\\), \\(\\log_3 x = \\frac{7}{3}\\)\n(c) A1: \\(x = 3^{7/3}\\), \\(y = 3^{8/3}\\)` },
      { q: `Some sheep are introduced onto an island at time \\(t = 0\\). The number of sheep, \\(P\\), on the island \\(t\\) years later is first modelled by\n\\(P = 40\\mathrm{e}^{0.2t}\\)\n\n(a) Find the number of sheep predicted after 10 years. [1]\n(b) Find the time taken for the population to reach 1000 according to this model. [2]\n(c) Explain why this model is unlikely to be suitable in the long term. [1]\n\nA refined model is\n\\(P = \\frac{1200}{1 + 29\\mathrm{e}^{-0.2t}}\\)\n\n(d) Show that both models give the same initial number of sheep. [1]\n(e) State the long-term number of sheep predicted by the refined model. [1]\n(f) Find the time taken for the population to reach 1000 according to the refined model. Give your answer to three significant figures. [3]`, marks: 9, command: 'Find', markScheme: `(a) B1: 296 (AWRT 295 or 296)\n(b) M1: \\(\\mathrm{e}^{0.2t} = 25\\), \\(t = 5\\ln 25\\)\n(b) A1: 16.1 years AWRT\n(c) E1: The model predicts the population grows without limit, but the island has limited space and food (so growth must slow)\n(d) B1: \\(t = 0\\) gives \\(\\frac{1200}{1 + 29} = 40\\), the same as \\(40\\mathrm{e}^0 = 40\\)\n(e) B1: 1200 (as \\(\\mathrm{e}^{-0.2t} \\to 0\\))\n(f) M1: \\(1 + 29\\mathrm{e}^{-0.2t} = \\frac{1200}{1000} = 1.2\\)\n(f) M1: \\(\\mathrm{e}^{-0.2t} = \\frac{0.2}{29}\\), \\(t = 5\\ln 145\\)\n(f) A1: 24.9 years AWRT` },
      { q: `Carbon-14 is used to date ancient organic material. The mass, \\(m\\) grams, of carbon-14 in a sample \\(t\\) years after the death of the organism is modelled by\n\\(m = m_0\\mathrm{e}^{-kt}\\)\nwhere \\(m_0\\) is the initial mass and \\(k\\) is a constant. The half-life of carbon-14 is 5730 years.\n\n(a) Show that \\(k = 1.21 \\times 10^{-4}\\) to three significant figures. [2]\n(b) A bone is found to contain 35% of its original mass of carbon-14. Estimate the age of the bone, giving your answer to three significant figures. [3]\n(c) Show that, according to the model, the time taken for the mass to fall from 80% to 20% of \\(m_0\\) is exactly two half-lives. [2]\n(d) Show that \\(\\frac{dm}{dt} = -km\\) and explain what this means about the rate of decay. [2]\n(e) Give one reason why the estimate of the age of the bone may be inaccurate. [1]`, marks: 10, command: 'Show that', markScheme: `(a) M1: \\(\\mathrm{e}^{-5730k} = \\frac{1}{2}\\)\n(a) A1: \\(k = \\frac{\\ln 2}{5730} = 1.2097 \\times 10^{-4} = 1.21 \\times 10^{-4}\\) (AG)\n(b) M1: \\(\\mathrm{e}^{-kt} = 0.35\\)\n(b) M1: \\(t = \\frac{\\ln(1/0.35)}{k}\\) (or \\(5730\\log_2 \\frac{1}{0.35}\\))\n(b) A1: 8680 years (AWRT 8680; condone 8676 from \\(k = 1.21 \\times 10^{-4}\\))\n(c) M1: \\(\\mathrm{e}^{-kt_1} = 0.8\\) and \\(\\mathrm{e}^{-kt_2} = 0.2\\), so \\(\\mathrm{e}^{-k(t_2 - t_1)} = \\frac{1}{4}\\)\n(c) A1: \\(t_2 - t_1 = \\frac{\\ln 4}{k} = \\frac{2\\ln 2}{k} = 2 \\times 5730\\), which is two half-lives\n(d) M1: \\(\\frac{dm}{dt} = -km_0\\mathrm{e}^{-kt} = -km\\)\n(d) E1: The rate of decay is proportional to the mass of carbon-14 remaining\n(e) E1: e.g. the original proportion of carbon-14 in the organism may not be known exactly; or the sample may have been contaminated; or measuring a very small mass is inaccurate` }
    ]
  },
  '1.7': {
    name: 'Differentiation',
    questions: [
      { q: `Given that \\(y = 5x^3 - \\frac{4}{x} + 7\\), find \\(\\frac{dy}{dx}\\)`, marks: 2, command: 'Find', markScheme: `M1: Differentiates with at least one power term correct, e.g. \\(15x^2\\) or \\(4x^{-2}\\)\nA1: \\(\\frac{dy}{dx} = 15x^2 + 4x^{-2}\\) or \\(15x^2 + \\frac{4}{x^2}\\) CAO\nCondone \\(+0\\) for the constant term.` },
      { q: `A curve has equation \\(y = e^{3x} + \\ln 2x\\)\n\nFind the exact value of the gradient of the curve at the point where \\(x = \\frac{1}{2}\\)`, marks: 2, command: 'Find', markScheme: `M1: \\(\\frac{dy}{dx} = 3e^{3x} + \\frac{1}{x}\\) (condone \\(\\frac{2}{2x}\\) unsimplified)\nA1: Gradient \\(= 3e^{\\frac{3}{2}} + 2\\) CAO (exact form required; 15.4 alone scores M1 A0)` },
      { q: `Given that \\(f(x) = \\sin 4x + \\tan 3x\\), find \\(f'(x)\\)`, marks: 2, command: 'Find', markScheme: `B1: \\(4\\cos 4x\\)\nB1: \\(3\\sec^2 3x\\) (accept \\(\\frac{3}{\\cos^2 3x}\\))\n\\(f'(x) = 4\\cos 4x + 3\\sec^2 3x\\)` },
      { q: `The number of bacteria, \\(N\\), in a culture \\(t\\) hours after the start of an experiment is modelled by\n\\(N = 400 \\times 3^t\\)\n\nFind the rate at which the number of bacteria is increasing when \\(t = 2\\)\nGive your answer to three significant figures.`, marks: 2, command: 'Find', markScheme: `M1: \\(\\frac{dN}{dt} = 400 \\ln 3 \\times 3^t\\) (accept \\(k \\times 3^t\\) with \\(k = 400\\ln 3\\) or \\(439.4\\))\nA1: \\(3600 \\ln 3 = 3960\\) bacteria per hour AWRT 3960` },
      { q: `Given that \\(y = x^3 e^{2x}\\), find \\(\\frac{dy}{dx}\\)\nGive your answer in the form \\(x^2 e^{2x}(ax + b)\\), where \\(a\\) and \\(b\\) are integers.`, marks: 3, command: 'Find', markScheme: `M1: Uses the product rule: form \\(Ax^2e^{2x} + Bx^3e^{2x}\\)\nA1: \\(3x^2e^{2x} + 2x^3e^{2x}\\)\nA1: \\(x^2e^{2x}(2x + 3)\\), so \\(a = 2,\\ b = 3\\) CAO` },
      { q: `Show that the derivative of \\(\\frac{\\ln x}{x^2}\\) can be written as \\(\\frac{1 - 2\\ln x}{x^3}\\)`, marks: 3, command: 'Show that', markScheme: `M1: Uses the quotient rule (or product rule on \\(x^{-2}\\ln x\\)) with \\(\\frac{d}{dx}(\\ln x) = \\frac{1}{x}\\)\nA1: \\(\\frac{x^2 \\cdot \\frac{1}{x} - 2x\\ln x}{x^4}\\) or \\(x^{-3} - 2x^{-3}\\ln x\\)\nA1: Simplifies fully to \\(\\frac{1 - 2\\ln x}{x^3}\\) with no errors seen (answer given)` },
      { q: `A curve has equation \\(y = (3x^2 - 1)^5\\)\n\nFind the gradient of the curve at the point where \\(x = 1\\)`, marks: 3, command: 'Find', markScheme: `M1: Uses the chain rule: \\(k x(3x^2 - 1)^4\\)\nA1: \\(\\frac{dy}{dx} = 30x(3x^2 - 1)^4\\)\nA1: Gradient \\(= 30 \\times 2^4 = 480\\) CAO` },
      { q: `A company models the total cost, \\(C\\) thousand pounds, of producing \\(x\\) thousand units of a product per month by\n\\(C = x^3 - 6x^2 + 15x + 4\\), for \\(x \\geq 0\\)\n\nShow that, according to the model, the total cost always increases as the number of units produced increases.`, marks: 3, command: 'Show that', markScheme: `M1: \\(\\frac{dC}{dx} = 3x^2 - 12x + 15\\)\nM1: Completes the square or uses the discriminant: \\(3(x - 2)^2 + 3\\) or \\(b^2 - 4ac = 144 - 180 \\lt 0\\)\nE1: \\(\\frac{dC}{dx} \\geq 3 \\gt 0\\) for all \\(x\\), so \\(C\\) is an increasing function; concludes in context` },
      { q: `Find the equation of the tangent to the curve \\(y = x^3 - 4x + 1\\) at the point \\((2, 1)\\)\nGive your answer in the form \\(y = mx + c\\)`, marks: 3, command: 'Find', markScheme: `B1: \\(\\frac{dy}{dx} = 3x^2 - 4\\)\nM1: Substitutes \\(x = 2\\) to obtain gradient 8 and uses \\(y - 1 = 8(x - 2)\\)\nA1: \\(y = 8x - 15\\) CAO` },
      { q: `A spherical balloon is being inflated so that its volume increases at a constant rate of \\(50\\ \\text{cm}^3\\ \\text{s}^{-1}\\)\n\nFind the rate at which the radius of the balloon is increasing at the instant when the radius is 10 cm.\nGive your answer to three significant figures.\n[The volume of a sphere of radius \\(r\\) is \\(\\frac{4}{3}\\pi r^3\\)]`, marks: 3, command: 'Find', markScheme: `B1: \\(\\frac{dV}{dr} = 4\\pi r^2\\)\nM1: Uses \\(\\frac{dr}{dt} = \\frac{dV}{dt} \\div \\frac{dV}{dr} = \\frac{50}{4\\pi \\times 10^2}\\)\nA1: \\(\\frac{1}{8\\pi} = 0.0398\\ \\text{cm s}^{-1}\\) AWRT 0.0398` },
      { q: `A curve has equation \\(y = x^4 - 6x^2\\)\n\nFind the set of values of \\(x\\) for which the curve is concave.`, marks: 3, command: 'Find', markScheme: `M1: Differentiates twice: \\(\\frac{d^2y}{dx^2} = 12x^2 - 12\\)\nM1: Sets \\(\\frac{d^2y}{dx^2} \\lt 0\\)\nA1: \\(-1 \\lt x \\lt 1\\) CAO (accept \\(\\{x : -1 \\lt x \\lt 1\\}\\))` },
      { q: `Given that \\(y = 3x^2\\), use differentiation from first principles to show that \\(\\frac{dy}{dx} = 6x\\)`, marks: 4, command: 'Show that', markScheme: `M1: Considers \\(\\frac{3(x + h)^2 - 3x^2}{h}\\) (condone \\(\\delta x\\) for \\(h\\))\nA1: Expands correctly: \\(\\frac{6xh + 3h^2}{h}\\)\nA1: Simplifies to \\(6x + 3h\\)\nE1: States that as \\(h \\to 0\\), \\(6x + 3h \\to 6x\\), so \\(\\frac{dy}{dx} = 6x\\). Must use limit notation or words "as \\(h\\) tends to 0"; setting \\(h = 0\\) is E0` },
      { q: `A curve \\(C\\) is defined by the parametric equations\n\\(x = t^2 + 1,\\quad y = t^3 - 3t\\)\n\nFind the equation of the tangent to \\(C\\) at the point where \\(t = 2\\)\nGive your answer in the form \\(ax + by = c\\), where \\(a\\), \\(b\\) and \\(c\\) are integers.`, marks: 4, command: 'Find', markScheme: `M1: \\(\\frac{dy}{dx} = \\frac{dy/dt}{dx/dt} = \\frac{3t^2 - 3}{2t}\\)\nA1: At \\(t = 2\\), gradient \\(= \\frac{9}{4}\\)\nB1: Point is \\((5, 2)\\)\nA1: \\(y - 2 = \\frac{9}{4}(x - 5)\\), so \\(9x - 4y = 37\\) (or any integer multiple) CAO` },
      { q: `A curve has equation \\(x^2 + 3xy + y^2 = 11\\)\n\nFind the gradient of the curve at the point \\((1, 2)\\)`, marks: 4, command: 'Find', markScheme: `M1: Implicit differentiation with \\(y^2 \\to 2y\\frac{dy}{dx}\\)\nM1: Product rule on \\(3xy\\): \\(3y + 3x\\frac{dy}{dx}\\)\nA1: \\(2x + 3y + 3x\\frac{dy}{dx} + 2y\\frac{dy}{dx} = 0\\)\nA1: Substitutes \\((1, 2)\\): \\(8 + 7\\frac{dy}{dx} = 0\\), gradient \\(= -\\frac{8}{7}\\) CAO` },
      { q: `The curve \\(y = x^2 \\ln x\\) passes through the point \\(P(e, e^2)\\)\n\nFind the equation of the normal to the curve at \\(P\\)\nGive your answer in the form \\(x + py = q\\), where \\(p\\) and \\(q\\) are expressed exactly in terms of \\(e\\)`, marks: 4, command: 'Find', markScheme: `M1: Product rule: \\(\\frac{dy}{dx} = 2x\\ln x + x\\)\nA1: At \\(x = e\\), gradient of tangent \\(= 3e\\)\nM1: Gradient of normal \\(= -\\frac{1}{3e}\\) and uses \\(y - e^2 = -\\frac{1}{3e}(x - e)\\)\nA1: \\(x + 3ey = 3e^3 + e\\) CAO` },
      { q: `(a) Given that \\(y = \\frac{1}{\\cos x}\\), use the quotient rule to show that \\(\\frac{dy}{dx} = \\sec x \\tan x\\)  [2]\n(b) Hence find the exact value of the gradient of the curve \\(y = \\sec 2x\\) at the point where \\(x = \\frac{\\pi}{8}\\)  [2]`, marks: 4, command: 'Show that', markScheme: `(a)\nM1: \\(\\frac{\\cos x \\times 0 - 1 \\times (-\\sin x)}{\\cos^2 x}\\)\nA1: \\(= \\frac{\\sin x}{\\cos^2 x} = \\frac{1}{\\cos x} \\cdot \\frac{\\sin x}{\\cos x} = \\sec x \\tan x\\) (answer given; intermediate step must be seen)\n(b)\nM1: \\(\\frac{dy}{dx} = 2\\sec 2x \\tan 2x\\)\nA1: \\(2 \\times \\sqrt{2} \\times 1 = 2\\sqrt{2}\\) CAO` },
      { q: `The concentration, \\(C\\) mg per litre, of a drug in a patient's bloodstream \\(t\\) hours after an injection is modelled by\n\\(C = 20te^{-0.5t}\\), for \\(t \\geq 0\\)\n\n(a) Find the maximum concentration predicted by the model. Give your answer to three significant figures.  [3]\n(b) State one limitation of the model.  [1]`, marks: 4, command: 'Find', markScheme: `(a)\nM1: Product rule: \\(\\frac{dC}{dt} = 20e^{-0.5t} - 10te^{-0.5t}\\)\nA1: Sets \\(\\frac{dC}{dt} = 0\\): \\(20e^{-0.5t}(1 - 0.5t) = 0\\), so \\(t = 2\\)\nA1: \\(C = 40e^{-1} = 14.7\\) mg per litre AWRT 14.7\n(b)\nE1: e.g. the model predicts the concentration is never exactly zero / the model assumes an instant rise from \\(t = 0\\) / it ignores variation between patients or further doses` },
      { q: `A curve has equation \\(y = x^4 - 4x^3 + 10\\)\n\nFind the coordinates of the points of inflection of the curve.\nFully justify your answer.`, marks: 4, command: 'Find', markScheme: `M1: \\(\\frac{dy}{dx} = 4x^3 - 12x^2\\) and \\(\\frac{d^2y}{dx^2} = 12x^2 - 24x\\)\nA1: \\(12x(x - 2) = 0\\), \\(x = 0\\) or \\(x = 2\\)\nR1: Shows \\(\\frac{d^2y}{dx^2}\\) changes sign at each, e.g. \\(y''(-1) = 36 \\gt 0,\\ y''(1) = -12 \\lt 0,\\ y''(3) = 36 \\gt 0\\)\nA1: \\((0, 10)\\) and \\((2, -6)\\) CAO\nNote: \\(y'' = 0\\) alone without a sign-change argument is R0.` },
      { q: `A curve has equation \\(y = \\ln(x^2 + 4)\\)\n\nProve that the gradient of the curve is never greater than \\(\\frac{1}{2}\\)`, marks: 4, command: 'Prove that', markScheme: `M1: Chain rule: \\(\\frac{dy}{dx} = \\frac{2x}{x^2 + 4}\\)\nA1: Correct derivative\nM1: Considers \\(\\frac{2x}{x^2 + 4} \\leq \\frac{1}{2}\\), multiplying by \\(x^2 + 4 \\gt 0\\): \\(4x \\leq x^2 + 4\\)\nR1: \\(x^2 - 4x + 4 = (x - 2)^2 \\geq 0\\), true for all real \\(x\\), so gradient \\(\\leq \\frac{1}{2}\\). Must state \\(x^2 + 4 \\gt 0\\) (or equivalent) and conclude` },
      { q: `A curve has equation \\(y = x^3 - 6x^2 + 9x + 2\\)\n\nFind the coordinates of the stationary points of the curve and determine the nature of each.`, marks: 5, command: 'Find', markScheme: `M1: \\(\\frac{dy}{dx} = 3x^2 - 12x + 9\\), sets equal to 0\nA1: \\(3(x - 1)(x - 3) = 0\\), \\(x = 1,\\ x = 3\\)\nA1: \\((1, 6)\\) and \\((3, 2)\\)\nM1: \\(\\frac{d^2y}{dx^2} = 6x - 12\\) evaluated at one point (or valid sign test of \\(\\frac{dy}{dx}\\))\nA1: \\(y''(1) = -6 \\lt 0\\): \\((1, 6)\\) is a maximum; \\(y''(3) = 6 \\gt 0\\): \\((3, 2)\\) is a minimum` },
      { q: `An open box is made from a square sheet of card of side 30 cm by cutting a square of side \\(x\\) cm from each corner and folding up the sides.\n\n(a) Show that the volume, \\(V\\ \\text{cm}^3\\), of the box is given by \\(V = 4x^3 - 120x^2 + 900x\\)  [1]\n(b) Find the maximum volume of the box, fully justifying that it is a maximum.  [4]`, marks: 5, command: 'Find', markScheme: `(a)\nB1: \\(V = x(30 - 2x)^2 = x(900 - 120x + 4x^2)\\) leading to given answer\n(b)\nM1: \\(\\frac{dV}{dx} = 12x^2 - 240x + 900\\), sets equal to 0\nA1: \\(12(x - 5)(x - 15) = 0\\); \\(x = 5\\) (rejects \\(x = 15\\) since then the base has zero width)\nA1: \\(V = 5 \\times 20^2 = 2000\\ \\text{cm}^3\\)\nR1: \\(\\frac{d^2V}{dx^2} = 24x - 240 = -120 \\lt 0\\) at \\(x = 5\\), so maximum` },
      { q: `A curve has equation \\(x^2 - xy + y^2 = 12\\)\n\nFind the coordinates of the points on the curve at which the tangent is parallel to the \\(x\\)-axis.`, marks: 5, command: 'Find', markScheme: `M1: Implicit differentiation, including product rule on \\(xy\\)\nA1: \\(2x - y - x\\frac{dy}{dx} + 2y\\frac{dy}{dx} = 0\\), so \\(\\frac{dy}{dx} = \\frac{y - 2x}{2y - x}\\)\nM1: Sets numerator \\(= 0\\): \\(y = 2x\\) and substitutes into the curve\nA1: \\(x^2 - 2x^2 + 4x^2 = 12\\), \\(3x^2 = 12\\), \\(x = \\pm 2\\)\nA1: \\((2, 4)\\) and \\((-2, -4)\\) CAO` },
      { q: `A water tank is in the shape of an inverted right circular cone with its vertex at the bottom. The tank has height 60 cm and the radius of its top is 30 cm.\nWater is poured into the tank at a constant rate of \\(200\\ \\text{cm}^3\\ \\text{s}^{-1}\\)\nWhen the depth of water is \\(h\\) cm, the volume of water in the tank is \\(V\\ \\text{cm}^3\\)\n\n(a) Show that \\(V = \\frac{\\pi h^3}{12}\\)  [2]\n(b) Find the rate at which the depth of water is increasing when \\(h = 20\\). Give your answer to three significant figures.  [3]`, marks: 5, command: 'Show that', markScheme: `(a)\nM1: Uses similar triangles: radius of water surface \\(r = \\frac{h}{2}\\)\nA1: \\(V = \\frac{1}{3}\\pi\\left(\\frac{h}{2}\\right)^2 h = \\frac{\\pi h^3}{12}\\) (answer given)\n(b)\nB1: \\(\\frac{dV}{dh} = \\frac{\\pi h^2}{4}\\)\nM1: \\(\\frac{dh}{dt} = \\frac{200}{\\pi h^2/4}\\) with \\(h = 20\\)\nA1: \\(\\frac{2}{\\pi} = 0.637\\ \\text{cm s}^{-1}\\) AWRT 0.637` },
      { q: `(a) Show that \\(\\frac{d}{dx}\\left(\\frac{\\sin x}{1 + \\cos x}\\right) = \\frac{1}{1 + \\cos x}\\)  [4]\n(b) Hence find the gradient of the curve \\(y = \\frac{\\sin x}{1 + \\cos x}\\) at the point where \\(x = \\frac{\\pi}{3}\\)  [1]`, marks: 5, command: 'Show that', markScheme: `(a)\nM1: Quotient rule with \\(\\frac{d}{dx}(\\cos x) = -\\sin x\\)\nA1: \\(\\frac{\\cos x(1 + \\cos x) + \\sin^2 x}{(1 + \\cos x)^2}\\)\nM1: Uses \\(\\sin^2 x + \\cos^2 x = 1\\): numerator \\(= 1 + \\cos x\\)\nA1: Cancels to \\(\\frac{1}{1 + \\cos x}\\) with no errors (answer given)\n(b)\nB1: \\(\\frac{1}{1 + \\frac{1}{2}} = \\frac{2}{3}\\) CAO` },
      { q: `A curve \\(C\\) is defined by the parametric equations\n\\(x = 2\\cos t,\\quad y = 3\\sin t,\\quad 0 \\leq t \\lt 2\\pi\\)\n\nThe normal to \\(C\\) at the point where \\(t = \\frac{\\pi}{4}\\) crosses the \\(x\\)-axis at the point \\(Q\\)\nFind the exact \\(x\\)-coordinate of \\(Q\\)`, marks: 5, command: 'Find', markScheme: `M1: \\(\\frac{dy}{dx} = \\frac{3\\cos t}{-2\\sin t}\\)\nA1: At \\(t = \\frac{\\pi}{4}\\), gradient of tangent \\(= -\\frac{3}{2}\\)\nB1: Point \\(\\left(\\sqrt{2}, \\frac{3\\sqrt{2}}{2}\\right)\\)\nM1: Normal gradient \\(\\frac{2}{3}\\): \\(y - \\frac{3\\sqrt{2}}{2} = \\frac{2}{3}(x - \\sqrt{2})\\), sets \\(y = 0\\)\nA1: \\(x = -\\frac{5\\sqrt{2}}{4}\\) CAO` },
      { q: `The population, \\(P\\), of a town \\(t\\) years after 1 January 2020 is modelled by\n\\(P = 2000 \\times 1.05^t\\)\n\n(a) Find an expression for \\(\\frac{dP}{dt}\\)  [2]\n(b) Find the rate at which the population is increasing when \\(t = 10\\)  [1]\n(c) Find the value of \\(t\\) at which the model predicts the population is increasing at a rate of 200 people per year. Give your answer to three significant figures.  [2]`, marks: 5, command: 'Find', markScheme: `(a)\nM1: Writes \\(1.05^t = e^{t\\ln 1.05}\\) or quotes \\(\\frac{d}{dt}(a^t) = a^t \\ln a\\)\nA1: \\(\\frac{dP}{dt} = 2000\\ln 1.05 \\times 1.05^t\\)\n(b)\nB1: 159 people per year AWRT 159\n(c)\nM1: \\(2000\\ln 1.05 \\times 1.05^t = 200\\), takes logs correctly: \\(t = \\frac{\\ln(0.1/\\ln 1.05)}{\\ln 1.05}\\)\nA1: \\(t = 14.7\\) AWRT 14.7` },
      { q: `A lorry makes a journey of 200 km at a constant speed of \\(v\\) km per hour. The cost of the journey, \\(£C\\), is modelled by\n\\(C = \\frac{3200}{v} + 2v\\), for \\(20 \\leq v \\leq 90\\)\n(model written for this practice question)\n\n(a) Find the value of \\(v\\) that minimises the cost, and the minimum cost.  [4]\n(b) Use calculus to verify that this value gives a minimum.  [1]\n(c) State one limitation of the model.  [1]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: \\(\\frac{dC}{dv} = -\\frac{3200}{v^2} + 2\\)\nM1: Sets \\(\\frac{dC}{dv} = 0\\): \\(v^2 = 1600\\)\nA1: \\(v = 40\\) (rejects \\(-40\\))\nA1: \\(C = 80 + 80 = £160\\)\n(b)\nR1: \\(\\frac{d^2C}{dv^2} = \\frac{6400}{v^3} \\gt 0\\) at \\(v = 40\\), so minimum\n(c)\nE1: e.g. the lorry cannot travel at a constant speed for the whole journey / the speed limit or traffic may prevent 40 km/h / fuel cost does not vary exactly linearly with speed` },
      { q: `A curve has equation \\(y = x^2 e^{-x}\\)\n\n(a) Find the exact coordinates of the stationary points of the curve.  [4]\n(b) Use the second derivative to determine the nature of each stationary point.  [2]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: Product rule: \\(\\frac{dy}{dx} = 2xe^{-x} - x^2e^{-x}\\)\nA1: Correct derivative\nM1: \\(xe^{-x}(2 - x) = 0\\), using \\(e^{-x} \\neq 0\\)\nA1: \\((0, 0)\\) and \\((2, 4e^{-2})\\) CAO\n(b)\nM1: \\(\\frac{d^2y}{dx^2} = e^{-x}(x^2 - 4x + 2)\\) and evaluates at either point\nA1: \\(y''(0) = 2 \\gt 0\\), minimum at \\((0, 0)\\); \\(y''(2) = -2e^{-2} \\lt 0\\), maximum at \\((2, 4e^{-2})\\)` },
      { q: `A manufacturer makes closed cylindrical cans, each with volume \\(500\\ \\text{cm}^3\\). A can has base radius \\(r\\) cm and total surface area \\(A\\ \\text{cm}^2\\)\n\n(a) Show that \\(A = 2\\pi r^2 + \\frac{1000}{r}\\)  [2]\n(b) Find the minimum surface area of a can, giving your answer to three significant figures. Fully justify that your answer is a minimum.  [4]`, marks: 6, command: 'Show that', markScheme: `(a)\nM1: \\(\\pi r^2 h = 500\\), so \\(h = \\frac{500}{\\pi r^2}\\), substituted into \\(A = 2\\pi r^2 + 2\\pi r h\\)\nA1: \\(A = 2\\pi r^2 + \\frac{1000}{r}\\) (answer given)\n(b)\nM1: \\(\\frac{dA}{dr} = 4\\pi r - \\frac{1000}{r^2}\\), sets equal to 0\nA1: \\(r^3 = \\frac{250}{\\pi}\\), \\(r = 4.30\\) AWRT 4.30\nA1: \\(A = 349\\ \\text{cm}^2\\) AWRT 349\nR1: \\(\\frac{d^2A}{dr^2} = 4\\pi + \\frac{2000}{r^3} \\gt 0\\) for \\(r \\gt 0\\), so minimum` },
      { q: `(a) Use the small-angle approximations for \\(\\sin h\\) and \\(\\cos h\\) to show that, as \\(h \\to 0\\),\n\\(\\frac{\\sin h}{h} \\to 1\\) and \\(\\frac{\\cos h - 1}{h} \\to 0\\)  [2]\n(b) Hence prove from first principles that the derivative of \\(\\sin x\\) is \\(\\cos x\\)  [4]`, marks: 6, command: 'Prove that', markScheme: `(a)\nB1: \\(\\sin h \\approx h\\), so \\(\\frac{\\sin h}{h} \\approx 1\\), tending to 1\nB1: \\(\\cos h \\approx 1 - \\frac{h^2}{2}\\), so \\(\\frac{\\cos h - 1}{h} \\approx -\\frac{h}{2} \\to 0\\)\n(b)\nM1: \\(f'(x) = \\lim_{h \\to 0} \\frac{\\sin(x + h) - \\sin x}{h}\\)\nM1: Expands \\(\\sin(x + h) = \\sin x\\cos h + \\cos x\\sin h\\)\nA1: Rearranges to \\(\\sin x\\left(\\frac{\\cos h - 1}{h}\\right) + \\cos x\\left(\\frac{\\sin h}{h}\\right)\\)\nR1: Applies the limits from (a) to obtain \\(\\sin x \\times 0 + \\cos x \\times 1 = \\cos x\\), with limit notation throughout` },
      { q: `A curve has equation \\(y^3 + 3xy - x^2 = 3\\)\n\n(a) Find \\(\\frac{dy}{dx}\\) in terms of \\(x\\) and \\(y\\)  [3]\n(b) Find the equation of the normal to the curve at the point \\((1, 1)\\)  [3]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: Implicit differentiation: \\(3y^2\\frac{dy}{dx}\\) seen\nM1: Product rule on \\(3xy\\): \\(3y + 3x\\frac{dy}{dx}\\)\nA1: \\(\\frac{dy}{dx} = \\frac{2x - 3y}{3y^2 + 3x}\\) oe\n(b)\nA1: At \\((1, 1)\\): \\(\\frac{dy}{dx} = -\\frac{1}{6}\\)\nM1: Normal gradient \\(6\\), uses \\(y - 1 = 6(x - 1)\\)\nA1: \\(y = 6x - 5\\) CAO` },
      { q: `A curve has equation \\(y = xe^x\\)\n\n(a) Find the exact coordinates of the stationary point of the curve and show that it is a minimum.  [4]\n(b) Find the exact coordinates of the point of inflection of the curve, justifying your answer.  [2]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: \\(\\frac{dy}{dx} = e^x + xe^x\\)\nA1: \\(e^x(1 + x) = 0\\), \\(x = -1\\), point \\(\\left(-1, -e^{-1}\\right)\\)\nM1: \\(\\frac{d^2y}{dx^2} = e^x(2 + x)\\)\nA1: \\(y''(-1) = e^{-1} \\gt 0\\), so minimum\n(b)\nM1: \\(e^x(2 + x) = 0\\), \\(x = -2\\), and \\(y''\\) changes sign since \\(e^x \\gt 0\\) and \\(2 + x\\) changes sign\nA1: \\(\\left(-2, -2e^{-2}\\right)\\) CAO` },
      { q: `A curve \\(C\\) is defined by the parametric equations\n\\(x = t^2 - 2t,\\quad y = t^3 - 3t\\)\n\n(a) Show that, for \\(t \\neq 1\\), \\(\\frac{dy}{dx} = \\frac{3}{2}(t + 1)\\)  [2]\n(b) Find the equation of the tangent to \\(C\\) at the point where \\(t = 2\\)  [3]\n(c) Find the coordinates of the stationary point on \\(C\\)  [2]`, marks: 7, command: 'Show that', markScheme: `(a)\nM1: \\(\\frac{dy}{dx} = \\frac{3t^2 - 3}{2t - 2}\\)\nA1: \\(= \\frac{3(t - 1)(t + 1)}{2(t - 1)} = \\frac{3}{2}(t + 1)\\) (answer given)\n(b)\nB1: Point \\((0, 2)\\)\nM1: Gradient \\(\\frac{9}{2}\\), uses \\(y - 2 = \\frac{9}{2}(x - 0)\\)\nA1: \\(y = \\frac{9}{2}x + 2\\) oe\n(c)\nM1: \\(\\frac{3}{2}(t + 1) = 0\\), \\(t = -1\\)\nA1: \\((3, 2)\\) CAO` },
      { q: `A window is in the shape of a rectangle of width \\(2r\\) metres and height \\(h\\) metres, with a semicircle of radius \\(r\\) metres on top. The total perimeter of the window is 6 metres.\n\n(a) Show that the area, \\(A\\ \\text{m}^2\\), of the window is given by \\(A = 6r - \\left(2 + \\frac{\\pi}{2}\\right)r^2\\)  [3]\n(b) Find the exact maximum area of the window, fully justifying that it is a maximum.  [4]`, marks: 7, command: 'Show that', markScheme: `(a)\nB1: Perimeter: \\(2r + 2h + \\pi r = 6\\)\nM1: \\(A = 2rh + \\frac{1}{2}\\pi r^2\\), substituting \\(h = \\frac{6 - 2r - \\pi r}{2}\\)\nA1: \\(A = 6r - 2r^2 - \\pi r^2 + \\frac{1}{2}\\pi r^2 = 6r - \\left(2 + \\frac{\\pi}{2}\\right)r^2\\) (answer given)\n(b)\nM1: \\(\\frac{dA}{dr} = 6 - (4 + \\pi)r = 0\\)\nA1: \\(r = \\frac{6}{4 + \\pi}\\)\nA1: \\(A = \\frac{18}{4 + \\pi}\\ \\text{m}^2\\) CAO (2.52 alone scores A0)\nR1: \\(\\frac{d^2A}{dr^2} = -(4 + \\pi) \\lt 0\\), so maximum` },
      { q: `The curve \\(y = x^2 - 4x + 5\\) passes through the point \\(P(3, 2)\\)\nThe tangent to the curve at \\(P\\) crosses the \\(x\\)-axis at \\(A\\). The normal to the curve at \\(P\\) crosses the \\(x\\)-axis at \\(B\\)\n\n(a) Find the equation of the tangent at \\(P\\)  [3]\n(b) Find the equation of the normal at \\(P\\)  [2]\n(c) Find the area of triangle \\(APB\\)  [2]`, marks: 7, command: 'Find', markScheme: `(a)\nB1: \\(\\frac{dy}{dx} = 2x - 4\\)\nM1: Gradient 2 at \\(x = 3\\), uses \\(y - 2 = 2(x - 3)\\)\nA1: \\(y = 2x - 4\\)\n(b)\nM1: Gradient \\(-\\frac{1}{2}\\), uses \\(y - 2 = -\\frac{1}{2}(x - 3)\\)\nA1: \\(x + 2y = 7\\) oe\n(c)\nM1: \\(A(2, 0)\\), \\(B(7, 0)\\) (ft their lines)\nA1: Area \\(= \\frac{1}{2} \\times 5 \\times 2 = 5\\) CAO` },
      { q: `The function f is defined by \\(f(x) = \\frac{e^{2x}}{x^2 + 1}\\), for \\(x \\in \\mathbb{R}\\)\n\n(a) Show that \\(f'(x) = \\frac{2e^{2x}(x^2 - x + 1)}{(x^2 + 1)^2}\\)  [3]\n(b) Prove that f is an increasing function.  [3]\n(c) Find the gradient of the curve \\(y = f(x)\\) where it crosses the \\(y\\)-axis.  [1]`, marks: 7, command: 'Show that', markScheme: `(a)\nM1: Quotient rule with \\(\\frac{d}{dx}(e^{2x}) = 2e^{2x}\\)\nA1: \\(\\frac{2e^{2x}(x^2 + 1) - 2xe^{2x}}{(x^2 + 1)^2}\\)\nA1: Factorises to the given answer\n(b)\nM1: Completes the square: \\(x^2 - x + 1 = \\left(x - \\frac{1}{2}\\right)^2 + \\frac{3}{4}\\)\nA1: \\(\\left(x - \\frac{1}{2}\\right)^2 + \\frac{3}{4} \\gt 0\\)\nR1: States \\(e^{2x} \\gt 0\\) and \\((x^2 + 1)^2 \\gt 0\\), so \\(f'(x) \\gt 0\\) for all \\(x\\); hence f is increasing\n(c)\nB1: \\(f'(0) = 2\\) CAO` },
      { q: `The concentration, \\(C\\) mg per litre, of a medicine in a patient's blood \\(t\\) hours after it is taken orally is modelled by\n\\(C = 10\\left(e^{-0.2t} - e^{-t}\\right)\\), for \\(t \\geq 0\\)\n(model written for this practice question)\n\n(a) Show that the concentration is a maximum when \\(t = \\frac{5}{4}\\ln 5\\)  [3]\n(b) Find the maximum concentration, giving your answer to three significant figures.  [1]\n(c) After the maximum, there is a time \\(T\\) at which the concentration is decreasing most rapidly. Find the exact value of \\(T\\), justifying your answer.  [3]\n(d) State one limitation of the model.  [1]`, marks: 8, command: 'Show that', markScheme: `(a)\nM1: \\(\\frac{dC}{dt} = 10\\left(-0.2e^{-0.2t} + e^{-t}\\right)\\), sets equal to 0\nM1: \\(e^{-0.8t} = 0.2\\) (or \\(e^{0.8t} = 5\\)), takes logs\nA1: \\(t = \\frac{\\ln 5}{0.8} = \\frac{5}{4}\\ln 5\\) (answer given) with sign change or \\(C'' \\lt 0\\) referenced\n(b)\nB1: \\(C = 5.35\\) mg per litre AWRT 5.35\n(c)\nM1: \\(\\frac{d^2C}{dt^2} = 10\\left(0.04e^{-0.2t} - e^{-t}\\right) = 0\\)\nA1: \\(e^{-0.8t} = 0.04\\), \\(T = \\frac{\\ln 25}{0.8} = \\frac{5}{2}\\ln 5\\) oe\nR1: \\(\\frac{d^2C}{dt^2}\\) changes sign from negative to positive at \\(T\\), so \\(\\frac{dC}{dt}\\) has a minimum there (point of inflection on the graph of \\(C\\))\n(d)\nE1: e.g. the model never predicts zero concentration / does not allow for further doses / the same parameters will not fit every patient` },
      { q: `An open-topped box has a square base of side \\(x\\) cm and height \\(h\\) cm. Its volume is \\(32\\,000\\ \\text{cm}^3\\)\nThe material for the base costs 3p per \\(\\text{cm}^2\\) and the material for the sides costs 2p per \\(\\text{cm}^2\\)\n(data written for this practice question)\n\n(a) Show that the cost of the material, \\(C\\) pence, is given by \\(C = 3x^2 + \\frac{256\\,000}{x}\\)  [3]\n(b) Find the value of \\(x\\) that minimises the cost, and the minimum cost in pounds. Give your answers to three significant figures.  [4]\n(c) Show that this value of \\(x\\) gives a minimum.  [1]`, marks: 8, command: 'Show that', markScheme: `(a)\nB1: \\(x^2 h = 32\\,000\\)\nM1: \\(C = 3x^2 + 2 \\times 4xh\\), substituting \\(h = \\frac{32\\,000}{x^2}\\)\nA1: \\(C = 3x^2 + \\frac{256\\,000}{x}\\) (answer given)\n(b)\nM1: \\(\\frac{dC}{dx} = 6x - \\frac{256\\,000}{x^2}\\), sets equal to 0\nA1: \\(x^3 = \\frac{128\\,000}{3}\\)\nA1: \\(x = 34.9\\) AWRT 34.9\nA1: Minimum cost \\(= 10\\,989\\) p \\(= £110\\) AWRT £110 (condone £109.89)\n(c)\nR1: \\(\\frac{d^2C}{dx^2} = 6 + \\frac{512\\,000}{x^3} \\gt 0\\), so minimum` },
      { q: `A curve has equation \\(y = \\frac{x^2}{x - 1}\\), \\(x \\neq 1\\)\n\n(a) Show that \\(\\frac{dy}{dx} = \\frac{x(x - 2)}{(x - 1)^2}\\)  [3]\n(b) Find the coordinates of the stationary points of the curve and determine their nature.  [4]\n(c) Find the set of values of \\(x\\) for which \\(y\\) is a decreasing function of \\(x\\)  [2]`, marks: 9, command: 'Show that', markScheme: `(a)\nM1: Quotient rule: \\(\\frac{2x(x - 1) - x^2}{(x - 1)^2}\\)\nA1: Numerator \\(= x^2 - 2x\\)\nA1: \\(= \\frac{x(x - 2)}{(x - 1)^2}\\) (answer given)\n(b)\nM1: Sets numerator \\(= 0\\): \\(x = 0\\) or \\(x = 2\\)\nA1: \\((0, 0)\\) and \\((2, 4)\\)\nM1: Valid test, e.g. \\(\\frac{d^2y}{dx^2} = \\frac{2}{(x - 1)^3}\\) or sign of \\(\\frac{dy}{dx}\\) either side\nA1: \\((0, 0)\\) maximum (\\(y'' = -2\\)); \\((2, 4)\\) minimum (\\(y'' = 2\\))\n(c)\nM1: \\(x(x - 2) \\lt 0\\) with \\((x - 1)^2 \\gt 0\\)\nA1: \\(0 \\lt x \\lt 1\\) and \\(1 \\lt x \\lt 2\\) CAO (must exclude \\(x = 1\\))` },
      { q: `A gutter is made by bending a strip of metal of width 30 cm. In cross-section, the gutter has a horizontal base of length 10 cm and two sides, each of length 10 cm, which each make an angle \\(\\theta\\) radians with the horizontal and slope outwards, where \\(0 \\lt \\theta \\leq \\frac{\\pi}{2}\\)\nThe cross-section is therefore an isosceles trapezium, open at the top.\n\n(a) Show that the area of the cross-section, \\(A\\ \\text{cm}^2\\), is given by \\(A = 100\\sin\\theta(1 + \\cos\\theta)\\)  [3]\n(b) Show that \\(\\frac{dA}{d\\theta} = 100\\left(2\\cos^2\\theta + \\cos\\theta - 1\\right)\\)  [2]\n(c) Hence find the exact maximum area of the cross-section, fully justifying that it is a maximum.  [4]\n(d) Explain why the maximum cross-sectional area might not give the gutter that carries the most rainwater in practice.  [1]`, marks: 10, command: 'Show that', markScheme: `(a)\nB1: Height of trapezium \\(= 10\\sin\\theta\\)\nB1: Width of top \\(= 10 + 20\\cos\\theta\\)\nM1: \\(A = \\frac{1}{2}(10 + 10 + 20\\cos\\theta) \\times 10\\sin\\theta = 100\\sin\\theta(1 + \\cos\\theta)\\) (answer given)\n(b)\nM1: Product rule: \\(100\\left[\\cos\\theta(1 + \\cos\\theta) - \\sin^2\\theta\\right]\\)\nA1: Uses \\(\\sin^2\\theta = 1 - \\cos^2\\theta\\) to obtain \\(100\\left(2\\cos^2\\theta + \\cos\\theta - 1\\right)\\) (answer given)\n(c)\nM1: \\((2\\cos\\theta - 1)(\\cos\\theta + 1) = 0\\)\nA1: \\(\\cos\\theta = \\frac{1}{2}\\), \\(\\theta = \\frac{\\pi}{3}\\) (rejects \\(\\cos\\theta = -1\\) as outside the range)\nA1: \\(A = 100 \\times \\frac{\\sqrt{3}}{2} \\times \\frac{3}{2} = 75\\sqrt{3}\\ \\text{cm}^2\\) CAO\nR1: \\(\\frac{d^2A}{d\\theta^2} = -100\\sin\\theta(1 + 4\\cos\\theta) = -150\\sqrt{3} \\lt 0\\) at \\(\\theta = \\frac{\\pi}{3}\\), so maximum (or valid sign change of \\(\\frac{dA}{d\\theta}\\))\n(d)\nE1: e.g. a wide, shallow shape may overflow in wind or if not exactly level / the metal will not bend into sharp corners / debris reduces the usable area` }
    ]
  },
  '1.8': {
    name: 'Integration',
    questions: [
      { q: `Find \\(\\displaystyle\\int \\left(6x^2 - \\frac{4}{x^3}\\right) dx\\)`, marks: 2, command: 'Find', markScheme: `M1: Raises at least one power by 1, e.g. \\(x^3\\) or \\(x^{-2}\\) seen\nA1: \\(2x^3 + 2x^{-2} + c\\) CAO (must include \\(+c\\))\nAnswer: \\(2x^3 + \\dfrac{2}{x^2} + c\\)` },
      { q: `Find \\(\\displaystyle\\int \\left(3e^{2x} + \\frac{1}{x}\\right) dx\\)`, marks: 2, command: 'Find', markScheme: `B1: \\(\\frac{3}{2}e^{2x}\\)\nB1: \\(\\ln|x| + c\\) (condone \\(\\ln x\\))\nAnswer: \\(\\frac{3}{2}e^{2x} + \\ln|x| + c\\)` },
      { q: `Find \\(\\displaystyle\\int \\frac{1}{2x + 5}\\, dx\\)`, marks: 2, command: 'Find', markScheme: `M1: \\(k\\ln|2x + 5|\\) for any non-zero constant \\(k\\)\nA1: \\(\\frac{1}{2}\\ln|2x + 5| + c\\) (condone missing modulus signs)\nAnswer: \\(\\frac{1}{2}\\ln|2x+5| + c\\)` },
      { q: `Find \\(\\displaystyle\\int \\sin x \\cos^4 x\\, dx\\)`, marks: 2, command: 'Find', markScheme: `M1: Recognises reverse chain rule: \\(k\\cos^5 x\\)\nA1: \\(-\\frac{1}{5}\\cos^5 x + c\\) CAO\nAnswer: \\(-\\frac{1}{5}\\cos^5 x + c\\)` },
      { q: `The height, \\(h\\) cm, of a plant \\(t\\) weeks after it is planted is modelled by\n\\[\\frac{dh}{dt} = 3\\sqrt{t} + \\frac{2}{t^2}, \\quad 1 \\leq t \\leq 4\\]\n(model written for this practice question)\n\nFind the increase in the height of the plant between \\(t = 1\\) and \\(t = 4\\)`, marks: 3, command: 'Find', markScheme: `M1: Integrates, at least one term correct: \\(2t^{3/2}\\) or \\(-2t^{-1}\\)\nA1: \\(\\left[2t^{3/2} - \\frac{2}{t}\\right]_1^4\\) fully correct\nA1: \\((16 - 0.5) - (2 - 2) = 15.5\\) cm CAO\nAnswer: 15.5 cm` },
      { q: `Find the exact value of\n\\[\\int_0^{\\pi/4} \\left(\\sin 2x + \\sec^2 x\\right) dx\\]`, marks: 3, command: 'Find', markScheme: `B1: \\(-\\frac{1}{2}\\cos 2x\\)\nB1: \\(\\tan x\\)\nB1: \\((0 + 1) - (-\\frac{1}{2} + 0) = \\frac{3}{2}\\) CAO\nAnswer: \\(\\frac{3}{2}\\)` },
      { q: `Show that\n\\[\\int_0^{2} \\frac{x}{x^2 + 4}\\, dx = \\frac{1}{2}\\ln 2\\]`, marks: 3, command: 'Show that', markScheme: `M1: Integrates to \\(k\\ln(x^2 + 4)\\)\nA1: \\(\\frac{1}{2}\\ln(x^2+4)\\)\nA1: \\(\\frac{1}{2}\\ln 8 - \\frac{1}{2}\\ln 4 = \\frac{1}{2}\\ln 2\\) with a correct log law step shown (AG, must be convincing)\nAnswer: \\(\\frac{1}{2}\\ln 2\\)` },
      { q: `It is given that\n\\[\\int_1^{k} (4x - 3)\\, dx = 10\\]\nwhere \\(k\\) is a constant and \\(k \\gt 1\\)\n\nFind the value of \\(k\\)`, marks: 3, command: 'Find', markScheme: `M1: Integrates and substitutes limits: \\((2k^2 - 3k) - (2 - 3)\\)\nA1: \\(2k^2 - 3k - 9 = 0\\) oe\nA1: \\((2k + 3)(k - 3) = 0\\), \\(k = 3\\) only (must reject \\(-\\frac{3}{2}\\))\nAnswer: \\(k = 3\\)` },
      { q: `The power output, \\(P\\) kW, of a set of solar panels \\(t\\) hours after 6 am is modelled by\n\\[P = 2t - \\frac{t^2}{6}, \\quad 0 \\leq t \\leq 12\\]\n(model written for this practice question)\nThe total energy produced, \\(E\\) kWh, is given by \\(\\displaystyle E = \\lim_{\\delta t \\to 0} \\sum_{t=0}^{12} P\\, \\delta t\\)\n\n(a) Write \\(E\\) as a definite integral. [1]\n(b) Find the value of \\(E\\) [2]`, marks: 3, command: 'Find', markScheme: `(a) B1: \\(E = \\int_0^{12} \\left(2t - \\frac{t^2}{6}\\right) dt\\)\n(b) M1: \\(\\left[t^2 - \\frac{t^3}{18}\\right]_0^{12}\\)\nA1: \\(144 - 96 = 48\\) kWh CAO\nAnswer: 48 kWh` },
      { q: `Find \\(\\displaystyle\\int \\tan^2 x\\, dx\\)`, marks: 3, command: 'Find', markScheme: `M1: Uses \\(\\tan^2 x = \\sec^2 x - 1\\)\nA1: One term correctly integrated: \\(\\tan x\\) or \\(-x\\)\nA1: \\(\\tan x - x + c\\) CAO\nAnswer: \\(\\tan x - x + c\\)` },
      { q: `Water flows into an empty tank. The rate of flow, in litres per minute, \\(t\\) minutes after the tap is opened is modelled by\n\\[r = 20e^{-0.1t}\\]\n(model written for this practice question)\n\nFind the total volume of water that flows into the tank in the first 10 minutes.\nGive your answer to three significant figures.`, marks: 3, command: 'Find', markScheme: `M1: \\(\\int_0^{10} 20e^{-0.1t}\\, dt\\) integrated to \\(ke^{-0.1t}\\)\nA1: \\(\\left[-200e^{-0.1t}\\right]_0^{10}\\)\nA1: \\(200(1 - e^{-1}) = 126\\) litres AWRT\nAnswer: 126 litres (3 sf)` },
      { q: `The curve \\(C\\) has equation \\(y = x^3 - 4x\\)\n\nFind the total area of the regions enclosed between \\(C\\) and the \\(x\\)-axis.\nFully justify your answer.`, marks: 4, command: 'Find', markScheme: `B1: Roots \\(x = -2, 0, 2\\)\nM1: Integrates: \\(\\frac{x^4}{4} - 2x^2\\)\nA1: \\(\\int_0^2 = -4\\) and \\(\\int_{-2}^0 = 4\\) (or uses symmetry)\nR1: Treats the region below the axis as positive area: total \\(= 4 + 4 = 8\\)\nNB \\(\\int_{-2}^{2} = 0\\) scores B1 M1 only\nAnswer: 8` },
      { q: `Find \\(\\displaystyle\\int x\\cos 3x\\, dx\\)`, marks: 4, command: 'Find', markScheme: `M1: Integration by parts with \\(u = x\\), \\(\\frac{dv}{dx} = \\cos 3x\\), giving \\(kx\\sin 3x - \\int k\\sin 3x\\, dx\\)\nA1: \\(\\frac{1}{3}x\\sin 3x - \\int \\frac{1}{3}\\sin 3x\\, dx\\)\ndM1: Integrates \\(\\sin 3x\\) to \\(\\pm\\frac{1}{3}\\cos 3x\\)\nA1: \\(\\frac{1}{3}x\\sin 3x + \\frac{1}{9}\\cos 3x + c\\) CAO\nAnswer: \\(\\frac{1}{3}x\\sin 3x + \\frac{1}{9}\\cos 3x + c\\)` },
      { q: `Use the substitution \\(u = x + 2\\) to find\n\\[\\int x\\sqrt{x + 2}\\, dx\\]\nGive your answer in terms of \\(x\\)`, marks: 4, command: 'Use', markScheme: `M1: Complete substitution: \\(\\int (u - 2)u^{1/2}\\, du\\)\nA1: \\(\\int \\left(u^{3/2} - 2u^{1/2}\\right) du\\)\ndM1: Integrates: \\(\\frac{2}{5}u^{5/2} - \\frac{4}{3}u^{3/2}\\)\nA1: \\(\\frac{2}{5}(x+2)^{5/2} - \\frac{4}{3}(x+2)^{3/2} + c\\) CAO, ISW\nAnswer: \\(\\frac{2}{5}(x+2)^{5/2} - \\frac{4}{3}(x+2)^{3/2} + c\\)` },
      { q: `Find \\(\\displaystyle\\int_2^3 \\frac{4}{x^2 - 1}\\, dx\\)\n\nGive your answer in the form \\(\\ln k\\), where \\(k\\) is a rational number.`, marks: 4, command: 'Find', markScheme: `M1: Partial fractions \\(\\frac{A}{x-1} + \\frac{B}{x+1}\\)\nA1: \\(\\frac{2}{x-1} - \\frac{2}{x+1}\\)\nM1: Integrates to \\(2\\ln(x-1) - 2\\ln(x+1)\\) and substitutes limits\nA1: \\((2\\ln 2 - 2\\ln 4) - (0 - 2\\ln 3) = \\ln\\frac{9}{4}\\) CAO\nAnswer: \\(\\ln\\frac{9}{4}\\)` },
      { q: `A circular puddle is drying up. Its radius, \\(r\\) cm, \\(t\\) minutes after it is first observed is modelled by\n\\[\\frac{dr}{dt} = -\\frac{0.2}{r}\\]\nWhen \\(t = 0\\), \\(r = 3\\)\n(model written for this practice question)\n\n(a) Solve the differential equation to find \\(r\\) in terms of \\(t\\) [3]\n(b) Find the time at which the model predicts the puddle disappears. [1]`, marks: 4, command: 'Solve', markScheme: `(a) M1: Separates and integrates: \\(\\int r\\, dr = \\int -0.2\\, dt\\)\nA1: \\(\\frac{1}{2}r^2 = -0.2t + c\\), \\(c = 4.5\\)\nA1: \\(r = \\sqrt{9 - 0.4t}\\) oe\n(b) B1ft: \\(9 - 0.4t = 0 \\Rightarrow t = 22.5\\) minutes\nAnswer: \\(r = \\sqrt{9 - 0.4t}\\); 22.5 minutes` },
      { q: `The cross-section of a road cutting is modelled by the region enclosed between the curve \\(y = 6x - x^2\\) and the line \\(y = 2x\\), where \\(x\\) and \\(y\\) are in metres.\n(model written for this practice question)\n\nFind the area of the cross-section.`, marks: 4, command: 'Find', markScheme: `M1: Equates \\(6x - x^2 = 2x\\) and solves: \\(x = 0\\), \\(x = 4\\)\nM1: \\(\\int_0^4 \\left(6x - x^2 - 2x\\right) dx\\) (or curve area minus triangle)\nA1: \\(\\left[2x^2 - \\frac{x^3}{3}\\right]_0^4\\)\nA1: \\(32 - \\frac{64}{3} = \\frac{32}{3}\\) m² (AWRT 10.7)\nAnswer: \\(\\frac{32}{3}\\) m²` },
      { q: `Find \\(\\displaystyle\\int x^2 \\ln x\\, dx\\)`, marks: 4, command: 'Find', markScheme: `M1: Integration by parts with \\(u = \\ln x\\), \\(\\frac{dv}{dx} = x^2\\)\nA1: \\(\\frac{x^3}{3}\\ln x - \\int \\frac{x^3}{3}\\cdot\\frac{1}{x}\\, dx\\)\ndM1: Simplifies and integrates \\(\\frac{x^2}{3}\\)\nA1: \\(\\frac{x^3}{3}\\ln x - \\frac{x^3}{9} + c\\) CAO\nNB \\(u = x^2\\) leads nowhere: M0\nAnswer: \\(\\frac{1}{3}x^3\\ln x - \\frac{1}{9}x^3 + c\\)` },
      { q: `Find the exact value of\n\\[\\int_0^{\\pi/3} \\sin^2 x\\, dx\\]`, marks: 4, command: 'Find', markScheme: `M1: Uses \\(\\sin^2 x = \\frac{1}{2}(1 - \\cos 2x)\\)\nA1: \\(\\frac{1}{2}x - \\frac{1}{4}\\sin 2x\\)\nM1: Substitutes limits \\(\\frac{\\pi}{3}\\) and 0\nA1: \\(\\frac{\\pi}{6} - \\frac{\\sqrt{3}}{8}\\) CAO\nAnswer: \\(\\frac{\\pi}{6} - \\frac{\\sqrt{3}}{8}\\)` },
      { q: `Use the substitution \\(u = \\sqrt{x}\\) to show that\n\\[\\int_1^4 \\frac{1}{1 + \\sqrt{x}}\\, dx = 2 + 2\\ln\\frac{2}{3}\\]`, marks: 5, command: 'Use', markScheme: `B1: \\(dx = 2u\\, du\\) oe\nM1: Full substitution: \\(\\int \\frac{2u}{1 + u}\\, du\\) with limits 1 and 2\nM1: Writes \\(\\frac{2u}{1+u} = 2 - \\frac{2}{1+u}\\) oe\nA1: \\(\\left[2u - 2\\ln(1 + u)\\right]_1^2\\)\nA1: \\((4 - 2\\ln 3) - (2 - 2\\ln 2) = 2 + 2\\ln\\frac{2}{3}\\) (AG, convincing)\nAnswer: \\(2 + 2\\ln\\frac{2}{3}\\)` },
      { q: `\\(\\displaystyle f(x) = \\frac{5x + 1}{(x - 1)(x + 2)}\\)\n\n(a) Express \\(f(x)\\) in partial fractions. [2]\n(b) Hence find \\(\\displaystyle\\int_2^4 f(x)\\, dx\\), giving your answer in the form \\(\\ln k\\), where \\(k\\) is a rational number. [3]`, marks: 5, command: 'Express', markScheme: `(a) M1: \\(5x + 1 = A(x + 2) + B(x - 1)\\) and a correct method for \\(A\\) or \\(B\\)\nA1: \\(\\frac{2}{x - 1} + \\frac{3}{x + 2}\\)\n(b) M1ft: \\(2\\ln(x - 1) + 3\\ln(x + 2)\\)\nM1: Substitutes limits: \\((2\\ln 3 + 3\\ln 6) - (0 + 3\\ln 4)\\)\nA1: \\(\\ln\\frac{243}{8}\\) CAO\nAnswer: (a) \\(\\frac{2}{x-1} + \\frac{3}{x+2}\\); (b) \\(\\ln\\frac{243}{8}\\)` },
      { q: `Solve the differential equation\n\\[\\frac{dy}{dx} = e^{2x - y}\\]\ngiven that \\(y = 0\\) when \\(x = 0\\)\n\nGive your answer in the form \\(y = f(x)\\)`, marks: 5, command: 'Solve', markScheme: `M1: Writes \\(e^{2x - y} = e^{2x}e^{-y}\\) and separates: \\(\\int e^{y}\\, dy = \\int e^{2x}\\, dx\\)\nA1: \\(e^{y}\\) and \\(\\frac{1}{2}e^{2x}\\)\nM1: Includes \\(+c\\) and uses \\(x = 0, y = 0\\): \\(c = \\frac{1}{2}\\)\nA1: \\(e^{y} = \\frac{1}{2}e^{2x} + \\frac{1}{2}\\)\nA1: \\(y = \\ln\\left(\\frac{e^{2x} + 1}{2}\\right)\\) CAO\nAnswer: \\(y = \\ln\\left(\\frac{1}{2}(e^{2x} + 1)\\right)\\)` },
      { q: `In a chemical reaction, a product is formed at a rate of \\(te^{-t}\\) moles per minute, where \\(t\\) is the time in minutes after the reaction starts.\n(model written for this practice question)\n\nFind the amount of product formed in the first 2 minutes.\nGive your answer in exact form and to three significant figures.`, marks: 5, command: 'Find', markScheme: `M1: \\(\\int_0^2 te^{-t}\\, dt\\) by parts with \\(u = t\\): \\(-te^{-t} - \\int -e^{-t}\\, dt\\)\nA1: \\(-te^{-t} - e^{-t}\\)\nM1: Substitutes limits correctly: \\((-2e^{-2} - e^{-2}) - (0 - 1)\\)\nA1: \\(1 - 3e^{-2}\\) moles\nA1: 0.594 moles AWRT\nAnswer: \\(1 - 3e^{-2} \\approx 0.594\\) moles` },
      { q: `A student is asked to find the area of the region bounded by the curve \\(y = x^2 - 2x - 3\\), the \\(x\\)-axis and the lines \\(x = 0\\) and \\(x = 4\\)\nThe student writes:\n"\\(\\int_0^4 (x^2 - 2x - 3)\\, dx = \\left[\\frac{x^3}{3} - x^2 - 3x\\right]_0^4 = -\\frac{20}{3}\\), so the area is \\(\\frac{20}{3}\\)"\n\n(a) Explain the error in the student's method. [1]\n(b) Find the correct area. [4]`, marks: 5, command: 'Explain', markScheme: `(a) E1: The curve crosses the \\(x\\)-axis at \\(x = 3\\) (between 0 and 4), so the negative area below the axis and the positive area above it partly cancel\n(b) B1: Root at \\(x = 3\\) identified\nM1: Splits into \\(\\int_0^3\\) and \\(\\int_3^4\\)\nA1: \\(\\int_0^3 = -9\\) and \\(\\int_3^4 = \\frac{7}{3}\\)\nA1: Area \\(= 9 + \\frac{7}{3} = \\frac{34}{3}\\) CAO\nAnswer: \\(\\frac{34}{3}\\)` },
      { q: `A drug is absorbed into a patient's bloodstream. The rate of absorption, in mg per hour, \\(t\\) hours after the drug is taken, is modelled by\n\\[r = 12te^{-0.5t}\\]\n(model written for this practice question)\n\nFind the total amount of the drug absorbed in the first 4 hours.\nGive your answer to three significant figures.`, marks: 5, command: 'Find', markScheme: `M1: Integration by parts on \\(\\int 12te^{-0.5t}\\, dt\\) with \\(u = 12t\\)\nA1: \\(-24te^{-0.5t} + \\int 24e^{-0.5t}\\, dt\\)\nA1: \\(-24te^{-0.5t} - 48e^{-0.5t}\\)\nM1: Uses limits 0 and 4: \\((-96e^{-2} - 48e^{-2}) - (-48)\\)\nA1: \\(48 - 144e^{-2} = 28.5\\) mg AWRT\nAnswer: 28.5 mg` },
      { q: `Show that\n\\[\\int_0^{\\pi/3} \\sin^3 x\\, dx = \\frac{5}{24}\\]`, marks: 5, command: 'Show that', markScheme: `M1: Writes \\(\\sin^3 x = \\sin x(1 - \\cos^2 x)\\)\nA1: \\(\\int (\\sin x - \\sin x\\cos^2 x)\\, dx\\)\nM1: Uses reverse chain rule: \\(\\int \\sin x\\cos^2 x\\, dx = -\\frac{1}{3}\\cos^3 x\\)\nA1: \\(-\\cos x + \\frac{1}{3}\\cos^3 x\\)\nA1: \\(\\left(-\\frac{1}{2} + \\frac{1}{24}\\right) - \\left(-1 + \\frac{1}{3}\\right) = \\frac{5}{24}\\) (AG, convincing)\nAnswer: \\(\\frac{5}{24}\\)` },
      { q: `(a) Use integration by parts to find \\(\\displaystyle\\int \\ln x\\, dx\\) [3]\n(b) The region \\(R\\) is bounded by the curve \\(y = \\ln x\\), the \\(x\\)-axis and the line \\(x = e^2\\)\nHence find the exact area of \\(R\\) [3]`, marks: 6, command: 'Find', markScheme: `(a) M1: Writes \\(\\ln x\\) as \\(1 \\times \\ln x\\) with \\(u = \\ln x\\), \\(\\frac{dv}{dx} = 1\\)\nA1: \\(x\\ln x - \\int x\\cdot\\frac{1}{x}\\, dx\\)\nA1: \\(x\\ln x - x + c\\)\n(b) B1: Lower limit \\(x = 1\\) (where \\(\\ln x = 0\\))\nM1: \\(\\left[x\\ln x - x\\right]_1^{e^2} = (2e^2 - e^2) - (0 - 1)\\)\nA1: \\(e^2 + 1\\) CAO\nAnswer: (a) \\(x\\ln x - x + c\\); (b) \\(e^2 + 1\\)` },
      { q: `A water tank has a small hole in its base. The depth of water, \\(h\\) metres, \\(t\\) minutes after the tank starts to leak is modelled by\n\\[\\frac{dh}{dt} = -k\\sqrt{h}\\]\nwhere \\(k\\) is a positive constant.\nInitially the depth is 4 metres. After 10 minutes the depth is 1 metre.\n(data written for this practice question)\n\n(a) Show that \\(h = (2 - 0.1t)^2\\) [5]\n(b) Find the time at which the model predicts the tank will be empty. [1]`, marks: 6, command: 'Show that', markScheme: `(a) M1: Separates: \\(\\int h^{-1/2}\\, dh = \\int -k\\, dt\\)\nA1: \\(2h^{1/2} = -kt + c\\)\nM1: Uses \\(t = 0, h = 4\\): \\(c = 4\\)\nM1: Uses \\(t = 10, h = 1\\): \\(2 = -10k + 4\\), \\(k = 0.2\\)\nA1: \\(\\sqrt{h} = 2 - 0.1t \\Rightarrow h = (2 - 0.1t)^2\\) (AG, convincing)\n(b) B1: \\(t = 20\\) minutes\nAnswer: (b) 20 minutes` },
      { q: `Use the substitution \\(x = 2\\sin\\theta\\) to find the exact value of\n\\[\\int_0^{1} \\frac{x^2}{\\sqrt{4 - x^2}}\\, dx\\]`, marks: 6, command: 'Use', markScheme: `B1: \\(dx = 2\\cos\\theta\\, d\\theta\\) and limits \\(0\\) and \\(\\frac{\\pi}{6}\\)\nM1: Full substitution: \\(\\int \\frac{4\\sin^2\\theta}{2\\cos\\theta}\\cdot 2\\cos\\theta\\, d\\theta = \\int 4\\sin^2\\theta\\, d\\theta\\)\nA1: \\(\\int 4\\sin^2\\theta\\, d\\theta\\) correct\nM1: Uses \\(\\sin^2\\theta = \\frac{1}{2}(1 - \\cos 2\\theta)\\)\nA1: \\(\\left[2\\theta - \\sin 2\\theta\\right]_0^{\\pi/6}\\)\nA1: \\(\\frac{\\pi}{3} - \\frac{\\sqrt{3}}{2}\\) CAO\nAnswer: \\(\\frac{\\pi}{3} - \\frac{\\sqrt{3}}{2}\\)` },
      { q: `The curves \\(y = \\sin x\\) and \\(y = \\cos x\\) are drawn for \\(0 \\leq x \\leq 2\\pi\\)\n\n(a) Find the \\(x\\)-coordinates of the points where the curves intersect. [2]\n(b) Find the exact area of the region enclosed between the two curves between these two points. [4]`, marks: 6, command: 'Find', markScheme: `(a) M1: \\(\\tan x = 1\\)\nA1: \\(x = \\frac{\\pi}{4}\\) and \\(x = \\frac{5\\pi}{4}\\)\n(b) M1: \\(\\int_{\\pi/4}^{5\\pi/4} (\\sin x - \\cos x)\\, dx\\) (correct order, or modulus taken)\nA1: \\(\\left[-\\cos x - \\sin x\\right]\\)\nM1: Substitutes limits: \\(\\left(\\frac{\\sqrt{2}}{2} + \\frac{\\sqrt{2}}{2}\\right) - \\left(-\\frac{\\sqrt{2}}{2} - \\frac{\\sqrt{2}}{2}\\right)\\)\nA1: \\(2\\sqrt{2}\\) CAO\nAnswer: (a) \\(\\frac{\\pi}{4}, \\frac{5\\pi}{4}\\); (b) \\(2\\sqrt{2}\\)` },
      { q: `A cup of tea is left to cool in a room. Its temperature, \\(\\theta\\) °C, \\(t\\) minutes after it is made is modelled by\n\\[\\frac{d\\theta}{dt} = -k(\\theta - 20)\\]\nwhere \\(k\\) is a positive constant. Initially the temperature is 90 °C. After 10 minutes the temperature is 55 °C.\n(data written for this practice question)\n\n(a) Show that \\(\\theta = 20 + 70e^{-kt}\\) [3]\n(b) Find the exact value of \\(k\\) and hence find the temperature of the tea 30 minutes after it is made. [2]\n(c) State one limitation of the model. [1]`, marks: 6, command: 'Show that', markScheme: `(a) M1: Separates: \\(\\int \\frac{1}{\\theta - 20}\\, d\\theta = \\int -k\\, dt\\)\nA1: \\(\\ln(\\theta - 20) = -kt + c\\)\nA1: Uses \\(t = 0, \\theta = 90\\) to obtain \\(\\theta = 20 + 70e^{-kt}\\) (AG)\n(b) B1: \\(35 = 70e^{-10k}\\), \\(k = \\frac{1}{10}\\ln 2\\)\nB1: \\(\\theta = 20 + \\frac{70}{8} = 28.75\\) °C (AWRT 28.8)\n(c) E1: e.g. assumes room temperature stays constant at 20 °C / ignores stirring or adding milk / \\(k\\) may not be constant\nAnswer: (b) \\(k = \\frac{1}{10}\\ln 2\\), 28.75 °C` },
      { q: `Find the exact value of\n\\[\\int_0^1 x^2 e^{2x}\\, dx\\]`, marks: 6, command: 'Find', markScheme: `M1: First application of parts with \\(u = x^2\\): \\(\\frac{1}{2}x^2e^{2x} - \\int xe^{2x}\\, dx\\)\nA1: Correct first stage\nM1: Second application of parts on \\(\\int xe^{2x}\\, dx\\)\nA1: \\(\\frac{1}{2}x^2e^{2x} - \\frac{1}{2}xe^{2x} + \\frac{1}{4}e^{2x}\\)\nM1: Substitutes limits 1 and 0: \\(\\frac{1}{4}e^2 - \\frac{1}{4}\\)\nA1: \\(\\frac{1}{4}(e^2 - 1)\\) CAO\nAnswer: \\(\\frac{1}{4}(e^2 - 1)\\)` },
      { q: `(a) Express \\(\\displaystyle\\frac{x + 5}{(x + 1)(x - 1)^2}\\) in the form \\(\\displaystyle\\frac{A}{x + 1} + \\frac{B}{x - 1} + \\frac{C}{(x - 1)^2}\\) [3]\n(b) Hence show that\n\\[\\int_2^3 \\frac{x + 5}{(x + 1)(x - 1)^2}\\, dx = \\frac{3}{2} + \\ln\\frac{2}{3}\\] [4]`, marks: 7, command: 'Express', markScheme: `(a) M1: \\(x + 5 = A(x - 1)^2 + B(x + 1)(x - 1) + C(x + 1)\\) and substitutes a value\nA1: Two of \\(A = 1\\), \\(B = -1\\), \\(C = 3\\)\nA1: All three correct\n(b) M1ft: Integrates to \\(\\ln(x + 1) - \\ln(x - 1) + k(x - 1)^{-1}\\)\nA1ft: \\(\\ln(x + 1) - \\ln(x - 1) - \\frac{3}{x - 1}\\)\nM1: Substitutes limits: \\(\\left(\\ln 4 - \\ln 2 - \\frac{3}{2}\\right) - (\\ln 3 - 0 - 3)\\)\nA1: \\(\\frac{3}{2} + \\ln\\frac{2}{3}\\) (AG, convincing log work)\nAnswer: \\(A = 1, B = -1, C = 3\\)` },
      { q: `Find the particular solution of the differential equation\n\\[\\frac{dy}{dx} = \\frac{y}{x(x + 1)}, \\quad x \\gt 0\\]\ngiven that \\(y = 1\\) when \\(x = 1\\)\n\nGive your answer in the form \\(y = f(x)\\)`, marks: 7, command: 'Find', markScheme: `M1: Separates: \\(\\int \\frac{1}{y}\\, dy = \\int \\frac{1}{x(x + 1)}\\, dx\\)\nM1: Partial fractions \\(\\frac{A}{x} + \\frac{B}{x+1}\\)\nA1: \\(\\frac{1}{x} - \\frac{1}{x + 1}\\)\nA1: \\(\\ln y = \\ln x - \\ln(x + 1) + c\\)\nM1: Uses \\(x = 1, y = 1\\): \\(c = \\ln 2\\)\ndM1: Combines logs and removes them: \\(y = \\frac{kx}{x + 1}\\)\nA1: \\(y = \\frac{2x}{x + 1}\\) CAO\nAnswer: \\(y = \\frac{2x}{x + 1}\\)` },
      { q: `Water flows into a large tank at a constant rate of 30 litres per minute. At the same time water leaks out of the tank at a rate proportional to the volume, \\(V\\) litres, of water in the tank. When \\(V = 100\\) the water leaks out at 10 litres per minute.\nThe tank is empty at time \\(t = 0\\) minutes.\n(data written for this practice question)\n\n(a) Show that \\(\\displaystyle\\frac{dV}{dt} = 30 - 0.1V\\) [2]\n(b) Solve the differential equation to find \\(V\\) in terms of \\(t\\) [4]\n(c) Describe what the model predicts about the volume of water in the tank in the long term. [1]`, marks: 7, command: 'Show that', markScheme: `(a) M1: \\(\\frac{dV}{dt} = 30 - kV\\)\nA1: \\(10 = 100k\\), \\(k = 0.1\\) (AG)\n(b) M1: Separates: \\(\\int \\frac{1}{30 - 0.1V}\\, dV = \\int 1\\, dt\\)\nA1: \\(-10\\ln(30 - 0.1V) = t + c\\)\nM1: Uses \\(t = 0, V = 0\\): \\(c = -10\\ln 30\\)\nA1: \\(V = 300(1 - e^{-0.1t})\\) oe\n(c) E1ft: The volume increases and approaches (but never reaches) 300 litres\nAnswer: \\(V = 300(1 - e^{-0.1t})\\)` },
      { q: `Use integration by parts twice to show that\n\\[\\int_0^{\\pi} e^{x}\\sin x\\, dx = \\frac{1}{2}\\left(e^{\\pi} + 1\\right)\\]`, marks: 7, command: 'Use', markScheme: `M1: First application: \\(I = \\left[-e^x\\cos x\\right] + \\int e^x\\cos x\\, dx\\) (or with \\(u = \\sin x\\))\nA1: Correct first stage\nM1: Second application, same choice of \\(u\\): \\(\\int e^x\\cos x\\, dx = e^x\\sin x - \\int e^x\\sin x\\, dx\\)\nA1: Correct second stage\nM1: Recognises the original integral: \\(2I = \\left[e^x\\sin x - e^x\\cos x\\right]_0^{\\pi}\\)\nA1: \\(2I = (0 + e^{\\pi}) - (0 - 1) = e^{\\pi} + 1\\)\nA1: \\(I = \\frac{1}{2}(e^{\\pi} + 1)\\) (AG, fully correct with no sign errors)\nAnswer: \\(\\frac{1}{2}(e^{\\pi} + 1)\\)` },
      { q: `A garden designer models the edge of a flower bed by the curve \\(y = x + \\dfrac{4}{x}\\) and the edge of a straight path by the line \\(y = 5\\). The flower bed is the region enclosed between the curve and the line. Distances are in metres.\n(model written for this practice question)\n\n(a) Find the \\(x\\)-coordinates of the points where the curve meets the line. [3]\n(b) Show that the area of the flower bed is \\(\\left(\\frac{15}{2} - 8\\ln 2\\right)\\) m² [5]`, marks: 8, command: 'Show that', markScheme: `(a) M1: \\(x + \\frac{4}{x} = 5 \\Rightarrow x^2 - 5x + 4 = 0\\)\nM1: Solves the quadratic\nA1: \\(x = 1\\) and \\(x = 4\\)\n(b) M1: \\(\\int_1^4 \\left(5 - x - \\frac{4}{x}\\right) dx\\) (or rectangle minus area under curve)\nA1: \\(\\left[5x - \\frac{x^2}{2} - 4\\ln x\\right]_1^4\\)\nM1: Substitutes limits: \\((20 - 8 - 4\\ln 4) - \\left(5 - \\frac{1}{2}\\right)\\)\nM1: Uses \\(\\ln 4 = 2\\ln 2\\)\nA1: \\(\\frac{15}{2} - 8\\ln 2\\) (AG, convincing)\nAnswer: (a) \\(x = 1, 4\\)` },
      { q: `(a) Show that \\(\\displaystyle\\int \\cos^2 x\\, dx = \\frac{1}{2}x + \\frac{1}{4}\\sin 2x + c\\) [3]\n(b) Hence find the particular solution of the differential equation\n\\[\\frac{dy}{dx} = y\\cos^2 x, \\quad y \\gt 0\\]\ngiven that \\(y = 1\\) when \\(x = 0\\). Give your answer in the form \\(y = f(x)\\) [4]\n(c) Find the exact value of \\(y\\) when \\(x = \\pi\\) [1]`, marks: 8, command: 'Show that', markScheme: `(a) M1: Uses \\(\\cos^2 x = \\frac{1}{2}(1 + \\cos 2x)\\)\nA1: \\(\\int \\frac{1}{2}(1 + \\cos 2x)\\, dx\\)\nA1: \\(\\frac{1}{2}x + \\frac{1}{4}\\sin 2x + c\\) (AG)\n(b) M1: Separates: \\(\\int \\frac{1}{y}\\, dy = \\int \\cos^2 x\\, dx\\)\nA1: \\(\\ln y = \\frac{1}{2}x + \\frac{1}{4}\\sin 2x + c\\)\nM1: Uses \\(x = 0, y = 1\\): \\(c = 0\\)\nA1: \\(y = e^{\\frac{1}{2}x + \\frac{1}{4}\\sin 2x}\\)\n(c) B1ft: \\(y = e^{\\pi/2}\\)\nAnswer: (b) \\(y = e^{\\frac{1}{2}x + \\frac{1}{4}\\sin 2x}\\); (c) \\(e^{\\pi/2}\\)` },
      { q: `A biologist models the number of fish, \\(P\\), in a lake \\(t\\) years after the fish are first introduced by\n\\[\\frac{dP}{dt} = \\frac{P(1000 - P)}{2000}\\]\nInitially there are 100 fish in the lake.\n(model written for this practice question)\n\n(a) Express \\(\\displaystyle\\frac{1}{P(1000 - P)}\\) in partial fractions. [2]\n(b) Hence show that \\(\\displaystyle P = \\frac{1000}{1 + 9e^{-0.5t}}\\) [5]\n(c) Find the time taken for the number of fish to reach 500. Give your answer to three significant figures. [1]\n(d) State what the model predicts about the number of fish in the long term. [1]`, marks: 9, command: 'Show that', markScheme: `(a) M1: \\(\\frac{A}{P} + \\frac{B}{1000 - P}\\) with a correct method\nA1: \\(\\frac{1}{1000P} + \\frac{1}{1000(1000 - P)}\\)\n(b) M1: Separates: \\(\\int \\frac{2000}{P(1000 - P)}\\, dP = \\int 1\\, dt\\)\nA1ft: \\(2\\ln P - 2\\ln(1000 - P) = t + c\\)\nM1: Uses \\(t = 0, P = 100\\): \\(c = 2\\ln\\frac{1}{9}\\) oe\ndM1: Removes logs: \\(\\frac{P}{1000 - P} = \\frac{1}{9}e^{0.5t}\\)\nA1: Rearranges to \\(P = \\frac{1000}{1 + 9e^{-0.5t}}\\) (AG, convincing)\n(c) B1: \\(9e^{-0.5t} = 1\\), \\(t = 2\\ln 9 = 4.39\\) years AWRT\n(d) E1: As \\(t \\to \\infty\\), \\(e^{-0.5t} \\to 0\\), so the number of fish approaches (levels off at) 1000\nAnswer: (c) 4.39 years; (d) tends to 1000` },
      { q: `The curve \\(C\\) has equation \\(y = 4xe^{-x}\\)\nThe line \\(L\\) has equation \\(y = x\\)\n\n(a) Show that \\(C\\) and \\(L\\) intersect where \\(x = 0\\) and where \\(x = 2\\ln 2\\) [2]\n(b) Find \\(\\displaystyle\\int xe^{-x}\\, dx\\) [3]\n(c) The region \\(R\\) is enclosed between \\(C\\) and \\(L\\)\nHence show that the area of \\(R\\) is \\(3 - 2\\ln 2 - 2(\\ln 2)^2\\) [5]`, marks: 10, command: 'Show that', markScheme: `(a) M1: \\(4xe^{-x} = x \\Rightarrow x(4e^{-x} - 1) = 0\\)\nA1: \\(x = 0\\) or \\(e^{x} = 4\\), \\(x = \\ln 4 = 2\\ln 2\\) (AG)\n(b) M1: Parts with \\(u = x\\), \\(\\frac{dv}{dx} = e^{-x}\\): \\(-xe^{-x} + \\int e^{-x}\\, dx\\)\nA1: Correct first stage\nA1: \\(-xe^{-x} - e^{-x} + c\\)\n(c) M1: Area \\(= \\int_0^{2\\ln 2} \\left(4xe^{-x} - x\\right) dx\\)\nM1ft: \\(\\left[-4xe^{-x} - 4e^{-x} - \\frac{1}{2}x^2\\right]_0^{2\\ln 2}\\)\nB1: Uses \\(e^{-2\\ln 2} = \\frac{1}{4}\\)\nA1: \\(\\left(-2\\ln 2 - 1 - 2(\\ln 2)^2\\right) - (-4)\\)\nA1: \\(3 - 2\\ln 2 - 2(\\ln 2)^2\\) (AG, convincing)\nAnswer: (b) \\(-xe^{-x} - e^{-x} + c\\)` }
    ]
  },
  '1.9': {
    name: 'Numerical Methods',
    questions: [
      { q: `Show that the equation \\(x^3 + 4x - 11 = 0\\) has a root between \\(x = 1.6\\) and \\(x = 1.7\\)`, marks: 2, command: 'Show that', markScheme: `M1: Evaluates \\(f(1.6)\\) and \\(f(1.7)\\) where \\(f(x) = x^3 + 4x - 11\\): \\(f(1.6) = -0.504\\), \\(f(1.7) = 0.713\\) (condone values to 1 s.f.)\nR1: Change of sign and \\(f\\) is continuous (polynomial), so there is a root between 1.6 and 1.7. Must mention both the sign change and continuity.` },
      { q: `The function f is defined by \\(f(x) = (2x - 3)^2\\)\nA student evaluates \\(f(1) = 1\\) and \\(f(2) = 1\\) and writes:\n"There is no change of sign, so the equation \\(f(x) = 0\\) has no roots between \\(x = 1\\) and \\(x = 2\\)."\n\nExplain why the student's conclusion is wrong.`, marks: 2, command: 'Explain', markScheme: `B1: Identifies the root \\(x = 1.5\\), which lies between 1 and 2\nE1: Explains that this is a repeated root: the graph touches the \\(x\\)-axis without crossing it, so \\(f(x)\\) does not change sign. A lack of a sign change does not mean there is no root.` },
      { q: `The function g is defined by \\(g(x) = \\frac{1}{x - 2}\\) for \\(x \\neq 2\\)\nIt is given that \\(g(1) = -1\\) and \\(g(3) = 1\\)\n\nExplain why this change of sign does not show that the equation \\(g(x) = 0\\) has a root between \\(x = 1\\) and \\(x = 3\\)`, marks: 2, command: 'Explain', markScheme: `E1: g is not continuous on the interval: it has a vertical asymptote at \\(x = 2\\), which lies between 1 and 3\nE1: The sign changes across the asymptote, not at a root. In fact \\(\\frac{1}{x-2}\\) is never zero, so \\(g(x) = 0\\) has no roots.` },
      { q: `The equation \\(x^3 - 6x^2 + 9x - 1 = 0\\) has a root between 0 and 1.\nA student tries to use the Newton–Raphson method with first approximation \\(x_1 = 1\\)\n\nExplain why the method fails.`, marks: 2, command: 'Explain', markScheme: `M1: \\(f'(x) = 3x^2 - 12x + 9\\), so \\(f'(1) = 3 - 12 + 9 = 0\\)\nE1: The Newton–Raphson formula would divide by \\(f'(1) = 0\\), so \\(x_2\\) cannot be found. The tangent at \\(x = 1\\) is horizontal (there is a stationary point) and never meets the \\(x\\)-axis.` },
      { q: `The curves \\(y = e^x\\) and \\(y = 5 - x^2\\) meet at a point where \\(x = \\alpha\\), \\(\\alpha \\gt 0\\)\nThe value of \\(\\alpha\\) can be found using the iterative formula\n\\[x_{n+1} = \\ln(5 - x_n^2)\\]\nwith \\(x_1 = 1\\)\n\n(a) Find the values of \\(x_2\\) and \\(x_3\\), giving your answers to three decimal places. [2]\n(b) State, with a reason, whether the iteration produces a staircase diagram or a cobweb diagram. [1]`, marks: 3, command: 'Find', markScheme: `(a)\nM1: Substitutes \\(x_1 = 1\\) correctly: \\(x_2 = \\ln 4\\)\nA1: \\(x_2 = 1.386\\), \\(x_3 = 1.124\\) (AWRT)\n(b)\nE1: Cobweb, because the values alternate above and below the root (\\(x_1 \\lt x_3 \\lt \\alpha \\lt x_2\\)), i.e. the gradient of \\(y = \\ln(5 - x^2)\\) is negative near \\(\\alpha\\). [\\(\\alpha \\approx 1.241\\)]` },
      { q: `The equation \\(x^3 + 4x - 11 = 0\\) has a single real root \\(\\alpha\\)\n\nUse the iterative formula\n\\[x_{n+1} = \\sqrt[3]{11 - 4x_n}\\]\nwith \\(x_1 = 1.6\\) to find the values of \\(x_2\\), \\(x_3\\) and \\(x_4\\), giving your answers to four decimal places.`, marks: 3, command: 'Use', markScheme: `M1: Correct substitution of \\(x_1 = 1.6\\): \\(x_2 = \\sqrt[3]{4.6}\\)\nA1: \\(x_2 = 1.6631\\)\nA1: \\(x_3 = 1.6321\\), \\(x_4 = 1.6475\\) (CAO, both)\n[Iterates oscillate towards \\(\\alpha = 1.6424\\)]` },
      { q: `The equation \\(x^3 + 4x - 11 = 0\\) has a single real root \\(\\alpha\\)\n\nShow that \\(\\alpha = 1.64\\) correct to two decimal places.\nFully justify your answer.`, marks: 3, command: 'Show that', markScheme: `M1: Chooses the interval \\([1.635, 1.645]\\) and evaluates \\(f(x) = x^3 + 4x - 11\\) at both ends\nA1: \\(f(1.635) = -0.0892...\\) and \\(f(1.645) = 0.0314...\\) (AWRT \\(-0.089\\) and \\(0.031\\))\nR1: Change of sign and f is continuous, so \\(1.635 \\lt \\alpha \\lt 1.645\\); hence \\(\\alpha = 1.64\\) to 2 d.p.` },
      { q: `The equation \\(x^4 - 3x - 5 = 0\\) has a root near \\(x = 1.8\\)\n\nTaking \\(x_1 = 1.8\\) as a first approximation, use the Newton–Raphson method to find \\(x_2\\), giving your answer to four decimal places.`, marks: 3, command: 'Use', markScheme: `B1: \\(f'(x) = 4x^3 - 3\\)\nM1: Correct use of \\(x_2 = x_1 - \\frac{f(x_1)}{f'(x_1)}\\) with \\(f(1.8) = 0.0976\\), \\(f'(1.8) = 20.328\\)\nA1: \\(x_2 = 1.7952\\) (CAO)` },
      { q: `(Data written for this practice question.)\nThe rate at which water flows into a reservoir is \\(r\\) cubic metres per hour. Measurements taken during a storm are shown below.\n\nt (hours): 0, 2, 4, 6, 8\nr (m³ per hour): 120, 310, 460, 380, 150\n\nUse the trapezium rule with all of these values to estimate the total volume of water that flowed into the reservoir during the 8 hours.`, marks: 3, command: 'Use', markScheme: `B1: Strip width \\(h = 2\\)\nM1: \\(\\frac{2}{2}[120 + 150 + 2(310 + 460 + 380)]\\)\nA1: \\(2570\\) m³ (CAO)` },
      { q: `The trapezium rule with 6 strips is used to estimate \\(\\int_1^4 x\\ln x \\, dx\\). The estimate obtained is 7.369 to three decimal places.\n\nDetermine whether this estimate is an overestimate or an underestimate. Fully justify your answer.`, marks: 3, command: 'Determine', markScheme: `M1: Differentiates twice: \\(\\frac{d}{dx}(x\\ln x) = \\ln x + 1\\)\nA1: \\(\\frac{d^2y}{dx^2} = \\frac{1}{x}\\), which is positive for \\(1 \\leq x \\leq 4\\)\nE1: So the curve is convex; the tops of the trapezia lie above the curve, so 7.369 is an overestimate. [Exact value \\(8\\ln 4 - \\frac{15}{4} = 7.340\\)]` },
      { q: `The equation \\(x = e^{-x}\\) has a single root \\(\\alpha\\)\n\nUsing the iteration \\(x_{n+1} = e^{-x_n}\\) with \\(x_1 = 0.5\\), find \\(x_2\\) and \\(x_3\\) to four decimal places, and describe how the iterates approach \\(\\alpha\\)`, marks: 3, command: 'Find', markScheme: `M1: \\(x_2 = e^{-0.5}\\)\nA1: \\(x_2 = 0.6065\\), \\(x_3 = 0.5452\\)\nE1: The iterates oscillate on alternate sides of \\(\\alpha\\) while getting closer to it (convergent cobweb), because the gradient of \\(y = e^{-x}\\) is negative with modulus less than 1 near \\(\\alpha\\). [\\(\\alpha = 0.5671\\)]` },
      { q: `A scientist models the mass, \\(A\\) grams, of a substance that is decaying, \\(t\\) hours after an experiment begins, by \\(A = 50e^{-0.3t}\\)\nAt the same time, the mass, \\(B\\) grams, of a second substance that is being produced is modelled by \\(B = 2t + 10\\)\n\n(a) Show that the two masses are equal at some time between \\(t = 3\\) and \\(t = 4\\) [2]\n(b) Show that, to one decimal place, the masses are equal when \\(t = 3.6\\) [2]`, marks: 4, command: 'Show that', markScheme: `(a)\nM1: Defines \\(f(t) = 50e^{-0.3t} - 2t - 10\\) and evaluates: \\(f(3) = 4.33\\), \\(f(4) = -2.94\\)\nR1: Change of sign and f continuous, so the masses are equal for some \\(t\\) between 3 and 4\n(b)\nM1: Evaluates \\(f(3.55) = 0.136\\) and \\(f(3.65) = -0.573\\)\nR1: Change of sign and f continuous, so the root lies in \\((3.55, 3.65)\\), hence \\(t = 3.6\\) to 1 d.p. [Root \\(t = 3.569\\)]` },
      { q: `The equation \\(x^3 - 2x - 5 = 0\\) has a root \\(\\alpha\\) near \\(x = 2\\)\n\nUse the Newton–Raphson method with \\(x_1 = 2\\) to find \\(x_2\\) and \\(x_3\\)\nGive \\(x_3\\) to four decimal places.`, marks: 4, command: 'Use', markScheme: `B1: \\(f'(x) = 3x^2 - 2\\)\nM1: \\(x_2 = 2 - \\frac{8 - 4 - 5}{12 - 2}\\)\nA1: \\(x_2 = 2.1\\)\nA1: \\(x_3 = 2.1 - \\frac{0.061}{11.23} = 2.0946\\) (CAO)` },
      { q: `Use the trapezium rule with four strips to find an estimate for\n\\[\\int_1^3 \\sqrt{x^3 + 1} \\, dx\\]\nGive your answer to three significant figures.`, marks: 4, command: 'Use', markScheme: `B1: \\(h = 0.5\\); \\(x\\)-values 1, 1.5, 2, 2.5, 3\nM1: \\(y\\)-values \\(1.4142, 2.0917, 3, 4.0774, 5.2915\\) (at least 3 correct)\nM1: \\(\\frac{0.5}{2}[1.4142 + 5.2915 + 2(2.0917 + 3 + 4.0774)]\\)\nA1: \\(6.26\\) (CAO)` },
      { q: `The function f is given by \\(f(x) = \\frac{1}{1 + x^2}\\). f is a decreasing function for \\(0 \\leq x \\leq 1\\)\n\nUsing four rectangles of equal width, find a lower bound and an upper bound for \\(\\int_0^1 \\frac{1}{1+x^2} \\, dx\\)\nGive your answers to three decimal places.`, marks: 4, command: 'Find', markScheme: `B1: Values \\(f(0) = 1\\), \\(f(0.25) = 0.9412\\), \\(f(0.5) = 0.8\\), \\(f(0.75) = 0.64\\), \\(f(1) = 0.5\\)\nM1: Lower bound uses right-hand heights since f is decreasing: \\(0.25(0.9412 + 0.8 + 0.64 + 0.5)\\)\nA1: Lower bound \\(= 0.720\\)\nA1: Upper bound \\(= 0.25(1 + 0.9412 + 0.8 + 0.64) = 0.845\\)\n[The exact value is \\(\\frac{\\pi}{4} = 0.785\\), which lies between them]` },
      { q: `The equation \\(x^3 - 4x + 1 = 0\\) has a root \\(\\beta = 1.861\\) to three decimal places.\nA student uses the iterative formula \\(x_{n+1} = \\frac{x_n^3 + 1}{4}\\) with \\(x_1 = 1.8\\)\n\n(a) Find \\(x_2\\), \\(x_3\\) and \\(x_4\\), giving your answers to three decimal places. [2]\n(b) Explain why this iterative formula cannot be used to find \\(\\beta\\) [2]`, marks: 4, command: 'Explain', markScheme: `(a)\nM1: \\(x_2 = \\frac{1.8^3 + 1}{4} = 1.708\\)\nA1: \\(x_3 = 1.496\\), \\(x_4 = 1.086\\)\n(b)\nE1: The iterates move away from \\(\\beta\\) (they diverge from it, in fact towards the other root near 0.254)\nE1: Because the gradient of \\(y = \\frac{x^3+1}{4}\\) near \\(\\beta\\) is \\(\\frac{3\\beta^2}{4} \\approx 2.6\\), which is greater than 1` },
      { q: `The function f is defined by \\(f(x) = xe^{-x}\\)\nThe equation \\(f(x) = 0\\) has the single root \\(x = 0\\)\n\n(a) Show that, for this function, the Newton–Raphson formula becomes \\(x_{n+1} = \\frac{x_n^2}{x_n - 1}\\) [2]\n(b) Taking \\(x_1 = 2\\), find \\(x_2\\) and \\(x_3\\), and explain what happens to the method. [2]`, marks: 4, command: 'Show that', markScheme: `(a)\nM1: \\(f'(x) = e^{-x} - xe^{-x} = (1 - x)e^{-x}\\)\nA1: \\(x_{n+1} = x_n - \\frac{x_n}{1 - x_n} = \\frac{x_n - x_n^2 - x_n}{1 - x_n} = \\frac{x_n^2}{x_n - 1}\\) (AG; must see intermediate step)\n(b)\nB1: \\(x_2 = 4\\), \\(x_3 = \\frac{16}{3}\\)\nE1: The approximations increase and move away from the root at 0 (diverge); the starting value is on the wrong side of the turning point at \\(x = 1\\), where the tangents slope away from the root.` },
      { q: `The equation \\(x = \\sqrt{x + 3}\\) has a root \\(\\alpha\\)\nThe iteration \\(x_{n+1} = \\sqrt{x_n + 3}\\) with \\(x_1 = 1\\) is used to find \\(\\alpha\\)\n\nOn the same axes, sketch the graphs of \\(y = x\\) and \\(y = \\sqrt{x + 3}\\) for \\(x \\geq 0\\), and draw a diagram showing the positions of \\(x_2\\) and \\(x_3\\) on the \\(x\\)-axis.`, marks: 4, command: 'Sketch', diagram: true, markScheme: `B1: Straight line \\(y = x\\) through the origin and curve \\(y = \\sqrt{x+3}\\) starting at \\((0, \\sqrt{3})\\), increasing with decreasing gradient\nB1: Graphs intersect once at \\(x = \\alpha\\) [\\(\\alpha = \\frac{1 + \\sqrt{13}}{2} \\approx 2.30\\)]\nM1: Vertical line from \\(x_1 = 1\\) to the curve, then horizontal to \\(y = x\\) (staircase pattern)\nA1: \\(x_2 = 2\\) and \\(x_3 \\approx 2.24\\) marked on the \\(x\\)-axis, increasing towards \\(\\alpha\\)` },
      { q: `A speed bump is 40 cm wide. Its cross-section is modelled by the curve\n\\[y = 6\\sin\\left(\\frac{\\pi x}{40}\\right), \\quad 0 \\leq x \\leq 40\\]\nwhere \\(y\\) cm is the height of the bump at a distance \\(x\\) cm from one edge.\n\n(a) Use the trapezium rule with four strips to estimate the area of the cross-section, giving your answer to one decimal place. [3]\n(b) Explain whether your answer is an overestimate or an underestimate. [1]`, marks: 4, command: 'Use', markScheme: `(a)\nB1: \\(h = 10\\); heights \\(0, 3\\sqrt{2}, 6, 3\\sqrt{2}, 0\\) (i.e. 0, 4.243, 6, 4.243, 0)\nM1: \\(\\frac{10}{2}[0 + 0 + 2(4.243 + 6 + 4.243)]\\)\nA1: \\(144.9\\) cm² (AWRT)\n(b)\nE1: Underestimate: the curve is concave (bends downwards) for \\(0 \\leq x \\leq 40\\), so the trapezia lie below the curve. [Exact area \\(\\frac{480}{\\pi} = 152.8\\) cm²]` },
      { q: `A horizontal pipe has a circular cross-section of radius 0.5 m. Water in the pipe fills a segment of the cross-section. The chord forming the water surface subtends an angle \\(\\theta\\) radians at the centre of the circle.\nThe area of this segment is 0.2 m².\n\n(a) Show that \\(\\theta - \\sin\\theta - 1.6 = 0\\) [1]\n(b) Show that this equation has a root between \\(\\theta = 2.3\\) and \\(\\theta = 2.4\\) [2]\n(c) Use the Newton–Raphson method with \\(\\theta_1 = 2.3\\) to find \\(\\theta_2\\), giving your answer to three decimal places. [2]`, marks: 5, command: 'Show that', markScheme: `(a)\nB1: Segment area \\(\\frac{1}{2}(0.5)^2(\\theta - \\sin\\theta) = 0.2\\) gives \\(\\theta - \\sin\\theta = 1.6\\), so \\(\\theta - \\sin\\theta - 1.6 = 0\\) (AG)\n(b)\nM1: \\(f(2.3) = -0.0457\\), \\(f(2.4) = 0.1245\\)\nR1: Change of sign and f continuous, so root between 2.3 and 2.4\n(c)\nM1: \\(f'(\\theta) = 1 - \\cos\\theta\\); \\(\\theta_2 = 2.3 - \\frac{-0.0457}{1 - \\cos 2.3}\\)\nA1: \\(\\theta_2 = 2.327\\) (CAO)` },
      { q: `The equation \\(e^x = 4x\\) has two roots, \\(\\alpha\\) and \\(\\beta\\), where \\(\\alpha \\lt \\beta\\)\n\n(a) Show that \\(\\alpha\\) lies between 0.3 and 0.4 [2]\n(b) Use the iterative formula \\(x_{n+1} = \\frac{1}{4}e^{x_n}\\) with \\(x_1 = 0.3\\) to find \\(x_2\\) and \\(x_3\\), giving your answers to four decimal places. [2]\n(c) It is given that \\(\\beta = 2.153\\) to three decimal places.\nExplain why the same iterative formula cannot be used to find \\(\\beta\\) [1]`, marks: 5, command: 'Show that', markScheme: `(a)\nM1: Let \\(f(x) = e^x - 4x\\); \\(f(0.3) = 0.150\\), \\(f(0.4) = -0.108\\)\nR1: Change of sign and f continuous, so \\(0.3 \\lt \\alpha \\lt 0.4\\)\n(b)\nM1: \\(x_2 = \\frac{1}{4}e^{0.3}\\)\nA1: \\(x_2 = 0.3375\\), \\(x_3 = 0.3503\\)\n(c)\nE1: The gradient of \\(y = \\frac{1}{4}e^x\\) at \\(\\beta\\) is \\(\\frac{1}{4}e^{\\beta} = \\beta \\approx 2.15\\), which is greater than 1, so the iteration diverges from \\(\\beta\\)` },
      { q: `(Data written for this practice question.)\nA river is 12 m wide. The depth of the river, \\(d\\) metres, is measured at points \\(x\\) metres from one bank.\n\nx (m): 0, 2, 4, 6, 8, 10, 12\nd (m): 0, 0.8, 1.5, 1.9, 1.7, 1.1, 0\n\n(a) Use the trapezium rule with all of these values to estimate the area of the cross-section of the river. [3]\n(b) The water flows through this cross-section at an average speed of 0.6 m s⁻¹.\nEstimate the volume of water that passes this point each minute. [1]\n(c) State one reason why your answer to (b) may not be accurate. [1]`, marks: 5, command: 'Use', markScheme: `(a)\nB1: \\(h = 2\\)\nM1: \\(\\frac{2}{2}[0 + 0 + 2(0.8 + 1.5 + 1.9 + 1.7 + 1.1)]\\)\nA1: \\(14\\) m² (CAO)\n(b)\nB1ft: \\(14 \\times 0.6 \\times 60 = 504\\) m³ (ft their area \\(\\times 36\\))\n(c)\nE1: Any one of: the riverbed between the measured points is not a straight line, so the trapezium rule is only an estimate; the speed of the water varies across the river and with depth; depths measured at only 7 points; the river level changes over time.` },
      { q: `The concentration, \\(C\\) mg per litre, of a drug in a patient's blood \\(t\\) hours after it is given is modelled by\n\\[C = 12te^{-0.4t}\\]\nThe drug is effective while \\(C \\geq 5\\)\n\nThe concentration falls to 5 mg per litre for the second time at a value of \\(t\\) close to 7.\nUse the Newton–Raphson method with \\(t_1 = 7\\) to find \\(t_2\\) and \\(t_3\\), giving \\(t_3\\) to three decimal places.`, marks: 5, command: 'Use', markScheme: `M1: Forms \\(f(t) = 12te^{-0.4t} - 5\\)\nB1: \\(f'(t) = 12e^{-0.4t} - 4.8te^{-0.4t}\\) or equivalent (product rule)\nM1: \\(t_2 = 7 - \\frac{f(7)}{f'(7)}\\) with \\(f(7) = 0.1080\\), \\(f'(7) = -1.3135\\)\nA1: \\(t_2 = 7.0823\\)\nA1: \\(t_3 = 7.083\\) (CAO)` },
      { q: `The equation \\(x^3 - 12x + 5 = 0\\) has a root \\(\\alpha\\) between 3 and 4.\n\n(a) Taking \\(x_1 = 2.1\\), use the Newton–Raphson method to find \\(x_2\\), giving your answer to two decimal places. [2]\n(b) Explain why \\(x_2\\) is not a good approximation to \\(\\alpha\\), referring to the shape of the graph of \\(y = x^3 - 12x + 5\\) [2]\n(c) Suggest a better first approximation, giving a reason. [1]`, marks: 5, command: 'Explain', markScheme: `(a)\nM1: \\(f'(x) = 3x^2 - 12\\); \\(x_2 = 2.1 - \\frac{-10.939}{1.23}\\)\nA1: \\(x_2 = 10.99\\)\n(b)\nE1: There is a stationary (minimum) point at \\(x = 2\\), close to \\(x_1 = 2.1\\)\nE1: So the tangent at \\(x_1\\) is almost horizontal and meets the \\(x\\)-axis a long way from \\(\\alpha\\) [\\(\\alpha \\approx 3.23\\)]\n(c)\nB1: e.g. \\(x_1 = 3\\) (or any value between 3 and 4) because the root is known to lie between 3 and 4, away from the turning point [from 3: \\(x_2 = 3.27\\)]` },
      { q: `The equation \\(x^2 - 2x - 5 = 0\\) has a positive root \\(\\alpha\\)\n\n(a) Use the iteration \\(x_{n+1} = \\sqrt{2x_n + 5}\\) with \\(x_1 = 2\\) to find \\(x_2\\), \\(x_3\\) and \\(x_4\\), giving your answers to three decimal places. [2]\n(b) Find the exact value of \\(\\alpha\\) [1]\n(c) Sketch the graphs of \\(y = x\\) and \\(y = \\sqrt{2x + 5}\\) on the same axes and use them to illustrate how the iteration converges. [2]`, marks: 5, command: 'Sketch', diagram: true, markScheme: `(a)\nM1: \\(x_2 = \\sqrt{9} = 3\\)\nA1: \\(x_3 = 3.317\\), \\(x_4 = 3.411\\)\n(b)\nB1: \\(\\alpha = 1 + \\sqrt{6}\\)\n(c)\nB1: Line \\(y = x\\) and increasing concave curve crossing \\(y\\)-axis at \\(\\sqrt{5}\\), intersecting once for \\(x \\gt 0\\)\nB1: Staircase from \\(x_1 = 2\\): vertical to the curve, horizontal to the line, steps increasing towards \\(\\alpha\\)` },
      { q: `(a) Use the trapezium rule with four strips to find an estimate for \\(\\int_1^2 \\frac{1}{x} \\, dx\\), giving your answer to four decimal places. [3]\n(b) Hence, with reference to the shape of the curve \\(y = \\frac{1}{x}\\), explain why \\(\\ln 2 \\lt 0.6971\\) [2]`, marks: 5, command: 'Use', markScheme: `(a)\nB1: \\(h = 0.25\\); \\(y\\)-values \\(1, 0.8, 0.6667, 0.5714, 0.5\\)\nM1: \\(\\frac{0.25}{2}[1 + 0.5 + 2(0.8 + 0.6667 + 0.5714)]\\)\nA1: \\(0.6970\\) (CAO)\n(b)\nE1: \\(\\frac{d^2y}{dx^2} = \\frac{2}{x^3} \\gt 0\\) so the curve is convex and the trapezium rule gives an overestimate\nE1: \\(\\int_1^2 \\frac{1}{x}\\,dx = \\ln 2\\), so \\(\\ln 2 \\lt 0.6970... \\lt 0.6971\\)` },
      { q: `A company models its weekly profit, \\(P\\) thousand pounds, when it makes and sells \\(x\\) thousand items, by\n\\[P = 30\\ln(x + 1) - 2x - 10\\]\nThe company breaks even when \\(P = 0\\)\n\n(a) Show that the company has a break-even point when \\(x\\) is between 55 and 56 [2]\n(b) Use the Newton–Raphson method with \\(x_1 = 50\\) to find \\(x_2\\), giving your answer to two decimal places. [3]\n(c) State one limitation of the model. [1]`, marks: 6, command: 'Show that', markScheme: `(a)\nM1: \\(P(55) = 0.761\\), \\(P(56) = -0.708\\)\nR1: Change of sign and P continuous, so a break-even point lies between 55 and 56\n(b)\nB1: \\(\\frac{dP}{dx} = \\frac{30}{x + 1} - 2\\)\nM1: \\(x_2 = 50 - \\frac{7.9548}{\\frac{30}{51} - 2}\\)\nA1: \\(x_2 = 55.63\\) (CAO)\n(c)\nE1: e.g. the model predicts a loss of £10 000 when nothing is sold, but costs may change with time; profit cannot be exact as items are sold in whole numbers; the model may not be valid for very large \\(x\\); prices or demand may change.` },
      { q: `An open box is made from a rectangular sheet of card measuring 20 cm by 12 cm. A square of side \\(x\\) cm is cut from each corner and the sides are folded up.\nThe volume of the box is 200 cm³.\n\n(a) Show that \\(x^3 - 16x^2 + 60x - 50 = 0\\) [2]\n(b) Show that this equation can be rearranged to \\(x = \\frac{50}{x^2 - 16x + 60}\\) [1]\n(c) Use the iteration \\(x_{n+1} = \\frac{50}{x_n^2 - 16x_n + 60}\\) with \\(x_1 = 1.5\\) to find \\(x_2\\) and \\(x_3\\), giving your answers to three decimal places. [2]\n(d) The equation also has a root at \\(x \\approx 10.9\\)\nExplain why this root is not a possible value of \\(x\\) in this context. [1]`, marks: 6, command: 'Show that', markScheme: `(a)\nM1: \\(V = x(20 - 2x)(12 - 2x) = 200\\)\nA1: \\(4x^3 - 64x^2 + 240x = 200\\), divide by 4: \\(x^3 - 16x^2 + 60x - 50 = 0\\) (AG)\n(b)\nB1: \\(x(x^2 - 16x + 60) = 50\\) so \\(x = \\frac{50}{x^2 - 16x + 60}\\) (AG)\n(c)\nM1: \\(x_2 = \\frac{50}{2.25 - 24 + 60}\\)\nA1: \\(x_2 = 1.307\\), \\(x_3 = 1.226\\)\n(d)\nE1: The squares cut from the 12 cm side must have \\(x \\lt 6\\) (and \\(12 - 2x \\gt 0\\)); \\(x = 10.9\\) would give negative dimensions.` },
      { q: `(a) Use the trapezium rule with four strips to find an estimate for\n\\[\\int_0^2 \\sqrt{4 - x^2} \\, dx\\]\ngiving your answer to four decimal places. [3]\n(b) By considering the graph of \\(y = \\sqrt{4 - x^2}\\), show that \\(\\int_0^2 \\sqrt{4 - x^2} \\, dx = \\pi\\) [1]\n(c) Explain why your answer to (a) is an underestimate. [1]\n(d) State how the trapezium rule could be used to give a better estimate for \\(\\pi\\) [1]`, marks: 6, command: 'Use', markScheme: `(a)\nB1: \\(h = 0.5\\); \\(y\\)-values \\(2, 1.9365, 1.7321, 1.3229, 0\\)\nM1: \\(\\frac{0.5}{2}[2 + 0 + 2(1.9365 + 1.7321 + 1.3229)]\\)\nA1: \\(2.9957\\) (AWRT)\n(b)\nB1: The curve is the quarter of the circle \\(x^2 + y^2 = 4\\) in the first quadrant, so the area is \\(\\frac{1}{4}\\pi(2)^2 = \\pi\\)\n(c)\nE1: The curve is concave (part of a circle bending downwards), so each trapezium lies below the curve\n(d)\nE1: Use more strips (smaller strip width)` },
      { q: `The function f is defined by \\(f(x) = x - \\frac{1}{x - 2}\\), \\(x \\neq 2\\)\n\n(a) Show that \\(f(1)\\) and \\(f(3)\\) have the same sign. [1]\n(b) Solve the equation \\(f(x) = 0\\), giving your answers in exact form. Hence show that the equation has a root between 1 and 3. [3]\n(c) Explain why the change of sign method fails to show the root in (b). [2]`, marks: 6, command: 'Solve', markScheme: `(a)\nB1: \\(f(1) = 1 + 1 = 2\\), \\(f(3) = 3 - 1 = 2\\), both positive\n(b)\nM1: Multiplies by \\((x - 2)\\): \\(x^2 - 2x - 1 = 0\\)\nA1: \\(x = 1 \\pm \\sqrt{2}\\)\nA1: \\(1 + \\sqrt{2} \\approx 2.414\\), which lies between 1 and 3\n(c)\nE1: f is discontinuous at \\(x = 2\\) (vertical asymptote), which lies in the interval\nE1: f changes sign twice in \\((1, 3)\\): once across the asymptote and once at the root, so the end values have the same sign` },
      { q: `(a) Show that, when the Newton–Raphson method is used to solve \\(x^2 - a = 0\\), where \\(a\\) is a positive constant, the iterative formula can be written as\n\\[x_{n+1} = \\frac{1}{2}\\left(x_n + \\frac{a}{x_n}\\right)\\] [3]\n(b) Use this formula with \\(a = 10\\) and \\(x_1 = 3\\) to find \\(x_2\\) and \\(x_3\\), giving \\(x_3\\) to five decimal places. [2]\n(c) Explain why \\(x_1 = 0\\) cannot be used as a first approximation. [1]`, marks: 6, command: 'Show that', markScheme: `(a)\nB1: \\(f'(x) = 2x\\)\nM1: \\(x_{n+1} = x_n - \\frac{x_n^2 - a}{2x_n}\\)\nA1: \\(= \\frac{2x_n^2 - x_n^2 + a}{2x_n} = \\frac{1}{2}\\left(x_n + \\frac{a}{x_n}\\right)\\) (AG)\n(b)\nM1: \\(x_2 = \\frac{1}{2}(3 + \\frac{10}{3}) = \\frac{19}{6} = 3.16667\\)\nA1: \\(x_3 = 3.16228\\) (CAO) [\\(\\sqrt{10} = 3.16228\\)]\n(c)\nE1: \\(f'(0) = 0\\), so the formula requires division by zero (the tangent at \\(x = 0\\) is horizontal)` },
      { q: `A solid ball of radius 10 cm floats in water with its centre above the surface. The depth of the ball below the surface is \\(h\\) cm.\nThe volume of the submerged part is \\(\\frac{1}{3}\\pi h^2(30 - h)\\) cm³, and for the ball to float this must equal \\(800\\pi\\) cm³.\n\n(a) Show that \\(h^3 - 30h^2 + 2400 = 0\\) [1]\n(b) Show that this equation has a root between \\(h = 11\\) and \\(h = 12\\) [2]\n(c) Use the iteration \\(h_{n+1} = \\sqrt{\\frac{2400}{30 - h_n}}\\) with \\(h_1 = 11\\) to find \\(h_2\\), \\(h_3\\) and \\(h_4\\), giving your answers to three decimal places. [2]\n(d) Comment on the suitability of this iteration for finding \\(h\\) to a high degree of accuracy. [1]`, marks: 6, command: 'Show that', markScheme: `(a)\nB1: \\(\\frac{1}{3}\\pi h^2(30 - h) = 800\\pi\\) so \\(30h^2 - h^3 = 2400\\), i.e. \\(h^3 - 30h^2 + 2400 = 0\\) (AG)\n(b)\nM1: \\(f(11) = 101\\), \\(f(12) = -192\\)\nR1: Change of sign and f continuous, so root between 11 and 12\n(c)\nM1: \\(h_2 = \\sqrt{\\frac{2400}{19}} = 11.239\\)\nA1: \\(h_3 = 11.310\\), \\(h_4 = 11.332\\)\n(d)\nE1: It converges, but slowly (successive differences only shrinking by a factor of about 0.3), so many iterations are needed; a change-of-sign check or Newton–Raphson would be quicker. [Root \\(h = 11.341\\)]` },
      { q: `The equation \\(\\ln x + x^2 - 4 = 0\\) has a single root \\(\\alpha\\)\n\n(a) Show that \\(\\alpha\\) lies between 1.8 and 1.9 [2]\n(b) Show that the equation can be rearranged into the form \\(x = \\sqrt{4 - \\ln x}\\) [1]\n(c) Use the iteration \\(x_{n+1} = \\sqrt{4 - \\ln x_n}\\) with \\(x_1 = 1.8\\) to find \\(x_2\\) and \\(x_3\\), giving your answers to four decimal places. [2]\n(d) State, with a reason, whether a diagram of this iteration would be a staircase or a cobweb, and describe how the values approach \\(\\alpha\\) [2]`, marks: 7, command: 'Show that', markScheme: `(a)\nM1: \\(f(1.8) = -0.172\\), \\(f(1.9) = 0.252\\)\nR1: Change of sign and f continuous on \\([1.8, 1.9]\\), so \\(1.8 \\lt \\alpha \\lt 1.9\\)\n(b)\nB1: \\(x^2 = 4 - \\ln x\\), and \\(x \\gt 0\\) so \\(x = \\sqrt{4 - \\ln x}\\) (AG)\n(c)\nM1: \\(x_2 = \\sqrt{4 - \\ln 1.8}\\)\nA1: \\(x_2 = 1.8472\\), \\(x_3 = 1.8402\\)\n(d)\nE1: Cobweb, because \\(y = \\sqrt{4 - \\ln x}\\) is decreasing (negative gradient) near \\(\\alpha\\)\nE1: Values lie alternately above and below \\(\\alpha\\) and converge to it [\\(\\alpha = 1.8411\\)]` },
      { q: `The equation \\(x^4 - 2x^3 - 5 = 0\\) has a positive root \\(\\alpha\\)\n\n(a) Show that \\(\\alpha\\) lies between 2 and 3 [2]\n(b) Taking \\(x_1 = 2.5\\), use the Newton–Raphson method to find \\(x_2\\) and \\(x_3\\), giving your answers to four decimal places. [4]\n(c) Explain why \\(x_1 = 1.5\\) would not be a suitable first approximation. [1]`, marks: 7, command: 'Use', markScheme: `(a)\nM1: \\(f(2) = -5\\), \\(f(3) = 22\\)\nR1: Change of sign and f continuous, so \\(2 \\lt \\alpha \\lt 3\\)\n(b)\nB1: \\(f'(x) = 4x^3 - 6x^2\\)\nM1: \\(x_2 = 2.5 - \\frac{f(2.5)}{f'(2.5)} = 2.5 - \\frac{2.8125}{25}\\)\nA1: \\(x_2 = 2.3875\\)\nA1: \\(x_3 = 2.3740\\) (CAO)\n(c)\nE1: \\(f'(1.5) = 4(3.375) - 6(2.25) = 0\\), so there is a stationary point there and the Newton–Raphson formula would divide by zero` },
      { q: `(Data written for this practice question.)\nA cyclist starts from rest. Her speed, \\(v\\) m s⁻¹, is recorded every 10 seconds for one minute.\n\nt (s): 0, 10, 20, 30, 40, 50, 60\nv (m s⁻¹): 0, 4.2, 6.8, 8.1, 8.6, 8.8, 8.9\n\n(a) State what the area under a speed–time graph represents. [1]\n(b) Use the trapezium rule with all of these values to estimate the distance the cyclist travels in the minute. [3]\n(c) The speed–time graph is concave throughout the minute. Explain whether your answer to (b) is an overestimate or an underestimate. [2]\n(d) State one limitation of using the trapezium rule with these data. [1]`, marks: 7, command: 'Use', markScheme: `(a)\nB1: The distance travelled\n(b)\nB1: \\(h = 10\\)\nM1: \\(\\frac{10}{2}[0 + 8.9 + 2(4.2 + 6.8 + 8.1 + 8.6 + 8.8)]\\)\nA1: \\(409.5\\) m (CAO; accept 410)\n(c)\nE1: Concave means the curve lies above each chord joining consecutive points\nE1: So the trapezia lie under the curve and 409.5 m is an underestimate\n(d)\nE1: e.g. speeds are only known every 10 s so the shape between readings is unknown; readings may be rounded or inaccurate; the speed may not vary smoothly.` },
      { q: `The function f is given by \\(f(x) = \\frac{1}{1 + x^3}\\), which is decreasing for \\(0 \\leq x \\leq 2\\)\n\n(a) Using four rectangles of equal width, find a lower bound \\(L\\) and an upper bound \\(U\\) for \\(\\int_0^2 \\frac{1}{1+x^3} \\, dx\\), giving your answers to four decimal places. [4]\n(b) Use the trapezium rule with four strips to find an estimate \\(T\\) of the same integral, giving your answer to four decimal places. [2]\n(c) Verify that \\(T = \\frac{1}{2}(L + U)\\) [1]`, marks: 7, command: 'Find', markScheme: `(a)\nB1: \\(f(0) = 1\\), \\(f(0.5) = 0.8889\\), \\(f(1) = 0.5\\), \\(f(1.5) = 0.2286\\), \\(f(2) = 0.1111\\)\nM1: Decreasing so lower bound uses right-hand ends: \\(L = 0.5(0.8889 + 0.5 + 0.2286 + 0.1111)\\)\nA1: \\(L = 0.8643\\)\nA1: \\(U = 0.5(1 + 0.8889 + 0.5 + 0.2286) = 1.3087\\)\n(b)\nM1: \\(\\frac{0.5}{2}[1 + 0.1111 + 2(0.8889 + 0.5 + 0.2286)]\\)\nA1: \\(T = 1.0865\\)\n(c)\nB1: \\(\\frac{1}{2}(0.8643 + 1.3087) = 1.0865 = T\\) [exact value of the integral 1.0900]` },
      { q: `The concentration, \\(C\\) mg per litre, of a medicine in a patient's bloodstream \\(t\\) hours after an injection is modelled by\n\\[C = 20\\left(e^{-0.2t} - e^{-t}\\right)\\]\nThe medicine is effective when \\(C \\geq 5\\)\n\n(a) Show that the concentration first reaches 5 mg per litre at a time between \\(t = 0.3\\) and \\(t = 0.4\\) [2]\n(b) The concentration falls back to 5 mg per litre at a time close to \\(t = 7\\)\nUse the Newton–Raphson method with \\(t_1 = 7\\) to find \\(t_2\\), giving your answer to three decimal places. [4]\n(c) Given that the first time is 0.394 hours to three decimal places, find, to the nearest minute, how long the medicine is effective. [1]\n(d) State one limitation of the model. [1]`, marks: 8, command: 'Show that', markScheme: `(a)\nM1: Let \\(f(t) = 20(e^{-0.2t} - e^{-t}) - 5\\); \\(f(0.3) = -0.981\\), \\(f(0.4) = 0.056\\)\nR1: Change of sign and f continuous, so first time is between 0.3 and 0.4\n(b)\nB1: \\(f'(t) = 20(-0.2e^{-0.2t} + e^{-t})\\)\nM1: \\(f(7) = -0.0863\\), \\(f'(7) = -0.9682\\) (either correct)\nM1: \\(t_2 = 7 - \\frac{-0.0863}{-0.9682}\\)\nA1: \\(t_2 = 6.911\\) (CAO)\n(c)\nB1ft: \\(6.911 - 0.394 = 6.517\\) hours, i.e. 6 hours 31 minutes (ft their \\(t_2\\))\n(d)\nE1: e.g. the same model may not apply to every patient (body mass, metabolism); concentration may not vary smoothly; the model ignores further doses.` },
      { q: `The equation \\(x^5 - 3x - 1 = 0\\) has a positive root \\(\\alpha\\)\n\n(a) Show that \\(\\alpha\\) lies between 1.3 and 1.4 [2]\n(b) Show that the equation can be written as \\(x = (3x + 1)^{\\frac{1}{5}}\\) [1]\n(c) Use the iteration \\(x_{n+1} = (3x_n + 1)^{\\frac{1}{5}}\\) with \\(x_1 = 1.3\\) to find \\(x_2\\), \\(x_3\\) and \\(x_4\\), giving your answers to four decimal places. [2]\n(d) Show that \\(\\alpha = 1.389\\) correct to three decimal places. [3]`, marks: 8, command: 'Show that', markScheme: `(a)\nM1: \\(f(1.3) = -1.187\\), \\(f(1.4) = 0.178\\)\nR1: Change of sign and f continuous, so \\(1.3 \\lt \\alpha \\lt 1.4\\)\n(b)\nB1: \\(x^5 = 3x + 1 \\Rightarrow x = (3x + 1)^{\\frac{1}{5}}\\) (AG)\n(c)\nM1: \\(x_2 = 4.9^{0.2} = 1.3742\\)\nA1: \\(x_3 = 1.3864\\), \\(x_4 = 1.3884\\)\n(d)\nM1: Uses the interval \\([1.3885, 1.3895]\\)\nA1: \\(f(1.3885) = -0.0046\\), \\(f(1.3895) = 0.0111\\)\nR1: Change of sign and f continuous, so \\(1.3885 \\lt \\alpha \\lt 1.3895\\) and \\(\\alpha = 1.389\\) to 3 d.p.` },
      { q: `(Data written for this practice question.)\nThe cross-section of a road tunnel is 8 m wide. The height of the roof, \\(y\\) metres, is measured at points \\(x\\) metres from one side.\n\nx (m): 0, 1, 2, 3, 4, 5, 6, 7, 8\ny (m): 0, 2.3, 3.8, 4.6, 5.0, 4.7, 3.9, 2.4, 0\n\n(a) Use the trapezium rule with all of these values to estimate the area of the cross-section. [3]\n(b) The tunnel is 400 m long. Estimate the volume of air in the tunnel. [1]\n(c) An engineer models the roof by \\(y = \\frac{5}{16}x(8 - x)\\)\nWithout further calculation, explain whether the trapezium rule with 8 strips applied to the engineer's model would give an overestimate or an underestimate of the area under the model. [2]\n(d) The exact area under the engineer's model is \\(\\frac{80}{3}\\) m².\nUse this and your answer to (a) to comment on the suitability of the model. [2]\n(e) Give one reason why the volume in (b) may be inaccurate. [1]`, marks: 9, command: 'Use', markScheme: `(a)\nB1: \\(h = 1\\)\nM1: \\(\\frac{1}{2}[0 + 0 + 2(2.3 + 3.8 + 4.6 + 5.0 + 4.7 + 3.9 + 2.4)]\\)\nA1: \\(26.7\\) m² (CAO)\n(b)\nB1ft: \\(26.7 \\times 400 = 10\\,680\\) m³ (ft their area)\n(c)\nE1: \\(\\frac{d^2y}{dx^2} = -\\frac{5}{8} \\lt 0\\), so the model curve is concave\nE1: The trapezia lie below the curve, so it would be an underestimate\n(d)\nM1: Compares \\(\\frac{80}{3} = 26.67\\) with 26.7 (e.g. difference about 0.03 m², about 0.1%)\nE1: Very close agreement, so the model is suitable for estimating the area (though model heights differ slightly from the data, e.g. 2.19 m vs 2.3 m at \\(x = 1\\))\n(e)\nE1: e.g. the cross-section may not be the same along the whole tunnel; the tunnel may not be straight; road surface and fittings reduce the air volume.` },
      { q: `The equation \\(x^3 - 6x + 2 = 0\\) has a root \\(\\alpha\\) between 2 and 3.\n\n(a) Show that \\(\\alpha\\) lies between 2.2 and 2.3 [2]\n(b) Show that the equation can be rearranged as \\(x = \\sqrt{6 - \\frac{2}{x}}\\) and use the iteration \\(x_{n+1} = \\sqrt{6 - \\frac{2}{x_n}}\\) with \\(x_1 = 2.2\\) to find \\(x_2\\) and \\(x_3\\), giving your answers to four decimal places. [3]\n(c) State, with a reason, whether a diagram of the iteration in (b) is a staircase or a cobweb. [1]\n(d) Use the Newton–Raphson method with \\(x_1 = 2.2\\) to find \\(x_2\\), giving your answer to four decimal places. [2]\n(e) Another student uses the Newton–Raphson method with \\(x_1 = \\sqrt{2}\\)\nExplain why this fails. [2]`, marks: 10, command: 'Show that', markScheme: `(a)\nM1: \\(f(2.2) = -0.552\\), \\(f(2.3) = 0.367\\)\nR1: Change of sign and f continuous, so \\(2.2 \\lt \\alpha \\lt 2.3\\)\n(b)\nB1: \\(x^3 = 6x - 2 \\Rightarrow x^2 = 6 - \\frac{2}{x} \\Rightarrow x = \\sqrt{6 - \\frac{2}{x}}\\) (\\(x \\gt 0\\)) (AG)\nM1: \\(x_2 = \\sqrt{6 - \\frac{2}{2.2}}\\)\nA1: \\(x_2 = 2.2563\\), \\(x_3 = 2.2613\\)\n(c)\nE1: Staircase, since the iterates increase steadily towards \\(\\alpha\\) (the gradient of \\(y = \\sqrt{6 - \\frac{2}{x}}\\) is positive near \\(\\alpha\\))\n(d)\nM1: \\(f'(x) = 3x^2 - 6\\); \\(x_2 = 2.2 - \\frac{-0.552}{8.52}\\)\nA1: \\(x_2 = 2.2648\\) (CAO)\n(e)\nM1: \\(f'(\\sqrt{2}) = 3(2) - 6 = 0\\)\nE1: There is a stationary point at \\(x = \\sqrt{2}\\); the tangent is horizontal and does not meet the \\(x\\)-axis, so \\(x_2\\) is undefined (division by zero). [\\(\\alpha = 2.2618\\)]` }
    ]
  },
  '1.10': {
    name: 'Vectors',
    questions: [
      { q: `The vector \\(\\mathbf{a} = 2\\mathbf{i} - 3\\mathbf{j} + 6\\mathbf{k}\\).\n\nFind a unit vector in the direction of \\(\\mathbf{a}\\).`, marks: 2, command: 'Find', markScheme: `M1: \\(|\\mathbf{a}| = \\sqrt{2^2 + (-3)^2 + 6^2} = \\sqrt{49} = 7\\)\nA1: \\(\\frac{1}{7}(2\\mathbf{i} - 3\\mathbf{j} + 6\\mathbf{k})\\) CAO (accept \\(\\frac{2}{7}\\mathbf{i} - \\frac{3}{7}\\mathbf{j} + \\frac{6}{7}\\mathbf{k}\\) or column vector)\nFinal answer: \\(\\frac{1}{7}(2\\mathbf{i} - 3\\mathbf{j} + 6\\mathbf{k})\\)` },
      { q: `A cyclist, modelled as a particle, moves with constant velocity \\((5\\mathbf{i} - 12\\mathbf{j})\\) m s⁻¹.\n\nFind the speed of the cyclist.`, marks: 2, command: 'Find', markScheme: `M1: \\(\\sqrt{5^2 + (-12)^2}\\)\nA1: 13 m s⁻¹ CAO\nFinal answer: 13 m s⁻¹` },
      { q: `The vectors \\(\\mathbf{p} = \\begin{pmatrix} k \\\\ 3 \\end{pmatrix}\\) and \\(\\mathbf{q} = \\begin{pmatrix} 6 \\\\ -9 \\end{pmatrix}\\) are parallel.\n\nFind the value of \\(k\\).`, marks: 2, command: 'Find', markScheme: `M1: uses \\(\\mathbf{p} = \\lambda\\mathbf{q}\\) or equal ratios \\(\\frac{k}{6} = \\frac{3}{-9}\\)\nA1: \\(k = -2\\) CAO\nFinal answer: \\(k = -2\\)` },
      { q: `Three forces \\(\\mathbf{F}_1 = (3\\mathbf{i} + 2\\mathbf{j})\\) N, \\(\\mathbf{F}_2 = (-5\\mathbf{i} + 4\\mathbf{j})\\) N and \\(\\mathbf{F}_3 = (a\\mathbf{i} + b\\mathbf{j})\\) N act on a particle. The particle is in equilibrium.\n\nFind the values of \\(a\\) and \\(b\\).`, marks: 2, command: 'Find', markScheme: `M1: sets \\(\\mathbf{F}_1 + \\mathbf{F}_2 + \\mathbf{F}_3 = \\mathbf{0}\\), i.e. \\(3 - 5 + a = 0\\) or \\(2 + 4 + b = 0\\)\nA1: \\(a = 2\\), \\(b = -6\\) CAO\nFinal answer: \\(a = 2,\\ b = -6\\)` },
      { q: `The vector \\(\\mathbf{v} = -5\\mathbf{i} + 12\\mathbf{j}\\).\n\nFind the magnitude of \\(\\mathbf{v}\\) and the angle that \\(\\mathbf{v}\\) makes with the unit vector \\(\\mathbf{i}\\).\nGive the angle to the nearest 0.1°.`, marks: 3, command: 'Find', markScheme: `B1: \\(|\\mathbf{v}| = 13\\)\nM1: \\(\\tan^{-1}\\left(\\frac{12}{5}\\right) = 67.4°\\) or equivalent trig used correctly with a sketch of the second-quadrant vector\nA1: angle with \\(\\mathbf{i}\\) \\(= 180° - 67.4° = 112.6°\\) AWRT\nFinal answer: magnitude 13, angle 112.6°` },
      { q: `In this question \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) are unit vectors due east and due north respectively.\nA yacht moves with constant velocity \\((4\\mathbf{i} + 7\\mathbf{j})\\) km h⁻¹.\n\nFind the speed of the yacht and the bearing on which it is moving.\nGive the bearing to the nearest degree.`, marks: 3, command: 'Find', markScheme: `B1: speed \\(= \\sqrt{65} = 8.06\\) km h⁻¹ AWRT\nM1: \\(\\tan\\theta = \\frac{4}{7}\\) (angle from north) or \\(\\tan^{-1}\\left(\\frac{7}{4}\\right) = 60.3°\\) then \\(90° - 60.3°\\)\nA1: bearing 030° CAO (condone 30°)\nFinal answer: 8.06 km h⁻¹ on a bearing of 030°` },
      { q: `A force of magnitude 20 N acts in a direction making an angle of 150° anticlockwise from the unit vector \\(\\mathbf{i}\\).\n\nExpress the force in the form \\((a\\mathbf{i} + b\\mathbf{j})\\) N, where \\(a\\) and \\(b\\) are exact.`, marks: 3, command: 'Express', markScheme: `M1: uses \\(20\\cos 150°\\) and \\(20\\sin 150°\\) (or resolves using 30° with correct signs)\nA1: \\(a = -10\\sqrt{3}\\)\nA1: \\(b = 10\\)\nFinal answer: \\((-10\\sqrt{3}\\,\\mathbf{i} + 10\\mathbf{j})\\) N` },
      { q: `The points \\(A\\) and \\(B\\) have coordinates \\((1, 4, -2)\\) and \\((5, -2, 1)\\) respectively.\nThe point \\(C\\) is such that \\(\\overrightarrow{AC} = 2\\overrightarrow{AB}\\).\n\nFind the exact distance \\(AB\\) and the coordinates of \\(C\\).`, marks: 3, command: 'Find', markScheme: `M1: \\(\\overrightarrow{AB} = \\begin{pmatrix} 4 \\\\ -6 \\\\ 3 \\end{pmatrix}\\) and attempts its magnitude\nA1: \\(AB = \\sqrt{61}\\) CAO\nB1: \\(C = (9, -8, 4)\\) CAO\nFinal answer: \\(AB = \\sqrt{61}\\); \\(C(9, -8, 4)\\)` },
      { q: `The vector \\(\\mathbf{p} = 2\\mathbf{i} + t\\mathbf{j} - \\mathbf{k}\\), where \\(t\\) is a constant.\nGiven that \\(|\\mathbf{p}| = \\sqrt{30}\\), find the possible values of \\(t\\).`, marks: 3, command: 'Find', markScheme: `M1: \\(2^2 + t^2 + (-1)^2 = 30\\)\nA1: \\(t^2 = 25\\)\nA1: \\(t = 5\\) or \\(t = -5\\) (both required)\nFinal answer: \\(t = \\pm 5\\)` },
      { q: `A particle of mass 4 kg is acted on by two forces, \\((6\\mathbf{i} - 2\\mathbf{j})\\) N and \\((2\\mathbf{i} + 8\\mathbf{j})\\) N, and no other forces.\n\nFind the magnitude of the acceleration of the particle.`, marks: 3, command: 'Find', markScheme: `M1: resultant force \\(= (8\\mathbf{i} + 6\\mathbf{j})\\) N and uses \\(\\mathbf{F} = m\\mathbf{a}\\)\nA1: \\(\\mathbf{a} = (2\\mathbf{i} + 1.5\\mathbf{j})\\) m s⁻² or \\(|\\mathbf{F}| = 10\\) N\nA1: 2.5 m s⁻² CAO\nFinal answer: 2.5 m s⁻²` },
      { q: `The points \\(A\\), \\(B\\) and \\(C\\) have coordinates \\((2, 1, 3)\\), \\((4, 5, -1)\\) and \\((8, 13, -9)\\) respectively.\n\nProve that \\(A\\), \\(B\\) and \\(C\\) are collinear.`, marks: 3, command: 'Prove', markScheme: `M1: finds two of \\(\\overrightarrow{AB} = \\begin{pmatrix} 2 \\\\ 4 \\\\ -4 \\end{pmatrix}\\), \\(\\overrightarrow{BC} = \\begin{pmatrix} 4 \\\\ 8 \\\\ -8 \\end{pmatrix}\\), \\(\\overrightarrow{AC} = \\begin{pmatrix} 6 \\\\ 12 \\\\ -12 \\end{pmatrix}\\)\nA1: \\(\\overrightarrow{BC} = 2\\overrightarrow{AB}\\) (or equivalent scalar multiple)\nE1: concludes: vectors are parallel AND share the common point \\(B\\), so \\(A\\), \\(B\\), \\(C\\) are collinear\nFinal answer: proof complete` },
      { q: `The vectors \\(\\mathbf{a} = 3\\mathbf{i} - \\mathbf{j}\\) and \\(\\mathbf{b} = -\\mathbf{i} + 2\\mathbf{j}\\).\nGiven that \\(\\lambda\\mathbf{a} + \\mu\\mathbf{b} = 7\\mathbf{i} + 6\\mathbf{j}\\), find the values of the constants \\(\\lambda\\) and \\(\\mu\\).`, marks: 4, command: 'Find', markScheme: `M1: forms \\(3\\lambda - \\mu = 7\\) and \\(-\\lambda + 2\\mu = 6\\)\nM1: solves simultaneous equations (substitution or elimination)\nA1: \\(\\lambda = 4\\)\nA1: \\(\\mu = 5\\)\nFinal answer: \\(\\lambda = 4,\\ \\mu = 5\\)` },
      { q: `The vectors \\(\\mathbf{a} = \\begin{pmatrix} 1 \\\\ -2 \\\\ 4 \\end{pmatrix}\\) and \\(\\mathbf{b} = \\begin{pmatrix} -1 \\\\ 0 \\\\ 2 \\end{pmatrix}\\). The vector \\(\\mathbf{c} = 2\\mathbf{a} - 3\\mathbf{b}\\).\n\nFind a unit vector in the direction of \\(\\mathbf{c}\\). Give your answer in exact form.`, marks: 4, command: 'Find', markScheme: `M1: attempts \\(2\\mathbf{a} - 3\\mathbf{b}\\) component-wise\nA1: \\(\\mathbf{c} = \\begin{pmatrix} 5 \\\\ -4 \\\\ 2 \\end{pmatrix}\\)\nM1: \\(|\\mathbf{c}| = \\sqrt{25 + 16 + 4} = \\sqrt{45} = 3\\sqrt{5}\\) and divides\nA1: \\(\\frac{1}{3\\sqrt{5}}\\begin{pmatrix} 5 \\\\ -4 \\\\ 2 \\end{pmatrix}\\) or \\(\\frac{\\sqrt{5}}{15}\\begin{pmatrix} 5 \\\\ -4 \\\\ 2 \\end{pmatrix}\\) ISW\nFinal answer: \\(\\frac{1}{3\\sqrt{5}}(5\\mathbf{i} - 4\\mathbf{j} + 2\\mathbf{k})\\)` },
      { q: `A drone is modelled as a particle. Relative to a fixed origin \\(O\\) on horizontal ground, where \\(\\mathbf{k}\\) is vertically upwards and distances are in metres, the drone moves in a straight line at constant velocity from the point with position vector \\((40\\mathbf{i} + 30\\mathbf{j} + 12\\mathbf{k})\\) to the point with position vector \\((16\\mathbf{i} + 102\\mathbf{j} + 30\\mathbf{k})\\). The journey takes 12 seconds.\n\nFind the distance travelled by the drone and its speed.`, marks: 4, command: 'Find', markScheme: `M1: displacement \\(= (-24\\mathbf{i} + 72\\mathbf{j} + 18\\mathbf{k})\\) m\nA1: distance \\(= \\sqrt{576 + 5184 + 324} = \\sqrt{6084} = 78\\) m\nM1: velocity \\(= \\frac{1}{12}(-24\\mathbf{i} + 72\\mathbf{j} + 18\\mathbf{k}) = (-2\\mathbf{i} + 6\\mathbf{j} + 1.5\\mathbf{k})\\) or \\(78 \\div 12\\)\nA1: speed 6.5 m s⁻¹ CAO\nFinal answer: 78 m, 6.5 m s⁻¹` },
      { q: `A garden plot is modelled as the parallelogram \\(ABCD\\). Relative to a fixed origin, with distances in metres, \\(A\\), \\(B\\) and \\(C\\) have coordinates \\((2, 1)\\), \\((10, 5)\\) and \\((13, 14)\\) respectively.\n\nFind the coordinates of \\(D\\) and the length of fencing needed to go once around the perimeter of the plot.\nGive the length to 3 significant figures.`, marks: 4, command: 'Find', markScheme: `M1: uses \\(\\overrightarrow{AD} = \\overrightarrow{BC}\\), i.e. \\(\\mathbf{d} = \\mathbf{a} + \\mathbf{c} - \\mathbf{b}\\)\nA1: \\(D(5, 10)\\)\nM1: \\(AB = \\sqrt{8^2 + 4^2} = \\sqrt{80}\\) and \\(BC = \\sqrt{3^2 + 9^2} = \\sqrt{90}\\)\nA1: perimeter \\(= 2(\\sqrt{80} + \\sqrt{90}) = 36.9\\) m AWRT\nFinal answer: \\(D(5, 10)\\); 36.9 m` },
      { q: `A straight cable for a ski lift runs from the point \\(A\\) to the point \\(B\\). Relative to a fixed origin \\(O\\), with distances in metres, \\(\\overrightarrow{OA} = \\begin{pmatrix} -40 \\\\ 100 \\\\ 20 \\end{pmatrix}\\) and \\(\\overrightarrow{OB} = \\begin{pmatrix} 160 \\\\ -100 \\\\ 120 \\end{pmatrix}\\).\nA support tower meets the cable at the point \\(P\\), where \\(AP : PB = 3 : 2\\).\n\n(a) Find the length of the cable. [2]\n(b) Find the position vector of \\(P\\). [2]`, marks: 4, command: 'Find', markScheme: `(a)\nM1: \\(\\overrightarrow{AB} = \\begin{pmatrix} 200 \\\\ -200 \\\\ 100 \\end{pmatrix}\\) and attempts magnitude\nA1: \\(\\sqrt{90000} = 300\\) m CAO\n(b)\nM1: \\(\\overrightarrow{OP} = \\overrightarrow{OA} + \\frac{3}{5}\\overrightarrow{AB}\\)\nA1: \\(\\begin{pmatrix} 80 \\\\ -20 \\\\ 80 \\end{pmatrix}\\) CAO\nFinal answer: (a) 300 m (b) \\(80\\mathbf{i} - 20\\mathbf{j} + 80\\mathbf{k}\\)` },
      { q: `In this question \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) are unit vectors due east and due north respectively, and position vectors are relative to a lighthouse \\(O\\).\nAt noon a ship is at the point with position vector \\((2\\mathbf{i} + 5\\mathbf{j})\\) km and is moving with constant velocity \\((3\\mathbf{i} - 4\\mathbf{j})\\) km h⁻¹.\n\nFind the time at which the ship is due east of the lighthouse, and its distance from the lighthouse at that time.`, marks: 4, command: 'Find', markScheme: `B1: \\(\\mathbf{r} = (2 + 3t)\\mathbf{i} + (5 - 4t)\\mathbf{j}\\)\nM1: sets \\(\\mathbf{j}\\) component equal to 0\nA1: \\(t = 1.25\\), i.e. 13:15 (1:15 pm)\nA1: 5.75 km CAO\nFinal answer: 13:15, 5.75 km` },
      { q: `Three forces \\((4\\mathbf{i} + 3\\mathbf{j})\\) N, \\((-7\\mathbf{i} + 5\\mathbf{j})\\) N and \\((2\\mathbf{i} - 2\\mathbf{j})\\) N act on a particle.\n\nFind the magnitude of the resultant force and the angle the resultant makes with the unit vector \\(\\mathbf{i}\\).`, marks: 4, command: 'Find', markScheme: `M1: adds components\nA1: resultant \\(= (-\\mathbf{i} + 6\\mathbf{j})\\) N\nB1ft: magnitude \\(\\sqrt{37} = 6.08\\) N AWRT\nA1: angle \\(= 180° - \\tan^{-1}6 = 99.5°\\) AWRT\nFinal answer: 6.08 N at 99.5° to \\(\\mathbf{i}\\)` },
      { q: `The vectors \\(\\mathbf{a} = 3\\mathbf{i} + \\mathbf{j} - 2\\mathbf{k}\\) and \\(\\mathbf{b} = \\mathbf{i} + \\mathbf{j}\\).\nGiven that \\(|\\mathbf{a} - k\\mathbf{b}| = \\sqrt{14}\\), find the possible values of the constant \\(k\\).`, marks: 4, command: 'Find', markScheme: `M1: \\(\\mathbf{a} - k\\mathbf{b} = (3 - k)\\mathbf{i} + (1 - k)\\mathbf{j} - 2\\mathbf{k}\\)\nM1: \\((3 - k)^2 + (1 - k)^2 + 4 = 14\\)\nA1: \\(2k^2 - 8k = 0\\)\nA1: \\(k = 0\\) or \\(k = 4\\)\nFinal answer: \\(k = 0\\) or \\(k = 4\\)` },
      { q: `The points \\(A\\), \\(B\\) and \\(C\\) have coordinates \\((1, 2, 3)\\), \\((3, 3, 1)\\) and \\((2, 2, 4)\\) respectively.\n\n(a) Prove that triangle \\(ABC\\) is right-angled. [3]\n(b) Find the exact area of triangle \\(ABC\\). [2]`, marks: 5, command: 'Prove', markScheme: `(a)\nM1: finds at least two of \\(AB^2 = 9\\), \\(AC^2 = 2\\), \\(BC^2 = 11\\) from \\(\\overrightarrow{AB} = (2, 1, -2)\\), \\(\\overrightarrow{AC} = (1, 0, 1)\\), \\(\\overrightarrow{BC} = (-1, -1, 3)\\)\nA1: all three correct\nR1: \\(AB^2 + AC^2 = 9 + 2 = 11 = BC^2\\), so by Pythagoras the angle at \\(A\\) is a right angle\n(b)\nM1: \\(\\frac{1}{2} \\times 3 \\times \\sqrt{2}\\)\nA1: \\(\\frac{3\\sqrt{2}}{2}\\) CAO\nFinal answer: (b) \\(\\frac{3\\sqrt{2}}{2}\\)` },
      { q: `A roof truss is modelled as the triangle \\(ABC\\). Relative to a fixed origin, with distances in metres, the points \\(A\\), \\(B\\) and \\(C\\) have coordinates \\((2, 0, 1)\\), \\((4, 3, 7)\\) and \\((-1, 4, 1)\\) respectively.\n\nFind the angle \\(BAC\\), giving your answer to the nearest 0.1°.`, marks: 5, command: 'Find', markScheme: `M1: finds \\(\\overrightarrow{AB} = (2, 3, 6)\\), \\(\\overrightarrow{AC} = (-3, 4, 0)\\), \\(\\overrightarrow{BC} = (-5, 1, -6)\\) (any two correct)\nA1: \\(AB = 7\\), \\(AC = 5\\), \\(BC = \\sqrt{62}\\)\nM1: uses the cosine rule with their lengths\nA1: \\(\\cos BAC = \\frac{49 + 25 - 62}{2 \\times 7 \\times 5} = \\frac{12}{70}\\)\nA1: 80.1° AWRT\nFinal answer: 80.1°` },
      { q: `In this question \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) are unit vectors due east and due north respectively.\nTwo remote-controlled toy cars, \\(P\\) and \\(Q\\), are modelled as particles moving on a horizontal playground. At time \\(t\\) seconds their position vectors, in metres, relative to a fixed origin are\n\\(\\mathbf{r}_P = (1 + 2t)\\mathbf{i} + (7 - t)\\mathbf{j}\\) and \\(\\mathbf{r}_Q = (13 - t)\\mathbf{i} + (1 + t)\\mathbf{j}\\).\n\n(a) Find \\(\\overrightarrow{PQ}\\) in terms of \\(t\\). [2]\n(b) Show that the cars never collide, and find the distance between them at the instant when \\(Q\\) is due north of \\(P\\). [3]`, marks: 5, command: 'Show that', markScheme: `(a)\nM1: \\(\\mathbf{r}_Q - \\mathbf{r}_P\\)\nA1: \\((12 - 3t)\\mathbf{i} + (2t - 6)\\mathbf{j}\\)\n(b)\nE1: \\(\\mathbf{i}\\) component zero only at \\(t = 4\\), \\(\\mathbf{j}\\) component zero only at \\(t = 3\\); not simultaneously zero, so no collision\nM1: due north when \\(\\mathbf{i}\\) component is 0, so \\(t = 4\\)\nA1: \\(\\overrightarrow{PQ} = 2\\mathbf{j}\\), distance 2 m CAO\nFinal answer: 2 m` },
      { q: `In this question \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) are unit vectors due east and due north respectively, and position vectors are relative to a harbour \\(O\\).\nA motor boat leaves the point with position vector \\((-2\\mathbf{i} + \\mathbf{j})\\) km and travels at a constant speed of 15 km h⁻¹ in the direction of the vector \\(3\\mathbf{i} + 4\\mathbf{j}\\).\n\nFind the distance of the boat from the harbour 20 minutes after it sets off.\nGive your answer to 3 significant figures.`, marks: 5, command: 'Find', markScheme: `M1: unit vector \\(\\frac{1}{5}(3\\mathbf{i} + 4\\mathbf{j})\\) multiplied by 15\nA1: velocity \\((9\\mathbf{i} + 12\\mathbf{j})\\) km h⁻¹\nM1: \\(\\mathbf{r} = (-2\\mathbf{i} + \\mathbf{j}) + \\frac{1}{3}(9\\mathbf{i} + 12\\mathbf{j})\\) (condone use of \\(t = 20\\) for M0)\nA1: \\(\\mathbf{r} = \\mathbf{i} + 5\\mathbf{j}\\)\nA1: \\(\\sqrt{26} = 5.10\\) km AWRT\nFinal answer: 5.10 km` },
      { q: `In triangle \\(OAB\\), \\(\\overrightarrow{OA} = \\mathbf{a}\\) and \\(\\overrightarrow{OB} = \\mathbf{b}\\).\n\\(M\\) is the midpoint of \\(OA\\). \\(N\\) is the point on \\(AB\\) such that \\(AN : NB = 2 : 1\\).\nThe point \\(P\\) lies on \\(OB\\) extended such that \\(\\overrightarrow{OP} = 2\\mathbf{b}\\).\n\n(a) Show that \\(\\overrightarrow{MN} = -\\frac{1}{6}\\mathbf{a} + \\frac{2}{3}\\mathbf{b}\\). [2]\n(b) Prove that \\(M\\), \\(N\\) and \\(P\\) are collinear. [3]`, marks: 5, command: 'Prove', markScheme: `(a)\nM1: \\(\\overrightarrow{MN} = \\overrightarrow{MA} + \\overrightarrow{AN} = \\frac{1}{2}\\mathbf{a} + \\frac{2}{3}(\\mathbf{b} - \\mathbf{a})\\)\nA1: \\(-\\frac{1}{6}\\mathbf{a} + \\frac{2}{3}\\mathbf{b}\\) AG, convincingly shown\n(b)\nM1: \\(\\overrightarrow{MP} = -\\frac{1}{2}\\mathbf{a} + 2\\mathbf{b}\\)\nA1: \\(\\overrightarrow{MP} = 3\\overrightarrow{MN}\\)\nE1: parallel with common point \\(M\\), hence collinear\nFinal answer: proof complete` },
      { q: `A particle of mass 3 kg moves under the action of three forces \\((2\\mathbf{i} + p\\mathbf{j})\\) N, \\((q\\mathbf{i} - 5\\mathbf{j})\\) N and \\((-6\\mathbf{i} + 3\\mathbf{j})\\) N, where \\(p\\) and \\(q\\) are constants.\nThe acceleration of the particle is \\((2\\mathbf{i} - \\mathbf{j})\\) m s⁻².\n\nFind the values of \\(p\\) and \\(q\\), and the magnitude of the resultant force.`, marks: 5, command: 'Find', markScheme: `M1: uses \\(\\mathbf{F} = m\\mathbf{a}\\) with the sum of the three forces\nA1: \\(m\\mathbf{a} = (6\\mathbf{i} - 3\\mathbf{j})\\) N\nM1: equates components: \\(q - 4 = 6\\), \\(p - 2 = -3\\)\nA1: \\(q = 10\\), \\(p = -1\\)\nB1: \\(|\\mathbf{F}| = \\sqrt{45} = 3\\sqrt{5} = 6.71\\) N AWRT\nFinal answer: \\(p = -1\\), \\(q = 10\\), 6.71 N` },
      { q: `A small drone is modelled as a particle. Its position vector, in metres, relative to a beacon at \\(t\\) minutes after it is released is modelled by\n\\(\\mathbf{r} = (1 + 2t)\\mathbf{i} + (3 - t)\\mathbf{j} + (2t - 4)\\mathbf{k}\\)\n(data written for this practice question).\n\nUse the model to find the time at which the drone is closest to the beacon and the exact minimum distance. State one limitation of the model.`, marks: 5, command: 'Find', markScheme: `M1: \\(|\\mathbf{r}|^2 = (1 + 2t)^2 + (3 - t)^2 + (2t - 4)^2\\)\nA1: \\(9t^2 - 18t + 26\\)\nM1: completes the square, \\(9(t - 1)^2 + 17\\), or differentiates and sets to 0\nA1: \\(t = 1\\) minute, minimum distance \\(\\sqrt{17}\\) m\nE1: valid limitation, e.g. the drone is not a particle / the drone would not move with exactly constant velocity (wind effects ignored)\nFinal answer: \\(t = 1\\), \\(\\sqrt{17}\\) m` },
      { q: `\\(OABC\\) is a parallelogram with \\(\\overrightarrow{OA} = \\mathbf{a}\\) and \\(\\overrightarrow{OC} = \\mathbf{c}\\).\n\\(M\\) is the midpoint of \\(AB\\). The point \\(X\\) lies on \\(OM\\) such that \\(OX : XM = 2 : 1\\).\n\nProve that \\(X\\) lies on the diagonal \\(AC\\), and find the ratio \\(AX : XC\\).`, marks: 6, command: 'Prove', markScheme: `M1: \\(\\overrightarrow{OM} = \\overrightarrow{OA} + \\frac{1}{2}\\overrightarrow{AB}\\) with \\(\\overrightarrow{AB} = \\mathbf{c}\\)\nA1: \\(\\overrightarrow{OM} = \\mathbf{a} + \\frac{1}{2}\\mathbf{c}\\)\nA1ft: \\(\\overrightarrow{OX} = \\frac{2}{3}\\mathbf{a} + \\frac{1}{3}\\mathbf{c}\\)\nM1: \\(\\overrightarrow{AX} = \\overrightarrow{OX} - \\mathbf{a} = \\frac{1}{3}(\\mathbf{c} - \\mathbf{a})\\), compared with \\(\\overrightarrow{AC} = \\mathbf{c} - \\mathbf{a}\\)\nE1: \\(\\overrightarrow{AX} = \\frac{1}{3}\\overrightarrow{AC}\\), parallel with common point \\(A\\), so \\(X\\) lies on \\(AC\\)\nA1: \\(AX : XC = 1 : 2\\) CAO\nFinal answer: \\(AX : XC = 1 : 2\\)` },
      { q: `In this question \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) are unit vectors due east and due north respectively, and distances are in kilometres.\nAt noon, ship \\(A\\) is at the origin \\(O\\) and ship \\(B\\) is at the point with position vector \\((15\\mathbf{i} - 5\\mathbf{j})\\). Ship \\(A\\) moves with constant velocity \\((5\\mathbf{i} + 2\\mathbf{j})\\) km h⁻¹ and ship \\(B\\) moves with constant velocity \\((2\\mathbf{i} + 6\\mathbf{j})\\) km h⁻¹.\n\nFind the minimum distance between the two ships and the time at which it occurs.\nFully justify your answer.`, marks: 6, command: 'Find', markScheme: `M1: position vectors at time \\(t\\): \\(\\mathbf{r}_A = 5t\\mathbf{i} + 2t\\mathbf{j}\\), \\(\\mathbf{r}_B = (15 + 2t)\\mathbf{i} + (-5 + 6t)\\mathbf{j}\\)\nA1: \\(\\overrightarrow{AB} = (15 - 3t)\\mathbf{i} + (4t - 5)\\mathbf{j}\\)\nM1: \\(AB^2 = (15 - 3t)^2 + (4t - 5)^2 = 25t^2 - 130t + 250\\)\ndM1: completes the square \\(25(t - 2.6)^2 + 81\\) (or differentiates and sets to 0)\nA1: \\(t = 2.6\\) hours, i.e. 14:36\nA1: minimum distance 9 km CAO\nFinal answer: 9 km at 14:36` },
      { q: `A particle of mass 2 kg is acted on by two forces only. The first force is \\((5\\mathbf{i} + 2\\mathbf{j})\\) N. The second force has magnitude 13 N and acts in the direction of the vector \\(-12\\mathbf{i} + 5\\mathbf{j}\\).\n\n(a) Express the second force in the form \\((a\\mathbf{i} + b\\mathbf{j})\\) N. [2]\n(b) Find the magnitude of the resultant force and the angle it makes with the unit vector \\(\\mathbf{i}\\). [3]\n(c) Find the magnitude of the acceleration of the particle. [1]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: \\(13 \\times \\frac{1}{13}(-12\\mathbf{i} + 5\\mathbf{j})\\), using \\(|-12\\mathbf{i} + 5\\mathbf{j}| = 13\\)\nA1: \\((-12\\mathbf{i} + 5\\mathbf{j})\\) N\n(b)\nM1ft: resultant \\((-7\\mathbf{i} + 7\\mathbf{j})\\) N\nA1: magnitude \\(7\\sqrt{2} = 9.90\\) N AWRT\nA1: 135° CAO\n(c)\nB1ft: \\(\\frac{7\\sqrt{2}}{2} = 4.95\\) m s⁻² AWRT\nFinal answer: (b) 9.90 N at 135° (c) 4.95 m s⁻²` },
      { q: `A sail is modelled as the triangle \\(ABC\\). Relative to a fixed origin, with distances in metres, the points \\(A\\), \\(B\\) and \\(C\\) have coordinates \\((3, -1, 2)\\), \\((1, 3, -2)\\) and \\((k, 5, 0)\\) respectively. The triangle is isosceles with \\(AC = BC\\).\n\n(a) Find the value of \\(k\\). [3]\n(b) Find the exact area of the sail. [3]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: \\(AC^2 = (k - 3)^2 + 6^2 + (-2)^2\\) and \\(BC^2 = (k - 1)^2 + 2^2 + 2^2\\)\nM1: equates and expands: \\(k^2 - 6k + 49 = k^2 - 2k + 9\\)\nA1: \\(k = 10\\)\n(b)\nM1: midpoint of \\(AB\\) is \\(M(2, 1, 0)\\) and finds \\(CM\\) (or uses cosine rule for an angle)\nA1: \\(CM = \\sqrt{80} = 4\\sqrt{5}\\) and \\(AB = 6\\)\nA1: area \\(= \\frac{1}{2} \\times 6 \\times 4\\sqrt{5} = 12\\sqrt{5}\\) m² CAO\nFinal answer: (a) \\(k = 10\\) (b) \\(12\\sqrt{5}\\) m²` },
      { q: `A straight zip wire runs from the top of a tower at \\(P\\) to an anchor point \\(Q\\) on horizontal ground. Relative to the base \\(O\\) of the tower, with \\(\\mathbf{k}\\) vertically upwards and distances in metres, \\(\\overrightarrow{OP} = 30\\mathbf{k}\\) and \\(\\overrightarrow{OQ} = 120\\mathbf{i} + 50\\mathbf{j}\\).\n\n(a) Find the length of the zip wire. Give your answer to 3 significant figures. [2]\n(b) A rider \\(R\\) is on the wire with \\(PR : RQ = 2 : 3\\). Find the height of \\(R\\) above the ground. [2]\n(c) Find the angle between the wire and the horizontal. [1]\n(d) State one limitation of modelling the zip wire as a straight line. [1]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: \\(\\overrightarrow{PQ} = 120\\mathbf{i} + 50\\mathbf{j} - 30\\mathbf{k}\\) and attempts magnitude\nA1: \\(\\sqrt{17800} = 133\\) m AWRT\n(b)\nM1: \\(\\overrightarrow{OR} = \\overrightarrow{OP} + \\frac{2}{5}\\overrightarrow{PQ} = 48\\mathbf{i} + 20\\mathbf{j} + 18\\mathbf{k}\\)\nA1: 18 m CAO\n(c)\nB1: \\(\\tan^{-1}\\left(\\frac{30}{130}\\right) = 13.0°\\) AWRT (horizontal distance \\(\\sqrt{120^2 + 50^2} = 130\\))\n(d)\nE1: e.g. the wire sags under the rider's weight so is not straight\nFinal answer: (a) 133 m (b) 18 m (c) 13.0°` },
      { q: `The vectors \\(\\mathbf{a} = \\begin{pmatrix} 2 \\\\ -1 \\end{pmatrix}\\) and \\(\\mathbf{b} = \\begin{pmatrix} 1 \\\\ 3 \\end{pmatrix}\\).\n\n(a) Find the value of the scalar \\(\\lambda\\) such that \\(\\mathbf{a} + \\lambda\\mathbf{b}\\) is parallel to \\(\\begin{pmatrix} 1 \\\\ 1 \\end{pmatrix}\\). [3]\n(b) Find the values of \\(\\mu\\) such that \\(|\\mathbf{a} + \\mu\\mathbf{b}| = 5\\). Give your answers to 3 significant figures. [3]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: \\(\\mathbf{a} + \\lambda\\mathbf{b} = \\begin{pmatrix} 2 + \\lambda \\\\ -1 + 3\\lambda \\end{pmatrix}\\)\nM1: equal components: \\(2 + \\lambda = -1 + 3\\lambda\\)\nA1: \\(\\lambda = 1.5\\)\n(b)\nM1: \\((2 + \\mu)^2 + (3\\mu - 1)^2 = 25\\)\nA1: \\(5\\mu^2 - \\mu - 10 = 0\\) (or \\(10\\mu^2 - 2\\mu - 20 = 0\\))\nA1: \\(\\mu = 1.52\\) or \\(\\mu = -1.32\\) AWRT\nFinal answer: (a) 1.5 (b) 1.52, −1.32` },
      { q: `\\(OABC\\) is a trapezium in which \\(\\overrightarrow{OA} = \\mathbf{a}\\), \\(\\overrightarrow{OC} = \\mathbf{c}\\) and \\(\\overrightarrow{CB} = 2\\mathbf{a}\\).\nThe point \\(D\\) lies on \\(AB\\) such that \\(AD : DB = 1 : 2\\).\n\n(a) Find \\(\\overrightarrow{AB}\\) in terms of \\(\\mathbf{a}\\) and \\(\\mathbf{c}\\). [1]\n(b) Show that \\(\\overrightarrow{OD} = \\frac{4}{3}\\mathbf{a} + \\frac{1}{3}\\mathbf{c}\\). [2]\n(c) The line \\(OD\\) is extended to meet the line \\(CB\\) extended at the point \\(E\\).\nProve that \\(B\\) is the midpoint of \\(CE\\). [4]`, marks: 7, command: 'Prove', markScheme: `(a)\nB1: \\(\\overrightarrow{AB} = \\mathbf{a} + \\mathbf{c}\\) (from \\(-\\mathbf{a} + \\mathbf{c} + 2\\mathbf{a}\\))\n(b)\nM1: \\(\\overrightarrow{OD} = \\mathbf{a} + \\frac{1}{3}(\\mathbf{a} + \\mathbf{c})\\)\nA1: \\(\\frac{4}{3}\\mathbf{a} + \\frac{1}{3}\\mathbf{c}\\) AG\n(c)\nM1: \\(\\overrightarrow{OE} = \\lambda\\left(\\frac{4}{3}\\mathbf{a} + \\frac{1}{3}\\mathbf{c}\\right)\\) and \\(\\overrightarrow{OE} = \\mathbf{c} + s\\mathbf{a}\\)\ndM1: equates coefficients of \\(\\mathbf{c}\\) (since \\(\\mathbf{a}\\), \\(\\mathbf{c}\\) not parallel): \\(\\frac{\\lambda}{3} = 1\\)\nA1: \\(\\lambda = 3\\), \\(\\overrightarrow{OE} = 4\\mathbf{a} + \\mathbf{c}\\)\nE1: \\(\\overrightarrow{CE} = 4\\mathbf{a} = 2\\overrightarrow{CB}\\), so \\(B\\) is the midpoint of \\(CE\\)\nFinal answer: proof complete` },
      { q: `A particle moves on a smooth horizontal surface. At time \\(t = 0\\) it is at the origin \\(O\\) with velocity \\((3\\mathbf{i} - 2\\mathbf{j})\\) m s⁻¹. It moves with constant acceleration \\((-\\mathbf{i} + 2\\mathbf{j})\\) m s⁻². The unit vectors \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) are due east and due north respectively.\n\n(a) Find the velocity of the particle at time \\(t\\) seconds. [1]\n(b) Find the speed of the particle at the instant when it is moving due east. [2]\n(c) Find the distance of the particle from \\(O\\) when \\(t = 4\\). [3]\n(d) Find the value of \\(t\\), where \\(t \\gt 0\\), when the particle is due north of \\(O\\). [1]`, marks: 7, command: 'Find', markScheme: `(a)\nB1: \\(\\mathbf{v} = (3 - t)\\mathbf{i} + (2t - 2)\\mathbf{j}\\)\n(b)\nM1: \\(\\mathbf{j}\\) component \\(= 0\\), so \\(t = 1\\)\nA1: \\(\\mathbf{v} = 2\\mathbf{i}\\), speed 2 m s⁻¹\n(c)\nM1: \\(\\mathbf{r} = \\mathbf{u}t + \\frac{1}{2}\\mathbf{a}t^2\\) with \\(t = 4\\)\nA1: \\(\\mathbf{r} = 4\\mathbf{i} + 8\\mathbf{j}\\)\nA1: \\(\\sqrt{80} = 8.94\\) m AWRT (accept \\(4\\sqrt{5}\\))\n(d)\nB1: \\(3t - \\frac{1}{2}t^2 = 0\\) so \\(t = 6\\) (with \\(\\mathbf{j}\\) component 24, positive)\nFinal answer: (b) 2 m s⁻¹ (c) 8.94 m (d) \\(t = 6\\)` },
      { q: `A tent is modelled as a pyramid with a square base \\(OABC\\) on horizontal ground and vertex \\(V\\). Relative to \\(O\\), with \\(\\mathbf{k}\\) vertically upwards and distances in metres, the points have coordinates \\(A(4, 0, 0)\\), \\(B(4, 4, 0)\\), \\(C(0, 4, 0)\\) and \\(V(2, 2, 3)\\). Each sloping edge is a straight pole.\n\n(a) Find the exact length of the pole \\(OV\\). [2]\n(b) Find the angle \\(OVA\\). [3]\n(c) A guy rope runs in a straight line from \\(O\\) to the midpoint \\(M\\) of the pole \\(VB\\). Show that the length of the rope is 4.5 m. [2]`, marks: 7, command: 'Find', markScheme: `(a)\nM1: \\(\\sqrt{2^2 + 2^2 + 3^2}\\)\nA1: \\(\\sqrt{17}\\) m\n(b)\nB1: \\(VA = \\sqrt{17}\\), \\(OA = 4\\)\nM1: cosine rule: \\(\\cos OVA = \\frac{17 + 17 - 16}{2 \\times 17} = \\frac{9}{17}\\)\nA1: 58.0° AWRT\n(c)\nM1: \\(M = \\frac{1}{2}\\left((2, 2, 3) + (4, 4, 0)\\right) = (3, 3, 1.5)\\)\nA1: \\(\\sqrt{9 + 9 + 2.25} = \\sqrt{20.25} = 4.5\\) AG\nFinal answer: (a) \\(\\sqrt{17}\\) m (b) 58.0°` },
      { q: `\\(ABCD\\) is a quadrilateral. The points \\(A\\), \\(B\\), \\(C\\) and \\(D\\) have position vectors \\(\\mathbf{a}\\), \\(\\mathbf{b}\\), \\(\\mathbf{c}\\) and \\(\\mathbf{d}\\) respectively. \\(P\\), \\(Q\\), \\(R\\) and \\(S\\) are the midpoints of \\(AB\\), \\(BC\\), \\(CD\\) and \\(DA\\) respectively.\n\n(a) Find \\(\\overrightarrow{PQ}\\) in terms of \\(\\mathbf{a}\\) and \\(\\mathbf{c}\\). [2]\n(b) Prove that \\(PQRS\\) is a parallelogram. [3]\n(c) Given that \\(A\\), \\(B\\), \\(C\\) and \\(D\\) have coordinates \\((1, 2, 0)\\), \\((5, 0, 2)\\), \\((7, 4, 6)\\) and \\((1, 6, 2)\\), find the perimeter of \\(PQRS\\), giving your answer to 3 significant figures. [2]`, marks: 7, command: 'Prove', markScheme: `(a)\nM1: \\(\\overrightarrow{PQ} = \\frac{1}{2}(\\mathbf{b} + \\mathbf{c}) - \\frac{1}{2}(\\mathbf{a} + \\mathbf{b})\\)\nA1: \\(\\frac{1}{2}(\\mathbf{c} - \\mathbf{a})\\)\n(b)\nM1: \\(\\overrightarrow{SR} = \\frac{1}{2}(\\mathbf{c} + \\mathbf{d}) - \\frac{1}{2}(\\mathbf{d} + \\mathbf{a})\\)\nA1: \\(= \\frac{1}{2}(\\mathbf{c} - \\mathbf{a})\\)\nE1: \\(\\overrightarrow{PQ} = \\overrightarrow{SR}\\), so one pair of opposite sides is equal and parallel, hence \\(PQRS\\) is a parallelogram\n(c)\nM1: \\(PQ = \\frac{1}{2}|\\mathbf{c} - \\mathbf{a}| = |(3, 1, 3)| = \\sqrt{19}\\) and \\(QR = \\frac{1}{2}|\\mathbf{d} - \\mathbf{b}| = |(-2, 3, 0)| = \\sqrt{13}\\)\nA1: \\(2(\\sqrt{19} + \\sqrt{13}) = 15.9\\) AWRT\nFinal answer: (c) 15.9` },
      { q: `In this question \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) are unit vectors due east and due north respectively, and position vectors are in metres relative to a fixed origin.\nTwo robots, \\(A\\) and \\(B\\), are modelled as particles moving across a warehouse floor. At time \\(t = 0\\), \\(A\\) is at \\((2\\mathbf{i} + 9\\mathbf{j})\\) and moves with constant velocity \\((3\\mathbf{i} - \\mathbf{j})\\) m s⁻¹; \\(B\\) is at \\((6\\mathbf{i} - 7\\mathbf{j})\\) and moves with constant velocity \\((2\\mathbf{i} + 3\\mathbf{j})\\) m s⁻¹.\n\n(a) Show that, if neither robot changes course, they will collide, and find the position vector of the point of collision. [3]\n(b) Find the distance between the robots when \\(t = 1\\). [2]\n(c) Find the bearing of \\(B\\) from \\(A\\) when \\(t = 1\\), giving your answer to the nearest degree. [3]`, marks: 8, command: 'Show that', markScheme: `(a)\nM1: \\(\\mathbf{r}_A = (2 + 3t)\\mathbf{i} + (9 - t)\\mathbf{j}\\), \\(\\mathbf{r}_B = (6 + 2t)\\mathbf{i} + (-7 + 3t)\\mathbf{j}\\) and equates one component\nA1: \\(t = 4\\) from both components (\\(2 + 3t = 6 + 2t\\) and \\(9 - t = -7 + 3t\\)), so they collide\nA1: \\(14\\mathbf{i} + 5\\mathbf{j}\\)\n(b)\nM1: \\(\\overrightarrow{AB} = (8\\mathbf{i} - 4\\mathbf{j}) - (5\\mathbf{i} + 8\\mathbf{j}) = 3\\mathbf{i} - 12\\mathbf{j}\\)\nA1: \\(\\sqrt{153} = 12.4\\) m AWRT\n(c)\nM1: \\(\\tan^{-1}\\left(\\frac{3}{12}\\right) = 14.0°\\) or \\(\\tan^{-1}\\left(\\frac{12}{3}\\right) = 76.0°\\)\nM1: correct use for a direction south of east (bearing \\(180° - 14.0°\\) or \\(90° + 76.0°\\))\nA1: 166° CAO\nFinal answer: (a) \\(14\\mathbf{i} + 5\\mathbf{j}\\) (b) 12.4 m (c) 166°` },
      { q: `In triangle \\(OAB\\), \\(\\overrightarrow{OA} = \\mathbf{a}\\) and \\(\\overrightarrow{OB} = \\mathbf{b}\\).\n\\(P\\) is the midpoint of \\(OA\\). \\(Q\\) is the point on \\(AB\\) such that \\(AQ : QB = 1 : 2\\).\nThe lines \\(OQ\\) and \\(BP\\) intersect at the point \\(R\\).\n\n(a) Find \\(\\overrightarrow{OQ}\\) in terms of \\(\\mathbf{a}\\) and \\(\\mathbf{b}\\). [2]\n(b) Find \\(\\overrightarrow{OR}\\) in terms of \\(\\mathbf{a}\\) and \\(\\mathbf{b}\\). [4]\n(c) Find the ratio \\(BR : RP\\). [2]`, marks: 8, command: 'Find', markScheme: `(a)\nM1: \\(\\overrightarrow{OQ} = \\mathbf{a} + \\frac{1}{3}(\\mathbf{b} - \\mathbf{a})\\)\nA1: \\(\\frac{2}{3}\\mathbf{a} + \\frac{1}{3}\\mathbf{b}\\)\n(b)\nM1: \\(\\overrightarrow{OR} = \\lambda\\left(\\frac{2}{3}\\mathbf{a} + \\frac{1}{3}\\mathbf{b}\\right)\\) and \\(\\overrightarrow{OR} = \\mathbf{b} + \\mu\\left(\\frac{1}{2}\\mathbf{a} - \\mathbf{b}\\right)\\)\nM1: equates coefficients: \\(\\frac{2\\lambda}{3} = \\frac{\\mu}{2}\\), \\(\\frac{\\lambda}{3} = 1 - \\mu\\)\nA1: \\(\\lambda = \\frac{3}{5}\\), \\(\\mu = \\frac{4}{5}\\)\nA1: \\(\\overrightarrow{OR} = \\frac{2}{5}\\mathbf{a} + \\frac{1}{5}\\mathbf{b}\\)\n(c)\nM1ft: uses \\(\\overrightarrow{BR} = \\frac{4}{5}\\overrightarrow{BP}\\)\nA1: \\(BR : RP = 4 : 1\\) CAO\nFinal answer: (b) \\(\\frac{2}{5}\\mathbf{a} + \\frac{1}{5}\\mathbf{b}\\) (c) 4 : 1` },
      { q: `A puck of mass 0.5 kg is modelled as a particle on smooth horizontal ice. It starts from rest at the origin \\(O\\) and is acted on by two forces, \\(\\mathbf{F}_1 = (3\\mathbf{i} - \\mathbf{j})\\) N and \\(\\mathbf{F}_2 = (-\\mathbf{i} + 2\\mathbf{j})\\) N, and no others. Distances are in metres.\n\n(a) Find the acceleration of the puck. [2]\n(b) Find the speed of the puck when \\(t = 3\\) seconds. [2]\n(c) At \\(t = 3\\), the force \\(\\mathbf{F}_2\\) is removed and immediately replaced by a force \\(\\mathbf{F}_3\\). The puck then moves with constant velocity. Find \\(\\mathbf{F}_3\\). [2]\n(d) Find the distance of the puck from \\(O\\) when \\(t = 5\\). [3]`, marks: 9, command: 'Find', markScheme: `(a)\nM1: \\(\\mathbf{F}_1 + \\mathbf{F}_2 = 0.5\\mathbf{a}\\), resultant \\((2\\mathbf{i} + \\mathbf{j})\\) N\nA1: \\(\\mathbf{a} = (4\\mathbf{i} + 2\\mathbf{j})\\) m s⁻²\n(b)\nM1ft: \\(\\mathbf{v} = \\mathbf{u} + \\mathbf{a}t = 12\\mathbf{i} + 6\\mathbf{j}\\)\nA1: \\(\\sqrt{180} = 13.4\\) m s⁻¹ AWRT (accept \\(6\\sqrt{5}\\))\n(c)\nM1: resultant must be zero: \\(\\mathbf{F}_1 + \\mathbf{F}_3 = \\mathbf{0}\\)\nA1: \\(\\mathbf{F}_3 = (-3\\mathbf{i} + \\mathbf{j})\\) N\n(d)\nM1: position at \\(t = 3\\): \\(\\frac{1}{2}(4\\mathbf{i} + 2\\mathbf{j})(9) = 18\\mathbf{i} + 9\\mathbf{j}\\)\nM1: adds \\(2(12\\mathbf{i} + 6\\mathbf{j})\\) to give \\(42\\mathbf{i} + 21\\mathbf{j}\\)\nA1: \\(21\\sqrt{5} = 47.0\\) m AWRT\nFinal answer: (a) \\(4\\mathbf{i} + 2\\mathbf{j}\\) (b) 13.4 m s⁻¹ (c) \\(-3\\mathbf{i} + \\mathbf{j}\\) (d) 47.0 m` },
      { q: `A flat solar panel is modelled as the parallelogram \\(ABCD\\). Relative to a fixed origin, with distances in metres, the points \\(A\\), \\(B\\) and \\(C\\) have coordinates \\((1, 0, 2)\\), \\((3, 2, 3)\\) and \\((6, -2, 3)\\) respectively.\n\n(a) Find the coordinates of \\(D\\). [2]\n(b) Show that \\(AB = 3\\) m and find the length \\(BC\\). [2]\n(c) Find the angle \\(ABC\\), giving your answer to the nearest 0.1°. [3]\n(d) Hence find the area of the solar panel. Give your answer in exact form. [3]`, marks: 10, command: 'Find', markScheme: `(a)\nM1: \\(\\overrightarrow{OD} = \\overrightarrow{OA} + \\overrightarrow{BC}\\) with \\(\\overrightarrow{BC} = (3, -4, 0)\\)\nA1: \\(D(4, -4, 2)\\)\n(b)\nB1: \\(\\overrightarrow{AB} = (2, 2, 1)\\), \\(AB = \\sqrt{9} = 3\\) AG\nB1: \\(BC = 5\\)\n(c)\nM1: \\(AC = |(5, -2, 1)| = \\sqrt{30}\\)\nM1: cosine rule \\(\\cos ABC = \\frac{9 + 25 - 30}{2 \\times 3 \\times 5} = \\frac{2}{15}\\)\nA1: 82.3° AWRT\n(d)\nM1: area \\(= AB \\times BC \\times \\sin ABC\\) (or twice the triangle area)\nM1: exact \\(\\sin ABC = \\sqrt{1 - \\frac{4}{225}} = \\frac{\\sqrt{221}}{15}\\)\nA1: \\(\\sqrt{221}\\) m² CAO (≈ 14.9)\nFinal answer: (a) \\(D(4, -4, 2)\\) (b) 5 m (c) 82.3° (d) \\(\\sqrt{221}\\) m²` }
    ]
  },
  '2.1': {
    name: 'Statistics',
    questions: [
      { q: `A car dealership group has a numbered list of the 1800 cars it sold in 2016. A manager wants to take a systematic sample of 60 of these cars to check their service records.\n\nDescribe how the manager should select the sample.`, marks: 2, command: 'Describe', markScheme: `B1 Interval: \\(1800 \\div 60 = 30\\), so select every 30th car on the list\nB1 Start at a randomly chosen number between 1 and 30 (e.g. using a random number generator), then select that car and every 30th car after it\nCondone "random start" without the range if the interval of 30 is clearly used.` },
      { q: `A student is using the Large Data Set to investigate the CO\\(_2\\) emissions, in g/km, of cars in the London region. She plans to calculate the mean CO\\(_2\\) emissions of all the cars in that region, including every propulsion type.\n\nUsing your knowledge of the Large Data Set, explain why she should consider removing the cars whose propulsion type is electric before calculating the mean.`, marks: 2, command: 'Explain', markScheme: `E1 Cars with an electric propulsion type have CO\\(_2\\) emissions recorded as 0 g/km\nE1 Including them would lower the mean, so it would not represent the emissions of cars with petrol or diesel engines\nAccept equivalent reasoning, e.g. electric cars are not relevant to an investigation of exhaust emissions.` },
      { q: `A garage finds that 15% of the cars brought in for an MOT test need at least one new tyre. On one day, 12 cars are brought in for an MOT test. You may assume these 12 cars form a random sample.\n\nFind the probability that exactly 3 of these cars need at least one new tyre.`, marks: 2, command: 'Find', markScheme: `M1 \\(X \\sim \\mathrm{B}(12, 0.15)\\) used: \\(\\binom{12}{3}(0.15)^3(0.85)^9\\)\nA1 0.172 (AWRT)\nFinal answer: 0.172` },
      { q: `The time, \\(T\\) minutes, taken by a mechanic to replace the brake pads on a car is modelled by \\(T \\sim \\mathrm{N}(48, 6^2)\\).\n\nFind the probability that the mechanic takes more than 55 minutes to replace the brake pads on a randomly chosen car.`, marks: 2, command: 'Find', markScheme: `M1 Attempts \\(P(T \\gt 55)\\), e.g. \\(P\\left(Z \\gt \\frac{55-48}{6}\\right) = P(Z \\gt 1.1667)\\)\nA1 0.122 (AWRT 0.122)\nFinal answer: 0.122` },
      { q: `A sample of 25 cars was taken from the Large Data Set. The engine size, \\(x\\) cc, of each car was coded using\n\\[ y = \\frac{x - 1600}{100} \\]\nThe mean of \\(y\\) is 1.36 and the standard deviation of \\(y\\) is 4.05 (data written for this practice question).\n\nFind the mean and the standard deviation of the engine sizes of these 25 cars.`, marks: 3, command: 'Find', markScheme: `M1 Uses \\(\\bar{x} = 100\\bar{y} + 1600\\)\nA1 \\(\\bar{x} = 1736\\) cc CAO\nB1 Standard deviation \\(= 100 \\times 4.05 = 405\\) cc\nFinal answers: mean 1736 cc, standard deviation 405 cc` },
      { q: `The masses, in kg, of a sample of cars were recorded (data written for this practice question). The lower quartile was 1240 kg and the upper quartile was 1520 kg. The lightest car had a mass of 835 kg and the heaviest car had a mass of 1985 kg.\n\nAn outlier is defined as a value that is more than \\(1.5 \\times\\) the interquartile range below the lower quartile or above the upper quartile.\n\nDetermine whether either of the masses 835 kg or 1985 kg is an outlier. Fully justify your answer.`, marks: 3, command: 'Determine', markScheme: `M1 IQR \\(= 1520 - 1240 = 280\\) and \\(1.5 \\times 280 = 420\\) used to find at least one limit\nA1 Limits 820 kg and 1940 kg\nA1 835 kg is not an outlier since \\(835 \\gt 820\\); 1985 kg is an outlier since \\(1985 \\gt 1940\\)` },
      { q: `An MOT test centre recorded the fuel type of 240 cars it tested and whether each car passed at its first test (data written for this practice question).\n\nFuel type | Passed | Failed\nPetrol | 96 | 24\nDiesel | 58 | 32\nHybrid | 26 | 4\n\nOne of these cars is chosen at random.\n\n(a) Find the probability that the car is diesel and failed its first test. [1]\n(b) Given that the car failed its first test, find the probability that it is a hybrid. [2]`, marks: 3, command: 'Find', markScheme: `(a)\nB1 \\(\\frac{32}{240} = \\frac{2}{15}\\) (AWRT 0.133)\n(b)\nM1 Total failed \\(= 24 + 32 + 4 = 60\\) used as denominator\nA1 \\(\\frac{4}{60} = \\frac{1}{15}\\) (AWRT 0.0667)` },
      { q: `An employee of a large company is chosen at random. \\(C\\) is the event that the employee cycles to work and \\(W\\) is the event that the employee works part-time.\n\\(P(C) = 0.4\\), \\(P(W) = 0.35\\) and \\(P(C \\cup W) = 0.61\\)\n\nDetermine whether the events \\(C\\) and \\(W\\) are independent. Fully justify your answer.`, marks: 3, command: 'Determine', markScheme: `M1 \\(P(C \\cap W) = 0.4 + 0.35 - 0.61\\)\nA1 \\(P(C \\cap W) = 0.14\\)\nE1 \\(P(C) \\times P(W) = 0.4 \\times 0.35 = 0.14 = P(C \\cap W)\\), so \\(C\\) and \\(W\\) are independent\nNote: E1 requires both values compared and a conclusion.` },
      { q: `The number of cars, \\(X\\), owned by a randomly chosen household in a village is modelled by the probability distribution\n\\[ P(X = x) = k(5 - x) \\quad \\text{for } x = 1, 2, 3, 4 \\]\nwhere \\(k\\) is a constant.\n\n(a) Show that \\(k = 0.1\\) [1]\n(b) Two households are chosen at random. Find the probability that they own the same number of cars. [2]`, marks: 3, command: 'Show that', markScheme: `(a)\nB1 \\(k(4 + 3 + 2 + 1) = 10k = 1\\), so \\(k = 0.1\\) AG\n(b)\nM1 Probabilities 0.4, 0.3, 0.2, 0.1 used and sum of squares formed: \\(0.4^2 + 0.3^2 + 0.2^2 + 0.1^2\\)\nA1 0.3 CAO` },
      { q: `The time, \\(t\\) minutes, that 80 customers waited at a car wash was recorded (data written for this practice question).\n\nTime, \\(t\\) minutes | Frequency\n\\(0 \\leq t \\lt 5\\) | 12\n\\(5 \\leq t \\lt 10\\) | 30\n\\(10 \\leq t \\lt 15\\) | 24\n\\(15 \\leq t \\lt 25\\) | 14\n\nUse linear interpolation to estimate the median waiting time.`, marks: 3, command: 'Use', markScheme: `M1 Identifies the median as the 40th value, in the class \\(5 \\leq t \\lt 10\\)\nM1 \\(5 + \\frac{40 - 12}{30} \\times 5\\)\nA1 9.67 minutes (AWRT 9.67; accept 9.7 or 9.68 from using 40.5th value)` },
      { q: `A student took a random sample of 30 petrol cars from the Large Data Set. For each car she recorded the engine size, \\(x\\) cc, and the CO\\(_2\\) emissions, \\(y\\) g/km. The engine sizes in her sample ranged from 998 cc to 2498 cc. The equation of the regression line of \\(y\\) on \\(x\\) is\n\\[ y = 62.4 + 0.058x \\]\n(data written for this practice question)\n\n(a) Interpret the value 0.058 in the context of the question. [1]\n(b) Use the regression line to estimate the CO\\(_2\\) emissions of a petrol car with an engine size of 1600 cc. [1]\n(c) Explain why it would not be reliable to use the regression line to estimate the CO\\(_2\\) emissions of a car with an engine size of 4500 cc. [1]`, marks: 3, command: 'Interpret', markScheme: `(a)\nE1 For each 1 cc increase in engine size, CO\\(_2\\) emissions increase by about 0.058 g/km (accept 5.8 g/km per 100 cc)\n(b)\nB1 \\(62.4 + 0.058 \\times 1600 = 155.2\\) g/km (AWRT 155)\n(c)\nE1 4500 cc is outside the range of the data (998 to 2498 cc), so this would be extrapolation` },
      { q: `The lengths, \\(t\\) minutes, of 150 telephone calls to a car insurance helpline were recorded (data written for this practice question).\n\nLength, \\(t\\) minutes | Frequency\n\\(0 \\leq t \\lt 2\\) | 30\n\\(2 \\leq t \\lt 5\\) | 54\n\\(5 \\leq t \\lt 10\\) | 45\n\\(10 \\leq t \\lt 20\\) | 21\n\nThe data are shown on a histogram. The bar for the class \\(0 \\leq t \\lt 2\\) has a height of 7.5 cm.\n\n(a) Find the height of the bar for the class \\(5 \\leq t \\lt 10\\) [2]\n(b) Estimate the number of calls that lasted between 4 and 12 minutes. [2]`, marks: 4, command: 'Find', markScheme: `(a)\nM1 Frequency densities: \\(30 \\div 2 = 15\\) and \\(45 \\div 5 = 9\\), with scale 15 → 7.5 cm (0.5 cm per unit)\nA1 4.5 cm\n(b)\nM1 \\(\\frac{1}{3} \\times 54 + 45 + \\frac{2}{10} \\times 21\\) (i.e. \\(18 + 45 + 4.2\\))\nA1 67 (accept 67.2)` },
      { q: `An analyst took a random sample of cars first registered in 2002 and a random sample of cars first registered in 2016 and recorded their CO\\(_2\\) emissions in g/km (data written for this practice question). The results are summarised below.\n\nYear | Minimum | Lower quartile | Median | Upper quartile | Maximum\n2002 | 128 | 165 | 182 | 204 | 265\n2016 | 92 | 112 | 124 | 139 | 210\n\nCompare the CO\\(_2\\) emissions of cars registered in 2002 with those of cars registered in 2016.`, marks: 4, command: 'Compare', markScheme: `B1 Compares medians: 2016 median (124) is lower than 2002 median (182)\nE1 In context: cars registered in 2016 generally (on average) had lower CO\\(_2\\) emissions\nB1 Compares a measure of spread: IQR for 2016 is 27, IQR for 2002 is 39 (or ranges 118 and 137)\nE1 In context: CO\\(_2\\) emissions of 2016 cars were less varied / more consistent\nE marks require the comparison to be stated in context.` },
      { q: `Records show that 20% of customers at a car service centre also pay for their car to be valeted. A random sample of 25 customers is taken. \\(X\\) is the number of these customers who pay for a valet.\n\n(a) Find \\(P(X \\leq 4)\\) [1]\n(b) Find the probability that between 3 and 8 inclusive of these customers pay for a valet. [2]\n(c) Find the mean of \\(X\\). [1]`, marks: 4, command: 'Find', markScheme: `(a)\nB1 \\(X \\sim \\mathrm{B}(25, 0.2)\\): \\(P(X \\leq 4) = 0.421\\) (AWRT 0.421)\n(b)\nM1 \\(P(3 \\leq X \\leq 8) = P(X \\leq 8) - P(X \\leq 2)\\)\nA1 0.855 (AWRT 0.855)\n(c)\nB1 \\(25 \\times 0.2 = 5\\)` },
      { q: `At a test centre, 60% of the cars tested run on petrol and the rest run on diesel. The probability that a petrol car fails its emissions test is 0.18. The probability that a diesel car fails its emissions test is 0.25. A car is chosen at random from those tested.\n\n(a) Find the probability that the car fails its emissions test. [2]\n(b) Given that the car fails its emissions test, find the probability that it runs on diesel. [2]`, marks: 4, command: 'Find', markScheme: `(a)\nM1 \\(0.6 \\times 0.18 + 0.4 \\times 0.25\\)\nA1 0.208\n(b)\nM1 \\(\\frac{0.4 \\times 0.25}{\\text{their } 0.208}\\)\nA1 0.481 (AWRT 0.481; accept \\(\\frac{25}{52}\\))` },
      { q: `The mass, \\(M\\) kg, of a bag of cement filled by a machine is modelled by \\(M \\sim \\mathrm{N}(25, \\sigma^2)\\). It is known that 3% of bags have a mass of less than 24.5 kg.\n\n(a) Find the value of \\(\\sigma\\). [3]\n(b) Find the probability that a randomly chosen bag has a mass of more than 25.3 kg. [1]`, marks: 4, command: 'Find', markScheme: `(a)\nB1 \\(z = -1.8808\\) (AWRT \\(\\pm 1.881\\))\nM1 \\(\\frac{24.5 - 25}{\\sigma} = -1.8808\\)\nA1 \\(\\sigma = 0.266\\) (AWRT 0.266)\n(b)\nB1ft \\(P(M \\gt 25.3) = 0.130\\) (AWRT 0.13)` },
      { q: `A café owner records, on each of 15 randomly chosen days, the maximum temperature and the number of cold drinks sold. The product moment correlation coefficient between these two variables is 0.512 (data written for this practice question).\n\nThe critical value for a one-tailed test at the 5% level of significance for a sample of size 15 is 0.4409.\n\nTest, at the 5% level of significance, whether there is positive correlation between the maximum temperature and the number of cold drinks sold.`, marks: 4, command: 'Test', markScheme: `B1 \\(\\mathrm{H}_0: \\rho = 0\\), \\(\\mathrm{H}_1: \\rho \\gt 0\\), where \\(\\rho\\) is the population correlation coefficient between maximum temperature and cold drinks sold\nM1 Compares 0.512 with 0.4409\nA1 \\(0.512 \\gt 0.4409\\), so reject \\(\\mathrm{H}_0\\)\nE1 There is sufficient evidence, at the 5% level, to suggest that there is positive correlation between maximum temperature and the number of cold drinks sold\nNote: E1 requires a conclusion in context that is not stated with certainty.` },
      { q: `The masses, \\(x\\) kg, of a random sample of 20 cars were recorded and summarised as\n\\[ \\sum x = 26\\,840 \\qquad \\sum x^2 = 36\\,703\\,780 \\]\n(data written for this practice question)\n\n(a) Find the mean and the standard deviation of the masses. [2]\n(b) An outlier is defined as a value more than two standard deviations from the mean. One of the cars in the sample has a mass of 1755 kg. Determine whether this mass is an outlier. [2]`, marks: 4, command: 'Find', markScheme: `(a)\nB1 Mean \\(= 26\\,840 \\div 20 = 1342\\) kg\nB1 Standard deviation \\(= \\sqrt{\\frac{36\\,703\\,780}{20} - 1342^2} = 185\\) kg (accept 190, AWRT 189.8, using divisor 19)\n(b)\nM1 \\(1342 + 2 \\times 185 = 1712\\) (or 1721.6)\nA1 \\(1755 \\gt 1712\\), so 1755 kg is an outlier` },
      { q: `A survey of 120 drivers asked whether their car has a dash cam \\((D)\\), parking sensors \\((P)\\) and satellite navigation \\((S)\\) (data written for this practice question).\n\n42 have a dash cam, 61 have parking sensors and 55 have satellite navigation.\n20 have a dash cam and parking sensors; 15 have a dash cam and satellite navigation; 30 have parking sensors and satellite navigation.\n8 have all three.\n\n(a) Find the number of drivers whose car has none of these features. [2]\n(b) A driver whose car has exactly two of these features is chosen at random. Find the probability that the car has satellite navigation. [2]`, marks: 4, command: 'Find', markScheme: `(a)\nM1 Correct Venn regions or inclusion-exclusion: \\(42 + 61 + 55 - 20 - 15 - 30 + 8 = 101\\)\nA1 \\(120 - 101 = 19\\)\n(b)\nM1 Exactly two: \\(12 + 7 + 22 = 41\\)\nA1 \\(\\frac{7 + 22}{41} = \\frac{29}{41}\\) (AWRT 0.707)` },
      { q: `In the past, 35% of customers at a motorway service station café ordered a hot drink. After a price increase, the manager believes that the proportion of customers ordering a hot drink has decreased. In a random sample of 30 customers, 5 ordered a hot drink.\n\nInvestigate the manager's belief, using a 5% level of significance.`, marks: 5, command: 'Investigate', markScheme: `B1 \\(\\mathrm{H}_0: p = 0.35\\), \\(\\mathrm{H}_1: p \\lt 0.35\\), where \\(p\\) is the proportion of customers who order a hot drink\nM1 Under \\(\\mathrm{H}_0\\), \\(X \\sim \\mathrm{B}(30, 0.35)\\)\nA1 \\(P(X \\leq 5) = 0.0233\\) (AWRT 0.0233) (or critical region \\(X \\leq 5\\) with \\(P(X \\leq 6) = 0.0586\\))\nM1 Compares \\(0.0233 \\lt 0.05\\), so reject \\(\\mathrm{H}_0\\)\nA1 There is sufficient evidence at the 5% level to support the manager's belief that the proportion of customers ordering a hot drink has decreased` },
      { q: `The lifetime, \\(X\\) hours, of a type of car headlamp bulb is normally distributed with standard deviation 12 hours. The manufacturer claims that the mean lifetime is 150 hours. A consumer group suspects that the mean lifetime is less than 150 hours. A random sample of 20 bulbs has a mean lifetime of 145.2 hours.\n\nTest the consumer group's suspicion at the 5% level of significance.`, marks: 5, command: 'Test', markScheme: `B1 \\(\\mathrm{H}_0: \\mu = 150\\), \\(\\mathrm{H}_1: \\mu \\lt 150\\), where \\(\\mu\\) is the mean lifetime of all bulbs of this type\nM1 Under \\(\\mathrm{H}_0\\), \\(\\bar{X} \\sim \\mathrm{N}\\left(150, \\frac{12^2}{20}\\right)\\)\nA1 \\(P(\\bar{X} \\leq 145.2) = 0.0368\\) (AWRT 0.0368) or \\(z = -1.789\\) compared with \\(-1.645\\)\nM1 \\(0.0368 \\lt 0.05\\), so reject \\(\\mathrm{H}_0\\)\nA1 There is sufficient evidence at the 5% level to suggest that the mean lifetime of the bulbs is less than 150 hours` },
      { q: `A car owners' club has 1250 members living in four regions: 400 in London, 325 in the North West, 275 in the South West and 250 in Scotland. The club wants to survey a sample of 50 members.\n\n(a) A stratified sample by region is to be taken. Calculate the number of members to be chosen from each region. [2]\n(b) Describe how the members from London could then be selected. [2]\n(c) The club secretary suggests instead surveying the first 50 members to arrive at the next club meeting. Give one reason why the stratified sample is likely to be better. [1]`, marks: 5, command: 'Calculate', markScheme: `(a)\nM1 \\(\\frac{400}{1250} \\times 50\\) or equivalent for any region\nA1 London 16, North West 13, South West 11, Scotland 10\n(b)\nB1 Number the London members 1 to 400 (use a list as a sampling frame)\nB1 Use a random number generator to select 16 different numbers, ignoring repeats\n(c)\nE1 The opportunity sample may not be representative, e.g. members who attend meetings may live nearby / one region would be over-represented; stratified sampling ensures each region is represented in proportion` },
      { q: `A car dealership finds that 40% of the cars it sells are bought using a finance agreement. In one month the dealership sells 150 cars. \\(X\\) is the number of these cars bought using a finance agreement.\n\n(a) Explain why a normal distribution can be used to approximate the distribution of \\(X\\). [1]\n(b) Using a suitable normal approximation, find the probability that more than 65 of these cars are bought using a finance agreement. [4]`, marks: 5, command: 'Find', markScheme: `(a)\nE1 \\(n\\) is large and \\(p\\) is close to 0.5 (or \\(np = 60\\) and \\(n(1-p) = 90\\) are both greater than 5)\n(b)\nB1 Mean \\(= 150 \\times 0.4 = 60\\)\nB1 Variance \\(= 150 \\times 0.4 \\times 0.6 = 36\\), so \\(Y \\sim \\mathrm{N}(60, 6^2)\\)\nM1 Continuity correction: \\(P(Y \\gt 65.5)\\)\nA1 0.180 (AWRT 0.180)\nNote: exact binomial gives 0.179 and scores M0 A0 for the last two marks.` },
      { q: `The masses, \\(m\\) kg, of a sample of 120 cars are summarised in the cumulative frequency table below (data written for this practice question).\n\nMass, \\(m\\) kg | Cumulative frequency\n\\(m \\lt 1000\\) | 9\n\\(m \\lt 1200\\) | 33\n\\(m \\lt 1400\\) | 72\n\\(m \\lt 1600\\) | 101\n\\(m \\lt 2000\\) | 120\n\n(a) Use linear interpolation to estimate the median mass. [2]\n(b) Use linear interpolation to estimate the interquartile range of the masses. [3]`, marks: 5, command: 'Use', markScheme: `(a)\nM1 \\(1200 + \\frac{60 - 33}{39} \\times 200\\)\nA1 1338 kg (AWRT 1340)\n(b)\nM1 Lower quartile: \\(1000 + \\frac{30 - 9}{24} \\times 200 = 1175\\)\nM1 Upper quartile: \\(1400 + \\frac{90 - 72}{29} \\times 200 = 1524.1\\)\nA1 IQR \\(= 349\\) kg (AWRT 349; accept 350)` },
      { q: `A household in a town is chosen at random. \\(A\\) is the event that the household owns a dog and \\(B\\) is the event that the household owns a cat.\n\\(P(A) = 0.45\\), \\(P(B) = 0.3\\) and \\(P(A \\cap B') = 0.33\\)\n\n(a) Find \\(P(A \\cap B)\\) [1]\n(b) Find the probability that the household owns neither a dog nor a cat. [2]\n(c) Given that the household owns a dog, find the probability that it also owns a cat. [2]`, marks: 5, command: 'Find', markScheme: `(a)\nB1 \\(0.45 - 0.33 = 0.12\\)\n(b)\nM1 \\(P(A \\cup B) = 0.45 + 0.3 - 0.12 = 0.63\\)\nA1 \\(1 - 0.63 = 0.37\\)\n(c)\nM1 \\(P(B \\mid A) = \\frac{0.12}{0.45}\\)\nA1 \\(\\frac{4}{15}\\) (AWRT 0.267)` },
      { q: `The time, \\(T\\) minutes, taken by candidates to complete a driving theory practice test is modelled by \\(T \\sim \\mathrm{N}(\\mu, \\sigma^2)\\). It is found that 10% of candidates take longer than 30 minutes and 25% of candidates take less than 18 minutes.\n\nFind the values of \\(\\mu\\) and \\(\\sigma\\).`, marks: 5, command: 'Find', markScheme: `B1 \\(z = 1.2816\\) and \\(z = -0.6745\\) (AWRT 1.28 and \\(-0.674\\))\nM1 \\(\\frac{30 - \\mu}{\\sigma} = 1.2816\\) or \\(\\frac{18 - \\mu}{\\sigma} = -0.6745\\)\nM1 Forms both equations and solves simultaneously\nA1 \\(\\sigma = 6.13\\) (AWRT 6.13)\nA1 \\(\\mu = 22.1\\) (AWRT 22.1)` },
      { q: `Records show that 20% of students at a large college walk to college. The college introduces a cycle-to-college scheme and the principal wants to know whether the proportion of students who walk to college has changed. A random sample of 40 students is taken.\n\n(a) Using a 10% level of significance, find the critical region for a two-tailed test of whether the proportion of students who walk to college has changed. The probability in each tail should be as close as possible to, but not exceed, 5%. [4]\n(b) In the sample, 3 students walk to college. Complete the test, stating your conclusion in context. [2]`, marks: 6, command: 'Find', markScheme: `(a)\nB1 \\(\\mathrm{H}_0: p = 0.2\\), \\(\\mathrm{H}_1: p \\neq 0.2\\), where \\(p\\) is the proportion of students who walk to college\nM1 \\(X \\sim \\mathrm{B}(40, 0.2)\\) and considers tail probabilities, e.g. \\(P(X \\leq 3) = 0.0285\\) or \\(P(X \\geq 13) = 0.0432\\)\nA1 Lower tail \\(X \\leq 3\\) (since \\(P(X \\leq 4) = 0.0759\\))\nA1 Upper tail \\(X \\geq 13\\) (since \\(P(X \\geq 12) = 0.0875\\)); critical region \\(X \\leq 3\\) or \\(X \\geq 13\\)\n(b)\nM1ft 3 lies in the critical region, so reject \\(\\mathrm{H}_0\\)\nA1 There is sufficient evidence at the 10% level to suggest that the proportion of students who walk to college has changed` },
      { q: `A machine makes bolts for car wheels. The diameters, \\(D\\) mm, of the bolts are normally distributed with standard deviation 0.15 mm. The bolts are designed to have a mean diameter of 8.00 mm. A quality controller takes a random sample of 25 bolts and finds that their mean diameter is 8.062 mm.\n\n(a) Test, at the 5% level of significance, whether the mean diameter of the bolts differs from 8.00 mm. [5]\n(b) State one assumption you have made about the standard deviation in carrying out this test. [1]`, marks: 6, command: 'Test', markScheme: `(a)\nB1 \\(\\mathrm{H}_0: \\mu = 8.00\\), \\(\\mathrm{H}_1: \\mu \\neq 8.00\\), where \\(\\mu\\) is the mean diameter of all bolts made by the machine\nM1 Under \\(\\mathrm{H}_0\\), \\(\\bar{D} \\sim \\mathrm{N}\\left(8, \\frac{0.15^2}{25}\\right)\\), i.e. standard error 0.03\nA1 \\(P(\\bar{D} \\geq 8.062) = 0.0194\\) (AWRT 0.0194) or \\(z = 2.067\\) compared with 1.960\nM1 Compares \\(0.0194 \\lt 0.025\\) (or \\(2.067 \\gt 1.960\\)), so reject \\(\\mathrm{H}_0\\)\nA1 There is sufficient evidence at the 5% level to suggest that the mean diameter of the bolts differs from 8.00 mm\n(b)\nB1 The standard deviation of the diameters is still 0.15 mm (it has not changed even if the mean has)` },
      { q: `A student uses the Large Data Set to investigate whether heavier cars tend to have higher CO\\(_2\\) emissions. She takes a random sample of 40 diesel cars registered in 2016 and finds that the product moment correlation coefficient between mass and CO\\(_2\\) emissions is 0.62 (data written for this practice question).\n\nThe critical value for a one-tailed test at the 1% level of significance for a sample of size 40 is 0.3665.\n\n(a) Test, at the 1% level of significance, whether there is positive correlation between mass and CO\\(_2\\) emissions for diesel cars registered in 2016. [4]\n(b) The student concludes that "increasing the mass of a car causes its CO\\(_2\\) emissions to increase". Comment on her conclusion. [1]\n(c) Explain why her result may not apply to petrol cars. [1]`, marks: 6, command: 'Test', markScheme: `(a)\nB1 \\(\\mathrm{H}_0: \\rho = 0\\), \\(\\mathrm{H}_1: \\rho \\gt 0\\), where \\(\\rho\\) is the population correlation coefficient between mass and CO\\(_2\\) emissions for 2016 diesel cars\nM1 Compares 0.62 with 0.3665\nA1 \\(0.62 \\gt 0.3665\\), so reject \\(\\mathrm{H}_0\\)\nE1 There is sufficient evidence at the 1% level to suggest positive correlation between mass and CO\\(_2\\) emissions for diesel cars registered in 2016\n(b)\nE1 Correlation does not imply causation; e.g. heavier cars tend to have larger engines, which may be the cause\n(c)\nE1 The sample contained only diesel cars, so it may not be representative of petrol cars (whose relationship may differ)` },
      { q: `Sam travels to work by one of three routes, \\(A\\), \\(B\\) or \\(C\\). On any day, the probabilities that Sam uses routes \\(A\\), \\(B\\) and \\(C\\) are 0.5, 0.3 and 0.2 respectively. The probabilities that Sam arrives late using routes \\(A\\), \\(B\\) and \\(C\\) are 0.1, 0.15 and 0.3 respectively.\n\n(a) Find the probability that, on a randomly chosen day, Sam arrives late. [2]\n(b) Given that Sam arrives late, find the probability that Sam used route \\(C\\). [2]\n(c) Find the probability that, on two randomly chosen days, Sam arrives late on exactly one of the days. State an assumption you have made. [2]`, marks: 6, command: 'Find', markScheme: `(a)\nM1 \\(0.5 \\times 0.1 + 0.3 \\times 0.15 + 0.2 \\times 0.3\\)\nA1 0.155\n(b)\nM1 \\(\\frac{0.2 \\times 0.3}{\\text{their } 0.155}\\)\nA1 \\(\\frac{12}{31}\\) (AWRT 0.387)\n(c)\nM1 \\(2 \\times 0.155 \\times 0.845\\)\nA1 0.262 (AWRT 0.262) with assumption that whether Sam is late on one day is independent of the other day` },
      { q: `The distances, \\(d\\) miles, driven on one day by 60 taxi drivers in a city are summarised below (data written for this practice question).\n\nDistance, \\(d\\) miles | Frequency\n\\(0 \\leq d \\lt 40\\) | 8\n\\(40 \\leq d \\lt 80\\) | 18\n\\(80 \\leq d \\lt 120\\) | 22\n\\(120 \\leq d \\lt 200\\) | 12\n\n(a) Calculate estimates of the mean and the standard deviation of the distances. [4]\n(b) Explain why your answers to (a) are estimates. [1]\n(c) A 61st driver drove 89 miles on the same day. Without further calculation, state the effect of including this driver on the standard deviation. Give a reason. [1]`, marks: 6, command: 'Calculate', markScheme: `(a)\nM1 Midpoints 20, 60, 100, 160 used with frequencies: \\(\\sum fx = 5360\\)\nA1 Mean \\(= 89.3\\) miles (AWRT 89.3)\nM1 \\(\\sum fx^2 = 595\\,200\\) used in \\(\\sqrt{\\frac{595\\,200}{60} - 89.33^2}\\)\nA1 Standard deviation \\(= 44.0\\) miles (AWRT 44.0; accept 44.4 using divisor 59)\n(b)\nE1 The original data values are not known; midpoints are used to represent each class\n(c)\nE1 The standard deviation decreases, because 89 is very close to the mean so the data become less spread out on average` },
      { q: `An analyst took a random sample of 50 cars registered in 2002 and a random sample of 50 cars registered in 2016 from the Large Data Set and calculated the following summary statistics for their CO\\(_2\\) emissions (data written for this practice question).\n\nYear | Mean (g/km) | Standard deviation (g/km)\n2002 | 182.4 | 31.6\n2016 | 121.8 | 26.9\n\n(a) Compare the CO\\(_2\\) emissions of the cars in the two samples. [2]\n(b) The analyst models the CO\\(_2\\) emissions of a randomly chosen 2016 car as \\(\\mathrm{N}(121.8, 26.9^2)\\). Use this model to find the probability that a 2016 car has CO\\(_2\\) emissions greater than 150 g/km. [2]\n(c) Using your knowledge of the Large Data Set, explain why this normal model may not be suitable for all cars registered in 2016. [2]`, marks: 6, command: 'Compare', markScheme: `(a)\nB1 Mean CO\\(_2\\) emissions were lower in 2016 (121.8) than in 2002 (182.4), so on average 2016 cars emitted less CO\\(_2\\)\nB1 Standard deviation lower in 2016, so 2016 emissions were less spread out / more consistent\n(b)\nM1 \\(P\\left(Z \\gt \\frac{150 - 121.8}{26.9}\\right) = P(Z \\gt 1.048)\\)\nA1 0.147 (AWRT 0.147)\n(c)\nB1 The data set includes electric cars, recorded with 0 g/km, and hybrid cars with very low values\nE1 So the distribution is unlikely to be symmetrical / bell-shaped (there is a cluster at 0), whereas the normal model would allow such values only with negligible probability` },
      { q: `A grower weighs 500 apples. A histogram of the masses is roughly symmetrical and bell-shaped, and the masses range from 92 g to 188 g (data written for this practice question).\n\n(a) Explain why a normal distribution may be a suitable model for the mass, \\(X\\) grams, of an apple, and use the information to suggest suitable values for the mean and standard deviation of the model. [3]\n(b) The grower models \\(X\\) as \\(\\mathrm{N}(140, 16^2)\\). Find \\(P(130 \\lt X \\lt 150)\\) [2]\n(c) Apples heavier than \\(w\\) grams are sold as "extra large". The grower wants 5% of apples to be sold as extra large. Using the model in (b), find the value of \\(w\\). [2]`, marks: 7, command: 'Explain', markScheme: `(a)\nE1 The histogram is symmetrical and bell-shaped, as for a normal distribution\nB1 Mean \\(\\approx \\frac{92 + 188}{2} = 140\\) g\nB1 Standard deviation \\(\\approx \\frac{188 - 92}{6} = 16\\) g (almost all data lie within 3 standard deviations of the mean)\n(b)\nM1 \\(P(-0.625 \\lt Z \\lt 0.625)\\) or direct calculator use\nA1 0.468 (AWRT 0.468)\n(c)\nM1 \\(\\frac{w - 140}{16} = 1.6449\\)\nA1 \\(w = 166\\) (AWRT 166.3)` },
      { q: `A packet contains 20 seeds. The manufacturer states that 85% of its seeds germinate. \\(X\\) is the number of seeds in a packet that germinate.\n\n(a) State two assumptions needed for \\(X\\) to be modelled by \\(\\mathrm{B}(20, 0.85)\\), in the context of the question. [2]\n(b) Using this model, find the probability that at least 18 seeds in a packet germinate. [2]\n(c) A gardener buys 6 packets. Find the probability that exactly 2 of these packets contain at least 18 seeds that germinate. [3]`, marks: 7, command: 'Find', markScheme: `(a)\nB1 Whether a seed germinates is independent of whether any other seed germinates\nB1 The probability that each seed germinates is constant (0.85)\n(b)\nM1 \\(P(X \\geq 18) = 1 - P(X \\leq 17)\\)\nA1 0.405 (AWRT 0.405)\n(c)\nM1 \\(Y \\sim \\mathrm{B}(6, \\text{their } 0.405)\\)\nM1 \\(\\binom{6}{2}(0.405)^2(0.595)^4\\)\nA1 0.308 (AWRT 0.308)` },
      { q: `Nationally, 60% of learner drivers pass their practical driving test at the first attempt. A driving school claims that its pupils are more likely than this to pass at the first attempt. A random sample of 25 of the school's pupils is taken.\n\n(a) Using a 5% level of significance, find the critical region for a test of the driving school's claim. [4]\n(b) State the actual significance level of this test. [1]\n(c) In the sample, 19 pupils passed at the first attempt. Complete the test, stating your conclusion in context. [2]`, marks: 7, command: 'Find', markScheme: `(a)\nB1 \\(\\mathrm{H}_0: p = 0.6\\), \\(\\mathrm{H}_1: p \\gt 0.6\\), where \\(p\\) is the proportion of the school's pupils who pass at the first attempt\nM1 \\(X \\sim \\mathrm{B}(25, 0.6)\\)\nM1 Considers \\(P(X \\geq 20) = 0.0294\\) and \\(P(X \\geq 19) = 0.0736\\)\nA1 Critical region \\(X \\geq 20\\)\n(b)\nB1 0.0294, i.e. 2.94% (AWRT)\n(c)\nM1ft 19 is not in the critical region, so do not reject \\(\\mathrm{H}_0\\)\nA1 There is insufficient evidence at the 5% level to support the driving school's claim that its pupils are more likely to pass at the first attempt` },
      { q: `Each morning, Priya takes a train and then a bus to work. On any morning, the probability that the train is late is \\(p\\) and the probability that the bus is late is \\(p + 0.2\\). Whether the train is late is independent of whether the bus is late. The probability that at least one of them is late is 0.65.\n\n(a) Show that \\(p^2 - 1.8p + 0.45 = 0\\) [3]\n(b) Hence find the value of \\(p\\). Fully justify your answer. [2]\n(c) Find the probability that exactly one of the train and the bus is late on a randomly chosen morning. [2]`, marks: 7, command: 'Show that', markScheme: `(a)\nM1 Uses independence: \\(P(\\text{neither late}) = (1 - p)(0.8 - p)\\) or \\(P(T \\cap B) = p(p + 0.2)\\)\nM1 Forms equation: \\(1 - (1 - p)(0.8 - p) = 0.65\\) or \\(p + (p + 0.2) - p(p + 0.2) = 0.65\\)\nA1 Expands and rearranges convincingly to \\(p^2 - 1.8p + 0.45 = 0\\) AG\n(b)\nM1 Solves: \\(p = 0.3\\) or \\(p = 1.5\\)\nA1 \\(p = 0.3\\), rejecting 1.5 because a probability cannot exceed 1\n(c)\nM1 \\(0.3 \\times 0.5 + 0.7 \\times 0.5\\)\nA1 0.5` },
      { q: `A machine fills cans of fizzy drink. The volume, \\(V\\) ml, of drink in a can is modelled by \\(V \\sim \\mathrm{N}(330, 4^2)\\). Cans containing less than 325 ml are rejected.\n\n(a) Find the probability that a randomly chosen can is rejected. [2]\n(b) Cans are packed in boxes of 24. Find the probability that a randomly chosen box contains more than 2 cans that would be rejected. State an assumption you have made. [3]\n(c) The machine is adjusted so that the mean volume is \\(\\mu\\) ml, the standard deviation remains 4 ml, and only 1% of cans are rejected. Find the value of \\(\\mu\\). [3]`, marks: 8, command: 'Find', markScheme: `(a)\nM1 \\(P(V \\lt 325) = P(Z \\lt -1.25)\\)\nA1 0.106 (AWRT 0.106)\n(b)\nM1 \\(R \\sim \\mathrm{B}(24, \\text{their } 0.106)\\) and \\(P(R \\gt 2) = 1 - P(R \\leq 2)\\)\nA1 0.473 (AWRT 0.473)\nB1 Assumption: the volumes in different cans are independent\n(c)\nB1 \\(z = -2.3263\\) (AWRT \\(\\pm 2.326\\))\nM1 \\(\\frac{325 - \\mu}{4} = -2.3263\\)\nA1 \\(\\mu = 334.3\\) ml (AWRT 334)` },
      { q: `A student takes a random sample of 120 petrol cars from the Large Data Set and records their CO\\(_2\\) emissions, \\(c\\) g/km. Her results are summarised below (data written for this practice question).\n\nCO\\(_2\\) emissions, \\(c\\) g/km | Frequency\n\\(80 \\leq c \\lt 100\\) | 6\n\\(100 \\leq c \\lt 110\\) | 18\n\\(110 \\leq c \\lt 120\\) | 30\n\\(120 \\leq c \\lt 140\\) | 38\n\\(140 \\leq c \\lt 180\\) | 22\n\\(180 \\leq c \\lt 240\\) | 6\n\n(a) The data are shown on a histogram. The bar for the class \\(110 \\leq c \\lt 120\\) has a height of 6 cm. Find the height of the bar for the class \\(140 \\leq c \\lt 180\\) [2]\n(b) Calculate estimates of the mean and the standard deviation of the CO\\(_2\\) emissions. [3]\n(c) Use linear interpolation to estimate the median. [2]\n(d) Use your answers to (b) and (c) to describe the skewness of the distribution. [1]`, marks: 8, command: 'Calculate', markScheme: `(a)\nM1 Frequency densities 3.0 and 0.55, giving a scale of 2 cm per unit of frequency density\nA1 1.1 cm\n(b)\nM1 Midpoints 90, 105, 115, 130, 160, 210 with \\(\\sum fx = 15\\,600\\)\nA1 Mean \\(= 130\\) g/km\nA1 Standard deviation \\(= 26.7\\) g/km (AWRT 26.7; accept 26.9 using divisor 119)\n(c)\nM1 60th value in \\(120 \\leq c \\lt 140\\): \\(120 + \\frac{60 - 54}{38} \\times 20\\)\nA1 123 g/km (AWRT 123)\n(d)\nE1ft Mean (130) is greater than median (123), so the distribution has positive skew` },
      { q: `A supermarket sells eggs in boxes of 12. Records show that 8% of the eggs delivered by its current supplier are cracked. You may assume that cracked eggs occur independently and at random.\n\n(a) Find the probability that a randomly chosen box contains no cracked eggs. [1]\n(b) Find the probability that a randomly chosen box contains more than 2 cracked eggs. [2]\n(c) The supermarket changes to a new supplier. The manager believes that the proportion of cracked eggs from the new supplier is lower than 8%. In a random sample of 60 eggs from the new supplier, 1 egg is cracked.\nTest the manager's belief at the 5% level of significance. [5]\n(d) Explain why, in carrying out the test in (c), you should calculate \\(P(X \\leq 1)\\) rather than \\(P(X = 1)\\). [1]`, marks: 9, command: 'Test', markScheme: `(a)\nB1 \\(0.92^{12} = 0.368\\) (AWRT 0.368)\n(b)\nM1 \\(1 - P(X \\leq 2)\\) with \\(X \\sim \\mathrm{B}(12, 0.08)\\)\nA1 0.0652 (AWRT 0.0652)\n(c)\nB1 \\(\\mathrm{H}_0: p = 0.08\\), \\(\\mathrm{H}_1: p \\lt 0.08\\), where \\(p\\) is the proportion of eggs from the new supplier that are cracked\nM1 Under \\(\\mathrm{H}_0\\), \\(X \\sim \\mathrm{B}(60, 0.08)\\)\nA1 \\(P(X \\leq 1) = 0.0418\\) (AWRT 0.0418)\nM1 \\(0.0418 \\lt 0.05\\), so reject \\(\\mathrm{H}_0\\)\nA1 There is sufficient evidence at the 5% level to support the manager's belief that the proportion of cracked eggs from the new supplier is lower than 8%\n(d)\nE1 The test needs the probability of a result as extreme as, or more extreme than, the one observed, i.e. 1 or fewer cracked eggs` },
      { q: `A student uses the Large Data Set to investigate the relationship between engine size, \\(x\\) cc, and CO\\(_2\\) emissions, \\(y\\) g/km, for cars registered in 2016. She selects 9 cars at random. Her values are shown below (data written for this practice question).\n\n\\(x\\) | 998 | 1198 | 1395 | 0 | 1499 | 1598 | 1968 | 1995 | 2179\n\\(y\\) | 104 | 112 | 129 | 0 | 118 | 139 | 149 | 158 | 171\n\n(a) Using your knowledge of the Large Data Set, suggest a reason why one car has \\(x = 0\\) and \\(y = 0\\), and explain what the student should do with this car's values in her investigation. [2]\n(b) After dealing with this car appropriately, calculate the product moment correlation coefficient between \\(x\\) and \\(y\\) for the remaining 8 cars. [1]\n(c) The critical value for a one-tailed test at the 5% level of significance for a sample of size 8 is 0.6215.\nTest, at the 5% level of significance, whether there is positive correlation between engine size and CO\\(_2\\) emissions for cars registered in 2016. [4]\n(d) Find the equation of the regression line of \\(y\\) on \\(x\\) for the 8 cars. [2]\n(e) Use your regression line to estimate the CO\\(_2\\) emissions of a car with an engine size of 1400 cc, and comment on the reliability of your estimate. [1]`, marks: 10, command: 'Test', markScheme: `(a)\nB1 The car is electric, so it has no engine size recorded and zero CO\\(_2\\) emissions\nE1 It should be removed (cleaned from the data) because it does not fit an investigation of engine size and emissions / would distort the correlation\n(b)\nB1 \\(r = 0.969\\) (AWRT 0.969)\n(c)\nB1 \\(\\mathrm{H}_0: \\rho = 0\\), \\(\\mathrm{H}_1: \\rho \\gt 0\\), where \\(\\rho\\) is the population correlation coefficient between engine size and CO\\(_2\\) emissions for 2016 cars\nM1 Compares their \\(r\\) with 0.6215\nA1ft \\(0.969 \\gt 0.6215\\), so reject \\(\\mathrm{H}_0\\)\nE1 There is sufficient evidence at the 5% level to suggest positive correlation between engine size and CO\\(_2\\) emissions for cars registered in 2016\n(d)\nM1 Calculator use for the regression line of \\(y\\) on \\(x\\) (gradient or intercept correct)\nA1 \\(y = 47.1 + 0.0548x\\) (AWRT 47.1 and 0.0548)\n(e)\nB1 124 g/km (AWRT 124), reliable because 1400 cc is within the range of the data (interpolation) and the correlation is strong` }
    ]
  },
  '2.2': {
    name: 'Mechanics',
    questions: [
      { q: `A cyclist moving at speed \\(v\\) m s⁻¹ experiences a resistance force of magnitude \\(kv^2\\) newtons, where \\(k\\) is a constant.\n\nFind the units of \\(k\\), giving your answer in terms of SI base units.`, marks: 2, command: 'Find', markScheme: `M1: Uses newton = kg m s⁻² and \\(k = \\frac{F}{v^2}\\), giving units \\(\\frac{\\text{kg m s}^{-2}}{\\text{m}^2\\text{ s}^{-2}}\\)\nA1: kg m⁻¹ CAO\nFinal answer: kg m⁻¹` },
      { q: `A particle of mass 4 kg is acted on by two forces, \\((3\\mathbf{i} - 2\\mathbf{j})\\) N and \\((5\\mathbf{i} + 8\\mathbf{j})\\) N, and no other forces.\n\nFind the acceleration of the particle, giving your answer in vector form.`, marks: 2, command: 'Find', markScheme: `M1: Adds the forces to get resultant \\((8\\mathbf{i} + 6\\mathbf{j})\\) N and uses \\(\\mathbf{F} = m\\mathbf{a}\\)\nA1: \\(\\mathbf{a} = (2\\mathbf{i} + 1.5\\mathbf{j})\\) m s⁻² CAO\nFinal answer: \\((2\\mathbf{i} + 1.5\\mathbf{j})\\) m s⁻²` },
      { q: `A car travels along a straight horizontal road. It passes a point A with speed 4 m s⁻¹ and accelerates uniformly, reaching a speed of 22 m s⁻¹ six seconds later.\n\nFind the distance the car travels in these six seconds.`, marks: 2, command: 'Find', markScheme: `M1: Uses \\(s = \\frac{1}{2}(u+v)t\\) with \\(u = 4\\), \\(v = 22\\), \\(t = 6\\) (or a full equivalent suvat method)\nA1: 78 m CAO\nFinal answer: 78 m` },
      { q: `A crate is lowered vertically from a crane by a cable. In a model of the situation, the cable is modelled as a light inextensible string.\n\nExplain what is meant by the terms "light" and "inextensible" in this context.`, marks: 2, command: 'Explain', markScheme: `B1: Light: the mass of the cable is negligible (ignored), so the tension is the same throughout the cable\nB1: Inextensible: the cable does not stretch, so the crate and the end of the cable have the same speed and acceleration\nCondone "has no mass" for light; must be in context of the cable/crate` },
      { q: `A ball is thrown vertically upwards with speed 14.7 m s⁻¹ from a point on horizontal ground.\n\n(a) Find the greatest height above the ground reached by the ball. [2]\n\n(b) State one modelling assumption you have used in answering (a). [1]`, marks: 3, command: 'Find', markScheme: `(a)\nM1: Uses \\(v^2 = u^2 + 2as\\) with \\(v = 0\\), \\(u = 14.7\\), \\(a = -9.8\\)\nA1: \\(s = \\frac{14.7^2}{19.6} = 11.025\\), AWRT 11.0 m\n(b)\nB1: Any one of: no air resistance; ball modelled as a particle; g constant at 9.8 m s⁻²; ball thrown from ground level\nFinal answer: 11.0 m (3 s.f.)` },
      { q: `A particle moves in a straight line. At time \\(t\\) seconds its velocity, \\(v\\) m s⁻¹, is given by\n\\(v = 3t^2 - 12t + 5\\) for \\(0 \\leq t \\leq 5\\).\n\nFind the minimum velocity of the particle.`, marks: 3, command: 'Find', markScheme: `M1: Differentiates to get \\(a = \\frac{dv}{dt} = 6t - 12\\) and sets equal to 0 (or completes the square)\nA1: \\(t = 2\\)\nA1: \\(v_{\\min} = 12 - 24 + 5 = -7\\) m s⁻¹ CAO\nFinal answer: −7 m s⁻¹` },
      { q: `A man of mass 75 kg stands on the floor of a lift. The lift is moving upwards and accelerating at 0.6 m s⁻².\n\nFind the magnitude of the normal reaction force exerted on the man by the floor of the lift.`, marks: 3, command: 'Find', markScheme: `M1: Applies Newton's second law to the man with two forces: \\(R - 75g = 75 \\times 0.6\\)\nA1: Correct equation\nA1: \\(R = 780\\) N CAO\nFinal answer: 780 N` },
      { q: `A uniform plank AB has length 4 m and mass 12 kg. The plank rests horizontally on two supports, one at A and one at the point C, where AC = 3 m.\n\nFind the magnitudes of the reaction forces exerted on the plank by each support.`, marks: 3, command: 'Find', markScheme: `M1: Takes moments about A (or C): \\(R_C \\times 3 = 12g \\times 2\\)\nA1: \\(R_C = 8g = 78.4\\) N\nA1ft: \\(R_A = 12g - R_C = 4g = 39.2\\) N\nFinal answers: 39.2 N at A, 78.4 N at C` },
      { q: `A box of mass 5 kg lies on a rough horizontal floor. The coefficient of friction between the box and the floor is 0.3. The box is pulled along the floor by a horizontal force of 20 N.\n\nFind the acceleration of the box.`, marks: 3, command: 'Find', markScheme: `B1: \\(R = 5g = 49\\) N and \\(F = 0.3 \\times 49 = 14.7\\) N\nM1: \\(20 - 14.7 = 5a\\)\nA1: \\(a = 1.06\\) m s⁻² CAO\nFinal answer: 1.06 m s⁻²` },
      { q: `A particle P moves on a horizontal plane with constant acceleration \\((0.5\\mathbf{i} - \\mathbf{j})\\) m s⁻². At time \\(t = 0\\), P is at the origin O and has velocity \\((2\\mathbf{i} + 5\\mathbf{j})\\) m s⁻¹.\n\nFind the distance of P from O when \\(t = 4\\).`, marks: 3, command: 'Find', markScheme: `M1: Uses \\(\\mathbf{r} = \\mathbf{u}t + \\frac{1}{2}\\mathbf{a}t^2\\) with \\(t = 4\\)\nA1: \\(\\mathbf{r} = (12\\mathbf{i} + 12\\mathbf{j})\\) m\nA1ft: distance \\(= \\sqrt{12^2 + 12^2} = 12\\sqrt{2}\\), AWRT 17.0 m\nFinal answer: 17.0 m` },
      { q: `A train travels along a straight track between two stations. It starts from rest and accelerates uniformly to a speed of 20 m s⁻¹ in 40 s. It then travels at 20 m s⁻¹ for \\(T\\) seconds, before decelerating uniformly to rest in 50 s. The distance between the stations is 5.9 km.\n\nUse a velocity–time graph, or otherwise, to find the value of \\(T\\).`, marks: 3, command: 'Find', markScheme: `M1: Total area under graph (trapezium or sum of parts) equated to 5900\nA1: \\(400 + 20T + 500 = 5900\\) oe\nA1: \\(T = 250\\) CAO\nFinal answer: \\(T = 250\\)` },
      { q: `A lamp of mass 3 kg is held in equilibrium by two light inextensible strings. One string makes an angle of 30° with the horizontal and the other makes an angle of 60° with the horizontal. The strings are on opposite sides of the lamp. The lamp is modelled as a particle.\n\nFind the tension in each string.`, marks: 4, command: 'Find', markScheme: `M1: Resolves horizontally: \\(T_1 \\cos 30° = T_2 \\cos 60°\\)\nM1: Resolves vertically: \\(T_1 \\sin 30° + T_2 \\sin 60° = 3g\\)\nA1: \\(T_1 = 14.7\\) N (string at 30°)\nA1: \\(T_2 = 14.7\\sqrt{3}\\), AWRT 25.5 N (string at 60°)\nCondone use of a triangle of forces / Lami for M marks` },
      { q: `A particle moves along a straight line. At time \\(t\\) seconds its acceleration, \\(a\\) m s⁻², is given by \\(a = 6 - 2t\\).\nWhen \\(t = 0\\) the particle is at the point O and has velocity 1 m s⁻¹.\n\nFind the displacement of the particle from O when \\(t = 3\\).`, marks: 4, command: 'Find', markScheme: `M1: Integrates \\(a\\) to get \\(v = 6t - t^2 + c\\)\nA1: \\(v = 1 + 6t - t^2\\)\nM1: Integrates \\(v\\) to get \\(x = t + 3t^2 - \\frac{t^3}{3}\\) (constant 0 since \\(x = 0\\) at \\(t = 0\\))\nA1: \\(x = 3 + 27 - 9 = 21\\) m CAO\nFinal answer: 21 m` },
      { q: `A football is kicked from a point on horizontal ground with speed 18 m s⁻¹ at an angle of 40° above the horizontal. The football is modelled as a particle moving freely under gravity.\n\nFind the horizontal distance travelled by the football before it first hits the ground.`, marks: 4, command: 'Find', markScheme: `M1: Vertical motion: \\(0 = 18\\sin 40° \\, t - 4.9t^2\\)\nA1: \\(t = \\frac{36\\sin 40°}{9.8} = 2.36\\) s\nM1: Horizontal distance \\(= 18\\cos 40° \\times t\\)\nA1: AWRT 32.6 m\nFinal answer: 32.6 m` },
      { q: `A small parcel is released from rest on a smooth ramp inclined at 25° to the horizontal. The parcel slides 3 m down a line of greatest slope of the ramp.\n\n(a) Find the speed of the parcel after it has slid 3 m. [3]\n\n(b) In reality the ramp is not smooth. State, with a reason, whether the actual speed of the parcel would be greater than or less than your answer to (a). [1]`, marks: 4, command: 'Find', markScheme: `(a)\nM1: Resolves parallel to the slope: \\(a = g\\sin 25°\\)\nA1: \\(a = 4.14\\) m s⁻²\nA1: \\(v = \\sqrt{2 \\times 4.14 \\times 3}\\), AWRT 4.98 m s⁻¹\n(b)\nE1: Less, because friction acts up the slope and reduces the acceleration\nFinal answer: 4.98 m s⁻¹` },
      { q: `A car of mass 1200 kg tows a trailer of mass 400 kg along a straight horizontal road by means of a light rigid horizontal towbar. The engine of the car produces a driving force of 2400 N. Resistance forces of 300 N and 100 N act on the car and the trailer respectively.\n\nFind the acceleration of the car and the tension in the towbar.`, marks: 4, command: 'Find', markScheme: `M1: Whole system: \\(2400 - 300 - 100 = 1600a\\)\nA1: \\(a = 1.25\\) m s⁻²\nM1: Trailer alone (or car alone): \\(T - 100 = 400a\\)\nA1: \\(T = 600\\) N CAO\nFinal answers: 1.25 m s⁻², 600 N` },
      { q: `In this question, \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) are unit vectors due east and due north respectively.\nA boat moves with constant velocity. At 09:00 it is at the point with position vector \\((2\\mathbf{i} - 3\\mathbf{j})\\) km and five hours later it is at the point with position vector \\((17\\mathbf{i} + 17\\mathbf{j})\\) km.\n\nFind the speed of the boat and the bearing on which it is moving.`, marks: 4, command: 'Find', markScheme: `M1: Velocity \\(= \\frac{(17\\mathbf{i} + 17\\mathbf{j}) - (2\\mathbf{i} - 3\\mathbf{j})}{5}\\)\nA1: \\((3\\mathbf{i} + 4\\mathbf{j})\\) km h⁻¹\nA1: speed \\(= 5\\) km h⁻¹\nB1: bearing \\(= \\tan^{-1}\\frac{3}{4}\\), AWRT 037°\nFinal answers: 5 km h⁻¹, 037°` },
      { q: `A box of mass 8 kg rests on rough horizontal ground. A rope is attached to the box and is pulled with a tension of 30 N at an angle of 20° above the horizontal. The box is on the point of moving.\n\nFind the coefficient of friction between the box and the ground.`, marks: 4, command: 'Find', markScheme: `M1: Resolves vertically: \\(R + 30\\sin 20° = 8g\\), so \\(R = 68.1\\) N\nM1: Resolves horizontally: \\(F = 30\\cos 20° = 28.2\\) N\nM1: Uses \\(F = \\mu R\\) (limiting friction)\nA1: \\(\\mu = 0.414\\) AWRT\nFinal answer: \\(\\mu = 0.414\\)` },
      { q: `Car A moves along a straight road at a constant speed of 12 m s⁻¹. At the instant A passes a point P, car B starts from rest at P and moves in the same direction as A with constant acceleration 1.5 m s⁻².\n\nFind the time taken for B to catch up with A, and the distance from P at which this happens.`, marks: 4, command: 'Find', markScheme: `M1: Displacement of A \\(= 12t\\); displacement of B \\(= 0.75t^2\\)\nM1: Equates and solves \\(12t = 0.75t^2\\)\nA1: \\(t = 16\\) s (reject \\(t = 0\\))\nA1: Distance \\(= 192\\) m CAO\nFinal answers: 16 s, 192 m` },
      { q: `Two particles A and B, of masses 5 kg and 3 kg respectively, are connected by a light inextensible string which passes over a smooth fixed pulley. The particles hang with the string taut and the hanging parts of the string vertical. The system is released from rest.\n\n(a) Find the acceleration of A and the tension in the string. [4]\n\n(b) State how you have used the fact that the string is inextensible. [1]`, marks: 5, command: 'Find', markScheme: `(a)\nM1: Newton's second law for A: \\(5g - T = 5a\\)\nM1: Newton's second law for B: \\(T - 3g = 3a\\)\nA1: \\(a = \\frac{2g}{8} = 2.45\\) m s⁻²\nA1: \\(T = 36.75\\), AWRT 36.8 N\n(b)\nE1: Both particles have the same magnitude of acceleration\nFinal answers: 2.45 m s⁻², 36.8 N` },
      { q: `A particle P, of mass 0.5 kg, moves so that its position vector at time \\(t\\) seconds is\n\\(\\mathbf{r} = (t^3 - 4t)\\mathbf{i} + (2t^2 + 1)\\mathbf{j}\\) metres, for \\(t \\geq 0\\).\n\n(a) Find the value of \\(t\\), for \\(t \\gt 0\\), at which P is moving parallel to \\(\\mathbf{j}\\). Give your answer in exact form. [3]\n\n(b) Find the magnitude of the resultant force acting on P when \\(t = 2\\). [2]`, marks: 5, command: 'Find', markScheme: `(a)\nM1: Differentiates: \\(\\mathbf{v} = (3t^2 - 4)\\mathbf{i} + 4t\\mathbf{j}\\)\nM1: Sets \\(\\mathbf{i}\\) component to zero: \\(3t^2 - 4 = 0\\)\nA1: \\(t = \\frac{2}{\\sqrt{3}}\\) oe exact\n(b)\nM1: \\(\\mathbf{a} = 6t\\mathbf{i} + 4\\mathbf{j} = 12\\mathbf{i} + 4\\mathbf{j}\\) at \\(t = 2\\), and uses \\(\\mathbf{F} = 0.5\\mathbf{a}\\)\nA1: \\(|\\mathbf{F}| = 0.5\\sqrt{160} = \\sqrt{40}\\), AWRT 6.32 N\nFinal answers: \\(t = \\frac{2\\sqrt{3}}{3}\\), 6.32 N` },
      { q: `A uniform ladder, of length 6 m and mass 20 kg, rests with its foot on rough horizontal ground and its top against a smooth vertical wall. The ladder makes an angle of 65° with the ground and is on the point of slipping.\n\nFind the coefficient of friction between the ladder and the ground.`, marks: 5, command: 'Find', markScheme: `B1: Resolves vertically: \\(R = 20g = 196\\) N\nM1: Takes moments about the foot: \\(S \\times 6\\sin 65° = 20g \\times 3\\cos 65°\\)\nA1: \\(S = 45.7\\) N\nM1: Resolves horizontally \\(F = S\\) and uses \\(F = \\mu R\\)\nA1: \\(\\mu = 0.233\\) AWRT\nFinal answer: 0.233` },
      { q: `A stone is thrown horizontally with speed 15 m s⁻¹ from the top of a vertical cliff, 40 m above the sea. The stone is modelled as a particle moving freely under gravity.\n\n(a) Find the horizontal distance from the foot of the cliff to the point where the stone hits the sea. [3]\n\n(b) Find the speed of the stone as it hits the sea. [2]`, marks: 5, command: 'Find', markScheme: `(a)\nM1: Vertical: \\(40 = 4.9t^2\\)\nA1: \\(t = 2.857\\) s\nA1: horizontal distance \\(= 15t\\), AWRT 42.9 m\n(b)\nM1: Vertical velocity \\(= 9.8t = 28\\) and uses Pythagoras with 15\nA1: \\(\\sqrt{1009}\\), AWRT 31.8 m s⁻¹\nFinal answers: 42.9 m, 31.8 m s⁻¹` },
      { q: `A sledge of mass 2 kg is released from rest on a rough slope inclined at 30° to the horizontal. The coefficient of friction between the sledge and the slope is 0.25. The sledge is modelled as a particle.\n\nFind the speed of the sledge after it has slid 4 m down the slope.`, marks: 5, command: 'Find', markScheme: `M1: Resolves perpendicular to slope: \\(R = 2g\\cos 30° = 16.97\\) N\nM1: Uses \\(F = 0.25R = 4.24\\) N\nM1: Resolves parallel: \\(2g\\sin 30° - F = 2a\\)\nA1: \\(a = 2.78\\) m s⁻²\nA1: \\(v = \\sqrt{2 \\times 2.78 \\times 4}\\), AWRT 4.71 m s⁻¹\nFinal answer: 4.71 m s⁻¹` },
      { q: `A block A of mass 4 kg lies on a rough horizontal table. The coefficient of friction between A and the table is 0.2. A light inextensible string attached to A passes over a smooth pulley fixed at the edge of the table and is attached to a particle B of mass 1 kg, which hangs freely 0.5 m above the floor. The system is released from rest with the string taut.\n\n(a) Show that the acceleration of B is 0.392 m s⁻². [3]\n\n(b) Find the tension in the string. [1]\n\n(c) Find the speed with which B hits the floor. [1]`, marks: 5, command: 'Show that', markScheme: `(a)\nB1: Friction \\(F = 0.2 \\times 4g = 7.84\\) N\nM1: Equations of motion, e.g. \\(T - 7.84 = 4a\\) and \\(g - T = a\\)\nA1: \\(5a = 9.8 - 7.84\\), so \\(a = 0.392\\) m s⁻² AG\n(b)\nB1: \\(T = 9.8 - 0.392 = 9.408\\), AWRT 9.41 N\n(c)\nB1: \\(v = \\sqrt{2 \\times 0.392 \\times 0.5}\\), AWRT 0.626 m s⁻¹` },
      { q: `A cyclist starts from rest and moves along a straight road. Her velocity, \\(v\\) m s⁻¹, at time \\(t\\) seconds is modelled by\n\\(v = 8t - t^2\\) for \\(0 \\leq t \\leq 8\\).\n\n(a) Find the maximum speed of the cyclist. [2]\n\n(b) Find the distance travelled by the cyclist during the 8 seconds. [3]`, marks: 5, command: 'Find', markScheme: `(a)\nM1: \\(\\frac{dv}{dt} = 8 - 2t = 0\\), \\(t = 4\\)\nA1: maximum speed \\(= 16\\) m s⁻¹\n(b)\nM1: \\(\\int_0^8 (8t - t^2)\\,dt\\)\nA1: \\(\\left[4t^2 - \\frac{t^3}{3}\\right]_0^8\\)\nA1: \\(\\frac{256}{3}\\), AWRT 85.3 m\nFinal answers: 16 m s⁻¹, 85.3 m` },
      { q: `A car of mass 900 kg moves up a straight road inclined at an angle \\(\\alpha\\) to the horizontal, where \\(\\sin\\alpha = \\frac{1}{15}\\). The engine produces a constant driving force of 2000 N and the car experiences a constant resistance to motion of 400 N.\n\n(a) Find the acceleration of the car. [3]\n\n(b) When the car is moving at 15 m s⁻¹ the engine is switched off. The resistance to motion remains 400 N. Find the further distance the car travels up the road before coming to rest. [3]`, marks: 6, command: 'Find', markScheme: `(a)\nB1: Weight component down slope \\(= 900g \\times \\frac{1}{15} = 588\\) N\nM1: \\(2000 - 400 - 588 = 900a\\)\nA1: \\(a = 1.12\\) m s⁻² AWRT\n(b)\nM1: \\(-(400 + 588) = 900a\\), deceleration \\(1.098\\) m s⁻²\nM1: \\(0 = 15^2 - 2 \\times 1.098 \\times s\\)\nA1: \\(s = 102\\) m AWRT\nFinal answers: 1.12 m s⁻², 102 m` },
      { q: `A lift of mass 500 kg is raised and lowered by a cable attached to its roof. A box of mass 40 kg rests on the floor of the lift. The lift is moving upwards and decelerating at 1.2 m s⁻².\n\n(a) Find the tension in the cable. [3]\n\n(b) Find the magnitude of the reaction force between the box and the floor of the lift. [2]\n\n(c) The cable is modelled as light. Explain why this modelling assumption is less appropriate if the lift is in a very tall building. [1]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: Whole system, with acceleration \\(-1.2\\): \\(T - 540g = 540 \\times (-1.2)\\)\nA1: Correct equation (sign of acceleration correct)\nA1: \\(T = 4644\\) N, AWRT 4640 N\n(b)\nM1: Box: \\(R - 40g = 40 \\times (-1.2)\\)\nA1: \\(R = 344\\) N CAO\n(c)\nE1: A very long cable has significant mass compared with the lift, so the tension would vary along the cable / could not be ignored` },
      { q: `A uniform plank AB has length 5 m and mass 30 kg. It rests horizontally on two supports at C and D, where AC = 1 m and DB = 1.5 m. A man of mass 70 kg stands on the plank. The man is modelled as a particle.\n\n(a) The man stands at the midpoint of AB. Find the magnitude of the reaction force at each support. [3]\n\n(b) The man walks slowly from the midpoint towards B. Find the distance of the man from B when the plank is about to tilt. [3]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: Moments about C: \\(R_D \\times 2.5 = 100g \\times 1.5\\)\nA1: \\(R_D = 60g = 588\\) N\nA1ft: \\(R_C = 100g - R_D = 392\\) N\n(b)\nM1: About to tilt about D so \\(R_C = 0\\)\nM1: Moments about D: \\(70g \\times d = 30g \\times 1\\), where \\(d\\) is the distance of the man beyond D\nA1: \\(d = \\frac{3}{7}\\), so distance from B \\(= 1.5 - \\frac{3}{7} = \\frac{15}{14}\\), AWRT 1.07 m\nFinal answers: 588 N, 392 N; 1.07 m` },
      { q: `A ball is projected from a point O on horizontal ground with initial velocity \\((12\\mathbf{i} + 14.7\\mathbf{j})\\) m s⁻¹, where \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) are unit vectors horizontal and vertically upwards respectively. A vertical wall of height 5 m stands 30 m horizontally from O, in the plane of motion of the ball.\n\n(a) Find the greatest height of the ball above the ground. [2]\n\n(b) Determine whether the ball passes over the wall. Fully justify your answer. [3]\n\n(c) State one modelling assumption you have made. [1]`, marks: 6, command: 'Determine', markScheme: `(a)\nM1: \\(0 = 14.7^2 - 2gh\\)\nA1: \\(h = 11.025\\), AWRT 11.0 m\n(b)\nM1: Time to reach wall: \\(t = \\frac{30}{12} = 2.5\\) s\nM1: Height \\(y = 14.7 \\times 2.5 - 4.9 \\times 2.5^2\\)\nA1: \\(y = 6.125\\) m, which is greater than 5 m, so the ball passes over the wall (by about 1.1 m)\n(c)\nB1: e.g. ball is a particle; no air resistance; no spin; g constant` },
      { q: `A particle moves along a straight line through a fixed point O. At time \\(t\\) seconds its velocity, \\(v\\) m s⁻¹, is given by \\(v = t^2 - 6t + 8\\). The particle is at O when \\(t = 0\\).\n\n(a) Find the times at which the particle is instantaneously at rest. [2]\n\n(b) Find the total distance travelled by the particle between \\(t = 0\\) and \\(t = 4\\). [4]`, marks: 6, command: 'Find', markScheme: `(a)\nM1: \\((t - 2)(t - 4) = 0\\)\nA1: \\(t = 2\\) and \\(t = 4\\)\n(b)\nM1: Integrates: \\(x = \\frac{t^3}{3} - 3t^2 + 8t\\)\nM1: Recognises change of direction at \\(t = 2\\) and evaluates separately on \\([0, 2]\\) and \\([2, 4]\\)\nA1: \\(x(2) = \\frac{20}{3}\\), \\(x(4) = \\frac{16}{3}\\)\nA1: Total distance \\(= \\frac{20}{3} + \\frac{4}{3} = 8\\) m CAO\nNote: \\(\\int_0^4 v\\,dt = \\frac{16}{3}\\) only scores M1 M0` },
      { q: `A crate of mass 4 kg is on a rough plane inclined at 30° to the horizontal. The coefficient of friction between the crate and the plane is 0.3. A horizontal force of magnitude \\(P\\) newtons, acting in the vertical plane containing a line of greatest slope, pushes the crate towards the plane. The crate is on the point of moving up the plane.\n\nFind the value of \\(P\\).`, marks: 6, command: 'Find', markScheme: `M1: Resolves perpendicular to the plane with three terms: \\(R = 4g\\cos 30° + P\\sin 30°\\)\nA1: Correct\nM1: Resolves parallel to the plane: \\(P\\cos 30° = 4g\\sin 30° + F\\)\nA1: Correct, with friction acting down the plane\nM1: Uses \\(F = 0.3R\\) and solves for \\(P\\)\nA1: \\(P = 41.6\\) AWRT` },
      { q: `A particle A, of mass 3 kg, rests on a rough plane inclined at 30° to the horizontal. The coefficient of friction between A and the plane is 0.2. A is attached to one end of a light inextensible string which passes over a smooth pulley fixed at the top of the plane. The other end of the string is attached to a particle B, of mass 5 kg, which hangs freely. The part of the string between A and the pulley is parallel to a line of greatest slope. The system is released from rest.\n\n(a) Find the acceleration of B. [4]\n\n(b) Find the tension in the string. [2]\n\n(c) State how you have used the fact that the pulley is smooth. [1]`, marks: 7, command: 'Find', markScheme: `(a)\nB1: \\(R = 3g\\cos 30° = 25.5\\) N, so \\(F = 0.2R = 5.09\\) N\nM1: Equation for A: \\(T - 3g\\sin 30° - F = 3a\\)\nM1: Equation for B: \\(5g - T = 5a\\)\nA1: \\(a = 3.65\\) m s⁻² AWRT\n(b)\nM1: Substitutes into either equation\nA1: \\(T = 30.7\\) N AWRT (30.75)\n(c)\nE1: The tension is the same on both sides of the pulley` },
      { q: `A particle P, of mass 2 kg, moves in a horizontal plane. At time \\(t\\) seconds its velocity is\n\\(\\mathbf{v} = (3t^2 - 2t)\\mathbf{i} + (8 - 4t)\\mathbf{j}\\) m s⁻¹.\nWhen \\(t = 0\\), P is at the point with position vector \\((2\\mathbf{i} - \\mathbf{j})\\) m.\n\n(a) Find the speed of P when \\(t = 2\\). [2]\n\n(b) Find the resultant force acting on P when \\(t = 1\\). [2]\n\n(c) Find the position vector of P when \\(t = 3\\). [3]`, marks: 7, command: 'Find', markScheme: `(a)\nM1: \\(\\mathbf{v} = 8\\mathbf{i} + 0\\mathbf{j}\\) at \\(t = 2\\)\nA1: speed \\(= 8\\) m s⁻¹\n(b)\nM1: \\(\\mathbf{a} = (6t - 2)\\mathbf{i} - 4\\mathbf{j}\\) and uses \\(\\mathbf{F} = 2\\mathbf{a}\\)\nA1: \\(\\mathbf{F} = (8\\mathbf{i} - 8\\mathbf{j})\\) N\n(c)\nM1: Integrates: \\(\\mathbf{r} = (t^3 - t^2)\\mathbf{i} + (8t - 2t^2)\\mathbf{j} + \\mathbf{c}\\)\nM1: \\(\\mathbf{c} = 2\\mathbf{i} - \\mathbf{j}\\)\nA1: \\(\\mathbf{r} = (20\\mathbf{i} + 5\\mathbf{j})\\) m CAO` },
      { q: `A uniform ladder AB, of length 5 m and mass 15 kg, rests with A on rough horizontal ground and B against a smooth vertical wall. The ladder makes an angle \\(\\theta\\) with the ground, where \\(\\tan\\theta = 2\\). The coefficient of friction between the ladder and the ground is 0.4. A man of mass 75 kg climbs slowly up the ladder.\n\n(a) Find the distance the man can climb along the ladder from A before the ladder slips. [6]\n\n(b) State one modelling assumption you have made about the man. [1]`, marks: 7, command: 'Find', markScheme: `(a)\nB1: \\(R = 90g\\)\nM1: Limiting friction \\(F = 0.4R = 36g\\) and wall reaction \\(S = F\\)\nM1: Moments about A with three terms: \\(S \\times 5\\sin\\theta = 15g \\times 2.5\\cos\\theta + 75g \\times x\\cos\\theta\\)\nA1: Correct equation, e.g. \\(36 \\times 5 \\times 2 = 37.5 + 75x\\)\ndM1: Solves for \\(x\\)\nA1: \\(x = 4.3\\) m CAO\n(b)\nB1: The man is modelled as a particle (his weight acts at a single point)` },
      { q: `A golf ball is struck from a point on horizontal ground with speed \\(V\\) m s⁻¹ at an angle of 35° above the horizontal. It first lands on the ground 120 m from where it was struck. The ball is modelled as a particle moving freely under gravity.\n\n(a) Show that \\(V = 35.4\\), correct to three significant figures. [4]\n\n(b) Find the time for which the ball is in the air. [2]\n\n(c) Give one criticism of the model, and state its likely effect on the predicted value of \\(V\\). [1]`, marks: 7, command: 'Show that', markScheme: `(a)\nM1: Time of flight \\(t = \\frac{2V\\sin 35°}{g}\\)\nM1: Range: \\(V\\cos 35° \\times t = 120\\)\nA1: \\(V^2 = \\frac{120g}{2\\sin 35°\\cos 35°}\\) oe\nA1: \\(V = 35.38\\ldots = 35.4\\) AG (must see more accuracy than 3 s.f.)\n(b)\nM1: \\(t = \\frac{120}{V\\cos 35°}\\) or \\(\\frac{2V\\sin 35°}{g}\\)\nA1: AWRT 4.14 s\n(c)\nE1: Air resistance is ignored; in reality the ball would need a greater speed to travel 120 m (or spin would affect the flight)` },
      { q: `A car starts from rest at time \\(t = 0\\) and moves along a straight road. For \\(0 \\leq t \\leq 20\\), its acceleration, \\(a\\) m s⁻², is modelled by \\(a = 3 - 0.15t\\). For \\(t \\gt 20\\) the car moves at constant speed.\n\n(a) Show that the speed of the car when \\(t = 20\\) is 30 m s⁻¹. [3]\n\n(b) Find the distance travelled by the car during the first 20 seconds. [3]\n\n(c) Find the total time taken for the car to travel 1 km from its starting point. [2]`, marks: 8, command: 'Show that', markScheme: `(a)\nM1: Integrates: \\(v = 3t - 0.075t^2 + c\\)\nB1: \\(c = 0\\) since starts from rest\nA1: \\(v(20) = 60 - 30 = 30\\) AG\n(b)\nM1: Integrates \\(v\\): \\(s = 1.5t^2 - 0.025t^3\\)\nA1: Correct expression\nA1: \\(s(20) = 600 - 200 = 400\\) m\n(c)\nM1: Remaining \\(600\\) m at \\(30\\) m s⁻¹ takes 20 s\nA1ft: total time \\(= 40\\) s` },
      { q: `Two particles A and B, of masses 2 kg and 3 kg respectively, are connected by a light inextensible string which passes over a smooth fixed pulley. The particles are held at rest with the string taut and its hanging parts vertical. B is 1.5 m above horizontal ground. The system is released from rest. When B hits the ground it does not rebound. A does not reach the pulley.\n\n(a) Find the acceleration of the particles while the string is taut. [3]\n\n(b) Find the speed of B as it hits the ground. [2]\n\n(c) Find the greatest height that A reaches above its starting position. [3]`, marks: 8, command: 'Find', markScheme: `(a)\nM1: Equations: \\(3g - T = 3a\\) and \\(T - 2g = 2a\\)\nM1: Eliminates \\(T\\): \\(g = 5a\\)\nA1: \\(a = 1.96\\) m s⁻²\n(b)\nM1: \\(v^2 = 2 \\times 1.96 \\times 1.5\\)\nA1: \\(v = \\sqrt{5.88}\\), AWRT 2.42 m s⁻¹\n(c)\nM1: After B lands, string slack and A moves freely under gravity: \\(0 = 5.88 - 2gh\\)\nA1: \\(h = 0.3\\) m\nA1ft: Greatest height \\(= 1.5 + 0.3 = 1.8\\) m above starting position` },
      { q: `A ball is projected from a point A, which is 1.2 m above horizontal ground, with speed 20 m s⁻¹ at an angle \\(\\alpha\\) above the horizontal, where \\(\\tan\\alpha = \\frac{3}{4}\\). The ball moves freely under gravity until it hits the ground at the point B.\n\n(a) Find the greatest height of the ball above the ground. [3]\n\n(b) Find the horizontal distance from A to B. [4]\n\n(c) Find the speed of the ball as it hits the ground at B. [2]`, marks: 9, command: 'Find', markScheme: `(a)\nB1: Components: horizontal \\(16\\) m s⁻¹, vertical \\(12\\) m s⁻¹\nM1: \\(0 = 12^2 - 2gh\\), \\(h = 7.35\\)\nA1: Greatest height above ground \\(= 1.2 + 7.35 = 8.55\\) m AWRT\n(b)\nM1: \\(-1.2 = 12t - 4.9t^2\\)\nM1: Solves the quadratic \\(4.9t^2 - 12t - 1.2 = 0\\)\nA1: \\(t = 2.545\\) s (reject negative root)\nA1: distance \\(= 16t\\), AWRT 40.7 m\n(c)\nM1: Vertical velocity \\(12 - 9.8t = -12.9\\) and combines with 16 (or uses \\(v^2 = 20^2 + 2 \\times 9.8 \\times 1.2\\))\nA1: AWRT 20.6 m s⁻¹` },
      { q: `A crate of mass 50 kg rests on rough horizontal ground. The coefficient of friction between the crate and the ground is 0.35. A rope is attached to the crate and pulled with tension \\(T\\) newtons at an angle of 30° above the horizontal. The crate is modelled as a particle and the rope as light.\n\n(a) Find the value of \\(T\\) for which the crate is on the point of moving. [4]\n\n(b) The tension is increased to 250 N and the crate starts from rest. Find the acceleration of the crate. [3]\n\n(c) After 4 seconds the rope breaks. Find the distance the crate then slides before coming to rest. [3]`, marks: 10, command: 'Find', markScheme: `(a)\nM1: Resolves vertically: \\(R = 50g - T\\sin 30° = 490 - 0.5T\\)\nM1: Resolves horizontally: \\(T\\cos 30° = F\\)\nM1: Uses \\(F = 0.35R\\): \\(T\\cos 30° = 0.35(490 - 0.5T)\\)\nA1: \\(T = 165\\) AWRT (164.7)\n(b)\nM1: \\(R = 490 - 125 = 365\\) N, \\(F = 127.75\\) N\nM1: \\(250\\cos 30° - 127.75 = 50a\\)\nA1: \\(a = 1.78\\) m s⁻² AWRT\n(c)\nB1ft: Speed when rope breaks \\(= 4a = 7.10\\) m s⁻¹\nM1: Deceleration now \\(0.35g = 3.43\\) m s⁻² (since \\(R = 50g\\)), uses \\(0 = v^2 - 2 \\times 3.43s\\)\nA1: \\(s = 7.35\\) m AWRT` }
    ]
  }
};
